        { name: 'ฐานข้อมูล', path: '/database' },
        { name: 'เปรียบเทียบ', path: '/compare' },
        { name: 'จัดการข้อมูล', path: '/manage' },
        { name: 'ตั้งค่า', path: '/settings' },
        { name: 'ติดต่อ', path: '/contact' },
    ];

    const isActive = (path: string) => location.pathname === path;

    const handleNav = (path: string) => {
        navigate(path);
