                    </div>
                    <div class="md:hidden">
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            class="text-gray-700 hover:text-purple-600 focus:outline-none"
                        >
                            {isOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>
            </div>
            {/* Mobile menu */}
            {isOpen && (
                <div class="md:hidden bg-white border-t absolute w-full shadow-lg">
                    <div class="px-2 pt-2 pb-3 space-y-1">
                        {navItems.map((item) => (
                            <button
                                key={item.path}
                                onClick={() => handleNav(item.path)}
                                class={`block w-full text-left px-3 py-2 text-base font-medium ${
                                    isActive(item.path)
                                        ? 'text-purple-600 bg-purple-50'
                                        : 'text-gray-700 hover:text-purple-600 hover:bg-gray-50'
                                }`}
                            >
                                {item.name}
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </nav>
    );
};

export default Navbar;

import React, { useState, useRef, useEffect } from 'react';
import { X, ChevronDown, Lock, Unlock } from 'lucide-react';

interface AutocompleteInputProps {
    id: string;
    label: string;
    value: string;
    options: string[];
    onChange: (value: string) => void;
    placeholder?: string;
    required?: boolean;
    disabled?: boolean;
    locked?: boolean;
    onLockToggle?: () => void;
}

const AutocompleteInput: React.FC<AutocompleteInputProps> = ({
    id,
    label,
    value,
    options,
    onChange,
    placeholder = 'เลือกหรือพิมพ์เพื่อค้นหา...',
    required = false,
    disabled = false,
    locked = false,
    onLockToggle
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [filter, setFilter] = useState('');
    const wrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const filteredOptions = options.filter(opt =>
        opt.toLowerCase().includes(filter.toLowerCase())
    );

    const handleSelect = (val: string) => {
        onChange(val);
        setFilter('');
        setIsOpen(false);
    };

    return (
        <div ref={wrapperRef} class="relative w-full">
            <div class="flex justify-between items-center mb-2">
                <label htmlFor={id} class="block text-sm font-medium text-gray-700">
                    {label} {required && <span class="text-red-500">*</span>}
                </label>
                {onLockToggle && (
                    <button
                        type="button"
                        onClick={onLockToggle}
                        class={`focus:outline-none transition-colors ${locked ? 'text-purple-600' : 'text-gray-400 hover:text-purple-600'}`}
                    >
                        {locked ? <Lock size={16} /> : <Unlock size={16} />}
                    </button>
                )}
            </div>
            <div class="relative">
                <input
                    type="text"
                    id={id}
                    value={value}
                    onChange={(e) => {
                        onChange(e.target.value);
                        setFilter(e.target.value);
                        setIsOpen(true);
                    }}
                    onFocus={() => setIsOpen(true)}
                    placeholder={placeholder}
                    disabled={disabled || locked}
                    class={`w-full px-4 py-3 pr-10 border rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent transition-all ${
                        locked ? 'bg-red-50 text-gray-600' : 'bg-white border-gray-300'
                    }`}
                    autoComplete="off"
                />
                {!locked && value && (
                    <button
                        type="button"
                        onClick={() => {
                            onChange('');
                            setFilter('');
                        }}
                        class="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-red-500"
                    >
                        <X size={18} />
                    </button>
                )}
                {isOpen && !locked && filteredOptions.length > 0 && (
                    <div class="absolute z-10 w-full bg-white border border-gray-300 rounded-lg mt-1 max-h-60 overflow-y-auto shadow-lg">
                        {filteredOptions.map((option, idx) => (
                            <div
                                key={idx}
                                onClick={() => handleSelect(option)}
                                class="px-4 py-2 hover:bg-purple-50 cursor-pointer text-gray-700 text-sm"
                            >
                                {option}
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default AutocompleteInput;

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';

const HomeView: React.FC = () => {
    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: '',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    const [isIntegrationActive, setIsIntegrationActive] = useState(false);

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }
        if (key === 'integration') {
           setIsIntegrationActive(value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)' || value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)');
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };
        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire('ข้อมูลไม่ครบ', 'กรุณากรอกข้อมูลที่จำเป็น (*)', 'warning');
            return;
        }

        Swal.fire({
            title: 'ยืนยันการบันทึก?',
            text: `ยอดรวม: ${formatNumber(totalBudget)} บาท`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#10b981'
        }).then((result) => {
            if (result.isConfirmed) {
                const newRecord: BudgetRecord = {
                    ...formData as BudgetRecord,
                    id: Date.now().toString(),
                    timestamp: getCurrentTimestamp()
                };
                dataService.addRecord(newRecord);

                // Keep locked fields, clear others
                const resetData = { ...formData };
                Object.keys(resetData).forEach(key => {
                    const k = key as keyof BudgetRecord;
                    if (!locks[k]) {
                        if (typeof resetData[k] === 'number') {
                            // @ts-ignore
                            resetData[k] = 0;
                        } else {
                            // @ts-ignore
                            resetData[k] = '';
                        }
                    }
                });

                setFormData(resetData);
                Swal.fire('สำเร็จ!', 'บันทึกข้อมูลเรียบร้อยแล้ว', 'success');
            }
        });
    };

    return (
        <div class="max-w-[95vw] mx-auto px-4 py-8">
            <div class="text-center mb-8">
                <h1 class="text-4xl font-bold text-gray-900 mb-4">แบบฟอร์มงบประมาณ</h1>
            </div>

            <form onSubmit={handleSubmit} class={`bg-white rounded-2xl shadow-xl p-8 transition-all duration-300 ${isIntegrationActive ? 'border-2 border-purple-400 bg-purple-50/30' : ''}`}>

                {/* Integration Top Right */}
                <div class="flex justify-end mb-6">
                    <div class="w-full md:w-1/3">
                        <AutocompleteInput
                            id="integration"
                            label="บูรณาการ"
                            required
                            value={formData.integration || ''}
                            options={['ไม่เป็นหน่วยงานบูรณาการ', 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)', 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)']}
                            onChange={(val) => handleChange('integration', val)}
                        />
                    </div>
                </div>

                {/* Section 1: Agency & Location */}
                <div class="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                    <AutocompleteInput
                        id="mainAgency"
                        label="หน่วยงานหลัก"
                        required
                        value={formData.mainAgency || ''}
                        options={dropdowns.mainAgency}
                        onChange={(val) => handleChange('mainAgency', val)}
                        locked={locks['mainAgency']}
                        onLockToggle={() => toggleLock('mainAgency')}
                    />
                     <AutocompleteInput
                        id="province"
                        label="จังหวัด"
                        required
                        value={formData.province || ''}
                        options={provinceOptions}
                        onChange={(val) => handleChange('province', val)}
                        locked={locks['province']}
                        onLockToggle={() => toggleLock('province')}
                    />
                    <AutocompleteInput
                        id="responsibleAgency"
                        label="หน่วยงานบูรณาการ"
                        value={formData.responsibleAgency || ''}
                        options={responsibleAgencyOptions}
                        onChange={(val) => handleChange('responsibleAgency', val)}
                        locked={locks['responsibleAgency']}
                        onLockToggle={() => toggleLock('responsibleAgency')}
                    />
                     <AutocompleteInput
                        id="integrationArea"
                        label="พื้นที่บูรณาการ"
                        value={formData.integrationArea || ''}
                        options={integrationAreaOptions}
                        onChange={(val) => handleChange('integrationArea', val)}
                        locked={locks['integrationArea']}
                        onLockToggle={() => toggleLock('integrationArea')}
                    />
                </div>

                {/* Section 2: Activity */}
                <div class="mb-6">
                     <AutocompleteInput
                        id="activity"
                        label="กิจกรรม"
                        required
                        value={formData.activity || ''}
                        options={dropdowns.activity}
                        onChange={(val) => handleChange('activity', val)}
                        locked={locks['activity']}
                        onLockToggle={() => toggleLock('activity')}
                    />
                </div>

                <div class="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-2">เป้าหมาย</label>
                        <input
                            type="text"
                            value={formData.target || ''}
                            onChange={(e) => handleChange('target', e.target.value)}
                            class="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                            placeholder="ระบุเป้าหมาย"
                        />
                    </div>
                     <AutocompleteInput
                        id="unit"
                        label="หน่วยนับ"
                        value={formData.unit || ''}
                        options={dropdowns.unit}
                        onChange={(val) => handleChange('unit', val)}
                    />
                </div>

                <hr class="my-8 border-gray-200" />

                {/* Section 3: Budget Details */}
                <h2 class="text-2xl font-bold text-gray-900 mb-6">งบประมาณ (บาท)</h2>

                <div class="grid md:grid-cols-2 gap-8">
                    {/* Left Col */}
                    <div class="space-y-6">
                        <div class="bg-blue-50 p-6 rounded-lg border border-blue-100">
                            <h3 class="text-xl font-semibold text-blue-800 mb-4">งบบุคลากร</h3>
                            <BudgetField label="เงินเดือนและค่าจ้างประจำ" val={formData.salaryPermanent} onChange={(v) => handleBudgetChange('salaryPermanent', v)} />
                            <div class="h-4"></div>
                            <BudgetField label="ค่าตอบแทนพนักงานราชการ" val={formData.governmentCompensation} onChange={(v) => handleBudgetChange('governmentCompensation', v)} />
                        </div>
                         <div class="bg-green-50 p-6 rounded-lg border border-green-100">
                            <h3 class="text-xl font-semibold text-green-800 mb-4">งบดำเนินงาน</h3>
                            <BudgetField label="ค่าตอบแทน ใช้สอย และวัสดุ" val={formData.compensationSupplies} onChange={(v) => handleBudgetChange('compensationSupplies', v)} />
                            <div class="h-4"></div>
                            <BudgetField label="ค่าจ้างเหมาพนักงาน" val={formData.contractEmployees} onChange={(v) => handleBudgetChange('contractEmployees', v)} />
                            <div class="h-4"></div>
                            <BudgetField label="ค่าสาธารณูปโภค" val={formData.utilities} onChange={(v) => handleBudgetChange('utilities', v)} />
                        </div>
                    </div>

                    {/* Right Col */}
                    <div class="space-y-6">
                        <div class="bg-yellow-50 p-6 rounded-lg border border-yellow-100">
                            <h3 class="text-xl font-semibold text-yellow-800 mb-4">งบลงทุน</h3>
                            <BudgetField label="ค่าครุภัณฑ์" val={formData.equipment} onChange={(v) => handleBudgetChange('equipment', v)} />
                            <div class="h-4"></div>
                            <BudgetField label="ค่าที่ดินและสิ่งก่อสร้าง" val={formData.landConstruction} onChange={(v) => handleBudgetChange('landConstruction', v)} />
                        </div>
                         <div class="bg-purple-50 p-6 rounded-lg border border-purple-100">
                            <h3 class="text-xl font-semibold text-purple-800 mb-4">งบอื่นๆ</h3>
                            <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />
                            <div class="h-4"></div>
                            <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />
                        </div>
                    </div>
                </div>

                {/* Total */}
