            {/* Stats Cards */}
            <div class="grid md:grid-cols-5 gap-4 mb-6">
                <SummaryCard title="งบบุคลากร" amount={summary.personnel} color="blue" icon="👥" />
                <SummaryCard title="งบดำเนินงาน" amount={summary.operational} color="green" icon="⚙️" />
                <SummaryCard title="งบลงทุน" amount={summary.investment} color="yellow" icon="🏗️" />
                <SummaryCard title="งบอื่นๆ" amount={summary.other} color="purple" icon="📋" />
                <SummaryCard title="รวมงบประมาณ" amount={totalBudget} color="gray" icon="💰" isTotal />
            </div>

            {/* Filters */}
            <div class="bg-white rounded-lg shadow-md mb-6 p-4">
                <div class="flex justify-between items-center mb-4 cursor-pointer" onClick={() => setShowFilters(!showFilters)}>
                    <div class="flex items-center gap-2 font-semibold text-gray-700">
                        <Filter size={20} /> กรองข้อมูล
                    </div>
                    <div class="text-sm text-gray-500">{showFilters ? 'ซ่อน' : 'แสดง'}</div>
                </div>

                {showFilters && (
                    <div class="grid md:grid-cols-3 gap-4">
                         <div class="relative">
                            <input
                                type="text"
                                placeholder="ค้นหาทั่วไป..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                class="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-purple-500"
                            />
                            <Search class="absolute left-3 top-2.5 text-gray-400" size={18} />
                        </div>
                        <select 
                            value={filterMainAgency} 
                            onChange={(e) => setFilterMainAgency(e.target.value)}
                            class="w-full px-4 py-2 border rounded-lg"
                        >
                            <option value="">ทุกหน่วยงาน</option>
                            {Array.from(new Set(records.map(r => r.mainAgency))).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                         <select 
                            value={filterProvince} 
                            onChange={(e) => setFilterProvince(e.target.value)}
                            class="w-full px-4 py-2 border rounded-lg"
                        >
                            <option value="">ทุกจังหวัด</option>
                            {Array.from(new Set(records.map(r => r.province))).map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                )}
            </div>

            {/* Table */}
            <div class="bg-white rounded-lg shadow-md overflow-hidden">
                <div class="overflow-x-auto custom-scrollbar">
                    <table class="min-w-full divide-y divide-gray-200">
                        <thead class="bg-gray-50">
                            <tr>
                                <Th>หน่วยงานหลัก</Th>
                                <Th>จังหวัด</Th>
                                <Th>กิจกรรม</Th>
                                <Th>งบบุคลากร</Th>
                                <Th>งบดำเนินงาน</Th>
                                <Th>งบลงทุน</Th>
                                <Th>งบอื่นๆ</Th>
                                <Th>รวม</Th>
                                <Th>วันที่บันทึก</Th>
                            </tr>
                        </thead>
                        <tbody class="bg-white divide-y divide-gray-200">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => {
                                const rowTotal = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                                               (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                                               (r.equipment || 0) + (r.landConstruction || 0) +
                                               (r.subsidies || 0) + (r.otherExpenses || 0);
                                return (
