                                        <Td align="right">{formatNumber((r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0))}</Td>
                                        <Td align="right">{formatNumber((r.equipment || 0) + (r.landConstruction || 0))}</Td>
                                        <Td align="right">{formatNumber((r.subsidies || 0) + (r.otherExpenses || 0))}</Td>
                                        <Td align="right" bold>{formatNumber(rowTotal)}</Td>
                                        <Td>{r.timestamp}</Td>
                                    </tr>
                                );
                            }) : (
                                <tr>
                                    <td colSpan={9} class="px-6 py-4 text-center text-gray-500">ไม่พบข้อมูล</td>
                                </tr>
