                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div class="px-6 py-4 border-t bg-gray-50 flex justify-between items-center">
                    <span class="text-sm text-gray-700">
                        แสดง {Math.min(filteredRecords.length, (currentPage - 1) * pageSize + 1)} ถึง {Math.min(filteredRecords.length, currentPage * pageSize)} จาก {filteredRecords.length} รายการ
