import React from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';

const CompareView: React.FC = () => {
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';
        if (actual === 0) status = 'nodata';
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    return (
        <div class="max-w-[98vw] mx-auto px-4 py-8">
            <div class="text-center mb-8">
                <h2 class="text-4xl font-bold text-gray-900 mb-4">เปรียบเทียบงบประมาณ</h2>
                <p class="text-xl text-gray-600">เปรียบเทียบงบประมาณที่บันทึกกับข้อมูลอ้างอิง</p>
            </div>

            {/* Summary */}
             <div class="grid md:grid-cols-3 gap-6 mb-8">
                <div class="bg-blue-50 p-6 rounded-lg shadow-md text-center">
                    <p class="text-gray-500">งบอ้างอิงรวม</p>
                    <p class="text-2xl font-bold text-blue-600">{formatNumber(totalRef)}</p>
                </div>
                 <div class="bg-gray-50 p-6 rounded-lg shadow-md text-center">
                    <p class="text-gray-500">งบที่บันทึกรวม</p>
                    <p class="text-2xl font-bold text-gray-800">{formatNumber(totalAct)}</p>
                </div>
                 <div class={`p-6 rounded-lg shadow-md text-center ${totalVar > 0 ? 'bg-yellow-50' : 'bg-green-50'}`}>
                    <p class="text-gray-500">ส่วนต่างรวม</p>
                    <p class={`text-2xl font-bold ${totalVar > 0 ? 'text-yellow-600' : 'text-green-600'}`}>
                        {totalVar > 0 ? '+' : ''}{formatNumber(totalVar)}
                    </p>
                </div>
            </div>

            <div class="bg-white rounded-lg shadow-md overflow-hidden">
                <div class="overflow-x-auto">
                    <table class="min-w-full divide-y divide-gray-200">
                        <thead class="bg-gray-50">
                            <tr>
                                <th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">กิจกรรม</th>
                                <th class="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">งบอ้างอิง</th>
                                <th class="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">งบที่บันทึก</th>
                                <th class="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">ส่วนต่าง</th>
                                <th class="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase">สถานะ</th>
                            </tr>
                        </thead>
                        <tbody class="divide-y divide-gray-200">
                            {comparisonResults.map(res => (
                                <tr key={res.id} class={res.status === 'over' ? 'bg-yellow-50' : res.status === 'under' ? 'bg-green-50' : ''}>
                                    <td class="px-6 py-4 text-sm text-gray-900">{res.activity}</td>
                                    <td class="px-6 py-4 text-sm text-gray-900 text-right">{formatNumber(res.referenceBudget)}</td>
                                    <td class="px-6 py-4 text-sm text-gray-900 text-right">{formatNumber(res.actual)}</td>
                                    <td class="px-6 py-4 text-sm text-gray-900 text-right font-medium">
                                        {res.variance > 0 ? '+' : ''}{formatNumber(res.variance)}
                                    </td>
                                    <td class="px-6 py-4 text-sm text-center">
                                        {res.status === 'nodata' && <span class="px-2 py-1 bg-gray-200 rounded text-xs">ไม่มีข้อมูล</span>}
                                        {res.status === 'over' && <span class="px-2 py-1 bg-yellow-200 text-yellow-800 rounded text-xs font-bold">เกินงบ</span>}
                                        {res.status === 'under' && <span class="px-2 py-1 bg-green-200 text-green-800 rounded text-xs font-bold">ต่ำกว่างบ</span>}
                                        {res.status === 'match' && <span class="px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs">ตรงตามงบ</span>}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

