import React, { useState, useRef, useEffect } from 'react';
import { X, ChevronDown, Lock, Unlock } from 'lucide-react';

interface AutocompleteInputProps {
    id: string;
    label: string;
    value: string;
    options: string[];
    onChange: (value: string) => void;
    placeholder?: string;
    required?: boolean;
    disabled?: boolean;
    locked?: boolean;
    onLockToggle?: () => void;
}

const AutocompleteInput: React.FC<AutocompleteInputProps> = ({
    id,
    label,
    value,
    options,
    onChange,
    placeholder = 'เลือกรายการ...',
    required = false,
    disabled = false,
    locked = false,
    onLockToggle
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [filter, setFilter] = useState('');
    const wrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const filteredOptions = options.filter(opt =>
        opt.toLowerCase().includes(filter.toLowerCase())
    );

    const handleSelect = (val: string) => {
        onChange(val);
        setFilter('');
        setIsOpen(false);
    };

    return (
        <div ref={wrapperRef} class="relative w-full group">
            <div class="flex justify-between items-center mb-1.5">
                <label htmlFor={id} class="block text-sm font-medium text-slate-700 group-hover:text-emerald-700 transition-colors">
                    {label} {required && <span class="text-red-500">*</span>}
                </label>
                {onLockToggle && (
                    <button
                        type="button"
                        onClick={onLockToggle}
                        class={`focus:outline-none transition-colors p-1 rounded-full ${locked ? 'text-emerald-600 bg-emerald-50' : 'text-slate-400 hover:text-emerald-600 hover:bg-slate-100'}`}
                    >
                        {locked ? <Lock size={14} /> : <Unlock size={14} />}
                    </button>
                )}
            </div>
            <div class="relative">
                <input
                    type="text"
                    id={id}
                    value={value}
                    onChange={(e) => {
                        onChange(e.target.value);
                        setFilter(e.target.value);
                        setIsOpen(true);
                    }}
                    onFocus={() => setIsOpen(true)}
                    placeholder={placeholder}
                    disabled={disabled || locked}
                    class={`w-full px-4 py-3 pr-10 border rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 transition-all outline-none text-slate-700 placeholder-slate-400 ${
                        locked 
                        ? 'bg-slate-50 border-slate-200 text-slate-500 cursor-not-allowed' 
                        : 'bg-white border-slate-200 hover:border-emerald-300'
                    }`}
                    autoComplete="off"
                />

                {!locked && value ? (
                    <button
                        type="button"
                        onClick={() => {
                            onChange('');
                            setFilter('');
                        }}
                        class="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 hover:text-red-500 transition-colors bg-white rounded-full p-0.5"
                    >
                        <X size={16} />
                    </button>
                ) : !locked && (
                     <div class="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none">
                        <ChevronDown size={16} />
                    </div>
                )}

                {isOpen && !locked && filteredOptions.length > 0 && (
                    <div class="absolute z-20 w-full bg-white border border-slate-100 rounded-xl mt-2 max-h-60 overflow-y-auto shadow-xl ring-1 ring-black ring-opacity-5 animate-in fade-in zoom-in-95 duration-100">
                        {filteredOptions.map((option, idx) => (
                            <div
                                key={idx}
                                onClick={() => handleSelect(option)}
                                class="px-4 py-2.5 hover:bg-emerald-50 hover:text-emerald-700 cursor-pointer text-slate-600 text-sm transition-colors border-b border-slate-50 last:border-0"
                            >
                                {option}
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default AutocompleteInput;

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';
import { Save, RefreshCw, Briefcase, MapPin, Calculator, Wallet, Building2, FileText, CheckCircle2 } from 'lucide-react';

const HomeView: React.FC = () => {
    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: '',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    const [isIntegrationActive, setIsIntegrationActive] = useState(false);

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }
        if (key === 'integration') {
           setIsIntegrationActive(value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)' || value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)');
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };
        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false,
            confirmButtonColor: '#10b981'
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire({
                title: 'ข้อมูลไม่ครบ',
                text: 'กรุณากรอกข้อมูลที่จำเป็น (*)',
                icon: 'warning',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        Swal.fire({
            title: 'ยืนยันการบันทึก?',
            html: `<div class="text-slate-600">ยอดรวมงบประมาณ</div><div class="text-3xl font-bold text-emerald-600 mt-2">${formatNumber(totalBudget)} บาท</div>`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: 'บันทึกข้อมูล',
            cancelButtonText: 'ตรวจสอบอีกครั้ง',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        }).then((result) => {
            if (result.isConfirmed) {
                const newRecord: BudgetRecord = {
                    ...formData as BudgetRecord,
                    id: Date.now().toString(),
                    timestamp: getCurrentTimestamp()
                };
                dataService.addRecord(newRecord);

                // Keep locked fields, clear others
                const resetData = { ...formData };
                Object.keys(resetData).forEach(key => {
                    const k = key as keyof BudgetRecord;
                    if (!locks[k]) {
                        if (typeof resetData[k] === 'number') {
                            // @ts-ignore
                            resetData[k] = 0;
                        } else {
                            // @ts-ignore
                            resetData[k] = '';
                        }
                    }
                });

                setFormData(resetData);
                Swal.fire({
                    title: 'บันทึกสำเร็จ!',
                    text: 'ข้อมูลถูกบันทึกลงในฐานข้อมูลเรียบร้อยแล้ว',
                    icon: 'success',
                    confirmButtonColor: '#059669',
                    timer: 2000
                });
            }
        });
    };

    return (
        <div class="max-w-[95vw] mx-auto px-4 py-8">
            <header class="text-center mb-10">
                <h1 class="text-3xl font-bold text-slate-800 mb-2">แบบฟอร์มบันทึกงบประมาณ</h1>
                <p class="text-slate-500">กรอกรายละเอียดโครงการและงบประมาณประจำปี</p>
            </header>

            <form onSubmit={handleSubmit} class="space-y-6">

                {/* Integration Card */}
                <div class={`bg-white rounded-2xl p-6 shadow-sm border border-slate-100 transition-all duration-300 ${isIntegrationActive ? 'ring-2 ring-emerald-400 bg-emerald-50/20' : ''}`}>
                    <div class="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div class="flex items-center gap-3">
                            <div class="p-2.5 bg-emerald-100 text-emerald-600 rounded-xl">
                                <Briefcase size={24} />
                            </div>
                            <div>
                                <h2 class="text-lg font-semibold text-slate-800">สถานะบูรณาการ</h2>
                                <p class="text-sm text-slate-500">ระบุประเภทหน่วยงานและการบูรณาการ</p>
                            </div>
                        </div>
                        <div class="w-full md:w-1/2 lg:w-1/3">
                            <AutocompleteInput
                                id="integration"
                                label="ประเภทหน่วยงาน"
                                required
                                value={formData.integration || ''}
                                options={['ไม่เป็นหน่วยงานบูรณาการ', 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)', 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)']}
                                onChange={(val) => handleChange('integration', val)}
                                placeholder="เลือกสถานะบูรณาการ..."
                            />
                        </div>
                    </div>
                </div>

                <div class="grid grid-cols-1 xl:grid-cols-2 gap-6">
                    {/* Section 1: Agency & Location */}
                    <div class="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 md:p-8">
                        <div class="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
