import React, { useState, useMemo } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { ChevronLeft, ChevronRight, Search, Filter, Users, Settings, Building, FileSpreadsheet, Wallet } from 'lucide-react';

const DatabaseView: React.FC = () => {
    const records = dataService.getRecords();
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(25);
    const [showFilters, setShowFilters] = useState(false);

    // Filters
    const [filterMainAgency, setFilterMainAgency] = useState('');
    const [filterProvince, setFilterProvince] = useState('');

    const filteredRecords = useMemo(() => {
        return records.filter(record => {
            const matchesSearch = 
                record.mainAgency.toLowerCase().includes(searchTerm.toLowerCase()) ||
                record.activity.toLowerCase().includes(searchTerm.toLowerCase()) ||
                record.province.toLowerCase().includes(searchTerm.toLowerCase());

            const matchesAgency = filterMainAgency ? record.mainAgency === filterMainAgency : true;
            const matchesProvince = filterProvince ? record.province === filterProvince : true;

            return matchesSearch && matchesAgency && matchesProvince;
        });
    }, [records, searchTerm, filterMainAgency, filterProvince]);

    // Pagination
    const totalPages = Math.ceil(filteredRecords.length / pageSize);
    const paginatedRecords = filteredRecords.slice((currentPage - 1) * pageSize, currentPage * pageSize);

    // Summary Stats
    const summary = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            personnel: acc.personnel + (r.salaryPermanent || 0) + (r.governmentCompensation || 0),
            operational: acc.operational + (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0),
            investment: acc.investment + (r.equipment || 0) + (r.landConstruction || 0),
            other: acc.other + (r.subsidies || 0) + (r.otherExpenses || 0)
        }), { personnel: 0, operational: 0, investment: 0, other: 0 });
    }, [filteredRecords]);

    const totalBudget = summary.personnel + summary.operational + summary.investment + summary.other;

    return (
        <div class="max-w-[98vw] mx-auto px-4 py-8">
            <div class="mb-8">
                <h2 class="text-3xl font-bold text-slate-800 mb-2">ฐานข้อมูลงบประมาณ</h2>
                <p class="text-slate-500">เรียกดูและค้นหาข้อมูลโครงการทั้งหมด</p>
            </div>

            {/* Stats Cards */}
            <div class="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
                <SummaryCard title="งบบุคลากร" amount={summary.personnel} color="blue" icon={<Users size={20} />} />
                <SummaryCard title="งบดำเนินงาน" amount={summary.operational} color="emerald" icon={<Settings size={20} />} />
                <SummaryCard title="งบลงทุน" amount={summary.investment} color="amber" icon={<Building size={20} />} />
                <SummaryCard title="งบอื่นๆ" amount={summary.other} color="purple" icon={<FileSpreadsheet size={20} />} />
                <SummaryCard title="รวมงบประมาณ" amount={totalBudget} color="slate" icon={<Wallet size={20} />} isTotal />
            </div>

            {/* Filters Bar */}
            <div class="bg-white rounded-2xl shadow-sm border border-slate-100 mb-6 p-4">
                <div class="flex justify-between items-center mb-4 cursor-pointer group" onClick={() => setShowFilters(!showFilters)}>
                    <div class="flex items-center gap-2 font-semibold text-slate-700 group-hover:text-emerald-700 transition-colors">
                        <Filter size={20} /> 
                        <span>ตัวกรองและค้นหา</span>
                    </div>
                    <div class="text-sm text-slate-400 bg-slate-50 px-3 py-1 rounded-full">{showFilters ? 'ซ่อน' : 'แสดง'}</div>
                </div>

                <div class={`transition-all duration-300 overflow-hidden ${showFilters ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
                    <div class="grid md:grid-cols-3 gap-4 pt-2">
                         <div class="relative">
                            <input
                                type="text"
                                placeholder="ค้นหาจากชื่อหน่วยงาน, กิจกรรม..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                class="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 outline-none text-slate-700"
                            />
                            <Search class="absolute left-3 top-3 text-slate-400" size={18} />
                        </div>
                        <select 
                            value={filterMainAgency} 
                            onChange={(e) => setFilterMainAgency(e.target.value)}
                            class="w-full px-4 py-2.5 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 outline-none text-slate-700 bg-white"
                        >
                            <option value="">ทุกหน่วยงาน</option>
                            {Array.from(new Set(records.map(r => r.mainAgency))).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                         <select 
                            value={filterProvince} 
                            onChange={(e) => setFilterProvince(e.target.value)}
                            class="w-full px-4 py-2.5 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 outline-none text-slate-700 bg-white"
                        >
                            <option value="">ทุกจังหวัด</option>
                            {Array.from(new Set(records.map(r => r.province))).map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div class="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <div class="overflow-x-auto custom-scrollbar">
                    <table class="min-w-full divide-y divide-slate-100">
                        <thead class="bg-slate-50">
                            <tr>
                                <Th>หน่วยงานหลัก</Th>
                                <Th>จังหวัด</Th>
                                <Th>กิจกรรม</Th>
                                <Th align="right">งบบุคลากร</Th>
                                <Th align="right">งบดำเนินงาน</Th>
                                <Th align="right">งบลงทุน</Th>
                                <Th align="right">งบอื่นๆ</Th>
                                <Th align="right">รวม</Th>
                                <Th>วันที่บันทึก</Th>
                            </tr>
                        </thead>
                        <tbody class="bg-white divide-y divide-slate-50">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => {
                                const rowTotal = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                                               (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                                               (r.equipment || 0) + (r.landConstruction || 0) +
                                               (r.subsidies || 0) + (r.otherExpenses || 0);
                                return (
                                    <tr key={r.id} class="hover:bg-slate-50/80 transition-colors">
                                        <Td>{r.mainAgency}</Td>
                                        <Td>{r.province}</Td>
                                        <Td>{r.activity}</Td>
                                        <Td align="right" subtle>{formatNumber((r.salaryPermanent || 0) + (r.governmentCompensation || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.equipment || 0) + (r.landConstruction || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.subsidies || 0) + (r.otherExpenses || 0))}</Td>
                                        <Td align="right" bold color="text-emerald-700">{formatNumber(rowTotal)}</Td>
                                        <Td subtle>{r.timestamp.split(' ')[0]}</Td>
                                    </tr>
                                );
                            }) : (
                                <tr>
                                    <td colSpan={9} class="px-6 py-12 text-center text-slate-400">
                                        <div class="flex flex-col items-center justify-center">
                                            <Search size={48} class="mb-4 opacity-20" />
                                            <p>ไม่พบข้อมูลที่ค้นหา</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div class="px-6 py-4 border-t border-slate-100 bg-slate-50/50 flex justify-between items-center">
                    <span class="text-sm text-slate-500">
                        แสดง {Math.min(filteredRecords.length, (currentPage - 1) * pageSize + 1)} - {Math.min(filteredRecords.length, currentPage * pageSize)} จาก {filteredRecords.length}
                    </span>
                    <div class="flex gap-2">
                        <button 
                            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                            disabled={currentPage === 1}
                            class="p-2 rounded-lg hover:bg-white hover:shadow-sm disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronLeft size={18} />
                        </button>
                        <span class="px-4 py-1.5 bg-white border border-slate-200 rounded-lg text-sm font-medium text-slate-700 shadow-sm">
                            {currentPage} / {totalPages || 1}
                        </span>
                        <button 
                            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                            disabled={currentPage === totalPages || totalPages === 0}
                            class="p-2 rounded-lg hover:bg-white hover:shadow-sm disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

