import React from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale } from 'lucide-react';

const CompareView: React.FC = () => {
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';
        if (actual === 0) status = 'nodata';
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="mb-8">
                <h2 className="text-3xl font-bold text-slate-800 mb-2">เปรียบเทียบงบประมาณ</h2>
                <p className="text-slate-500">วิเคราะห์ความแตกต่างระหว่างงบประมาณที่ตั้งไว้และงบที่ใช้จริง</p>
            </div>

            {/* Summary */}
             <div className="grid md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
                    <div>
                        <p className="text-slate-500 text-sm font-medium mb-1">งบอ้างอิงรวม</p>
                        <p className="text-2xl font-bold text-blue-600">{formatNumber(totalRef)}</p>
                    </div>
                    <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
                        <Target size={24} />
                    </div>
                </div>
                 <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
                    <div>
                        <p className="text-slate-500 text-sm font-medium mb-1">งบที่บันทึกรวม</p>
                        <p className="text-2xl font-bold text-emerald-600">{formatNumber(totalAct)}</p>
                    </div>
                    <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl">
                        <TrendingUp size={24} />
                    </div>
                </div>
                 <div className={`p-6 rounded-2xl shadow-sm border flex items-center justify-between ${totalVar > 0 ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
                    <div>
                        <p className={`text-sm font-medium mb-1 ${totalVar > 0 ? 'text-amber-700' : 'text-emerald-700'}`}>ส่วนต่างรวม</p>
                        <p className={`text-2xl font-bold ${totalVar > 0 ? 'text-amber-700' : 'text-emerald-700'}`}>
                            {totalVar > 0 ? '+' : ''}{formatNumber(totalVar)}
                        </p>
                    </div>
                    <div className={`p-3 rounded-xl ${totalVar > 0 ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                        <Scale size={24} />
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-100">
                        <thead className="bg-slate-50">
                            <tr>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">กิจกรรม</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">งบอ้างอิง</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">งบที่บันทึก</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">ส่วนต่าง</th>
                                <th className="px-6 py-4 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">สถานะ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {comparisonResults.map(res => (
                                <tr key={res.id} className="hover:bg-slate-50/50 transition-colors">
                                    <td className="px-6 py-4 text-sm font-medium text-slate-700">{res.activity}</td>
                                    <td className="px-6 py-4 text-sm text-slate-500 text-right">{formatNumber(res.referenceBudget)}</td>
                                    <td className="px-6 py-4 text-sm text-slate-900 text-right font-medium">{formatNumber(res.actual)}</td>
                                    <td className={`px-6 py-4 text-sm text-right font-bold ${res.variance > 0 ? 'text-amber-600' : res.variance < 0 ? 'text-emerald-600' : 'text-slate-400'}`}>
                                        {res.variance > 0 ? '+' : ''}{formatNumber(res.variance)}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-center">
                                        {res.status === 'nodata' && <span className="px-3 py-1 bg-slate-100 text-slate-500 rounded-full text-xs font-medium">ไม่มีข้อมูล</span>}
                                        {res.status === 'over' && <span className="px-3 py-1 bg-amber-100 text-amber-700 rounded-full text-xs font-bold">เกินงบ</span>}
                                        {res.status === 'under' && <span className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-full text-xs font-bold">ต่ำกว่างบ</span>}
                                        {res.status === 'match' && <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-bold">ตรงตามงบ</span>}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

