                                className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 outline-none text-slate-700 text-base"
                            />
                            <Search className="absolute left-3 top-3.5 text-slate-400" size={20} />
                        </div>
                        <select 
                            value={filterMainAgency} 
                            onChange={(e) => setFilterMainAgency(e.target.value)}
                            className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-4 focus:ring-emerald-100 focus:border-emerald-500 outline-none text-slate-700 bg-white text-base"
                        >
                            <option value="">ทุกหน่วยงาน</option>
