import React, { useEffect, useState } from 'react';
import { Sun, Moon } from 'lucide-react';

const ThemeToggle: React.FC = () => {
    const [isDark, setIsDark] = useState(false);

    useEffect(() => {
        // Check local storage or system preference
        const savedTheme = localStorage.getItem('theme');
        const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

        if (savedTheme === 'dark' || (!savedTheme && systemPrefersDark)) {
            setIsDark(true);
            document.documentElement.classList.add('dark');
        } else {
            setIsDark(false);
            document.documentElement.classList.remove('dark');
        }
    }, []);

    const toggleTheme = () => {
        if (isDark) {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
            setIsDark(false);
        } else {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
            setIsDark(true);
        }
    };

    return (
        <div className="fixed bottom-6 left-6 z-50 flex flex-col items-center gap-3 p-2 bg-white/80 dark:bg-slate-800/80 backdrop-blur-md rounded-full shadow-lg border border-slate-200 dark:border-slate-700 transition-all duration-300">
            <Sun size={20} className={`transition-colors mt-1 ${!isDark ? 'text-amber-500' : 'text-slate-400'}`} />

            <button 
                onClick={toggleTheme}
                className="w-8 h-14 bg-slate-200 dark:bg-slate-700 rounded-full relative transition-colors focus:outline-none shadow-inner"
                aria-label="Toggle Dark Mode"
            >
                <div 
                    className={`absolute left-1 w-6 h-6 rounded-full shadow-md transform transition-transform duration-300 ${
                        isDark 
                        ? 'translate-y-7 bg-slate-800 border border-slate-600' 
                        : 'translate-y-1 bg-white'
                    }`}
                ></div>
            </button>

            <Moon size={20} className={`transition-colors mb-1 ${isDark ? 'text-blue-400' : 'text-slate-400'}`} />
        </div>
    );
};

export default ThemeToggle;

