import React, { useState, useMemo } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { ChevronLeft, ChevronRight, Search, Filter, Users, Settings, Building, FileSpreadsheet, Wallet } from 'lucide-react';

const DatabaseView: React.FC = () => {
    const records = dataService.getRecords();
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(25);
    const [showFilters, setShowFilters] = useState(false);

    // Filters
    const [filterMainAgency, setFilterMainAgency] = useState('');
    const [filterProvince, setFilterProvince] = useState('');

    const filteredRecords = useMemo(() => {
        return records.filter(record => {
            const matchesSearch = 
                record.mainAgency.toLowerCase().includes(searchTerm.toLowerCase()) ||
                record.activity.toLowerCase().includes(searchTerm.toLowerCase()) ||
                record.province.toLowerCase().includes(searchTerm.toLowerCase());

            const matchesAgency = filterMainAgency ? record.mainAgency === filterMainAgency : true;
            const matchesProvince = filterProvince ? record.province === filterProvince : true;

            return matchesSearch && matchesAgency && matchesProvince;
        });
    }, [records, searchTerm, filterMainAgency, filterProvince]);

    // Pagination
    const totalPages = Math.ceil(filteredRecords.length / pageSize);
    const paginatedRecords = filteredRecords.slice((currentPage - 1) * pageSize, currentPage * pageSize);

    // Summary Stats
    const summary = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            personnel: acc.personnel + (r.salaryPermanent || 0) + (r.governmentCompensation || 0),
            operational: acc.operational + (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0),
            investment: acc.investment + (r.equipment || 0) + (r.landConstruction || 0),
            other: acc.other + (r.subsidies || 0) + (r.otherExpenses || 0)
        }), { personnel: 0, operational: 0, investment: 0, other: 0 });
    }, [filteredRecords]);

    const totalBudget = summary.personnel + summary.operational + summary.investment + summary.other;

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="mb-8">
                <h2 className="text-4xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">ฐานข้อมูลงบประมาณ</h2>
                <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">เรียกดูและค้นหาข้อมูลโครงการทั้งหมด</p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
                <SummaryCard title="งบบุคลากร" amount={summary.personnel} color="blue" icon={<Users size={20} />} />
                <SummaryCard title="งบดำเนินงาน" amount={summary.operational} color="emerald" icon={<Settings size={20} />} />
                <SummaryCard title="งบลงทุน" amount={summary.investment} color="amber" icon={<Building size={20} />} />
                <SummaryCard title="งบอื่นๆ" amount={summary.other} color="purple" icon={<FileSpreadsheet size={20} />} />
                <SummaryCard title="รวมงบประมาณ" amount={totalBudget} color="slate" icon={<Wallet size={20} />} isTotal />
            </div>

            {/* Filters Bar */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-6 p-4 transition-colors">
                <div className="flex justify-between items-center mb-4 cursor-pointer group" onClick={() => setShowFilters(!showFilters)}>
                    <div className="flex items-center gap-2 font-semibold text-slate-700 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors text-lg">
                        <Filter size={24} /> 
                        <span>ตัวกรองและค้นหา</span>
                    </div>
                    <div className="text-sm text-slate-400 bg-slate-50 dark:bg-slate-700 px-3 py-1 rounded-full">{showFilters ? 'ซ่อน' : 'แสดง'}</div>
                </div>

                <div className={`transition-all duration-300 overflow-hidden ${showFilters ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
                    <div className="grid md:grid-cols-3 gap-4 pt-2">
                         <div className="relative">
                            <input
                                type="text"
                                placeholder="ค้นหาจากชื่อหน่วยงาน, กิจกรรม..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                            />
                            <Search className="absolute left-3 top-3.5 text-slate-400" size={20} />
                        </div>
                        <select 
                            value={filterMainAgency} 
                            onChange={(e) => setFilterMainAgency(e.target.value)}
                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                        >
                            <option value="">ทุกหน่วยงาน</option>
                            {Array.from(new Set(records.map(r => r.mainAgency))).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                         <select 
                            value={filterProvince} 
                            onChange={(e) => setFilterProvince(e.target.value)}
                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                        >
                            <option value="">ทุกจังหวัด</option>
                            {Array.from(new Set(records.map(r => r.province))).map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="min-w-full divide-y divide-slate-100 dark:divide-slate-700">
                        <thead className="bg-slate-50 dark:bg-slate-900/50">
                            <tr>
                                <Th>หน่วยงานหลัก</Th>
                                <Th>จังหวัด</Th>
                                <Th>กิจกรรม</Th>
                                <Th align="right">งบบุคลากร</Th>
                                <Th align="right">งบดำเนินงาน</Th>
                                <Th align="right">งบลงทุน</Th>
                                <Th align="right">งบอื่นๆ</Th>
                                <Th align="right">รวม</Th>
                                <Th>วันที่บันทึก</Th>
                            </tr>
                        </thead>
                        <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-50 dark:divide-slate-700">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => {
                                const rowTotal = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                                               (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                                               (r.equipment || 0) + (r.landConstruction || 0) +
                                               (r.subsidies || 0) + (r.otherExpenses || 0);
                                return (
                                    <tr key={r.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-700/50 transition-colors">
                                        <Td>{r.mainAgency}</Td>
                                        <Td>{r.province}</Td>
                                        <Td>{r.activity}</Td>
                                        <Td align="right" subtle>{formatNumber((r.salaryPermanent || 0) + (r.governmentCompensation || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.equipment || 0) + (r.landConstruction || 0))}</Td>
                                        <Td align="right" subtle>{formatNumber((r.subsidies || 0) + (r.otherExpenses || 0))}</Td>
                                        <Td align="right" bold color="text-emerald-700 dark:text-emerald-400">{formatNumber(rowTotal)}</Td>
                                        <Td subtle>{r.timestamp.split(' ')[0]}</Td>
                                    </tr>
                                );
                            }) : (
                                <tr>
                                    <td colSpan={9} className="px-6 py-12 text-center text-slate-400">
                                        <div className="flex flex-col items-center justify-center">
                                            <Search size={48} className="mb-4 opacity-20" />
                                            <p>ไม่พบข้อมูลที่ค้นหา</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50 flex justify-between items-center transition-colors">
                    <span className="text-sm text-slate-500 dark:text-slate-400">
                        แสดง {Math.min(filteredRecords.length, (currentPage - 1) * pageSize + 1)} - {Math.min(filteredRecords.length, currentPage * pageSize)} จาก {filteredRecords.length}
                    </span>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronLeft size={18} />
                        </button>
                        <span className="px-4 py-1.5 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200 shadow-sm">
                            {currentPage} / {totalPages || 1}
                        </span>
                        <button 
                            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                            disabled={currentPage === totalPages || totalPages === 0}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

const Th = ({ children, align = 'left' }: { children?: React.ReactNode, align?: 'left'|'right'|'center' }) => (
    <th className={`px-6 py-4 text-${align} text-sm font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap`}>
        {children}
    </th>
);

const Td = ({ children, align = 'left', bold = false, subtle = false, color }: { children?: React.ReactNode, align?: 'left'|'right'|'center', bold?: boolean, subtle?: boolean, color?: string }) => (
    <td className={`px-6 py-4 whitespace-nowrap text-base text-${align} ${bold ? 'font-bold' : 'font-normal'} ${subtle ? 'text-slate-500 dark:text-slate-400' : (color || 'text-slate-700 dark:text-slate-200')}`}>
        {children}
    </td>
);

const SummaryCard = ({ title, amount, color, icon, isTotal = false }: any) => {
    const colorClasses: Record<string, string> = {
        blue: 'bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 border-blue-100 dark:border-blue-900/50',
        emerald: 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border-emerald-100 dark:border-emerald-900/50',
        amber: 'bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300 border-amber-100 dark:border-amber-900/50',
        purple: 'bg-purple-50 dark:bg-purple-900/20 text-purple-700 dark:text-purple-300 border-purple-100 dark:border-purple-900/50',
        slate: 'bg-slate-800 dark:bg-slate-700 text-white border-slate-700 shadow-lg',
    };

    return (
        <div className={`rounded-2xl p-5 border ${colorClasses[color]} flex flex-col justify-between h-full transition-transform hover:-translate-y-1 duration-300`}>
            <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-bold uppercase tracking-wider ${isTotal ? 'text-slate-400' : 'opacity-70'}`}>{title}</span>
                <div className={`p-1.5 rounded-lg ${isTotal ? 'bg-slate-700 text-emerald-400' : 'bg-white/50 dark:bg-black/20'}`}>
                    {icon}
                </div>
            </div>
            <p className={`font-bold ${isTotal ? 'text-3xl' : 'text-2xl'}`}>{formatNumber(amount)}</p>
        </div>
    );
};

export default DatabaseView;

import React from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale } from 'lucide-react';

const CompareView: React.FC = () => {
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';
        if (actual === 0) status = 'nodata';
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="mb-8">
                <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">เปรียบเทียบงบประมาณ</h2>
                <p className="text-slate-500 dark:text-slate-400 transition-colors">วิเคราะห์ความแตกต่างระหว่างงบประมาณที่ตั้งไว้และงบที่ใช้จริง</p>
            </div>

            {/* Summary */}
             <div className="grid md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">งบอ้างอิงรวม</p>
                        <p className="text-2xl font-bold text-blue-600 dark:text-blue-400">{formatNumber(totalRef)}</p>
                    </div>
                    <div className="p-3 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl">
                        <Target size={24} />
                    </div>
                </div>
                 <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">งบที่บันทึกรวม</p>
                        <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{formatNumber(totalAct)}</p>
                    </div>
                    <div className="p-3 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl">
                        <TrendingUp size={24} />
                    </div>
                </div>
                 <div className={`p-6 rounded-2xl shadow-sm border flex items-center justify-between transition-colors ${totalVar > 0 ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-100 dark:border-amber-900/50' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-900/50'}`}>
                    <div>
                        <p className={`text-sm font-medium mb-1 ${totalVar > 0 ? 'text-amber-700 dark:text-amber-400' : 'text-emerald-700 dark:text-emerald-400'}`}>ส่วนต่างรวม</p>
                        <p className={`text-2xl font-bold ${totalVar > 0 ? 'text-amber-700 dark:text-amber-400' : 'text-emerald-700 dark:text-emerald-400'}`}>
                            {totalVar > 0 ? '+' : ''}{formatNumber(totalVar)}
                        </p>
                    </div>
                    <div className={`p-3 rounded-xl ${totalVar > 0 ? 'bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400' : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400'}`}>
                        <Scale size={24} />
                    </div>
                </div>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-100 dark:divide-slate-700">
                        <thead className="bg-slate-50 dark:bg-slate-900/50">
                            <tr>
                                <th className="px-6 py-4 text-left text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">กิจกรรม</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">งบอ้างอิง</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">งบที่บันทึก</th>
                                <th className="px-6 py-4 text-right text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">ส่วนต่าง</th>
                                <th className="px-6 py-4 text-center text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">สถานะ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
                            {comparisonResults.map(res => (
                                <tr key={res.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-700/50 transition-colors">
                                    <td className="px-6 py-4 text-sm font-medium text-slate-700 dark:text-slate-200">{res.activity}</td>
                                    <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400 text-right">{formatNumber(res.referenceBudget)}</td>
                                    <td className="px-6 py-4 text-sm text-slate-900 dark:text-slate-100 text-right font-medium">{formatNumber(res.actual)}</td>
                                    <td className={`px-6 py-4 text-sm text-right font-bold ${res.variance > 0 ? 'text-amber-600 dark:text-amber-400' : res.variance < 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-400'}`}>
                                        {res.variance > 0 ? '+' : ''}{formatNumber(res.variance)}
                                    </td>
                                    <td className="px-6 py-4 text-sm text-center">
                                        {res.status === 'nodata' && <span className="px-3 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-300 rounded-full text-xs font-medium">ไม่มีข้อมูล</span>}
                                        {res.status === 'over' && <span className="px-3 py-1 bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400 rounded-full text-xs font-bold">เกินงบ</span>}
                                        {res.status === 'under' && <span className="px-3 py-1 bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400 rounded-full text-xs font-bold">ต่ำกว่างบ</span>}
                                        {res.status === 'match' && <span className="px-3 py-1 bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-400 rounded-full text-xs font-bold">ตรงตามงบ</span>}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default CompareView;

