import React, { useEffect, useState } from 'react';
import { Sun, Moon } from 'lucide-react';

const ThemeToggle: React.FC = () => {
    const [isDark, setIsDark] = useState(false);

    useEffect(() => {
        // Check local storage or system preference
        const savedTheme = localStorage.getItem('theme');
        const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

        if (savedTheme === 'dark' || (!savedTheme && systemPrefersDark)) {
            setIsDark(true);
            document.documentElement.classList.add('dark');
        } else {
            setIsDark(false);
            document.documentElement.classList.remove('dark');
        }
    }, []);

    const toggleTheme = () => {
        if (isDark) {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
            setIsDark(false);
        } else {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
            setIsDark(true);
        }
    };

    return (
        <div className="fixed bottom-6 left-6 z-50 flex flex-col items-center justify-between py-4 px-2 bg-slate-800/95 dark:bg-slate-950/95 backdrop-blur-md rounded-full shadow-2xl border border-slate-700 transition-all duration-300 gap-4">

            {/* Sun Icon */}
            <Sun 
                size={20} 
                className={`transition-colors duration-300 ${!isDark ? 'text-amber-400' : 'text-slate-500'}`} 
            />

            {/* Toggle Switch */}
            <button 
                onClick={toggleTheme}
                className="w-8 h-16 bg-slate-700/50 dark:bg-slate-800/50 rounded-full relative transition-colors focus:outline-none border border-slate-600 shadow-inner overflow-hidden p-0"
                aria-label="Toggle Dark Mode"
            >
                {/* Knob */}
                <div 
                    className={`absolute left-1 top-1 w-6 h-6 rounded-full shadow-md transform transition-transform duration-300 cubic-bezier(0.4, 0, 0.2, 1) ${
                        isDark 
                        ? 'translate-y-8 bg-slate-200' 
                        : 'translate-y-0 bg-white'
                    }`}
                ></div>
            </button>

            {/* Moon Icon */}
            <Moon 
                size={20} 
                className={`transition-colors duration-300 ${isDark ? 'text-blue-400' : 'text-slate-500'}`} 
            />
        </div>
    );
};

