                            <div className="bg-emerald-50/70 dark:bg-emerald-900/20 p-6 rounded-2xl border border-emerald-100 dark:border-emerald-900/50 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-emerald-700 dark:text-emerald-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-emerald-500 rounded-full"></div>
                                    งบดำเนินงาน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าตอบแทน ใช้สอย และวัสดุ" val={formData.compensationSupplies} onChange={(v) => handleBudgetChange('compensationSupplies', v)} />
                                    <BudgetField label="ค่าจ้างเหมาพนักงาน" val={formData.contractEmployees} onChange={(v) => handleBudgetChange('contractEmployees', v)} />
                                    <BudgetField label="ค่าสาธารณูปโภค" val={formData.utilities} onChange={(v) => handleBudgetChange('utilities', v)} />
                                </div>
                            </div>
                        </div>

                        {/* Right Col */}
                        <div className="space-y-6">
                            <div className="bg-amber-50/70 dark:bg-amber-900/20 p-6 rounded-2xl border border-amber-100 dark:border-amber-900/50 hover:border-amber-200 dark:hover:border-amber-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-amber-700 dark:text-amber-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-amber-500 rounded-full"></div>
                                    งบลงทุน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าครุภัณฑ์" val={formData.equipment} onChange={(v) => handleBudgetChange('equipment', v)} />
                                    <BudgetField label="ค่าที่ดินและสิ่งก่อสร้าง" val={formData.landConstruction} onChange={(v) => handleBudgetChange('landConstruction', v)} />
                                </div>
                            </div>
                            <div className="bg-purple-50/70 dark:bg-purple-900/20 p-6 rounded-2xl border border-purple-100 dark:border-purple-900/50 hover:border-purple-200 dark:hover:border-purple-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-purple-700 dark:text-purple-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-purple-500 rounded-full"></div>
                                    งบอื่นๆ
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />
                                    <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />
