                            <div className="bg-emerald-50/70 dark:bg-emerald-900/20 p-6 rounded-2xl border border-emerald-100 dark:border-emerald-900/50 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-emerald-700 dark:text-emerald-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-emerald-500 rounded-full"></div>
                                    งบดำเนินงาน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าตอบแทน ใช้สอย และวัสดุ" val={formData.compensationSupplies} onChange={(v) => handleBudgetChange('compensationSupplies', v)} />
                                    <BudgetField label="ค่าจ้างเหมาพนักงาน" val={formData.contractEmployees} onChange={(v) => handleBudgetChange('contractEmployees', v)} />
                                    <BudgetField label="ค่าสาธารณูปโภค" val={formData.utilities} onChange={(v) => handleBudgetChange('utilities', v)} />
                                </div>
                            </div>
                        </div>

                        {/* Right Col */}
                        <div className="space-y-6">
                            <div className="bg-amber-50/70 dark:bg-amber-900/20 p-6 rounded-2xl border border-amber-100 dark:border-amber-900/50 hover:border-amber-200 dark:hover:border-amber-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-amber-700 dark:text-amber-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-amber-500 rounded-full"></div>
                                    งบลงทุน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าครุภัณฑ์" val={formData.equipment} onChange={(v) => handleBudgetChange('equipment', v)} />
                                    <BudgetField label="ค่าที่ดินและสิ่งก่อสร้าง" val={formData.landConstruction} onChange={(v) => handleBudgetChange('landConstruction', v)} />
                                </div>
                            </div>
                            <div className="bg-purple-50/70 dark:bg-purple-900/20 p-6 rounded-2xl border border-purple-100 dark:border-purple-900/50 hover:border-purple-200 dark:hover:border-purple-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-purple-700 dark:text-purple-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-purple-500 rounded-full"></div>
                                    งบอื่นๆ
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />
                                    <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Action Bar */}
                <div className="sticky bottom-4 z-20">
                     <div className="bg-slate-900/90 dark:bg-slate-950/90 backdrop-blur-md text-white p-4 rounded-2xl shadow-2xl flex flex-col md:flex-row justify-between items-center gap-4 border border-slate-700/50">
                        <div className="flex flex-col md:flex-row items-center gap-2 md:gap-6">
                            <div className="text-slate-300 text-base font-medium">รวมงบประมาณสุทธิ</div>
                            <div className={`text-3xl font-bold ${getThemeTextColor()}`}>
                                {formatNumber(totalBudget)} <span className="text-xl text-slate-400 font-normal">บาท</span>
                            </div>
                        </div>

                        <div className="flex gap-3 w-full md:w-auto">
                            <button 
                                type="button" 
                                onClick={clearForm} 
                                className="flex-1 md:flex-none px-8 py-3 rounded-xl bg-slate-800 text-slate-300 font-semibold hover:bg-slate-700 transition-all border border-slate-700 flex items-center justify-center gap-2 text-base"
                            >
                                <RefreshCw size={20} /> ล้างค่า
                            </button>
                            <button 
                                type="submit" 
                                className={`flex-1 md:flex-none px-10 py-3 rounded-xl text-white font-semibold transition-all shadow-lg transform hover:-translate-y-0.5 flex items-center justify-center gap-2 text-base ${getButtonColor()}`}
                            >
                                <CheckCircle2 size={22} /> บันทึกข้อมูล
                            </button>
                        </div>
                    </div>
                </div>
            </form>
            <div className="h-8"></div>
        </div>
    );
};

const BudgetField = ({ label, val, onChange }: { label: string, val: number | undefined, onChange: (v: string) => void }) => (
    <div className="group">
        <label className="block text-base font-medium text-slate-600 dark:text-slate-300 mb-2 group-hover:text-slate-800 dark:group-hover:text-slate-100 transition-colors">{label}</label>
        <div className="relative">
            <input
                type="text"
                value={val ? formatNumber(val) : ''}
                onChange={(e) => onChange(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all text-right font-medium text-slate-800 dark:text-slate-100 placeholder-slate-300 text-lg"
                placeholder="0"
            />
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-base">฿</span>
        </div>
    </div>
);

export default HomeView;

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';
import { Save, RefreshCw, Briefcase, MapPin, Calculator, Wallet, Building2, FileText, CheckCircle2 } from 'lucide-react';

const HomeView: React.FC = () => {
    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: '',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    // integrationType state: 'none', 'park' (Green), 'wildlife' (Pink)
    const [integrationType, setIntegrationType] = useState<'none' | 'park' | 'wildlife'>('none');

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }

        // Handle Integration Type Logic
        if (key === 'integration') {
           if (value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') {
                setIntegrationType('park');
           } else if (value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') {
                setIntegrationType('wildlife');
           } else {
                setIntegrationType('none');
           }
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };
        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        // Reset integration type if integration field is cleared and not locked
        if (!locks['integration']) {
            setIntegrationType('none');
        } else {
             // Re-evaluate integration type from locked value
             if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') setIntegrationType('park');
             else if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') setIntegrationType('wildlife');
             else setIntegrationType('none');
        }

        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false,
            confirmButtonColor: '#10b981'
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire({
                title: 'ข้อมูลไม่ครบ',
                text: 'กรุณากรอกข้อมูลที่จำเป็น (*)',
                icon: 'warning',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        Swal.fire({
            title: 'ยืนยันการบันทึก?',
            html: `<div class="text-slate-600">ยอดรวมงบประมาณ</div><div class="text-3xl font-bold text-emerald-600 mt-2">${formatNumber(totalBudget)} บาท</div>`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: 'บันทึกข้อมูล',
            cancelButtonText: 'ตรวจสอบอีกครั้ง',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        }).then((result) => {
            if (result.isConfirmed) {
                const newRecord: BudgetRecord = {
                    ...formData as BudgetRecord,
                    id: Date.now().toString(),
                    timestamp: getCurrentTimestamp()
                };
                dataService.addRecord(newRecord);

                // Keep locked fields, clear others
                const resetData = { ...formData };
                Object.keys(resetData).forEach(key => {
                    const k = key as keyof BudgetRecord;
                    if (!locks[k]) {
                        if (typeof resetData[k] === 'number') {
                            // @ts-ignore
                            resetData[k] = 0;
                        } else {
                            // @ts-ignore
                            resetData[k] = '';
                        }
                    }
                });

                setFormData(resetData);
                if (!locks['integration']) setIntegrationType('none');

                Swal.fire({
                    title: 'บันทึกสำเร็จ!',
                    text: 'ข้อมูลถูกบันทึกลงในฐานข้อมูลเรียบร้อยแล้ว',
                    icon: 'success',
                    confirmButtonColor: '#059669',
                    timer: 2000
                });
            }
        });
    };

    // Dynamic Style Helpers for Cards
    const getCardStyle = (type: 'none' | 'park' | 'wildlife') => {
        switch (type) {
            case 'park':
                return 'bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400 ring-2 ring-emerald-400/80 shadow-emerald-100 dark:shadow-emerald-900/10';
            case 'wildlife':
                return 'bg-pink-50/20 dark:bg-pink-900/10 border-pink-400 ring-2 ring-pink-400/80 shadow-pink-100 dark:shadow-pink-900/10';
            default:
                return 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700';
        }
    };

    const getIntegrationCardStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'ring-2 ring-emerald-400 bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400';
            case 'wildlife':
                return 'ring-2 ring-pink-400 bg-pink-50/20 dark:bg-pink-900/10 border-pink-400';
            default:
                return 'border-slate-100 dark:border-slate-700';
        }
    };

    // --- Dynamic Footer Styles ---

    const getFooterContainerStyle = () => {
        switch (integrationType) {
            case 'park':
                // Green background
                return 'bg-emerald-600/95 dark:bg-emerald-800/95 border-emerald-500/50 shadow-emerald-900/20';
            case 'wildlife':
                // Pink background
                return 'bg-pink-600/95 dark:bg-pink-800/95 border-pink-500/50 shadow-pink-900/20';
            default:
                // Gray/Slate background (Default)
                return 'bg-slate-900/90 dark:bg-slate-950/90 border-slate-700/50 shadow-slate-900/20';
        }
    };

    const getFooterLabelColor = () => {
        switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white/80';
            default:
                return 'text-slate-300';
        }
    };

    const getFooterValueColor = () => {
         switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white';
            default:
                return 'text-emerald-400';
        }
    };

    const getSubmitButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                // White button on Green background
                return 'bg-white text-emerald-600 hover:bg-emerald-50 shadow-emerald-900/20';
            case 'wildlife':
                // White button on Pink background
                return 'bg-white text-pink-600 hover:bg-pink-50 shadow-pink-900/20';
            default:
                // Green button on Dark Gray background
                return 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-900/20 hover:shadow-emerald-900/40';
        }
    };

    const getClearButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'bg-emerald-700/50 text-emerald-50 hover:bg-emerald-700 border-emerald-500/50';
            case 'wildlife':
                return 'bg-pink-700/50 text-pink-50 hover:bg-pink-700 border-pink-500/50';
            default:
                return 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-slate-700';
        }
    };

    return (
        <div className="max-w-[95vw] mx-auto px-4 py-8">
            <header className="text-center mb-10">
                <h1 className="text-4xl font-bold text-slate-800 dark:text-white mb-3 transition-colors">แบบฟอร์มบันทึกงบประมาณ</h1>
                <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">กรอกรายละเอียดโครงการและงบประมาณประจำปี</p>
            </header>

            <form onSubmit={handleSubmit} className="space-y-6">

                {/* Integration Card */}
                <div className={`bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border transition-all duration-300 ${getIntegrationCardStyle()}`}>
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-3 rounded-xl ${
                                integrationType === 'wildlife' 
                                ? 'bg-pink-100 dark:bg-pink-900/40 text-pink-600 dark:text-pink-400' 
                                : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400'
                            }`}>
                                <Briefcase size={28} />
                            </div>
                            <div>
                                <h2 className="text-xl font-semibold text-slate-800 dark:text-white">สถานะบูรณาการ</h2>
                                <p className="text-base text-slate-500 dark:text-slate-400">ระบุประเภทหน่วยงานและการบูรณาการ</p>
                            </div>
                        </div>
                        <div className="w-full md:w-1/2 lg:w-1/3">
                            <AutocompleteInput
                                id="integration"
                                label="ประเภทหน่วยงาน"
                                required
                                value={formData.integration || ''}
                                options={['ไม่เป็นหน่วยงานบูรณาการ', 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)', 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)']}
                                onChange={(val) => handleChange('integration', val)}
                                placeholder="เลือกสถานะบูรณาการ..."
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                    {/* Section 1: Agency & Location */}
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                            <div className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-xl">
                                <Building2 size={24} />
                            </div>
                            <h2 className="text-xl font-semibold text-slate-800 dark:text-white">ข้อมูลหน่วยงานและพื้นที่</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-6">
                            <AutocompleteInput
                                id="mainAgency"
                                label="หน่วยงานหลัก"
                                required
                                value={formData.mainAgency || ''}
                                options={dropdowns.mainAgency}
                                onChange={(val) => handleChange('mainAgency', val)}
                                locked={locks['mainAgency']}
                                onLockToggle={() => toggleLock('mainAgency')}
                            />
                            <AutocompleteInput
                                id="province"
                                label="จังหวัด"
                                required
                                value={formData.province || ''}
                                options={provinceOptions}
                                onChange={(val) => handleChange('province', val)}
                                locked={locks['province']}
                                onLockToggle={() => toggleLock('province')}
                            />
                            <AutocompleteInput
                                id="responsibleAgency"
                                label="หน่วยงานบูรณาการ"
                                value={formData.responsibleAgency || ''}
                                options={responsibleAgencyOptions}
                                onChange={(val) => handleChange('responsibleAgency', val)}
                                locked={locks['responsibleAgency']}
                                onLockToggle={() => toggleLock('responsibleAgency')}
                            />
                            <AutocompleteInput
                                id="integrationArea"
                                label="พื้นที่บูรณาการ"
                                value={formData.integrationArea || ''}
                                options={integrationAreaOptions}
                                onChange={(val) => handleChange('integrationArea', val)}
                                locked={locks['integrationArea']}
                                onLockToggle={() => toggleLock('integrationArea')}
                            />
                        </div>
                    </div>

                    {/* Section 2: Activity */}
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                         <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                            <div className="p-3 bg-purple-50 dark:bg-purple-900/40 text-purple-600 dark:text-purple-400 rounded-xl">
                                <FileText size={24} />
                            </div>
                            <h2 className="text-xl font-semibold text-slate-800 dark:text-white">รายละเอียดกิจกรรม</h2>
                        </div>

                        <div className="space-y-6">
                            <AutocompleteInput
                                id="activity"
                                label="กิจกรรม"
                                required
                                value={formData.activity || ''}
                                options={dropdowns.activity}
                                onChange={(val) => handleChange('activity', val)}
                                locked={locks['activity']}
                                onLockToggle={() => toggleLock('activity')}
                            />

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-2">เป้าหมาย</label>
                                    <input
                                        type="text"
                                        value={formData.target || ''}
                                        onChange={(e) => handleChange('target', e.target.value)}
                                        className="w-full px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all outline-none text-lg text-slate-800 dark:text-slate-100 placeholder-slate-400"
                                        placeholder="ระบุตัวเลขเป้าหมาย"
                                    />
                                </div>
                                <AutocompleteInput
                                    id="unit"
                                    label="หน่วยนับ"
                                    value={formData.unit || ''}
                                    options={dropdowns.unit}
                                    onChange={(val) => handleChange('unit', val)}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Section 3: Budget Details */}
                <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                    <div className="flex items-center gap-3 mb-8">
                        <div className="p-3 bg-emerald-50 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400 rounded-xl">
                            <Calculator size={28} />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-slate-800 dark:text-white">รายละเอียดงบประมาณ</h2>
                            <p className="text-slate-500 dark:text-slate-400 text-base">ระบุจำนวนเงินในแต่ละหมวดรายจ่าย (หน่วย: บาท)</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Left Col */}
                        <div className="space-y-6">
                            <div className="bg-blue-50/70 dark:bg-blue-900/20 p-6 rounded-2xl border border-blue-100 dark:border-blue-900/50 hover:border-blue-200 dark:hover:border-blue-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-blue-700 dark:text-blue-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-blue-500 rounded-full"></div>
                                    งบบุคลากร
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="เงินเดือนและค่าจ้างประจำ" val={formData.salaryPermanent} onChange={(v) => handleBudgetChange('salaryPermanent', v)} />
                                    <BudgetField label="ค่าตอบแทนพนักงานราชการ" val={formData.governmentCompensation} onChange={(v) => handleBudgetChange('governmentCompensation', v)} />
                                </div>
                            </div>
                            <div className="bg-emerald-50/70 dark:bg-emerald-900/20 p-6 rounded-2xl border border-emerald-100 dark:border-emerald-900/50 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-emerald-700 dark:text-emerald-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-emerald-500 rounded-full"></div>
                                    งบดำเนินงาน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าตอบแทน ใช้สอย และวัสดุ" val={formData.compensationSupplies} onChange={(v) => handleBudgetChange('compensationSupplies', v)} />
                                    <BudgetField label="ค่าจ้างเหมาพนักงาน" val={formData.contractEmployees} onChange={(v) => handleBudgetChange('contractEmployees', v)} />
                                    <BudgetField label="ค่าสาธารณูปโภค" val={formData.utilities} onChange={(v) => handleBudgetChange('utilities', v)} />
                                </div>
                            </div>
                        </div>

                        {/* Right Col */}
                        <div className="space-y-6">
                            <div className="bg-amber-50/70 dark:bg-amber-900/20 p-6 rounded-2xl border border-amber-100 dark:border-amber-900/50 hover:border-amber-200 dark:hover:border-amber-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-amber-700 dark:text-amber-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-amber-500 rounded-full"></div>
                                    งบลงทุน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าครุภัณฑ์" val={formData.equipment} onChange={(v) => handleBudgetChange('equipment', v)} />
                                    <BudgetField label="ค่าที่ดินและสิ่งก่อสร้าง" val={formData.landConstruction} onChange={(v) => handleBudgetChange('landConstruction', v)} />
                                </div>
                            </div>
                            <div className="bg-purple-50/70 dark:bg-purple-900/20 p-6 rounded-2xl border border-purple-100 dark:border-purple-900/50 hover:border-purple-200 dark:hover:border-purple-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-purple-700 dark:text-purple-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-purple-500 rounded-full"></div>
                                    งบอื่นๆ
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />
                                    <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Action Bar */}
                <div className="sticky bottom-4 z-20">
                     <div className={`backdrop-blur-md p-4 rounded-2xl shadow-2xl flex flex-col md:flex-row justify-between items-center gap-4 border transition-all duration-300 ${getFooterContainerStyle()}`}>
                        <div className="flex flex-col md:flex-row items-center gap-2 md:gap-6">
                            <div className={`text-base font-medium ${getFooterLabelColor()}`}>รวมงบประมาณสุทธิ</div>
                            <div className={`text-3xl font-bold ${getFooterValueColor()}`}>
                                {formatNumber(totalBudget)} <span className="text-xl font-normal opacity-80">บาท</span>
                            </div>
                        </div>

                        <div className="flex gap-3 w-full md:w-auto">
                            <button 
                                type="button" 
                                onClick={clearForm} 
                                className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-semibold transition-all border flex items-center justify-center gap-2 text-base ${getClearButtonStyle()}`}
                            >
                                <RefreshCw size={20} /> ล้างค่า
                            </button>
                            <button 
                                type="submit" 
                                className={`flex-1 md:flex-none px-10 py-3 rounded-xl font-semibold transition-all shadow-lg transform hover:-translate-y-0.5 flex items-center justify-center gap-2 text-base ${getSubmitButtonStyle()}`}
                            >
                                <CheckCircle2 size={22} /> บันทึกข้อมูล
                            </button>
                        </div>
                    </div>
                </div>
            </form>
            <div className="h-8"></div>
        </div>
    );
};

const BudgetField = ({ label, val, onChange }: { label: string, val: number | undefined, onChange: (v: string) => void }) => (
    <div className="group">
        <label className="block text-base font-medium text-slate-600 dark:text-slate-300 mb-2 group-hover:text-slate-800 dark:group-hover:text-slate-100 transition-colors">{label}</label>
        <div className="relative">
            <input
                type="text"
                value={val ? formatNumber(val) : ''}
                onChange={(e) => onChange(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all text-right font-medium text-slate-800 dark:text-slate-100 placeholder-slate-300 text-lg"
                placeholder="0"
            />
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-base">฿</span>
        </div>
    </div>
);

export default HomeView;

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';
import { Save, RefreshCw, Briefcase, MapPin, Calculator, Wallet, Building2, FileText, CheckCircle2 } from 'lucide-react';

const HomeView: React.FC = () => {
    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: 'ไม่เป็นหน่วยงานบูรณาการ',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    // integrationType state: 'none', 'park' (Green), 'wildlife' (Pink)
    const [integrationType, setIntegrationType] = useState<'none' | 'park' | 'wildlife'>('none');

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }

        // Handle Integration Type Logic
        if (key === 'integration') {
           if (value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') {
                setIntegrationType('park');
           } else if (value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') {
                setIntegrationType('wildlife');
           } else {
                setIntegrationType('none');
           }
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };
        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else if (k === 'integration') {
                    // @ts-ignore
                    newForm[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        // Reset integration type if integration field is cleared and not locked
        if (!locks['integration']) {
            setIntegrationType('none');
        } else {
             // Re-evaluate integration type from locked value
             if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') setIntegrationType('park');
             else if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') setIntegrationType('wildlife');
             else setIntegrationType('none');
        }

        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false,
            confirmButtonColor: '#10b981'
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire({
                title: 'ข้อมูลไม่ครบ',
                text: 'กรุณากรอกข้อมูลที่จำเป็น (*)',
                icon: 'warning',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        Swal.fire({
            title: 'ยืนยันการบันทึก?',
            html: `<div class="text-slate-600">ยอดรวมงบประมาณ</div><div class="text-3xl font-bold text-emerald-600 mt-2">${formatNumber(totalBudget)} บาท</div>`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: 'บันทึกข้อมูล',
            cancelButtonText: 'ตรวจสอบอีกครั้ง',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        }).then((result) => {
            if (result.isConfirmed) {
                const newRecord: BudgetRecord = {
                    ...formData as BudgetRecord,
                    id: Date.now().toString(),
                    timestamp: getCurrentTimestamp()
                };
                dataService.addRecord(newRecord);

                // Keep locked fields, clear others
                const resetData = { ...formData };
                Object.keys(resetData).forEach(key => {
                    const k = key as keyof BudgetRecord;
                    if (!locks[k]) {
                        if (typeof resetData[k] === 'number') {
                            // @ts-ignore
                            resetData[k] = 0;
                        } else if (k === 'integration') {
                            // @ts-ignore
                            resetData[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                        } else {
                            // @ts-ignore
                            resetData[k] = '';
                        }
                    }
                });

                setFormData(resetData);
                if (!locks['integration']) setIntegrationType('none');

                Swal.fire({
                    title: 'บันทึกสำเร็จ!',
                    text: 'ข้อมูลถูกบันทึกลงในฐานข้อมูลเรียบร้อยแล้ว',
                    icon: 'success',
                    confirmButtonColor: '#059669',
                    timer: 2000
                });
            }
        });
    };

    // Dynamic Style Helpers for Cards
    const getCardStyle = (type: 'none' | 'park' | 'wildlife') => {
        switch (type) {
            case 'park':
                return 'bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400 ring-2 ring-emerald-400/80 shadow-emerald-100 dark:shadow-emerald-900/10';
            case 'wildlife':
                return 'bg-pink-50/20 dark:bg-pink-900/10 border-pink-400 ring-2 ring-pink-400/80 shadow-pink-100 dark:shadow-pink-900/10';
            default:
                return 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700';
        }
    };

    const getIntegrationCardStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'ring-2 ring-emerald-400 bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400';
            case 'wildlife':
                return 'ring-2 ring-pink-400 bg-pink-50/20 dark:bg-pink-900/10 border-pink-400';
            default:
                return 'border-slate-100 dark:border-slate-700';
        }
    };

    // --- Dynamic Footer Styles ---

    const getFooterContainerStyle = () => {
        switch (integrationType) {
            case 'park':
                // Green background
                return 'bg-emerald-600/95 dark:bg-emerald-800/95 border-emerald-500/50 shadow-emerald-900/20';
            case 'wildlife':
                // Pink background
                return 'bg-pink-600/95 dark:bg-pink-800/95 border-pink-500/50 shadow-pink-900/20';
            default:
                // Gray/Slate background (Default)
                return 'bg-slate-900/90 dark:bg-slate-950/90 border-slate-700/50 shadow-slate-900/20';
        }
    };

    const getFooterLabelColor = () => {
        switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white/80';
            default:
                return 'text-slate-300';
        }
    };

    const getFooterValueColor = () => {
         switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white';
            default:
                return 'text-emerald-400';
        }
    };

    const getSubmitButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                // White button on Green background
                return 'bg-white text-emerald-600 hover:bg-emerald-50 shadow-emerald-900/20';
            case 'wildlife':
                // White button on Pink background
                return 'bg-white text-pink-600 hover:bg-pink-50 shadow-pink-900/20';
            default:
                // Green button on Dark Gray background
                return 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-900/20 hover:shadow-emerald-900/40';
        }
    };

    const getClearButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'bg-emerald-700/50 text-emerald-50 hover:bg-emerald-700 border-emerald-500/50';
            case 'wildlife':
                return 'bg-pink-700/50 text-pink-50 hover:bg-pink-700 border-pink-500/50';
            default:
                return 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-slate-700';
        }
    };

    return (
        <div className="max-w-[95vw] mx-auto px-4 py-8">
            <header className="text-center mb-10">
                <h1 className="text-4xl font-bold text-slate-800 dark:text-white mb-3 transition-colors">แบบฟอร์มบันทึกงบประมาณ</h1>
                <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">กรอกรายละเอียดโครงการและงบประมาณประจำปี</p>
            </header>

            <form onSubmit={handleSubmit} className="space-y-6">

                {/* Integration Card */}
                <div className={`bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border transition-all duration-300 ${getIntegrationCardStyle()}`}>
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-3 rounded-xl ${
                                integrationType === 'wildlife' 
                                ? 'bg-pink-100 dark:bg-pink-900/40 text-pink-600 dark:text-pink-400' 
                                : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400'
                            }`}>
                                <Briefcase size={28} />
                            </div>
                            <div>
                                <h2 className="text-xl font-semibold text-slate-800 dark:text-white">สถานะบูรณาการ</h2>
                                <p className="text-base text-slate-500 dark:text-slate-400">ระบุประเภทหน่วยงานและการบูรณาการ</p>
                            </div>
                        </div>
                        <div className="w-full md:w-1/2 lg:w-1/3">
                            <AutocompleteInput
                                id="integration"
                                label="ประเภทหน่วยงาน"
                                required
                                value={formData.integration || ''}
                                options={['ไม่เป็นหน่วยงานบูรณาการ', 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)', 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)']}
                                onChange={(val) => handleChange('integration', val)}
                                placeholder="เลือกสถานะบูรณาการ..."
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                    {/* Section 1: Agency & Location */}
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                            <div className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-xl">
                                <Building2 size={24} />
                            </div>
                            <h2 className="text-xl font-semibold text-slate-800 dark:text-white">ข้อมูลหน่วยงานและพื้นที่</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-6">
                            <AutocompleteInput
                                id="mainAgency"
                                label="หน่วยงานหลัก"
                                required
                                value={formData.mainAgency || ''}
                                options={dropdowns.mainAgency}
                                onChange={(val) => handleChange('mainAgency', val)}
                                locked={locks['mainAgency']}
                                onLockToggle={() => toggleLock('mainAgency')}
                            />
                            <AutocompleteInput
                                id="province"
                                label="จังหวัด"
                                required
                                value={formData.province || ''}
                                options={provinceOptions}
                                onChange={(val) => handleChange('province', val)}
                                locked={locks['province']}
                                onLockToggle={() => toggleLock('province')}
                            />
                            <AutocompleteInput
                                id="responsibleAgency"
                                label="หน่วยงานบูรณาการ"
                                value={formData.responsibleAgency || ''}
                                options={responsibleAgencyOptions}
                                onChange={(val) => handleChange('responsibleAgency', val)}
                                locked={locks['responsibleAgency']}
                                onLockToggle={() => toggleLock('responsibleAgency')}
                            />
                            <AutocompleteInput
                                id="integrationArea"
                                label="พื้นที่บูรณาการ"
                                value={formData.integrationArea || ''}
                                options={integrationAreaOptions}
                                onChange={(val) => handleChange('integrationArea', val)}
                                locked={locks['integrationArea']}
                                onLockToggle={() => toggleLock('integrationArea')}
                            />
                        </div>
                    </div>

                    {/* Section 2: Activity */}
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                         <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                            <div className="p-3 bg-purple-50 dark:bg-purple-900/40 text-purple-600 dark:text-purple-400 rounded-xl">
                                <FileText size={24} />
                            </div>
                            <h2 className="text-xl font-semibold text-slate-800 dark:text-white">รายละเอียดกิจกรรม</h2>
                        </div>

                        <div className="space-y-6">
                            <AutocompleteInput
                                id="activity"
                                label="กิจกรรม"
                                required
                                value={formData.activity || ''}
                                options={dropdowns.activity}
                                onChange={(val) => handleChange('activity', val)}
                                locked={locks['activity']}
                                onLockToggle={() => toggleLock('activity')}
                            />

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-2">เป้าหมาย</label>
                                    <input
                                        type="text"
                                        value={formData.target || ''}
                                        onChange={(e) => handleChange('target', e.target.value)}
                                        className="w-full px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all outline-none text-lg text-slate-800 dark:text-slate-100 placeholder-slate-400"
                                        placeholder="ระบุตัวเลขเป้าหมาย"
                                    />
                                </div>
                                <AutocompleteInput
                                    id="unit"
                                    label="หน่วยนับ"
                                    value={formData.unit || ''}
                                    options={dropdowns.unit}
                                    onChange={(val) => handleChange('unit', val)}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Section 3: Budget Details */}
                <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                    <div className="flex items-center gap-3 mb-8">
                        <div className="p-3 bg-emerald-50 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400 rounded-xl">
                            <Calculator size={28} />
                        </div>
                        <div>
                            <h2 className="text-2xl font-bold text-slate-800 dark:text-white">รายละเอียดงบประมาณ</h2>
                            <p className="text-slate-500 dark:text-slate-400 text-base">ระบุจำนวนเงินในแต่ละหมวดรายจ่าย (หน่วย: บาท)</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Left Col */}
                        <div className="space-y-6">
                            <div className="bg-blue-50/70 dark:bg-blue-900/20 p-6 rounded-2xl border border-blue-100 dark:border-blue-900/50 hover:border-blue-200 dark:hover:border-blue-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-blue-700 dark:text-blue-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-blue-500 rounded-full"></div>
                                    งบบุคลากร
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="เงินเดือนและค่าจ้างประจำ" val={formData.salaryPermanent} onChange={(v) => handleBudgetChange('salaryPermanent', v)} />
                                    <BudgetField label="ค่าตอบแทนพนักงานราชการ" val={formData.governmentCompensation} onChange={(v) => handleBudgetChange('governmentCompensation', v)} />
                                </div>
                            </div>
                            <div className="bg-emerald-50/70 dark:bg-emerald-900/20 p-6 rounded-2xl border border-emerald-100 dark:border-emerald-900/50 hover:border-emerald-200 dark:hover:border-emerald-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-emerald-700 dark:text-emerald-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-emerald-500 rounded-full"></div>
                                    งบดำเนินงาน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าตอบแทน ใช้สอย และวัสดุ" val={formData.compensationSupplies} onChange={(v) => handleBudgetChange('compensationSupplies', v)} />
                                    <BudgetField label="ค่าจ้างเหมาพนักงาน" val={formData.contractEmployees} onChange={(v) => handleBudgetChange('contractEmployees', v)} />
                                    <BudgetField label="ค่าสาธารณูปโภค" val={formData.utilities} onChange={(v) => handleBudgetChange('utilities', v)} />
                                </div>
                            </div>
                        </div>

                        {/* Right Col */}
                        <div className="space-y-6">
                            <div className="bg-amber-50/70 dark:bg-amber-900/20 p-6 rounded-2xl border border-amber-100 dark:border-amber-900/50 hover:border-amber-200 dark:hover:border-amber-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-amber-700 dark:text-amber-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-amber-500 rounded-full"></div>
                                    งบลงทุน
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="ค่าครุภัณฑ์" val={formData.equipment} onChange={(v) => handleBudgetChange('equipment', v)} />
                                    <BudgetField label="ค่าที่ดินและสิ่งก่อสร้าง" val={formData.landConstruction} onChange={(v) => handleBudgetChange('landConstruction', v)} />
                                </div>
                            </div>
                            <div className="bg-purple-50/70 dark:bg-purple-900/20 p-6 rounded-2xl border border-purple-100 dark:border-purple-900/50 hover:border-purple-200 dark:hover:border-purple-800 transition-colors shadow-sm">
                                <h3 className="text-xl font-semibold text-purple-700 dark:text-purple-300 mb-4 flex items-center gap-2">
                                    <div className="w-2 h-6 bg-purple-500 rounded-full"></div>
                                    งบอื่นๆ
                                </h3>
                                <div className="space-y-4">
                                    <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />
                                    <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Action Bar */}
                <div className="sticky bottom-4 z-20">
                     <div className={`backdrop-blur-md p-4 rounded-2xl shadow-2xl flex flex-col md:flex-row justify-between items-center gap-4 border transition-all duration-300 ${getFooterContainerStyle()}`}>
                        <div className="flex flex-col md:flex-row items-center gap-2 md:gap-6">
                            <div className={`text-base font-medium ${getFooterLabelColor()}`}>รวมงบประมาณสุทธิ</div>
                            <div className={`text-3xl font-bold ${getFooterValueColor()}`}>
                                {formatNumber(totalBudget)} <span className="text-xl font-normal opacity-80">บาท</span>
                            </div>
                        </div>

                        <div className="flex gap-3 w-full md:w-auto">
                            <button 
                                type="button" 
                                onClick={clearForm} 
                                className={`flex-1 md:flex-none px-8 py-3 rounded-xl font-semibold transition-all border flex items-center justify-center gap-2 text-base ${getClearButtonStyle()}`}
                            >
                                <RefreshCw size={20} /> ล้างค่า
                            </button>
                            <button 
                                type="submit" 
                                className={`flex-1 md:flex-none px-10 py-3 rounded-xl font-semibold transition-all shadow-lg transform hover:-translate-y-0.5 flex items-center justify-center gap-2 text-base ${getSubmitButtonStyle()}`}
                            >
                                <CheckCircle2 size={22} /> บันทึกข้อมูล
                            </button>
                        </div>
                    </div>
                </div>
            </form>
            <div className="h-8"></div>
        </div>
    );
};

const BudgetField = ({ label, val, onChange }: { label: string, val: number | undefined, onChange: (v: string) => void }) => (
    <div className="group">
        <label className="block text-base font-medium text-slate-600 dark:text-slate-300 mb-2 group-hover:text-slate-800 dark:group-hover:text-slate-100 transition-colors">{label}</label>
        <div className="relative">
            <input
                type="text"
                value={val ? formatNumber(val) : ''}
                onChange={(e) => onChange(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all text-right font-medium text-slate-800 dark:text-slate-100 placeholder-slate-300 text-lg"
                placeholder="0"
            />
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-base">฿</span>
        </div>
    </div>
);

export default HomeView;

export interface BudgetRecord {
    id: string;
    integration: string;
    mainAgency: string;
    province: string;
    responsibleAgency: string;
    integrationArea: string;
    activity: string;
    target: string;
    unit: string;
    salaryPermanent: number;
    governmentCompensation: number;
    compensationSupplies: number;
    contractEmployees: number;
    utilities: number;
    equipment: number;
    landConstruction: number;
    subsidies: number;
    otherExpenses: number;
    timestamp: string;
}

export interface AppSettings {
    gasUrl: string;
    sheetsId: string;
    dataSheetName: string;
    databaseSheetName: string;
}

export interface DropdownOptions {
    integration: string[];
    mainAgency: string[];
    responsibleAgency: string[];
    integrationArea: string[];
    province: string[];
    activity: string[];
    unit: string[];
}

// Helper to map Main Agency -> Province
export interface HierarchyData {
    mainAgency: string;
    province: string;
}

// Helper to map Main Agency -> Responsible Agency -> Integration Area
export interface ResponsibleAgencyData {
    mainAgency: string;
    responsibleAgency: string;
    integrationArea: string;
}

export interface CompareRecord {
    id: string;
    activity: string;
    referenceBudget: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';
import { Save, RefreshCw, Briefcase, MapPin, Calculator, Wallet, Building2, FileText, CheckCircle2 } from 'lucide-react';

const HomeView: React.FC = () => {
    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: 'ไม่เป็นหน่วยงานบูรณาการ',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    // integrationType state: 'none', 'park' (Green), 'wildlife' (Pink)
    const [integrationType, setIntegrationType] = useState<'none' | 'park' | 'wildlife'>('none');

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }

        // Handle Integration Type Logic
        if (key === 'integration') {
           if (value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') {
                setIntegrationType('park');
           } else if (value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') {
                setIntegrationType('wildlife');
           } else {
                setIntegrationType('none');
           }
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };
        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else if (k === 'integration') {
                    // @ts-ignore
                    newForm[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        // Reset integration type if integration field is cleared and not locked
        if (!locks['integration']) {
            setIntegrationType('none');
        } else {
             // Re-evaluate integration type from locked value
             if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') setIntegrationType('park');
             else if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') setIntegrationType('wildlife');
             else setIntegrationType('none');
        }

        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false,
            confirmButtonColor: '#10b981'
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire({
                title: 'ข้อมูลไม่ครบ',
                text: 'กรุณากรอกข้อมูลที่จำเป็น (*)',
                icon: 'warning',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        Swal.fire({
            title: 'ยืนยันการบันทึก?',
            html: `<div class="text-slate-600">ยอดรวมงบประมาณ</div><div class="text-3xl font-bold text-emerald-600 mt-2">${formatNumber(totalBudget)} บาท</div>`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: 'บันทึกข้อมูล',
            cancelButtonText: 'ตรวจสอบอีกครั้ง',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        }).then((result) => {
            if (result.isConfirmed) {
                const newRecord: BudgetRecord = {
                    ...formData as BudgetRecord,
                    id: Date.now().toString(),
                    timestamp: getCurrentTimestamp()
                };
                dataService.addRecord(newRecord);

                // Keep locked fields, clear others
                const resetData = { ...formData };
                Object.keys(resetData).forEach(key => {
                    const k = key as keyof BudgetRecord;
                    if (!locks[k]) {
                        if (typeof resetData[k] === 'number') {
                            // @ts-ignore
                            resetData[k] = 0;
                        } else if (k === 'integration') {
                            // @ts-ignore
                            resetData[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                        } else {
                            // @ts-ignore
                            resetData[k] = '';
                        }
                    }
                });

                setFormData(resetData);
                if (!locks['integration']) setIntegrationType('none');

                Swal.fire({
                    title: 'บันทึกสำเร็จ!',
                    text: 'ข้อมูลถูกบันทึกลงในฐานข้อมูลเรียบร้อยแล้ว',
                    icon: 'success',
                    confirmButtonColor: '#059669',
                    timer: 2000
                });
            }
        });
    };

    // Dynamic Style Helpers for Cards
    const getCardStyle = (type: 'none' | 'park' | 'wildlife') => {
        switch (type) {
            case 'park':
                return 'bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400 ring-2 ring-emerald-400/80 shadow-emerald-100 dark:shadow-emerald-900/10';
            case 'wildlife':
                return 'bg-pink-50/20 dark:bg-pink-900/10 border-pink-400 ring-2 ring-pink-400/80 shadow-pink-100 dark:shadow-pink-900/10';
            default:
                return 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700';
        }
    };

    const getIntegrationCardStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'ring-2 ring-emerald-400 bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400';
            case 'wildlife':
                return 'ring-2 ring-pink-400 bg-pink-50/20 dark:bg-pink-900/10 border-pink-400';
            default:
                return 'border-slate-100 dark:border-slate-700';
        }
    };

    // --- Dynamic Footer Styles ---

    const getFooterContainerStyle = () => {
        switch (integrationType) {
            case 'park':
                // Green background
                return 'bg-emerald-600/95 dark:bg-emerald-800/95 border-emerald-500/50 shadow-emerald-900/20';
            case 'wildlife':
                // Pink background
                return 'bg-pink-600/95 dark:bg-pink-800/95 border-pink-500/50 shadow-pink-900/20';
            default:
                // Gray/Slate background (Default)
                return 'bg-slate-900/90 dark:bg-slate-950/90 border-slate-700/50 shadow-slate-900/20';
        }
    };

    const getFooterLabelColor = () => {
        switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white/80';
            default:
                return 'text-slate-300';
        }
    };

    const getFooterValueColor = () => {
         switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white';
            default:
                return 'text-emerald-400';
        }
    };

    const getSubmitButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                // White button on Green background
                return 'bg-white text-emerald-600 hover:bg-emerald-50 shadow-emerald-900/20';
            case 'wildlife':
                // White button on Pink background
                return 'bg-white text-pink-600 hover:bg-pink-50 shadow-pink-900/20';
            default:
                // Green button on Dark Gray background
                return 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-900/20 hover:shadow-emerald-900/40';
        }
    };

    const getClearButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'bg-emerald-700/50 text-emerald-50 hover:bg-emerald-700 border-emerald-500/50';
            case 'wildlife':
                return 'bg-pink-700/50 text-pink-50 hover:bg-pink-700 border-pink-500/50';
            default:
                return 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-slate-700';
        }
    };

    return (
        <div className="max-w-[95vw] mx-auto px-4 py-8">
            <header className="text-center mb-10">
                <h1 className="text-4xl font-bold text-slate-800 dark:text-white mb-3 transition-colors">แบบฟอร์มบันทึกงบประมาณ</h1>
                <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">กรอกรายละเอียดโครงการและงบประมาณประจำปี</p>
            </header>

            <form onSubmit={handleSubmit} className="space-y-6">

                {/* Integration Card */}
                <div className={`bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border transition-all duration-300 ${getIntegrationCardStyle()}`}>
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-3 rounded-xl ${
                                integrationType === 'wildlife' 
                                ? 'bg-pink-100 dark:bg-pink-900/40 text-pink-600 dark:text-pink-400' 
                                : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400'
                            }`}>
                                <Briefcase size={28} />
                            </div>
                            <div>
                                <h2 className="text-xl font-semibold text-slate-800 dark:text-white">สถานะบูรณาการ</h2>
                                <p className="text-base text-slate-500 dark:text-slate-400">ระบุประเภทหน่วยงานและการบูรณาการ</p>
                            </div>
                        </div>
                        <div className="w-full md:w-1/2 lg:w-1/3">
                            <AutocompleteInput
                                id="integration"
                                label="ประเภทหน่วยงาน"
                                required
                                value={formData.integration || ''}
                                options={dropdowns.integration}
                                onChange={(val) => handleChange('integration', val)}
                                placeholder="เลือกสถานะบูรณาการ..."
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                    {/* Section 1: Agency & Location */}
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                            <div className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 rounded-xl">
                                <Building2 size={24} />
                            </div>
                            <h2 className="text-xl font-semibold text-slate-800 dark:text-white">ข้อมูลหน่วยงานและพื้นที่</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-6">
                            <AutocompleteInput
                                id="mainAgency"
                                label="หน่วยงานหลัก"
                                required
                                value={formData.mainAgency || ''}
                                options={dropdowns.mainAgency}
                                onChange={(val) => handleChange('mainAgency', val)}
                                locked={locks['mainAgency']}
                                onLockToggle={() => toggleLock('mainAgency')}
                            />
                            <AutocompleteInput
                                id="province"
                                label="จังหวัด"
                                required
                                value={formData.province || ''}
                                options={provinceOptions}
                                onChange={(val) => handleChange('province', val)}
                                locked={locks['province']}
                                onLockToggle={() => toggleLock('province')}
                            />
                            <AutocompleteInput
                                id="responsibleAgency"
                                label="หน่วยงานบูรณาการ"
                                value={formData.responsibleAgency || ''}
                                options={responsibleAgencyOptions}
                                onChange={(val) => handleChange('responsibleAgency', val)}
                                locked={locks['responsibleAgency']}
