payload.text:
**จำเป็นต้องแก้ไขครับ**

เนื่องจากปัจจุบันเว็บแอพทำงานอยู่บน "ข้อมูลจำลอง" (Mock Data) ที่ฝังอยู่ในโค้ด หากต้องการให้ดึงข้อมูลจริงๆ จาก Google Sheets ตามที่คุณกำหนด (Integration, Hierarchy, ResponsibleAgency ฯลฯ) **คุณจะต้องสร้างและ Deploy Google Apps Script (GAS)** เพื่อทำหน้าที่เป็นตัวกลาง (API) ส่งข้อมูลจาก Sheets มายังเว็บครับ

นี่คือโค้ด Google Apps Script ที่เขียนขึ้นตามโครงสร้างข้อมูลที่คุณต้องการครับ

### 1. โค้ดสำหรับ Google Apps Script (`Code.gs`)

ให้นำโค้ดนี้ไปวางใน Google Apps Script Editor ของ Google Sheet ที่คุณใช้งานอยู่

```javascript
function doGet(e) {
  const op = e.parameter.op;

  // กรณีเรียกดูข้อมูล Dropdown ทั้งหมด
  if (op === 'getDropdowns' || !op) {
    return getDropdownData();
  }
}

function doPost(e) {
  // รองรับการบันทึกข้อมูล (ในอนาคต)
  return ContentService.createTextOutput(JSON.stringify({status: 'success'}))
    .setMimeType(ContentService.MimeType.JSON);
}

function getDropdownData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const data = {};

  // 1. บูรณาการ (Sheet: Integration, Col A)
  const shIntegration = ss.getSheetByName('Integration');
  if (shIntegration && shIntegration.getLastRow() > 1) {
    data.integration = shIntegration.getRange(2, 1, shIntegration.getLastRow() - 1, 1)
      .getValues().flat().filter(String);
  } else {
    data.integration = [];
  }

  // 2. หน่วยงานและจังหวัด (Sheet: Hierarchy, Col A=Main, B=Province)
  const shHierarchy = ss.getSheetByName('Hierarchy');
  if (shHierarchy && shHierarchy.getLastRow() > 1) {
    const raw = shHierarchy.getRange(2, 1, shHierarchy.getLastRow() - 1, 2).getValues();
    data.hierarchy = raw.map(r => ({
      mainAgency: r[0],
      province: r[1]
    })).filter(r => r.mainAgency);
  } else {
    data.hierarchy = [];
  }

  // 3. หน่วยงานบูรณาการและพื้นที่ (Sheet: ResponsibleAgency, Col A=Main, B=Responsible, C=Area)
  // *สมมติว่า Col A ใช้เชื่อมกับหน่วยงานหลักเพื่อการกรอง
  const shResp = ss.getSheetByName('ResponsibleAgency');
  if (shResp && shResp.getLastRow() > 1) {
    const raw = shResp.getRange(2, 1, shResp.getLastRow() - 1, 3).getValues();
    data.responsible = raw.map(r => ({
      mainAgency: r[0],
      responsibleAgency: r[1],
      integrationArea: r[2]
    })).filter(r => r.responsibleAgency);
  } else {
    data.responsible = [];
  }

  // 4. กิจกรรม (Sheet: Compare, Col B=Activity)
  // *ผมดึง Col C มาด้วยเผื่อเป็น Budget อ้างอิงสำหรับการเปรียบเทียบ
  const shCompare = ss.getSheetByName('Compare');
  if (shCompare && shCompare.getLastRow() > 1) {
    const raw = shCompare.getRange(2, 2, shCompare.getLastRow() - 1, 2).getValues();
    data.compare = raw.map((r, i) => ({
      id: (i + 1).toString(),
      activity: r[0],
      referenceBudget: Number(r[1]) || 0
    })).filter(r => r.activity);
  } else {
    data.compare = [];
  }

  // 5. หน่วยนับ (Sheet: Unit, Col A)
  const shUnit = ss.getSheetByName('Unit');
  if (shUnit && shUnit.getLastRow() > 1) {
    data.unit = shUnit.getRange(2, 1, shUnit.getLastRow() - 1, 1)
      .getValues().flat().filter(String);
  } else {
    data.unit = [];
  }

  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
```

### 2. วิธีการติดตั้ง (Deployment)
1.  ไปที่ **Extensions** > **Apps Script**
2.  วางโค้ดด้านบน
3.  กด **Deploy** > **New deployment**
4.  เลือก type เป็น **Web app**
5.  Execute as: **Me** (ตัวคุณเอง)
6.  Who has access: **Anyone** (ทุกคน) **สำคัญมาก** เพื่อให้เว็บเรียกข้อมูลได้โดยไม่ต้องล็อกอินซ้ำซ้อน
