                return null;
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">จัดการข้อมูลตัวเลือก</h2>
                    <p className="text-slate-500 dark:text-slate-400 transition-colors">จัดการข้อมูล Dropdown ในระบบและซิงค์ข้อมูลจาก Google Sheets</p>
                </div>
                <button 
                    onClick={handleRefresh}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-medium text-sm disabled:opacity-70 disabled:cursor-not-allowed`}
                >
                    <RefreshCw size={16} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูลจาก Sheets'}
                </button>
            </div>

            <div className="flex flex-col lg:flex-row gap-6">
                {/* Sidebar Navigation */}
                <div className="w-full lg:w-64 flex-shrink-0">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-2 overflow-hidden sticky top-24">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-all duration-200 mb-1 last:mb-0 ${
                                    activeTab === tab.id 
                                    ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 font-semibold shadow-sm' 
                                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700/50 hover:text-emerald-600 dark:hover:text-emerald-400'
                                }`}
                            >
                                {tab.icon}
                                <span>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Area */}
                <div className="flex-1 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-6 min-h-[500px]">
                    <div className="flex items-center gap-2 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                        <FileSpreadsheet className="text-emerald-500" />
                        <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200">
                            ข้อมูล: <span className="text-emerald-600 dark:text-emerald-400">{tabs.find(t => t.id === activeTab)?.label}</span>
                        </h3>
                    </div>
                    {renderContent()}
                </div>
            </div>
        </div>
    );
};

interface TableProps {
    headers: string[];
    data: {
        columns: (string | number)[];
        onEdit?: () => void;
        onDelete?: () => void;
    }[];
    hasActions?: boolean;
}

const Table = ({ headers, data, hasActions = false }: TableProps) => (
    <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-700">
        <table className="w-full text-left border-collapse">
            <thead>
                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                    {headers.map((h, i) => (
                        <th key={i} className="px-6 py-4 text-sm font-semibold text-slate-600 dark:text-slate-300 whitespace-nowrap">
                            {h}
                        </th>
                    ))}
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700 bg-white dark:bg-slate-800">
                {data.length > 0 ? data.map((row, i) => (
                    <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                        {row.columns.map((cell, j) => (
                            <td key={j} className="px-6 py-3 text-slate-700 dark:text-slate-300 text-sm">
                                {cell}
                            </td>
                        ))}
                        {hasActions && (
                            <td className="px-6 py-3 text-right w-32">
                                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={row.onEdit} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="แก้ไข">
                                        <Edit2 size={16} />
                                    </button>
                                    <button onClick={row.onDelete} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="ลบ">
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </td>
                        )}
                    </tr>
                )) : (
                    <tr>
                        <td colSpan={headers.length} className="px-6 py-8 text-center text-slate-400">
                            ไม่พบข้อมูล
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
    </div>
);

export default ManageView;

import React, { useState, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { Layers, Map, Users, Target, LayoutGrid, FileSpreadsheet, RefreshCw, Building2, MapPin, Plus, Edit2, Trash2 } from 'lucide-react';
import Swal from 'sweetalert2';

type Tab = 'integration' | 'mainAgency' | 'province' | 'responsible' | 'activity' | 'unit';

const ManageView: React.FC = () => {
    const [activeTab, setActiveTab] = useState<Tab>('mainAgency');
    const [isLoading, setIsLoading] = useState(false);

    // Use state to force re-render when data updates
    const [refreshTrigger, setRefreshTrigger] = useState(0);

    // Specific state for Province/Responsible tab filtering
    const [selectedMainAgency, setSelectedMainAgency] = useState<string>('');

    useEffect(() => {
        setSelectedMainAgency('');
    }, [activeTab]);

    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();
    const compareData = dataService.getCompareData();

    const tabs: { id: Tab; label: string; sheet: string; icon: React.ReactNode }[] = [
        { id: 'mainAgency', label: 'หน่วยงานหลัก', sheet: 'Hierarchy (Col A)', icon: <Building2 size={18} /> },
        { id: 'province', label: 'จังหวัด', sheet: 'Hierarchy (Col B)', icon: <MapPin size={18} /> },
        { id: 'responsible', label: 'หน่วยงานบูรณาการ', sheet: 'ResponsibleAgency', icon: <Users size={18} /> },
        { id: 'integration', label: 'บูรณาการ', sheet: 'Integration', icon: <Layers size={18} /> },
        { id: 'activity', label: 'กิจกรรม', sheet: 'Compare', icon: <Target size={18} /> },
        { id: 'unit', label: 'หน่วยนับ', sheet: 'Unit', icon: <LayoutGrid size={18} /> },
    ];

    const handleRefresh = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1); 
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลจาก Google Sheets เรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: 'ไม่สามารถดึงข้อมูลจาก Google Sheets ได้ กรุณาตรวจสอบการตั้งค่า',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    // --- CRUD Handlers for Main Agency ---
    const handleAddMainAgency = async () => {
        const { value: name } = await Swal.fire({
            title: 'เพิ่มหน่วยงานหลัก',
            input: 'text',
            inputLabel: 'ชื่อหน่วยงาน',
            inputPlaceholder: 'กรอกชื่อหน่วยงาน...',
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name) {
            dataService.addMainAgency(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มหน่วยงานเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditMainAgency = async (oldName: string) => {
        const { value: name } = await Swal.fire({
            title: 'แก้ไขชื่อหน่วยงาน',
            input: 'text',
            inputLabel: 'ชื่อหน่วยงาน',
            inputValue: oldName,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name && name !== oldName) {
            dataService.updateMainAgency(oldName, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteMainAgency = async (name: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `คุณต้องการลบ "${name}" และข้อมูลที่เกี่ยวข้องทั้งหมดหรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });

        if (result.isConfirmed) {
            dataService.deleteMainAgency(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบเรียบร้อยแล้ว', 'success');
        }
    };

    // --- CRUD Handlers for Province ---
    const handleAddProvince = async () => {
        if (!selectedMainAgency) return;
        const { value: name } = await Swal.fire({
            title: `เพิ่มจังหวัดสำหรับ ${selectedMainAgency}`,
            input: 'text',
            inputLabel: 'ชื่อจังหวัด',
            inputPlaceholder: 'กรอกชื่อจังหวัด...',
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name) {
            dataService.addProvince(selectedMainAgency, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มจังหวัดเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditProvince = async (oldName: string) => {
        if (!selectedMainAgency) return;
        const { value: name } = await Swal.fire({
            title: 'แก้ไขชื่อจังหวัด',
            input: 'text',
            inputValue: oldName,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name && name !== oldName) {
            dataService.updateProvince(selectedMainAgency, oldName, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteProvince = async (name: string) => {
        if (!selectedMainAgency) return;
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ต้องการลบจังหวัด "${name}" จาก "${selectedMainAgency}" หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });

        if (result.isConfirmed) {
            dataService.deleteProvince(selectedMainAgency, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบเรียบร้อยแล้ว', 'success');
        }
    };

    // --- CRUD Handlers for Responsible Agency ---
    const handleAddResponsible = async () => {
        if (!selectedMainAgency) return;

        const { value: formValues } = await Swal.fire({
            title: 'เพิ่มหน่วยงานบูรณาการ',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">หน่วยงานบูรณาการ</div>' +
                '<input id="swal-input1" class="swal2-input" placeholder="ชื่อหน่วยงานบูรณาการ" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">' +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">พื้นที่บูรณาการ</div>' +
                '<input id="swal-input2" class="swal2-input" placeholder="พื้นที่บูรณาการ (ถ้ามี)" style="margin: 0; width: 100%; box-sizing: border-box;">',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                return [
                    (document.getElementById('swal-input1') as HTMLInputElement).value,
                    (document.getElementById('swal-input2') as HTMLInputElement).value
                ]
            }
        });

        if (formValues) {
            const [resp, area] = formValues;
            if (resp) {
                dataService.addResponsibleAgency(selectedMainAgency, resp, area);
                setRefreshTrigger(prev => prev + 1);
                Swal.fire('สำเร็จ', 'เพิ่มข้อมูลเรียบร้อยแล้ว', 'success');
            }
        }
    };

    const handleEditResponsible = async (oldResp: string, oldArea: string) => {
        if (!selectedMainAgency) return;

        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูล',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">หน่วยงานบูรณาการ</div>' +
                `<input id="swal-input1" class="swal2-input" placeholder="ชื่อหน่วยงานบูรณาการ" value="${oldResp}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">พื้นที่บูรณาการ</div>' +
                `<input id="swal-input2" class="swal2-input" placeholder="พื้นที่บูรณาการ" value="${oldArea}" style="margin: 0; width: 100%; box-sizing: border-box;">`,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                return [
                    (document.getElementById('swal-input1') as HTMLInputElement).value,
                    (document.getElementById('swal-input2') as HTMLInputElement).value
                ]
            }
        });

        if (formValues) {
            const [newResp, newArea] = formValues;
            if (newResp) {
                dataService.updateResponsibleAgency(selectedMainAgency, oldResp, oldArea, newResp, newArea);
                setRefreshTrigger(prev => prev + 1);
                Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
            }
        }
    };

    const handleDeleteResponsible = async (resp: string, area: string) => {
        if (!selectedMainAgency) return;
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ต้องการลบข้อมูล "${resp}" ออกจาก "${selectedMainAgency}" หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });

        if (result.isConfirmed) {
            dataService.deleteResponsibleAgency(selectedMainAgency, resp, area);
