                            >
                                <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                {dropdowns.mainAgency.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>

                        {selectedMainAgency && (
                             <div className="space-y-4">
                                <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                                    <h4 className="text-lg font-semibold text-slate-800 dark:text-white">รายชื่อจังหวัด ({provinces.length})</h4>
                                    <button onClick={handleAddProvince} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
