// Simplified Data Store Simulation (in a real app, use Redux or Context)
export class DataService {
    private records: BudgetRecord[] = [];
    private dropdowns: DropdownOptions = INITIAL_DROPDOWN_DATA;
    private hierarchy: HierarchyData[] = INITIAL_HIERARCHY;
    private respData: ResponsibleAgencyData[] = INITIAL_RESP_DATA;
    private compareData: CompareRecord[] = INITIAL_COMPARE_DATA;

    constructor() {
        this.loadFromCache();
    }

    private loadFromCache() {
        const cached = localStorage.getItem(CACHE_KEY);
        if (cached) {
            const parsed = JSON.parse(cached);
            this.records = parsed.records || INITIAL_BUDGET_RECORDS;
            this.dropdowns = parsed.dropdowns || INITIAL_DROPDOWN_DATA;
            this.hierarchy = parsed.hierarchy || INITIAL_HIERARCHY;
            this.respData = parsed.respData || INITIAL_RESP_DATA;
            this.compareData = parsed.compareData || INITIAL_COMPARE_DATA;
        } else {
            this.records = INITIAL_BUDGET_RECORDS;
        }
    }

    private saveToCache() {
        localStorage.setItem(CACHE_KEY, JSON.stringify({
            records: this.records,
            dropdowns: this.dropdowns,
            hierarchy: this.hierarchy,
            respData: this.respData,
            compareData: this.compareData
        }));
    }

    getRecords(): BudgetRecord[] {
        return this.records;
    }

    addRecord(record: BudgetRecord) {
        this.records.push(record);
        this.saveToCache();
    }

    updateRecord(updatedRecord: BudgetRecord) {
        const index = this.records.findIndex(r => r.id === updatedRecord.id);
        if (index !== -1) {
            this.records[index] = updatedRecord;
            this.saveToCache();
        }
    }

    deleteRecord(id: string) {
        this.records = this.records.filter(r => r.id !== id);
        this.saveToCache();
    }

    getDropdowns(): DropdownOptions {
        return this.dropdowns;
    }

    getHierarchy(): HierarchyData[] {
        return this.hierarchy;
    }

    getResponsibleData(): ResponsibleAgencyData[] {
        return this.respData;
    }

    getCompareData(): CompareRecord[] {
        return this.compareData;
    }

    // --- Main Agency CRUD ---
    addMainAgency(name: string) {
        if (!this.dropdowns.mainAgency.includes(name)) {
            this.dropdowns.mainAgency = [...this.dropdowns.mainAgency, name];
            this.saveToCache();
        }
    }

    updateMainAgency(oldName: string, newName: string) {
        // Update dropdown list
        this.dropdowns.mainAgency = this.dropdowns.mainAgency.map(m => m === oldName ? newName : m);

        // Update hierarchy
        this.hierarchy = this.hierarchy.map(h => h.mainAgency === oldName ? { ...h, mainAgency: newName } : h);

        // Update Responsible Data references
        this.respData = this.respData.map(r => r.mainAgency === oldName ? { ...r, mainAgency: newName } : r);

        this.saveToCache();
    }

    deleteMainAgency(name: string) {
        this.dropdowns.mainAgency = this.dropdowns.mainAgency.filter(m => m !== name);
        this.hierarchy = this.hierarchy.filter(h => h.mainAgency !== name);
        this.respData = this.respData.filter(r => r.mainAgency !== name);
        this.saveToCache();
    }

    // --- Province CRUD ---
    addProvince(mainAgency: string, province: string) {
        const exists = this.hierarchy.some(h => h.mainAgency === mainAgency && h.province === province);
        if (!exists) {
            this.hierarchy.push({ mainAgency, province });
            // Re-derive global province list
            const allProvinces = new Set(this.hierarchy.map(h => h.province));
            this.dropdowns.province = Array.from(allProvinces);
            this.saveToCache();
        }
    }

    updateProvince(mainAgency: string, oldProvince: string, newProvince: string) {
        this.hierarchy = this.hierarchy.map(h => 
            (h.mainAgency === mainAgency && h.province === oldProvince) 
            ? { ...h, province: newProvince } 
            : h
        );

        // Re-derive global province list
        const allProvinces = new Set(this.hierarchy.map(h => h.province));
        this.dropdowns.province = Array.from(allProvinces);

        this.saveToCache();
    }

    deleteProvince(mainAgency: string, province: string) {
        this.hierarchy = this.hierarchy.filter(h => !(h.mainAgency === mainAgency && h.province === province));

        // Re-derive global province list
        const allProvinces = new Set(this.hierarchy.map(h => h.province));
        this.dropdowns.province = Array.from(allProvinces);

        this.saveToCache();
    }

    // --- Responsible Agency CRUD ---
    addResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        const exists = this.respData.some(r =>
            r.mainAgency === mainAgency &&
            r.responsibleAgency === responsibleAgency &&
            r.integrationArea === integrationArea
        );
        if (!exists) {
            this.respData.push({ mainAgency, responsibleAgency, integrationArea });

            // Re-derive global lists
            this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
            this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));

            this.saveToCache();
        }
    }

    updateResponsibleAgency(mainAgency: string, oldResp: string, oldArea: string, newResp: string, newArea: string) {
        const index = this.respData.findIndex(r =>
            r.mainAgency === mainAgency &&
            r.responsibleAgency === oldResp &&
            r.integrationArea === oldArea
        );

        if (index !== -1) {
            this.respData[index] = { mainAgency, responsibleAgency: newResp, integrationArea: newArea };

            // Re-derive global lists
            this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
            this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));

            this.saveToCache();
        }
    }

    deleteResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData = this.respData.filter(r =>
            !(r.mainAgency === mainAgency && r.responsibleAgency === responsibleAgency && r.integrationArea === integrationArea)
        );

        // Re-derive global lists
        this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
        this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));

        this.saveToCache();
    }

    // --- Activity CRUD ---
    addActivity(name: string) {
        if (!this.compareData.some(c => c.activity === name)) {
            const newId = Date.now().toString() + Math.random().toString(36).substr(2, 9);
            this.compareData.push({ id: newId, activity: name, referenceBudget: 0 });
            this.dropdowns.activity = this.compareData.map(c => c.activity);
            this.saveToCache();
        }
    }

    updateActivity(oldName: string, newName: string) {
        const record = this.compareData.find(c => c.activity === oldName);
        if (record) {
            record.activity = newName;
            this.dropdowns.activity = this.compareData.map(c => c.activity);
            this.saveToCache();
        }
    }

    deleteActivity(name: string) {
        this.compareData = this.compareData.filter(c => c.activity !== name);
        this.dropdowns.activity = this.compareData.map(c => c.activity);
        this.saveToCache();
    }

    // --- Unit CRUD ---
    addUnit(name: string) {
        if (!this.dropdowns.unit.includes(name)) {
            this.dropdowns.unit = [...this.dropdowns.unit, name];
            this.saveToCache();
        }
    }

    updateUnit(oldName: string, newName: string) {
        this.dropdowns.unit = this.dropdowns.unit.map(u => u === oldName ? newName : u);
        this.saveToCache();
    }

    deleteUnit(name: string) {
        this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name);
        this.saveToCache();
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');
        // Implementation for syncing would go here
        return Promise.resolve();
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        // Mock connection test
        return Promise.resolve(true);
    }
}

