1.  **แก้ไขฝั่ง Google Apps Script (GAS):** เพื่อให้อ่านข้อมูลจาก Sheet และส่งกลับมาเป็น JSON ตามรูปแบบที่เว็บต้องการ
2.  **แก้ไขฝั่งเว็บ (`dataService.ts`):** เพื่อให้เลิกใช้ข้อมูลจำลอง (Mock Data) และเปลี่ยนไปดึงข้อมูลผ่าน API จาก GAS แทน

นี่คือขั้นตอนและโค้ดที่ต้องใช้ครับ:

### ส่วนที่ 1: Google Apps Script (Code.gs)
คุณต้องนำโค้ดนี้ไปวางใน Google Apps Script Editor ของไฟล์ Google Sheet ของคุณ และกด **Deploy as Web App** (ตั้งค่า Execute as: Me, Who has access: Anyone)

```javascript
function doGet(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var output = {};

  // 1. อ่านข้อมูล Hierarchy (หน่วยงานหลัก -> จังหวัด)
  var hierarchySheet = ss.getSheetByName('Hierarchy');
  var hierarchyData = [];
  if (hierarchySheet) {
    var rows = hierarchySheet.getDataRange().getValues();
    // สมมติแถว 1 เป็น Header, เริ่มอ่านแถว 2
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0]) {
        hierarchyData.push({
          mainAgency: rows[i][0].toString(),
          province: rows[i][1].toString()
        });
      }
    }
  }

  // 2. อ่านข้อมูล ResponsibleAgency (หน่วยงานบูรณาการ)
  var respSheet = ss.getSheetByName('ResponsibleAgency');
  var respData = [];
  if (respSheet) {
    var rows = respSheet.getDataRange().getValues();
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0]) {
        respData.push({
          mainAgency: rows[i][0].toString(),
          responsibleAgency: rows[i][1].toString(),
          integrationArea: rows[i][2].toString()
        });
      }
    }
  }

  // 3. อ่านข้อมูล Compare (กิจกรรม & งบอ้างอิง)
  var compareSheet = ss.getSheetByName('Compare');
  var compareData = [];
  if (compareSheet) {
    var rows = compareSheet.getDataRange().getValues();
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][1]) { // เช็ค Column B (Activity Name)
        compareData.push({
          id: (i).toString(), // ใช้เลขแถวเป็น ID ชั่วคราว
          activity: rows[i][1].toString(),
          referenceBudget: Number(rows[i][2]) || 0
        });
      }
    }
  }

  // 4. อ่านข้อมูล Unit (หน่วยนับ)
  var unitSheet = ss.getSheetByName('Unit');
  var unitData = [];
  if (unitSheet) {
    var rows = unitSheet.getDataRange().getValues();
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0]) unitData.push(rows[i][0].toString());
    }
  }

  // 5. อ่านข้อมูล Integration (ประเภทบูรณาการ)
  var intSheet = ss.getSheetByName('Integration');
  var intData = [];
  if (intSheet) {
    var rows = intSheet.getDataRange().getValues();
    for (var i = 1; i < rows.length; i++) {
      if (rows[i][0]) intData.push(rows[i][0].toString());
    }
  }

  // สร้าง Dropdowns Object
  var dropdowns = {
    integration: intData.length > 0 ? intData : ['ไม่เป็นหน่วยงานบูรณาการ'],
    mainAgency: [...new Set(hierarchyData.map(h => h.mainAgency))],
    province: [...new Set(hierarchyData.map(h => h.province))],
    responsibleAgency: [...new Set(respData.map(r => r.responsibleAgency))],
    integrationArea: [...new Set(respData.map(r => r.integrationArea))],
    activity: compareData.map(c => c.activity),
    unit: unitData
  };

  // ส่งค่ากลับเป็น JSON
  var result = {
    status: 'success',
    data: {
      dropdowns: dropdowns,
      hierarchy: hierarchyData,
      respData: respData,
      compareData: compareData
    }
  };

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}
```

