import { BudgetRecord, AppSettings, DropdownOptions, HierarchyData, ResponsibleAgencyData, CompareRecord } from '../types';
import { INITIAL_BUDGET_RECORDS, INITIAL_DROPDOWN_DATA, INITIAL_HIERARCHY, INITIAL_RESP_DATA, INITIAL_COMPARE_DATA } from './mockData';

const SETTINGS_KEY = 'budgetPlanSettings';
const CACHE_KEY = 'budgetPlanCache';

export const getSettings = (): AppSettings => {
    const stored = localStorage.getItem(SETTINGS_KEY);
    return stored ? JSON.parse(stored) : {
        gasUrl: 'https://script.google.com/macros/s/AKfycbwdmg-DcHes5WGTWihXPIuREB5JJAxHox8ROAAiFDU5hCnMAvXbf2X5j4eh3FYu2B4v/exec',
        sheetsId: '1rwyAt0TsSSpZ7uqrAHq6C39AYvGogK0rj1b7QI8efkM',
