const CompareView: React.FC = () => {
    const [refreshTrigger, setRefreshTrigger] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Get Data
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';
        if (actual === 0 && target.referenceBudget > 0) status = 'nodata';
        else if (actual === 0 && target.referenceBudget === 0) status = 'nodata'; // Or handle as match/empty
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
