                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                        >
                            <option value="">ทุกจังหวัด</option>
                            {Array.from(new Set(records.map(r => r.province))).filter(Boolean).map((p: string) => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors flex flex-col h-[70vh]">
                <div className="p-2 bg-slate-50 dark:bg-slate-900/50 border-b border-slate-100 dark:border-slate-700 text-xs text-slate-400 flex items-center gap-1">
                    <ArrowRightLeft size={12} />
                    <span>สามารถลากเส้นแบ่งคอลัมน์เพื่อปรับความกว้างได้</span>
                </div>
                <div className="overflow-auto custom-scrollbar flex-1">
                    <table className="min-w-max border-collapse">
                        <thead className="bg-slate-50 dark:bg-slate-900/50 sticky top-0 z-10 shadow-sm">
                            <tr>
                                <Th width="180px">บูรณาการ (B)</Th>
                                <Th width="150px">หน่วยงานหลัก (C)</Th>
                                <Th width="120px">จังหวัด (D)</Th>
                                <Th width="150px">หน่วยงานบูรณาการ (E)</Th>
                                <Th width="150px">พื้นที่บูรณาการ (F)</Th>
                                <Th width="200px">กิจกรรม (G)</Th>
                                <Th width="100px" align="center">เป้าหมาย (H)</Th>
                                <Th width="100px" align="center">หน่วยนับ (I)</Th>
                                <Th width="140px" align="right">เงินเดือน/ค่าจ้าง (J)</Th>
                                <Th width="140px" align="right">ค่าตอบแทนพนง. (K)</Th>
                                <Th width="140px" align="right">ตอบแทน/ใช้สอย (L)</Th>
                                <Th width="140px" align="right">ค่าจ้างเหมา (M)</Th>
                                <Th width="140px" align="right">ค่าสาธารณูปโภค (N)</Th>
                                <Th width="140px" align="right">ค่าครุภัณฑ์ (O)</Th>
                                <Th width="140px" align="right">ที่ดิน/สิ่งก่อสร้าง (P)</Th>
                                <Th width="140px" align="right">เงินอุดหนุน (Q)</Th>
                                <Th width="140px" align="right">รายจ่ายอื่น (R)</Th>
                                <Th width="160px">วันที่บันทึก (S)</Th>
                            </tr>
                        </thead>
                        <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-100 dark:divide-slate-700">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => (
                                <tr key={r.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-700/50 transition-colors">
                                    <DataCell text={r.integration} />
                                    <DataCell text={r.mainAgency} />
                                    <DataCell text={r.province} />
                                    <DataCell text={r.responsibleAgency} />
                                    <DataCell text={r.integrationArea} />
                                    <DataCell text={r.activity} />
                                    <DataCell text={r.target} align="center" />
                                    <DataCell text={r.unit} align="center" />
                                    <DataCell text={formatNumber(r.salaryPermanent)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.governmentCompensation)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.compensationSupplies)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.contractEmployees)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.utilities)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.equipment)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.landConstruction)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.subsidies)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.otherExpenses)} align="right" isNumber />
                                    <DataCell text={r.timestamp} />
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan={18} className="px-6 py-12 text-center text-slate-400">
                                        <div className="flex flex-col items-center justify-center">
                                            <Search size={48} className="mb-4 opacity-20" />
                                            <p>ไม่พบข้อมูลที่ค้นหา</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50 flex justify-between items-center transition-colors shrink-0">
                    <span className="text-sm text-slate-500 dark:text-slate-400">
                        แสดง {Math.min(filteredRecords.length, (currentPage - 1) * pageSize + 1)} - {Math.min(filteredRecords.length, currentPage * pageSize)} จาก {filteredRecords.length}
                    </span>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronLeft size={18} />
                        </button>
                        <span className="px-4 py-1.5 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200 shadow-sm">
                            {currentPage} / {totalPages || 1}
                        </span>
                        <button 
                            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                            disabled={currentPage === totalPages || totalPages === 0}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

// Resizable Header Component
const Th = ({ children, align = 'left', width }: { children?: React.ReactNode, align?: 'left'|'right'|'center', width?: string }) => (
    <th 
        className={`px-4 py-4 text-${align} text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider border-b border-r border-slate-200 dark:border-slate-700 last:border-r-0 relative group`}
        style={{ width: width, minWidth: '100px', resize: 'horizontal', overflow: 'auto' }}
    >
        <div className="flex items-center w-full h-full">
            <span className="truncate w-full">{children}</span>
        </div>
    </th>
);

// Data Cell with Tooltip and Truncation
const DataCell = ({ text, align = 'left', isNumber = false }: { text: string | number, align?: 'left'|'right'|'center', isNumber?: boolean }) => {
    return (
        <td className={`px-4 py-3 border-b border-r border-slate-100 dark:border-slate-700 last:border-r-0 text-sm text-${align} text-slate-700 dark:text-slate-200 ${isNumber ? 'font-mono' : ''}`}>
            <div className="w-full truncate" title={String(text)}>
                {text || '-'}
            </div>
        </td>
    );
};

const SummaryCard = ({ title, amount, color, icon, isTotal = false }: any) => {
    const colorClasses: Record<string, string> = {
        blue: 'bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 border-blue-100 dark:border-blue-900/50',
        emerald: 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border-emerald-100 dark:border-emerald-900/50',
        amber: 'bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300 border-amber-100 dark:border-amber-900/50',
        purple: 'bg-purple-50 dark:bg-purple-900/20 text-purple-700 dark:text-purple-300 border-purple-100 dark:border-purple-900/50',
        slate: 'bg-slate-800 dark:bg-slate-700 text-white border-slate-700 shadow-lg',
    };

    return (
        <div className={`rounded-2xl p-5 border ${colorClasses[color]} flex flex-col justify-between h-full transition-transform hover:-translate-y-1 duration-300`}>
            <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-bold uppercase tracking-wider ${isTotal ? 'text-slate-400' : 'opacity-70'}`}>{title}</span>
                <div className={`p-1.5 rounded-lg ${isTotal ? 'bg-slate-700 text-emerald-400' : 'bg-white/50 dark:bg-black/20'}`}>
                    {icon}
                </div>
            </div>
            <p className={`font-bold ${isTotal ? 'text-3xl' : 'text-2xl'}`}>{formatNumber(amount)}</p>
        </div>
    );
};

export default DatabaseView;

import React, { useState, useEffect, useMemo } from 'react';
import Swal from 'sweetalert2';
import { useLocation, useNavigate } from 'react-router-dom';
import { dataService } from '../../services/dataService';
import AutocompleteInput from '../Form/AutocompleteInput';
import { formatNumber, parseNumber, getCurrentTimestamp } from '../../utils';
import { BudgetRecord } from '../../types';
import { Save, RefreshCw, Briefcase, MapPin, Calculator, Wallet, Building2, FileText, CheckCircle2 } from 'lucide-react';

const HomeView: React.FC = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Form State
    const [formData, setFormData] = useState<Partial<BudgetRecord>>({
        integration: 'ไม่เป็นหน่วยงานบูรณาการ',
        mainAgency: '',
        province: '',
        responsibleAgency: '',
        integrationArea: '',
        activity: '',
        target: '',
        unit: '',
        salaryPermanent: 0,
        governmentCompensation: 0,
        compensationSupplies: 0,
        contractEmployees: 0,
        utilities: 0,
        equipment: 0,
        landConstruction: 0,
        subsidies: 0,
        otherExpenses: 0,
    });

    const [locks, setLocks] = useState<Record<string, boolean>>({});
    // integrationType state: 'none', 'park' (Green), 'wildlife' (Pink)
    const [integrationType, setIntegrationType] = useState<'none' | 'park' | 'wildlife'>('none');

    // Load data for editing if available
    useEffect(() => {
        if (location.state?.editRecord) {
            const record = location.state.editRecord;
            setFormData(record);

            // Set integration type style
            if (record.integration === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') {
                setIntegrationType('park');
            } else if (record.integration === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') {
                setIntegrationType('wildlife');
            } else {
                setIntegrationType('none');
            }
        }
    }, [location]);

    // Data Sources
    const dropdowns = dataService.getDropdowns();
    const hierarchy = dataService.getHierarchy();
    const respData = dataService.getResponsibleData();

    // Derived Options based on cascading logic
    const provinceOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.province;
        return hierarchy
            .filter(h => h.mainAgency === formData.mainAgency)
            .map(h => h.province);
    }, [formData.mainAgency, dropdowns.province, hierarchy]);

    const responsibleAgencyOptions = useMemo(() => {
        if (!formData.mainAgency) return dropdowns.responsibleAgency;
        return respData
            .filter(r => r.mainAgency === formData.mainAgency)
            .map(r => r.responsibleAgency)
            .filter((v, i, a) => a.indexOf(v) === i); // Unique
    }, [formData.mainAgency, dropdowns.responsibleAgency, respData]);

    const integrationAreaOptions = useMemo(() => {
        if (!formData.responsibleAgency) return dropdowns.integrationArea;
        return respData
            .filter(r => r.responsibleAgency === formData.responsibleAgency)
            .map(r => r.integrationArea)
            .filter((v, i, a) => a.indexOf(v) === i);
    }, [formData.responsibleAgency, dropdowns.integrationArea, respData]);

    // Handlers
    const handleChange = (key: keyof BudgetRecord, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));

        // Cascading clears
        if (key === 'mainAgency') {
            setFormData(prev => ({ ...prev, province: '', responsibleAgency: '', integrationArea: '' }));
        }
        if (key === 'responsibleAgency') {
            setFormData(prev => ({ ...prev, integrationArea: '' }));
        }

        // Handle Integration Type Logic
        if (key === 'integration') {
           if (value === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') {
                setIntegrationType('park');
           } else if (value === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') {
                setIntegrationType('wildlife');
           } else {
                setIntegrationType('none');
           }
        }
    };

    const handleBudgetChange = (key: keyof BudgetRecord, value: string) => {
        const num = parseNumber(value);
        handleChange(key, num);
    };

    const toggleLock = (key: string) => {
        setLocks(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const totalBudget = useMemo(() => {
        return (formData.salaryPermanent || 0) +
            (formData.governmentCompensation || 0) +
            (formData.compensationSupplies || 0) +
            (formData.contractEmployees || 0) +
            (formData.utilities || 0) +
            (formData.equipment || 0) +
            (formData.landConstruction || 0) +
            (formData.subsidies || 0) +
            (formData.otherExpenses || 0);
    }, [formData]);

    const clearForm = () => {
        const newForm = { ...formData };

        // Remove ID to exit edit mode if present
        if ('id' in newForm) {
            delete (newForm as any).id;
        }

        Object.keys(newForm).forEach(key => {
            const k = key as keyof BudgetRecord;
            if (!locks[k]) {
                if (typeof newForm[k] === 'number') {
                    // @ts-ignore
                    newForm[k] = 0;
                } else if (k === 'integration') {
                    // @ts-ignore
                    newForm[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                } else {
                     // @ts-ignore
                    newForm[k] = '';
                }
            }
        });
        setFormData(newForm);
        // Reset integration type if integration field is cleared and not locked
        if (!locks['integration']) {
            setIntegrationType('none');
        } else {
             // Re-evaluate integration type from locked value
             if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านอุทยานแห่งชาติ)') setIntegrationType('park');
             else if (newForm.integration === 'หน่วยงานบูรณาการ (ด้านสัตว์ป่า)') setIntegrationType('wildlife');
             else setIntegrationType('none');
        }

        // Clear navigation state
        navigate('/', { replace: true, state: {} });

        Swal.fire({
            icon: 'success',
            title: 'ล้างข้อมูลเรียบร้อย',
            timer: 1500,
            showConfirmButton: false,
            confirmButtonColor: '#10b981'
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.mainAgency || !formData.province || !formData.activity) {
            Swal.fire({
                title: 'ข้อมูลไม่ครบ',
                text: 'กรุณากรอกข้อมูลที่จำเป็น (*)',
                icon: 'warning',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        const isEditMode = !!formData.id;

        Swal.fire({
            title: isEditMode ? 'ยืนยันการแก้ไข?' : 'ยืนยันการบันทึก?',
            html: `<div class="text-slate-600">ยอดรวมงบประมาณ</div><div class="text-3xl font-bold text-emerald-600 mt-2">${formatNumber(totalBudget)} บาท</div>`,
            icon: 'question',
            showCancelButton: true,
            confirmButtonText: isEditMode ? 'บันทึกการแก้ไข' : 'บันทึกข้อมูล',
            cancelButtonText: 'ตรวจสอบอีกครั้ง',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        }).then((result) => {
            if (result.isConfirmed) {
                if (isEditMode) {
                    // Update existing record
                    const updatedRecord: BudgetRecord = {
                        ...formData as BudgetRecord,
                        timestamp: getCurrentTimestamp()
                    };
                    dataService.updateRecord(updatedRecord);

                    Swal.fire({
                        title: 'แก้ไขสำเร็จ!',
                        text: 'ข้อมูลถูกปรับปรุงเรียบร้อยแล้ว',
                        icon: 'success',
                        confirmButtonColor: '#059669',
                        timer: 2000
                    }).then(() => {
                        clearForm();
                    });
                } else {
                    // Create new record
                    const newRecord: BudgetRecord = {
                        ...formData as BudgetRecord,
                        id: Date.now().toString(),
                        timestamp: getCurrentTimestamp()
                    };
                    dataService.addRecord(newRecord);

                    // Keep locked fields, clear others
                    const resetData = { ...formData };
                    if ('id' in resetData) delete (resetData as any).id;

                    Object.keys(resetData).forEach(key => {
                        const k = key as keyof BudgetRecord;
                        if (!locks[k]) {
                            if (typeof resetData[k] === 'number') {
                                // @ts-ignore
                                resetData[k] = 0;
                            } else if (k === 'integration') {
                                // @ts-ignore
                                resetData[k] = 'ไม่เป็นหน่วยงานบูรณาการ';
                            } else {
                                // @ts-ignore
                                resetData[k] = '';
                            }
                        }
                    });

                    setFormData(resetData);
                    if (!locks['integration']) setIntegrationType('none');

                    Swal.fire({
                        title: 'บันทึกสำเร็จ!',
                        text: 'ข้อมูลถูกบันทึกลงในฐานข้อมูลเรียบร้อยแล้ว',
                        icon: 'success',
                        confirmButtonColor: '#059669',
                        timer: 2000
                    });
                }
            }
        });
    };

    // Dynamic Style Helpers for Cards
    const getCardStyle = (type: 'none' | 'park' | 'wildlife') => {
        switch (type) {
            case 'park':
                return 'bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400 ring-2 ring-emerald-400/80 shadow-emerald-100 dark:shadow-emerald-900/10';
            case 'wildlife':
                return 'bg-pink-50/20 dark:bg-pink-900/10 border-pink-400 ring-2 ring-pink-400/80 shadow-pink-100 dark:shadow-pink-900/10';
            default:
                return 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700';
        }
    };

    const getIntegrationCardStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'ring-2 ring-emerald-400 bg-emerald-50/20 dark:bg-emerald-900/10 border-emerald-400';
            case 'wildlife':
                return 'ring-2 ring-pink-400 bg-pink-50/20 dark:bg-pink-900/10 border-pink-400';
            default:
                return 'border-slate-100 dark:border-slate-700';
        }
    };

    // --- Dynamic Footer Styles ---

    const getFooterContainerStyle = () => {
        switch (integrationType) {
            case 'park':
                // Green background
                return 'bg-emerald-600/95 dark:bg-emerald-800/95 border-emerald-500/50 shadow-emerald-900/20';
            case 'wildlife':
                // Pink background
                return 'bg-pink-600/95 dark:bg-pink-800/95 border-pink-500/50 shadow-pink-900/20';
            default:
                // Gray/Slate background (Default)
                return 'bg-slate-900/90 dark:bg-slate-950/90 border-slate-700/50 shadow-slate-900/20';
        }
    };

    const getFooterLabelColor = () => {
        switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white/80';
            default:
                return 'text-slate-300';
        }
    };

    const getFooterValueColor = () => {
         switch (integrationType) {
            case 'park':
            case 'wildlife':
                return 'text-white';
            default:
                return 'text-emerald-400';
        }
    };

    const getSubmitButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                // White button on Green background
                return 'bg-white text-emerald-600 hover:bg-emerald-50 shadow-emerald-900/20';
            case 'wildlife':
                // White button on Pink background
                return 'bg-white text-pink-600 hover:bg-pink-50 shadow-pink-900/20';
            default:
                // Green button on Dark Gray background
                return 'bg-emerald-600 text-white hover:bg-emerald-500 shadow-emerald-900/20 hover:shadow-emerald-900/40';
        }
    };

    const getClearButtonStyle = () => {
         switch (integrationType) {
            case 'park':
                return 'bg-emerald-700/50 text-emerald-50 hover:bg-emerald-700 border-emerald-500/50';
            case 'wildlife':
                return 'bg-pink-700/50 text-pink-50 hover:bg-pink-700 border-pink-500/50';
            default:
                return 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-slate-700';
        }
    };

    return (
        <div className="max-w-[95vw] mx-auto px-4 py-8">
            <header className="text-center mb-10">
                <h1 className="text-4xl font-bold text-slate-800 dark:text-white mb-3 transition-colors">
                    {formData.id ? 'แก้ไขข้อมูลงบประมาณ' : 'แบบฟอร์มบันทึกงบประมาณ'}
                </h1>
                <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">
                    {formData.id ? 'แก้ไขรายละเอียดโครงการและงบประมาณ' : 'กรอกรายละเอียดโครงการและงบประมาณประจำปี'}
                </p>
            </header>

            <form onSubmit={handleSubmit} className="space-y-6">

                {/* Integration Card */}
                <div className={`bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border transition-all duration-300 ${getIntegrationCardStyle()}`}>
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-3 rounded-xl ${
                                integrationType === 'wildlife' 
                                ? 'bg-pink-100 dark:bg-pink-900/40 text-pink-600 dark:text-pink-400' 
                                : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-600 dark:text-emerald-400'
                            }`}>
                                <Briefcase size={28} />
                            </div>
                            <div>
                                <h2 className="text-xl font-semibold text-slate-800 dark:text-white">สถานะบูรณาการ</h2>
                                <p className="text-base text-slate-500 dark:text-slate-400">ระบุประเภทหน่วยงานและการบูรณาการ</p>
                            </div>
                        </div>
                        <div className="w-full md:w-1/2 lg:w-1/3">
                            <AutocompleteInput
                                id="integration"
                                label="ประเภทหน่วยงาน"
                                required
                                value={formData.integration || ''}
                                options={dropdowns.integration}
                                onChange={(val) => handleChange('integration', val)}
                                placeholder="เลือกสถานะบูรณาการ..."
                            />
