import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { ChevronLeft, ChevronRight, Search, Filter, Users, Settings, Building, FileSpreadsheet, Wallet, ArrowRightLeft, RefreshCw, Edit2, Trash2 } from 'lucide-react';
import Swal from 'sweetalert2';

const DatabaseView: React.FC = () => {
    const records = dataService.getRecords();
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [pageSize, setPageSize] = useState(20);
    const [showFilters, setShowFilters] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [refreshTrigger, setRefreshTrigger] = useState(0); // Add trigger for re-render

    // Filters
    const [filterMainAgency, setFilterMainAgency] = useState('');
    const [filterProvince, setFilterProvince] = useState('');

    const filteredRecords = useMemo(() => {
        return records.filter(record => {
            const matchesSearch = 
                (record.mainAgency || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                (record.activity || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                (record.province || '').toLowerCase().includes(searchTerm.toLowerCase());

            const matchesAgency = filterMainAgency ? record.mainAgency === filterMainAgency : true;
            const matchesProvince = filterProvince ? record.province === filterProvince : true;

            return matchesSearch && matchesAgency && matchesProvince;
        });
    }, [records, searchTerm, filterMainAgency, filterProvince, refreshTrigger]);

    // Pagination
    const totalPages = Math.ceil(filteredRecords.length / pageSize);
    const paginatedRecords = filteredRecords.slice((currentPage - 1) * pageSize, currentPage * pageSize);

    // Summary Stats
    const summary = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            personnel: acc.personnel + (r.salaryPermanent || 0) + (r.governmentCompensation || 0),
            operational: acc.operational + (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0),
            investment: acc.investment + (r.equipment || 0) + (r.landConstruction || 0),
            other: acc.other + (r.subsidies || 0) + (r.otherExpenses || 0)
        }), { personnel: 0, operational: 0, investment: 0, other: 0 });
    }, [filteredRecords]);

    const totalBudget = summary.personnel + summary.operational + summary.investment + summary.other;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลเรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: 'ไม่สามารถดึงข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleEdit = (record: any) => {
        navigate('/', { state: { editRecord: record } });
    };

    const handleDelete = async (id: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบรายการ?',
            text: "ข้อมูลนี้จะถูกลบออกจากระบบและไม่สามารถกู้คืนได้",
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
            cancelButtonColor: '#94a3b8'
        });

        if (result.isConfirmed) {
            dataService.deleteRecord(id);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire(
                'ลบสำเร็จ!',
                'ข้อมูลถูกลบเรียบร้อยแล้ว',
                'success'
            );
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-4xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">ฐานข้อมูลงบประมาณ</h2>
                    <p className="text-lg text-slate-500 dark:text-slate-400 transition-colors">เรียกดูและค้นหาข้อมูลโครงการทั้งหมดจากฐานข้อมูล</p>
                </div>
                <button 
                    onClick={handleSync}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-5 py-2.5 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-medium text-base shadow-sm disabled:opacity-70 disabled:cursor-not-allowed`}
                >
                    <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูล'}
                </button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
                <SummaryCard title="งบบุคลากร" amount={summary.personnel} color="blue" icon={<Users size={20} />} />
                <SummaryCard title="งบดำเนินงาน" amount={summary.operational} color="emerald" icon={<Settings size={20} />} />
                <SummaryCard title="งบลงทุน" amount={summary.investment} color="amber" icon={<Building size={20} />} />
                <SummaryCard title="งบอื่นๆ" amount={summary.other} color="purple" icon={<FileSpreadsheet size={20} />} />
                <SummaryCard title="รวมงบประมาณ" amount={totalBudget} color="slate" icon={<Wallet size={20} />} isTotal />
            </div>

            {/* Filters Bar */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-6 p-4 transition-colors">
                <div className="flex justify-between items-center mb-4 cursor-pointer group" onClick={() => setShowFilters(!showFilters)}>
                    <div className="flex items-center gap-2 font-semibold text-slate-700 dark:text-slate-200 group-hover:text-emerald-700 dark:group-hover:text-emerald-400 transition-colors text-lg">
                        <Filter size={24} /> 
                        <span>ตัวกรองและค้นหา</span>
                    </div>
                    <div className="text-sm text-slate-400 bg-slate-50 dark:bg-slate-700 px-3 py-1 rounded-full">{showFilters ? 'ซ่อน' : 'แสดง'}</div>
                </div>

                <div className={`transition-all duration-300 overflow-hidden ${showFilters ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
                    <div className="grid md:grid-cols-3 gap-4 pt-2">
                         <div className="relative">
                            <input
                                type="text"
                                placeholder="ค้นหาจากชื่อหน่วยงาน, กิจกรรม..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                            />
                            <Search className="absolute left-3 top-3.5 text-slate-400" size={20} />
                        </div>
                        <select 
                            value={filterMainAgency} 
                            onChange={(e) => setFilterMainAgency(e.target.value)}
                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                        >
                            <option value="">ทุกหน่วยงาน</option>
                            {Array.from(new Set(records.map(r => r.mainAgency))).filter(Boolean).map((a: string) => <option key={a} value={a}>{a}</option>)}
                        </select>
                         <select 
                            value={filterProvince} 
                            onChange={(e) => setFilterProvince(e.target.value)}
                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 text-base"
                        >
                            <option value="">ทุกจังหวัด</option>
                            {Array.from(new Set(records.map(r => r.province))).filter(Boolean).map((p: string) => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors flex flex-col h-[70vh]">
                <div className="p-2 bg-slate-50 dark:bg-slate-900/50 border-b border-slate-100 dark:border-slate-700 text-xs text-slate-400 flex items-center gap-1">
                    <ArrowRightLeft size={12} />
                    <span>สามารถลากเส้นแบ่งคอลัมน์เพื่อปรับความกว้างได้</span>
                </div>
                <div className="overflow-auto custom-scrollbar flex-1">
                    <table className="min-w-max border-collapse">
                        <thead className="bg-slate-50 dark:bg-slate-900/50 sticky top-0 z-10 shadow-sm">
                            <tr>
                                <Th width="180px">บูรณาการ (B)</Th>
                                <Th width="150px">หน่วยงานหลัก (C)</Th>
                                <Th width="120px">จังหวัด (D)</Th>
                                <Th width="150px">หน่วยงานบูรณาการ (E)</Th>
                                <Th width="150px">พื้นที่บูรณาการ (F)</Th>
                                <Th width="200px">กิจกรรม (G)</Th>
                                <Th width="100px" align="center">เป้าหมาย (H)</Th>
                                <Th width="100px" align="center">หน่วยนับ (I)</Th>
                                <Th width="140px" align="right">เงินเดือน/ค่าจ้าง (J)</Th>
                                <Th width="140px" align="right">ค่าตอบแทนพนง. (K)</Th>
                                <Th width="140px" align="right">ตอบแทน/ใช้สอย (L)</Th>
                                <Th width="140px" align="right">ค่าจ้างเหมา (M)</Th>
                                <Th width="140px" align="right">ค่าสาธารณูปโภค (N)</Th>
                                <Th width="140px" align="right">ค่าครุภัณฑ์ (O)</Th>
                                <Th width="140px" align="right">ที่ดิน/สิ่งก่อสร้าง (P)</Th>
                                <Th width="140px" align="right">เงินอุดหนุน (Q)</Th>
                                <Th width="140px" align="right">รายจ่ายอื่น (R)</Th>
                                <Th width="160px">วันที่บันทึก (S)</Th>
                                <Th width="120px" align="center" isStickyRight>จัดการ</Th>
                            </tr>
                        </thead>
                        <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-100 dark:divide-slate-700">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => (
                                <tr key={r.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-700/50 transition-colors group">
                                    <DataCell text={r.integration} />
                                    <DataCell text={r.mainAgency} />
                                    <DataCell text={r.province} />
                                    <DataCell text={r.responsibleAgency} />
                                    <DataCell text={r.integrationArea} />
                                    <DataCell text={r.activity} />
                                    <DataCell text={r.target} align="center" />
                                    <DataCell text={r.unit} align="center" />
                                    <DataCell text={formatNumber(r.salaryPermanent)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.governmentCompensation)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.compensationSupplies)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.contractEmployees)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.utilities)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.equipment)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.landConstruction)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.subsidies)} align="right" isNumber />
                                    <DataCell text={formatNumber(r.otherExpenses)} align="right" isNumber />
                                    <DataCell text={r.timestamp} />
                                    <td className="px-2 py-3 border-b border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800 sticky right-0 z-5 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]">
                                        <div className="flex justify-center items-center gap-1">
                                            <button 
                                                onClick={() => handleEdit(r)}
                                                className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors"
                                                title="แก้ไข"
                                            >
                                                <Edit2 size={16} />
                                            </button>
                                            <button 
                                                onClick={() => handleDelete(r.id)}
                                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg transition-colors"
                                                title="ลบ"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan={19} className="px-6 py-12 text-center text-slate-400">
                                        <div className="flex flex-col items-center justify-center">
                                            <Search size={48} className="mb-4 opacity-20" />
                                            <p>ไม่พบข้อมูลที่ค้นหา</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination Controls */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/50 flex justify-between items-center transition-colors shrink-0">
                    <span className="text-sm text-slate-500 dark:text-slate-400">
                        แสดง {Math.min(filteredRecords.length, (currentPage - 1) * pageSize + 1)} - {Math.min(filteredRecords.length, currentPage * pageSize)} จาก {filteredRecords.length}
                    </span>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronLeft size={18} />
                        </button>
                        <span className="px-4 py-1.5 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-200 shadow-sm">
                            {currentPage} / {totalPages || 1}
                        </span>
                        <button 
                            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                            disabled={currentPage === totalPages || totalPages === 0}
                            className="p-2 rounded-lg hover:bg-white dark:hover:bg-slate-700 hover:shadow-sm dark:text-slate-300 disabled:opacity-30 disabled:hover:shadow-none transition-all"
                        >
                            <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

