### 2. โค้ด Google Apps Script (GAS)

คัดลอกโค้ดด้านล่างนี้ไปแทนที่โค้ดเดิมในไฟล์ `Code.gs` บน Google Apps Script Editor ครับ

**ข้อกำหนด:** ชีท `Database` จะต้องมีคอลัมน์ A ถึง S โดยคอลัมน์ A เป็น ID (สามารถปล่อยว่างตอนเพิ่มข้อมูลใหม่ได้ แต่ควรมีคอลัมน์ไว้) และคอลัมน์ B-S ตามที่ระบุ

```javascript
// --- Configuration ---
const SPREADSHEET_ID = '1rwyAt0TsSSpZ7uqrAHq6C39AYvGogK0rj1b7QI8efkM'; // เปลี่ยนเป็น ID ของคุณ
const DATA_SHEET_NAME = 'Data';       // ชีทเก็บตัวเลือก Dropdown
const DATABASE_SHEET_NAME = 'Database'; // ชีทเก็บข้อมูลรายการงบประมาณ
const HIERARCHY_SHEET_NAME = 'Hierarchy'; // (ถ้ามี)
const COMPARE_SHEET_NAME = 'Compare'; // (ถ้ามี)
// ---------------------

function doGet(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const result = {
      status: 'success',
      data: {
        dropdowns: getDropdowns(ss),
        hierarchy: getHierarchyData(ss),
        respData: getRespData(ss),
        compareData: getCompareData(ss),
        records: getDatabaseRecords(ss) // เพิ่มฟังก์ชันนี้
      }
    };

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

// ฟังก์ชันอ่านข้อมูลจากชีท Database (Col B - S)
// สมมติว่า Col A = ID, Col B = Integration, ..., Col S = Timestamp
function getDatabaseRecords(ss) {
  const sheet = ss.getSheetByName(DATABASE_SHEET_NAME);
  if (!sheet) return [];

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return []; // ไม่มีข้อมูล (มีแค่หัวตาราง)

  // อ่านข้อมูลทั้งหมดตั้งแต่แถวที่ 2 ถึงแถวสุดท้าย
  const data = sheet.getRange(2, 1, lastRow - 1, 19).getValues(); // A-S = 19 columns

  return data.map(row => {
    // ตรวจสอบว่ามีข้อมูลหรือไม่ (เพื่อข้ามแถวว่าง)
    if (!row[1] && !row[2]) return null;

    return {
      id: row[0] ? String(row[0]) : Utilities.getUuid(), // ถ้าไม่มี ID ให้สร้างชั่วคราว (แนะนำให้ชีทมี ID จริงๆ)
      integration: row[1],             // Col B
      mainAgency: row[2],              // Col C
      province: row[3],                // Col D
      responsibleAgency: row[4],       // Col E
      integrationArea: row[5],         // Col F
      activity: row[6],                // Col G
      target: row[7],                  // Col H
      unit: row[8],                    // Col I
      salaryPermanent: Number(row[9]) || 0,        // Col J
      governmentCompensation: Number(row[10]) || 0, // Col K
      compensationSupplies: Number(row[11]) || 0,   // Col L
      contractEmployees: Number(row[12]) || 0,      // Col M
      utilities: Number(row[13]) || 0,              // Col N
      equipment: Number(row[14]) || 0,              // Col O
      landConstruction: Number(row[15]) || 0,       // Col P
      subsidies: Number(row[16]) || 0,              // Col Q
      otherExpenses: Number(row[17]) || 0,          // Col R
      timestamp: row[18] instanceof Date ? formatDate(row[18]) : String(row[18]) // Col S
    };
  }).filter(r => r !== null);
}

// --- Helper Functions เดิม (คงไว้ตามเดิม) ---
function getDropdowns(ss) {
  // ... โค้ดเดิมของคุณสำหรับการดึง Dropdown ...
  // ตัวอย่างแบบย่อ:
  return {
     integration: getListFromSheet(ss, DATA_SHEET_NAME, "A"), // ปรับคอลัมน์ตามจริง
