// Utility: อ่านคอลัมน์เป็น List
function getListFromSheet(ss, sheetName, colLetter) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const range = sheet.getRange(colLetter + "2:" + colLetter + lastRow);
  const values = range.getValues();
  return values.map(r => r[0]).filter(String);
}

function formatDate(date) {
    return Utilities.formatDate(date, "Asia/Bangkok", "dd/MM/yyyy HH:mm:ss");
}
