import React, { useState, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale, Edit2, RefreshCw } from 'lucide-react';
import Swal from 'sweetalert2';
import { CompareRecord } from '../../types';

const CompareView: React.FC = () => {
    const [refreshTrigger, setRefreshTrigger] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Get Data
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';
        if (actual === 0 && target.referenceBudget > 0) status = 'nodata';
        else if (actual === 0 && target.referenceBudget === 0) status = 'nodata'; // Or handle as match/empty
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลล่าสุดเรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error: any) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'ไม่สามารถดึงข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleEdit = async (record: CompareRecord) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูลกิจกรรม',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">ชื่อกิจกรรม</div>' +
                `<input id="swal-input-activity" class="swal2-input" placeholder="ชื่อกิจกรรม" value="${record.activity}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">งบอ้างอิง (บาท)</div>' +
                `<input id="swal-input-budget" type="text" class="swal2-input" placeholder="งบประมาณ" value="${formatNumber(record.referenceBudget)}" style="margin: 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-top: 0.25rem; font-size: 0.875rem; color: #6b7280;">* ใส่ลูกน้ำ (,) เพื่อให้อ่านง่าย</div>',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            didOpen: () => {
                const input = Swal.getPopup()?.querySelector('#swal-input-budget') as HTMLInputElement;
                if (input) {
                    input.addEventListener('input', (e) => {
                        let val = (e.target as HTMLInputElement).value.replace(/[^0-9.]/g, '');
                        // Prevent multiple dots
                        const parts = val.split('.');
                        if (parts.length > 2) val = parts[0] + '.' + parts.slice(1).join('');

                        if (val) {
                            const numberParts = val.split('.');
                            numberParts[0] = numberParts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
                            (e.target as HTMLInputElement).value = numberParts.join('.');
                        } else {
                            (e.target as HTMLInputElement).value = '';
                        }
                    });
                }
            },
            preConfirm: () => {
                const activity = (document.getElementById('swal-input-activity') as HTMLInputElement).value;
                const budgetStr = (document.getElementById('swal-input-budget') as HTMLInputElement).value;
                if (!activity) {
                    Swal.showValidationMessage('กรุณาระบุชื่อกิจกรรม');
                }
                const budget = parseFloat(budgetStr.replace(/,/g, '')) || 0;
                return {
                    activity: activity,
                    budget: budget
                };
            }
        });

        if (formValues) {
            dataService.updateCompareData(record.id, formValues.activity, formValues.budget);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
