import React, { useState } from 'react';
import { getSettings, saveSettings, dataService } from '../../services/dataService';
import Swal from 'sweetalert2';
import { Database, Link, Save, Wifi, CheckCircle2, XCircle } from 'lucide-react';

const SettingsView: React.FC = () => {
    const [settings, setSettingsState] = useState(getSettings());
    const [isTesting, setIsTesting] = useState(false);

    const handleChange = (key: string, value: string) => {
        setSettingsState(prev => ({ ...prev, [key]: value }));
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        saveSettings(settings);
        Swal.fire({
            title: 'บันทึกสำเร็จ',
            text: 'การตั้งค่าระบบถูกอัปเดตเรียบร้อยแล้ว',
            icon: 'success',
            confirmButtonColor: '#059669'
        });
    };

    const handleTestConnection = async () => {
        // Save temporary settings first to test the new values
        saveSettings(settings);
        setIsTesting(true);

        try {
            const success = await dataService.testConnection();
            if (success) {
                Swal.fire({
                    title: 'เชื่อมต่อสำเร็จ',
                    text: 'สามารถดึงข้อมูลจาก Google Apps Script ได้อย่างถูกต้อง',
                    icon: 'success',
                    confirmButtonColor: '#059669'
                });
            } else {
                Swal.fire({
                    title: 'เชื่อมต่อไม่สำเร็จ',
                    text: 'กรุณาตรวจสอบ URL หรือสิทธิ์การเข้าถึง (Deploy as Web App: Anyone)',
                    icon: 'error',
                    confirmButtonColor: '#ef4444'
                });
            }
        } catch (error) {
             Swal.fire({
                title: 'เกิดข้อผิดพลาด',
                text: 'ไม่สามารถติดต่อเซิร์ฟเวอร์ได้',
                icon: 'error',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsTesting(false);
        }
    };

    return (
        <div className="max-w-3xl mx-auto px-4 py-12">
            <div className="mb-8">
                <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">ตั้งค่าระบบ</h2>
                <p className="text-slate-500 dark:text-slate-400 transition-colors">จัดการการเชื่อมต่อข้อมูล Google Sheets และฐานข้อมูล</p>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-8 transition-colors">
                <form onSubmit={handleSave} className="space-y-8">

                    <div className="space-y-6">
                        <div className="pb-2 border-b border-slate-100 dark:border-slate-700 mb-4 flex justify-between items-center">
                            <h3 className="text-lg font-semibold text-slate-800 dark:text-white flex items-center gap-2">
                                <Link size={20} className="text-blue-500" /> 
                                การเชื่อมต่อ API
                            </h3>
                            <button 
                                type="button"
                                onClick={handleTestConnection}
                                disabled={isTesting}
                                className="text-sm px-4 py-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/50 transition-colors flex items-center gap-2 font-medium disabled:opacity-50"
                            >
                                {isTesting ? (
                                    <span className="animate-pulse">กำลังทดสอบ...</span>
                                ) : (
                                    <>
                                        <Wifi size={16} /> ทดสอบการเชื่อมต่อ
                                    </>
                                )}
                            </button>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Google Apps Script URL</label>
                            <input
                                type="url"
                                value={settings.gasUrl}
                                onChange={(e) => handleChange('gasUrl', e.target.value)}
                                className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 font-mono text-sm"
                                placeholder="https://script.google.com/macros/s/..."
                            />
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Google Sheets ID</label>
                            <input
                                type="text"
                                value={settings.sheetsId}
                                onChange={(e) => handleChange('sheetsId', e.target.value)}
                                className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900 font-mono text-sm"
                                placeholder="1BxiMVs0XRA5nFMd..."
                            />
                        </div>
                    </div>

                    <div className="space-y-6">
                         <div className="pb-2 border-b border-slate-100 dark:border-slate-700 mb-4">
                            <h3 className="text-lg font-semibold text-slate-800 dark:text-white flex items-center gap-2">
                                <Database size={20} className="text-emerald-500" /> 
                                โครงสร้างข้อมูล
                            </h3>
                        </div>

                        <div className="grid md:grid-cols-2 gap-6">
                             <div>
                                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">ชื่อชีทข้อมูล (Database)</label>
                                <input
                                    type="text"
                                    value={settings.databaseSheetName}
                                    onChange={(e) => handleChange('databaseSheetName', e.target.value)}
                                    className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900"
                                />
                            </div>
                             <div>
                                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">ชื่อชีทตั้งค่า (Data)</label>
                                <input
                                    type="text"
                                    value={settings.dataSheetName}
                                    onChange={(e) => handleChange('dataSheetName', e.target.value)}
                                    className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="pt-6 border-t border-slate-100 dark:border-slate-700">
                        <button type="submit" className="w-full bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-4 rounded-xl font-bold transition-all shadow-lg shadow-emerald-900/20 hover:shadow-emerald-900/30 flex items-center justify-center gap-2">
                            <Save size={20} />
                            บันทึกการตั้งค่า
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default SettingsView;

