// --- Configuration ---
const SPREADSHEET_ID = '1rwyAt0TsSSpZ7uqrAHq6C39AYvGogK0rj1b7QI8efkM';

// ชื่อชีทต่างๆ (ต้องตรงกับใน Google Sheets)
const SHEET_DATABASE = 'Database';
const SHEET_INTEGRATION = 'Integration';
const SHEET_HIERARCHY = 'Hierarchy';         // Col A: MainAgency, Col B: Province
const SHEET_RESPONSIBLE = 'ResponsibleAgency'; // Col A: Main, Col B: Resp, Col C: Area
const SHEET_COMPARE = 'Compare';             // Col A: Activity, Col B: Reference Budget
const SHEET_UNIT = 'Unit';                   // Col A: Unit Name

function doGet(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  // รอสูงสุด 10 วินาทีเพื่อป้องกันการชนกันของข้อมูล (Concurrency)
  lock.tryLock(10000);

  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);

    // 1. ดึงข้อมูล Master Data ต่างๆ
    const hierarchy = getHierarchyData(ss);
    const respData = getRespData(ss);
    const compareData = getCompareData(ss);

    // 2. สร้างรายการ Dropdown จากข้อมูล Master (เพื่อให้ Frontend ใช้งานง่าย)
    const mainAgencies = unique(hierarchy.map(function(h){ return h.mainAgency; }));
    const provinces = unique(hierarchy.map(function(h){ return h.province; }));

    const dropdowns = {
      integration: getSimpleList(ss, SHEET_INTEGRATION),
      mainAgency: mainAgencies,
      province: provinces,
      responsibleAgency: unique(respData.map(function(r){ return r.responsibleAgency; })),
      integrationArea: unique(respData.map(function(r){ return r.integrationArea; })),
      activity: compareData.map(function(c){ return c.activity; }),
      unit: getSimpleList(ss, SHEET_UNIT)
    };

    // 3. รวมข้อมูลทั้งหมดส่งกลับ
    const result = {
      status: 'success',
      data: {
        dropdowns: dropdowns,
        hierarchy: hierarchy,
        respData: respData,
        compareData: compareData,
        records: getDatabaseRecords(ss)
      }
    };

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    // กรณีเกิด Error ให้ส่งกลับไปบอก Frontend
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: error.toString() + " Stack: " + error.stack
    })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- Data Fetchers ---

// ดึงข้อมูลรายการงบประมาณ (Database)
function getDatabaseRecords(ss) {
  const sheet = ss.getSheetByName(SHEET_DATABASE);
  if (!sheet) return [];

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];

  // A-S = 19 columns
  const data = sheet.getRange(2, 1, lastRow - 1, 19).getValues();

  return data.map(function(row) {
    if (!row[1] && !row[2]) return null; // ข้ามแถวว่าง
    return {
      id: row[0] ? String(row[0]) : Utilities.getUuid(),
      integration: row[1],
      mainAgency: row[2],
      province: row[3],
      responsibleAgency: row[4],
      integrationArea: row[5],
      activity: row[6],
      target: row[7],
      unit: row[8],
      salaryPermanent: Number(row[9]) || 0,
      governmentCompensation: Number(row[10]) || 0,
      compensationSupplies: Number(row[11]) || 0,
      contractEmployees: Number(row[12]) || 0,
      utilities: Number(row[13]) || 0,
      equipment: Number(row[14]) || 0,
      landConstruction: Number(row[15]) || 0,
      subsidies: Number(row[16]) || 0,
      otherExpenses: Number(row[17]) || 0,
      timestamp: row[18] instanceof Date ? formatDate(row[18]) : String(row[18])
    };
  }).filter(function(r) { return r !== null; });
}

// ดึงข้อมูล Hierarchy (Main Agency -> Province)
function getHierarchyData(ss) {
  const rows = getSheetData(ss, SHEET_HIERARCHY);
  return rows.map(function(row) {
    return { mainAgency: row[0], province: row[1] };
  }).filter(function(x) { return x.mainAgency && x.province; });
}

// ดึงข้อมูล Responsible Agency
function getRespData(ss) {
  const rows = getSheetData(ss, SHEET_RESPONSIBLE);
  return rows.map(function(row) {
    return { mainAgency: row[0], responsibleAgency: row[1], integrationArea: row[2] };
  }).filter(function(x) { return x.mainAgency && x.responsibleAgency; });
}

// ดึงข้อมูล Compare (Activity -> Budget)
function getCompareData(ss) {
  const rows = getSheetData(ss, SHEET_COMPARE);
  return rows.map(function(row, index) {
    return { 
      id: 'GAS-' + (index + 1), 
      activity: row[0], 
      referenceBudget: Number(row[1]) || 0 
    };
  }).filter(function(x) { return x.activity; });
}

// ดึงข้อมูลลิสต์รายการเดียว (เช่น Unit, Integration Type)
function getSimpleList(ss, sheetName) {
  const rows = getSheetData(ss, sheetName);
  return rows.map(function(row) { return row[0]; }).filter(String);
}

// --- Helpers ---

// ฟังก์ชันดึงข้อมูลจาก Sheet แบบ Generic (ตัด Header แถว 1 ออก)
function getSheetData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  const lastCol = sheet.getLastColumn();
  if (lastRow < 2 || lastCol < 1) return [];
  return sheet.getRange(2, 1, lastRow - 1, lastCol).getValues();
}

// ฟังก์ชันหาค่า Unique ใน Array
function unique(arr) {
  var seen = {};
  return arr.filter(function(item) {
    return item && seen.hasOwnProperty(item) ? false : (seen[item] = true);
  });
}

function formatDate(date) {
  return Utilities.formatDate(date, "Asia/Bangkok", "dd/MM/yyyy HH:mm:ss");
}
