                                {/* Personnel */}
                                <Th width="120px" align="center" className="border-t border-slate-200 dark:border-slate-700">เงินเดือน/ค่าจ้าง</Th>
                                <Th width="120px" align="center" className="border-t border-slate-200 dark:border-slate-700">ค่าตอบแทนพนง.</Th>

                                {/* Operational */}
                                <Th width="120px" align="center" className="border-t border-slate-200 dark:border-slate-700">ค่าตอบแทน/ใช้สอย</Th>
