                {/* Section 3: Budget Details */}
                {showBudgetSection && (
                    <div className={`rounded-2xl shadow-sm border p-6 md:p-8 transition-all duration-300 ${getCardStyle(integrationType)}`}>
                        <div className="flex items-center gap-3 mb-8">
