                            {showBudgetOther && (
                                <div className="bg-purple-50/70 dark:bg-purple-900/20 p-6 rounded-2xl border border-purple-100 dark:border-purple-900/50 hover:border-purple-200 dark:hover:border-purple-800 transition-colors shadow-sm">
                                    <h3 className="text-xl font-semibold text-purple-700 dark:text-purple-300 mb-4 flex items-center gap-2">
                                        <div className="w-2 h-6 bg-purple-500 rounded-full"></div>
                                        งบอื่นๆ
                                    </h3>
                                    <div className="space-y-4">
                                        {fieldVisibility.subsidies && <BudgetField label="งบเงินอุดหนุน" val={formData.subsidies} onChange={(v) => handleBudgetChange('subsidies', v)} />}
                                        {fieldVisibility.otherExpenses && <BudgetField label="งบรายจ่ายอื่น" val={formData.otherExpenses} onChange={(v) => handleBudgetChange('otherExpenses', v)} />}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {/* Footer Action Bar */}
                <div className="sticky bottom-4 z-20">
                     <div className={`backdrop-blur-md px-6 py-3 rounded-xl shadow-2xl flex flex-col md:flex-row justify-between items-center gap-3 border transition-all duration-300 ${getFooterContainerStyle()}`}>
                        <div className="flex flex-row items-center gap-4">
                            <div className={`text-sm font-medium ${getFooterLabelColor()}`}>รวมงบประมาณสุทธิ</div>
                            <div className={`text-2xl font-bold ${getFooterValueColor()}`}>
                                {formatNumber(totalBudget)} <span className="text-base font-normal opacity-80">บาท</span>
                            </div>
                        </div>

                        <div className="flex gap-3 w-full md:w-auto">
                            <button 
                                type="button" 
                                onClick={clearForm} 
                                className={`flex-1 md:flex-none px-5 py-2 rounded-lg font-semibold transition-all border flex items-center justify-center gap-2 text-sm ${getClearButtonStyle()}`}
                            >
                                <RefreshCw size={16} /> ล้างค่า
                            </button>
                            <button 
                                type="submit" 
                                className={`flex-1 md:flex-none px-6 py-2 rounded-lg font-semibold transition-all shadow-lg transform hover:-translate-y-0.5 flex items-center justify-center gap-2 text-sm ${getSubmitButtonStyle()}`}
                            >
                                <CheckCircle2 size={18} /> {formData.id ? 'บันทึกการแก้ไข' : 'บันทึกข้อมูล'}
                            </button>
                        </div>
                    </div>
                </div>
            </form>
            <div className="h-8"></div>
        </div>
    );
};

const BudgetField = ({ label, val, onChange }: { label: string, val: number | undefined, onChange: (v: string) => void }) => (
    <div className="group">
        <label className="block text-base font-medium text-slate-600 dark:text-slate-300 mb-2 group-hover:text-slate-800 dark:group-hover:text-slate-100 transition-colors">{label}</label>
        <div className="relative">
            <input
                type="text"
                value={val ? formatNumber(val) : ''}
                onChange={(e) => onChange(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 transition-all text-right font-medium text-slate-800 dark:text-slate-100 placeholder-slate-300 text-lg"
                placeholder="0"
            />
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-base">฿</span>
        </div>
    </div>
);

export default HomeView;

payload.text:
นี่คือโค้ด **Google Apps Script (GAS)** ฉบับสมบูรณ์ที่ออกแบบมาเพื่อทำงานร่วมกับโค้ด React ของคุณโดยเฉพาะครับ

โค้ดชุดนี้รองรับฟีเจอร์:
1.  **GET**: ดึงข้อมูลทั้งหมด (Database, Dropdowns, Hierarchy, Config) ไปแสดงผล
2.  **POST**: รองรับการ `addRecord` (เพิ่ม), `updateRecord` (แก้ไข), `deleteRecord` (ลบ) และ `saveSettings` (บันทึกการตั้งค่า Dropdown/Hierarchy กลับลง Sheet)
3.  **Setup**: มีฟังก์ชันสำหรับสร้างหัวตารางให้อัตโนมัติในครั้งแรก

### วิธีการติดตั้ง
1.  ไปที่ [Google Sheets](https://sheets.google.com) สร้างไฟล์ใหม่
2.  ไปที่เมนู **Extensions (ส่วนขยาย)** > **Apps Script**
3.  ลบโค้ดเก่าทั้งหมด แล้ววางโค้ดด้านล่างนี้ลงไป
4.  กดปุ่ม **Run** ที่ฟังก์ชัน `setupFirstTime` หนึ่งครั้ง (เพื่อสร้าง Sheet และหัวตาราง)
5.  กด **Deploy (ทำให้ใช้งานได้)** > **New deployment (การทำให้ใช้งานได้รายการใหม่)**
    *   Select type: **Web app**
    *   Description: (ตั้งชื่อตามต้องการ)
    *   Execute as: **Me (ฉัน)**
    *   Who has access: **Anyone (ทุกคน)** (สำคัญมาก!)
6.  คัดลอก **Web App URL** ไปใส่ในโค้ด React ส่วน `services/dataService.ts`

---

### Google Apps Script Code (`Code.gs`)

```javascript
/**
 * DNP Budget Plan - Backend API
 * รองรับการทำงาน: Database CRUD, Dropdown Management, Hierarchy, Settings
 */

const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
const SHEET_DB = 'Database';
const SHEET_DATA = 'Data'; // สำหรับเก็บ Dropdowns และ Settings

// ชื่อคอลัมน์ใน Database (ต้องตรงกับลำดับการบันทึก)
const DB_HEADERS = [
  'id', 'integration', 'mainAgency', 'province', 'responsibleAgency', 
  'integrationArea', 'activity', 'target', 'unit', 
