/**
 * API: Handle GET Requests (ดึงข้อมูล)
 */
function doGet(e) {
  const output = {
    status: 'success',
    data: {
      records: getRecords(),
      ...getSettingsData() // กระจาย object: dropdowns, hierarchy, etc.
    }
  };
  return responseJSON(output);
}

/**
 * API: Handle POST Requests (เพิ่ม/แก้ไข/ลบ/บันทึกตั้งค่า)
 */
function doPost(e) {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000); // รอคิวสูงสุด 10 วินาที

    const params = JSON.parse(e.postData.contents);
    const action = params.action;
    let result = {};

    if (action === 'addRecord') {
      result = addRecord(params.record);
    } else if (action === 'updateRecord') {
      result = updateRecord(params.record);
    } else if (action === 'deleteRecord') {
      result = deleteRecord(params.id);
    } else if (action === 'saveSettings') {
      // สำหรับบันทึก Dropdowns, Hierarchy, Visibility กลับมาที่ Sheet
      result = saveSettingsData(params.data); 
    } else {
      throw new Error('Invalid action: ' + action);
    }

    return responseJSON({ status: 'success', ...result });

  } catch (error) {
    return responseJSON({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

