function getRecords() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DB);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const records = [];

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    const record = {};
    // Map array to object based on headers
    for (let j = 0; j < headers.length; j++) {
      record[headers[j]] = row[j];
    }
    records.push(record);
  }
  return records;
}

function addRecord(record) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DB);
  const newRow = DB_HEADERS.map(header => {
    // แปลงค่าให้เหมาะสมกับการบันทึก (เช่น วันที่)
    if (header === 'timestamp') return new Date(); // ใช้วันที่ปัจจุบันของ Server
    return record[header] || '';
  });

  sheet.appendRow(newRow);
  return { message: 'Record added successfully' };
}

function updateRecord(record) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DB);
  const data = sheet.getDataRange().getValues();
  const idIndex = DB_HEADERS.indexOf('id');

  // ค้นหาแถวที่ ID ตรงกัน (เริ่มที่ Row 2 เพราะมี Header)
  for (let i = 1; i < data.length; i++) {
    // เปรียบเทียบเป็น String เพื่อความชัวร์
    if (String(data[i][idIndex]) === String(record.id)) {
      const rowIndex = i + 1;
      const updatedRow = DB_HEADERS.map(header => {
         if (header === 'timestamp') return new Date(); // Update timestamp
         return record[header] !== undefined ? record[header] : data[i][DB_HEADERS.indexOf(header)];
      });

      sheet.getRange(rowIndex, 1, 1, updatedRow.length).setValues([updatedRow]);
      return { message: 'Record updated successfully' };
    }
  }
  throw new Error('Record ID not found');
}

function deleteRecord(id) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DB);
  const data = sheet.getDataRange().getValues();
  const idIndex = DB_HEADERS.indexOf('id');

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][idIndex]) === String(id)) {
      sheet.deleteRow(i + 1);
      return { message: 'Record deleted successfully' };
    }
  }
  throw new Error('Record ID not found');
}

// ------------------------------------------------------------------------
// Settings & Dropdowns Operations (Stored in 'Data' Sheet Cell A2)
// ------------------------------------------------------------------------

function getSettingsData() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DATA);
  const jsonString = sheet.getRange("A2").getValue();
  try {
    return JSON.parse(jsonString);
  } catch (e) {
    // กรณีข้อมูลเสียหายหรือยังไม่มี ให้ return ค่าว่าง
    return { dropdowns: {}, hierarchy: [], respData: [], compareData: [], fieldVisibility: {} };
  }
}

function saveSettingsData(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_DATA);
  // data คือ object ที่รวม dropdowns, hierarchy, etc.
  // เราจะ Merge กับข้อมูลเดิม หรือเขียนทับเลยก็ได้ ในที่นี้เขียนทับเพื่อให้ตรงกับ Frontend
  const currentString = sheet.getRange("A2").getValue();
  let currentData = {};
  try { currentData = JSON.parse(currentString); } catch(e) {}

  const newData = { ...currentData, ...data };

  sheet.getRange("A2").setValue(JSON.stringify(newData));
  return { message: 'Settings saved successfully' };
}

// ------------------------------------------------------------------------
// Helper Functions
// ------------------------------------------------------------------------

function responseJSON(content) {
  return ContentService.createTextOutput(JSON.stringify(content))
    .setMimeType(ContentService.MimeType.JSON);
}
