// --- RECORD MANAGEMENT (Database) ---

function manageRecord(ss, params) {
  const sheet = ss.getSheetByName(SHEETS.DB);
  if (!sheet) throw new Error("Database sheet not found");

  const type = params.type; // add, update, delete
  const record = params.data;
  const id = params.id; // for delete

  if (type === 'add') {
    const row = DB_HEADERS.map(h => {
      if (h === 'timestamp') return new Date();
      return record[h] || '';
    });
    sheet.appendRow(row);
    return { message: 'Record added' };
  }

  // Find row
  const data = sheet.getDataRange().getValues();
  const idIndex = DB_HEADERS.indexOf('id');
  let rowIndex = -1;

  // search by ID
  const searchId = type === 'delete' ? id : record.id;

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][idIndex]) === String(searchId)) {
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex === -1) throw new Error('Record ID not found');

  if (type === 'delete') {
    sheet.deleteRow(rowIndex);
    return { message: 'Record deleted' };
  }

  if (type === 'update') {
    const oldRowValues = data[rowIndex - 1];
    const newRow = DB_HEADERS.map((h, idx) => {
      if (h === 'timestamp') return new Date();
      return record[h] !== undefined ? record[h] : oldRowValues[idx];
    });
    sheet.getRange(rowIndex, 1, 1, newRow.length).setValues([newRow]);
    return { message: 'Record updated' };
  }
}

// --- MASTER DATA MANAGEMENT ---

function manageMaster(ss, params) {
  const target = params.target; // Integration, Hierarchy, etc.
  const type = params.type; // add, update, delete
  const data = params.data; // Object with fields corresponding to sheet columns

  // 1. Simple Single Column Sheets (Integration, Unit)
  if (target === 'Integration' || target === 'Unit') {
    return manageSimpleSheet(ss, SHEETS[target.toUpperCase()], type, data);
  }

  // 2. Compare Sheet (Activity, Budget)
  if (target === 'Compare') {
    return manageCompareSheet(ss, type, data);
  }

  // 3. Hierarchy Sheet (MainAgency, Province)
  if (target === 'Hierarchy') {
    return manageHierarchySheet(ss, type, data);
  }

  // 4. ResponsibleAgency Sheet
  if (target === 'ResponsibleAgency') {
    return manageResponsibleSheet(ss, type, data);
  }

  throw new Error('Unknown target: ' + target);
}

// Handler for simple 1-col sheets (Integration, Unit)
function manageSimpleSheet(ss, sheetName, type, data) {
  const sheet = ss.getSheetByName(sheetName) || ss.insertSheet(sheetName);
  const rows = sheet.getDataRange().getValues();
  const name = data.name; // Expect { name: '...' }
  const oldName = data.oldName; // For update

  if (type === 'add') {
    if (rows.flat().includes(name)) return { message: 'Already exists' };
    sheet.appendRow([name]);
  } else if (type === 'update') {
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === oldName) {
        sheet.getRange(i + 1, 1).setValue(name);
        break;
      }
    }
  } else if (type === 'delete') {
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === name) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

// Handler for Compare (Activity, Budget)
function manageCompareSheet(ss, type, data) {
  const sheet = ss.getSheetByName(SHEETS.COMPARE) || ss.insertSheet(SHEETS.COMPARE);
  const rows = sheet.getDataRange().getValues();
  // data: { activity: '...', referenceBudget: 1000, oldActivity: '...' }

  if (type === 'add') {
    sheet.appendRow([data.activity, data.referenceBudget || 0]);
  } else if (type === 'update') {
    const searchKey = data.oldActivity || data.activity;
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === searchKey) {
        sheet.getRange(i + 1, 1, 1, 2).setValues([[data.activity, data.referenceBudget]]);
        break;
      }
    }
  } else if (type === 'delete') {
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === data.activity) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

// Handler for Hierarchy (MainAgency, Province)
function manageHierarchySheet(ss, type, data) {
  const sheet = ss.getSheetByName(SHEETS.HIERARCHY) || ss.insertSheet(SHEETS.HIERARCHY);
  const rows = sheet.getDataRange().getValues();
  // data: { mainAgency, province, oldMainAgency, oldProvince }

  if (type === 'add') {
    sheet.appendRow([data.mainAgency, data.province]);
  } else if (type === 'update') {
    // Find exact match
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === (data.oldMainAgency || data.mainAgency) && 
          rows[i][1] === (data.oldProvince || data.province)) {
        sheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
        break;
      }
    }
  } else if (type === 'delete') {
    // Delete specific pair
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === data.mainAgency && rows[i][1] === data.province) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  } else if (type === 'delete_by_agency') {
    // Delete all rows with this mainAgency (loop backwards)
    for (let i = rows.length - 1; i >= 0; i--) {
      if (rows[i][0] === data.mainAgency) {
        sheet.deleteRow(i + 1);
      }
    }
  }
  return { message: 'Success' };
}

// Handler for ResponsibleAgency
function manageResponsibleSheet(ss, type, data) {
  const sheet = ss.getSheetByName(SHEETS.RESPONSIBLE) || ss.insertSheet(SHEETS.RESPONSIBLE);
  const rows = sheet.getDataRange().getValues();
  // data: { mainAgency, responsibleAgency, integrationArea, ...oldFields }

  if (type === 'add') {
    sheet.appendRow([data.mainAgency, data.responsibleAgency, data.integrationArea]);
  } else if (type === 'update') {
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === data.mainAgency && 
          rows[i][1] === data.oldResponsibleAgency && 
          rows[i][2] === data.oldIntegrationArea) {
        sheet.getRange(i + 1, 1, 1, 3).setValues([[data.mainAgency, data.responsibleAgency, data.integrationArea]]);
        break;
      }
    }
  } else if (type === 'delete') {
    for (let i = 0; i < rows.length; i++) {
      if (rows[i][0] === data.mainAgency && 
          rows[i][1] === data.responsibleAgency && 
          rows[i][2] === data.integrationArea) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}


// --- UTILS ---

function getSheetData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0]; // Assume Row 1 is header if it exists
  const results = [];

  // Specific mapping based on sheet structure knowledge
  if (sheetName === SHEETS.DB) {
     for (let i = 1; i < rows.length; i++) {
       let obj = {};
       headers.forEach((h, idx) => obj[h] = rows[i][idx]);
       results.push(obj);
     }
  } else if (sheetName === SHEETS.HIERARCHY) {
    // No header row assumed in simple master sheets? Or yes? 
    // Let's assume user might not have headers or has them. 
    // Safer to just map columns by index based on prompt description.
    // If user has headers, we might include them, but frontend filters.
    // Let's assume headers exist for standardisation.
    for (let i = 1; i < rows.length; i++) {
      if(!rows[i][0]) continue;
      results.push({ mainAgency: rows[i][0], province: rows[i][1] });
    }
  } else if (sheetName === SHEETS.RESPONSIBLE) {
    for (let i = 1; i < rows.length; i++) {
       if(!rows[i][0]) continue;
       results.push({ mainAgency: rows[i][0], responsibleAgency: rows[i][1], integrationArea: rows[i][2] });
    }
  } else if (sheetName === SHEETS.COMPARE) {
    for (let i = 1; i < rows.length; i++) {
       if(!rows[i][0]) continue;
       // ถ้า Compare มี Header เป็น Activity, ReferenceBudget
       results.push({ id: rows[i][0], activity: rows[i][0], referenceBudget: rows[i][1] });
    }
  }
  return results;
}

function getSimpleColumnData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  const values = sheet.getDataRange().getValues();
  // Assume Row 1 is Header, skip it. Column A only.
  const list = [];
  for (let i = 1; i < values.length; i++) {
    if (values[i][0]) list.push(values[i][0]);
  }
  return list;
}

function responseJSON(content) {
  return ContentService.createTextOutput(JSON.stringify(content))
    .setMimeType(ContentService.MimeType.JSON);
}
