        // Use fetch with no-cors for simple fire-and-forget to GAS Web App
        // Note: We cannot read the response in no-cors mode, but it allows sending data without complex CORS setup
        try {
            await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' }, // 'text/plain' prevents preflight OPTIONS check in some cases
                body: JSON.stringify({ action, ...payload })
