        Object.keys(FIELD_LABELS).forEach(key => newVisibility[key] = visible);
        this.fieldVisibility = newVisibility;
        this.saveToCache();
    }

    // --- Master Data CRUD ---

    private updateDerivedDropdowns() {
        const unique = (arr: any[]) => Array.from(new Set(arr.filter(item => item && typeof item === 'string' && item.trim() !== '')));
        this.dropdowns.mainAgency = unique(this.hierarchy.map(h => h.mainAgency));
        this.dropdowns.province = unique(this.hierarchy.map(h => h.province));
    }

    // --- Hierarchy (Main Agency & Province) ---

    addHierarchyItem(mainAgency: string, province: string) {
        const exists = this.hierarchy.some(h => h.mainAgency === mainAgency && h.province === province);
        if (!exists) {
            this.hierarchy.push({ mainAgency, province });
            this.updateDerivedDropdowns();
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'Hierarchy', 
                type: 'add', 
                data: { mainAgency, province } 
            });
        }
    }

    updateHierarchyItem(oldMain: string, oldProv: string, newMain: string, newProv: string) {
        const index = this.hierarchy.findIndex(h => h.mainAgency === oldMain && h.province === oldProv);
        if (index !== -1) {
            this.hierarchy[index] = { mainAgency: newMain, province: newProv };
            this.updateDerivedDropdowns();
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'Hierarchy', 
                type: 'update', 
                data: { mainAgency: newMain, province: newProv, oldMainAgency: oldMain, oldProvince: oldProv } 
            });
        }
    }

    deleteHierarchyItem(mainAgency: string, province: string) {
        this.hierarchy = this.hierarchy.filter(h => !(h.mainAgency === mainAgency && h.province === province));
        this.updateDerivedDropdowns();
        this.saveToCache();

        this.sendToGas('MANAGE_MASTER', { 
            target: 'Hierarchy', 
            type: 'delete', 
            data: { mainAgency, province } 
        });
    }

    // --- Other Masters ---

    addResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData.push({ mainAgency, responsibleAgency, integrationArea });
        this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
        this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));
        this.saveToCache();

        this.sendToGas('MANAGE_MASTER', { 
            target: 'ResponsibleAgency', 
            type: 'add', 
            data: { mainAgency, responsibleAgency, integrationArea } 
        });
    }

    updateResponsibleAgency(mainAgency: string, oldResp: string, oldArea: string, newResp: string, newArea: string) {
        const index = this.respData.findIndex(r => r.mainAgency === mainAgency && r.responsibleAgency === oldResp && r.integrationArea === oldArea);
        if (index !== -1) {
            this.respData[index] = { mainAgency, responsibleAgency: newResp, integrationArea: newArea };
            this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
            this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'ResponsibleAgency', 
                type: 'update', 
                data: { mainAgency, responsibleAgency: newResp, integrationArea: newArea, oldResponsibleAgency: oldResp, oldIntegrationArea: oldArea } 
            });
        }
    }

    deleteResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData = this.respData.filter(r => !(r.mainAgency === mainAgency && r.responsibleAgency === responsibleAgency && r.integrationArea === integrationArea));
        this.dropdowns.responsibleAgency = Array.from(new Set(this.respData.map(r => r.responsibleAgency)));
        this.dropdowns.integrationArea = Array.from(new Set(this.respData.map(r => r.integrationArea)));
        this.saveToCache();

        this.sendToGas('MANAGE_MASTER', { 
            target: 'ResponsibleAgency', 
            type: 'delete', 
            data: { mainAgency, responsibleAgency, integrationArea } 
        });
    }

    addActivity(name: string) {
        if (!this.compareData.some(c => c.activity === name)) {
            const newId = name;
            this.compareData.push({ id: newId, activity: name, referenceBudget: 0 });
            this.dropdowns.activity = this.compareData.map(c => c.activity);
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'Compare', 
                type: 'add', 
                data: { activity: name, referenceBudget: 0 } 
            });
        }
    }

    updateActivity(oldName: string, newName: string) {
        const record = this.compareData.find(c => c.activity === oldName);
        if (record) {
            record.activity = newName;
            this.dropdowns.activity = this.compareData.map(c => c.activity);
            if (oldName !== newName) {
                this.records = this.records.map(r => r.activity === oldName ? { ...r, activity: newName } : r);
            }
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'Compare', 
                type: 'update', 
                data: { activity: newName, oldActivity: oldName, referenceBudget: record.referenceBudget } 
            });
        }
    }

    updateCompareData(id: string, newActivity: string, newBudget: number) {
        const index = this.compareData.findIndex(c => c.id === id);
        if (index !== -1) {
            const oldActivity = this.compareData[index].activity;
            this.compareData[index].activity = newActivity;
            this.compareData[index].referenceBudget = newBudget;

            if (oldActivity !== newActivity) {
                this.dropdowns.activity = this.compareData.map(c => c.activity);
                this.records = this.records.map(r => r.activity === oldActivity ? { ...r, activity: newActivity } : r);
            }
            this.saveToCache();

            this.sendToGas('MANAGE_MASTER', { 
                target: 'Compare', 
                type: 'update', 
                data: { activity: newActivity, oldActivity: oldActivity, referenceBudget: newBudget } 
            });
        }
    }

    deleteActivity(name: string) {
        this.compareData = this.compareData.filter(c => c.activity !== name);
        this.dropdowns.activity = this.compareData.map(c => c.activity);
        this.saveToCache();

        this.sendToGas('MANAGE_MASTER', { 
            target: 'Compare', 
            type: 'delete', 
            data: { activity: name } 
        });
    }

    addUnit(name: string) {
        if (!this.dropdowns.unit.includes(name)) {
            this.dropdowns.unit = [...this.dropdowns.unit, name];
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'add', data: { name } });
        }
    }

    updateUnit(oldName: string, newName: string) {
        this.dropdowns.unit = this.dropdowns.unit.map(u => u === oldName ? newName : u);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'update', data: { name: newName, oldName } });
    }

    deleteUnit(name: string) {
        this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'delete', data: { name } });
    }

    addIntegration(name: string) {
        if (!this.dropdowns.integration.includes(name)) {
            this.dropdowns.integration = [...this.dropdowns.integration, name];
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'add', data: { name } });
        }
    }

    updateIntegration(oldName: string, newName: string) {
        this.dropdowns.integration = this.dropdowns.integration.map(i => i === oldName ? newName : i);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'update', data: { name: newName, oldName } });
    }

    deleteIntegration(name: string) {
        this.dropdowns.integration = this.dropdowns.integration.filter(i => i !== name);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'delete', data: { name } });
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');

        try {
            const response = await fetch(settings.gasUrl);
            if (!response.ok) throw new Error(`Network response was not ok`);

            const json = await response.json();

            if (json.status === 'success' && json.data) {
                const serverData = json.data;
                const unique = (arr: any[]) => Array.from(new Set(arr.filter(item => item && typeof item === 'string' && item.trim() !== '')));

                const hierarchyRaw = serverData.hierarchy || [];
                const respDataRaw = serverData.respData || [];
                const compareDataRaw = serverData.compareData || [];

                this.dropdowns = {
                    ...this.dropdowns,
                    integration: serverData.dropdowns.integration || [],
                    unit: serverData.dropdowns.unit || [],
                    mainAgency: unique(hierarchyRaw.map((h: any) => h.mainAgency)),
                    province: unique(hierarchyRaw.map((h: any) => h.province)),
                    responsibleAgency: unique(respDataRaw.map((r: any) => r.responsibleAgency)),
                    integrationArea: unique(respDataRaw.map((r: any) => r.integrationArea)),
                    activity: unique(compareDataRaw.map((c: any) => c.activity))
                };

                this.hierarchy = hierarchyRaw;
                this.respData = respDataRaw;
                this.compareData = compareDataRaw;

                if (serverData.records && Array.isArray(serverData.records)) {
                    this.records = serverData.records.map((r: any) => this.normalizeRecord(r));
                }

                this.saveToCache();
                return;
            }
            throw new Error('Invalid data format from server');
        } catch (error: any) {
            console.error('Failed to sync data:', error);
            throw new Error(error.message || 'Failed to sync data');
        }
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const response = await fetch(settings.gasUrl);
            const json = await response.json();
            return json.status === 'success';
        } catch (error) {
            return false;
        }
    }
}

