            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name && name !== oldName) {
            dataService.updateUnit(oldName, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteUnit = async (name: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ต้องการลบหน่วยนับ "${name}" หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });

        if (result.isConfirmed) {
            dataService.deleteUnit(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบเรียบร้อยแล้ว', 'success');
        }
    };

    // --- CRUD Handlers for Integration ---
    const handleAddIntegration = async () => {
        const { value: name } = await Swal.fire({
            title: 'เพิ่มรายการบูรณาการ',
            input: 'text',
            inputLabel: 'ชื่อรายการ',
            inputPlaceholder: 'กรอกชื่อรายการ...',
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name) {
            dataService.addIntegration(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มรายการเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditIntegration = async (oldName: string) => {
        const { value: name } = await Swal.fire({
            title: 'แก้ไขชื่อรายการ',
            input: 'text',
            inputLabel: 'ชื่อรายการ',
            inputValue: oldName,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
        });

        if (name && name !== oldName) {
            dataService.updateIntegration(oldName, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteIntegration = async (name: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ต้องการลบรายการ "${name}" หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });

        if (result.isConfirmed) {
            dataService.deleteIntegration(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบเรียบร้อยแล้ว', 'success');
        }
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'hierarchy':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                            <h4 className="text-lg font-semibold text-slate-800 dark:text-white">ข้อมูลหน่วยงานหลักและจังหวัด ({hierarchy.length})</h4>
                            <button onClick={handleAddHierarchy} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มข้อมูล
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'หน่วยงานหลัก', 'จังหวัด', 'จัดการ']}
                            data={hierarchy.map((item, idx) => ({
                                columns: [idx + 1, item.mainAgency, item.province],
                                onEdit: () => handleEditHierarchy(item.mainAgency, item.province),
                                onDelete: () => handleDeleteHierarchy(item.mainAgency, item.province)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'responsible':
                const responsibles = selectedMainAgency 
                    ? respData.filter(r => r.mainAgency === selectedMainAgency)
                    : [];
                return (
                    <div className="space-y-6">
                        <div className="max-w-md">
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">เลือกหน่วยงานหลัก</label>
                            <select
                                value={selectedMainAgency}
                                onChange={(e) => setSelectedMainAgency(e.target.value)}
                                className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900"
                            >
                                <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                {dropdowns.mainAgency.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>

                        {selectedMainAgency && (
                             <div className="space-y-4">
                                <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                                    <h4 className="text-lg font-semibold text-slate-800 dark:text-white">รายการหน่วยงานบูรณาการ ({responsibles.length})</h4>
                                    <button onClick={handleAddResponsible} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                        <Plus size={16} /> เพิ่มหน่วยงานบูรณาการ
                                    </button>
                                </div>
                                <Table 
                                    headers={['หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'จัดการ']}
                                    data={responsibles.map((item, idx) => ({
                                        columns: [item.responsibleAgency, item.integrationArea],
                                        onEdit: () => handleEditResponsible(item.responsibleAgency, item.integrationArea),
                                        onDelete: () => handleDeleteResponsible(item.responsibleAgency, item.integrationArea)
                                    }))}
                                    hasActions
                                />
                            </div>
                        )}
                        {!selectedMainAgency && (
                            <div className="text-center py-10 text-slate-400 dark:text-slate-500">
                                <Users size={48} className="mx-auto mb-3 opacity-20" />
                                <p>กรุณาเลือกหน่วยงานหลักเพื่อจัดการข้อมูลหน่วยงานบูรณาการ</p>
                            </div>
                        )}
                    </div>
                );
            case 'integration':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-end">
                            <button onClick={handleAddIntegration} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มรายการบูรณาการ
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อรายการบูรณาการ', 'จัดการ']}
                            data={dropdowns.integration.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditIntegration(item),
                                onDelete: () => handleDeleteIntegration(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'activity':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-end">
                            <button onClick={handleAddActivity} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มกิจกรรม
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อกิจกรรม', 'จัดการ']}
                            data={dropdowns.activity.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditActivity(item),
                                onDelete: () => handleDeleteActivity(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'unit':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-end">
                            <button onClick={handleAddUnit} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มหน่วยนับ
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อหน่วยนับ', 'จัดการ']}
                            data={dropdowns.unit.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditUnit(item),
                                onDelete: () => handleDeleteUnit(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'fields':
                const fieldKeys = Object.keys(FIELD_LABELS);
                return (
                    <div className="space-y-4">
                        <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center mb-4">
                            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/50 rounded-xl p-4 flex-1">
                                <p className="text-sm text-blue-700 dark:text-blue-300 flex items-center gap-2">
                                    <Eye size={16} /> 
                                    <strong>คำแนะนำ:</strong> ฟิลด์ที่ถูกปิดการใช้งานจะถูกซ่อนในหน้าบันทึกข้อมูล และเมื่อกดบันทึก ข้อมูลในฟิลด์นั้นจะถูกเคลียร์เป็นค่าว่างหรือ 0
                                </p>
                            </div>
                            <div className="flex gap-2 shrink-0">
                                <button
                                    onClick={() => handleSetAllFields(true)}
                                    className="px-4 py-2 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-lg text-sm font-medium hover:bg-emerald-200 dark:hover:bg-emerald-900/50 transition-colors flex items-center gap-2"
                                >
                                    <Eye size={16} /> แสดงทุกฟิลด์
                                </button>
                                <button
                                    onClick={() => handleSetAllFields(false)}
                                    className="px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-sm font-medium hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors flex items-center gap-2"
                                >
                                    <EyeOff size={16} /> ซ่อนทุกฟิลด์
                                </button>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {fieldKeys.map((key) => (
                                <div key={key} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${fieldVisibility[key] ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 opacity-70'}`}>
                                    <span className="font-medium text-slate-700 dark:text-slate-300">{FIELD_LABELS[key]}</span>
                                    <button
                                        onClick={() => handleToggleField(key)}
                                        className={`p-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium ${fieldVisibility[key] ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' : 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400'}`}
                                    >
                                        {fieldVisibility[key] ? (
                                            <>
                                                <ToggleRight size={20} /> แสดง
                                            </>
                                        ) : (
                                            <>
                                                <ToggleLeft size={20} /> ซ่อน
                                            </>
                                        )}
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                );
            default:
                return null;
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">จัดการข้อมูลตัวเลือก</h2>
                    <p className="text-slate-500 dark:text-slate-400 transition-colors">จัดการข้อมูล Dropdown ในระบบและซิงค์ข้อมูลจาก Google Sheets</p>
                </div>
                <button 
                    onClick={handleRefresh}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-medium text-sm disabled:opacity-70 disabled:cursor-not-allowed`}
                >
                    <RefreshCw size={16} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูลจาก Sheets'}
                </button>
            </div>

            <div className="flex flex-col lg:flex-row gap-6">
                {/* Sidebar Navigation */}
                <div className="w-full lg:w-64 flex-shrink-0">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-2 overflow-hidden sticky top-24">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-all duration-200 mb-1 last:mb-0 ${
                                    activeTab === tab.id 
                                    ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 font-semibold shadow-sm' 
                                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700/50 hover:text-emerald-600 dark:hover:text-emerald-400'
                                }`}
                            >
                                {tab.icon}
                                <span>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Area */}
                <div className="flex-1 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-6 min-h-[500px]">
                    <div className="flex items-center gap-2 mb-6 pb-4 border-b border-slate-100 dark:border-slate-700">
                        <FileSpreadsheet className="text-emerald-500" />
                        <h3 className="text-lg font-bold text-slate-700 dark:text-slate-200">
                            ข้อมูล: <span className="text-emerald-600 dark:text-emerald-400">{tabs.find(t => t.id === activeTab)?.label}</span>
                        </h3>
                    </div>
                    {renderContent()}
                </div>
            </div>
        </div>
    );
};

interface TableProps {
    headers: string[];
    data: {
        columns: (string | number)[];
        onEdit?: () => void;
        onDelete?: () => void;
    }[];
    hasActions?: boolean;
}

const Table = ({ headers, data, hasActions = false }: TableProps) => (
    <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-700">
        <table className="w-full text-left border-collapse">
            <thead>
                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                    {headers.map((h, i) => (
                        <th key={i} className="px-6 py-4 text-sm font-semibold text-slate-600 dark:text-slate-300 whitespace-nowrap">
                            {h}
                        </th>
                    ))}
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700 bg-white dark:bg-slate-800">
                {data.length > 0 ? data.map((row, i) => (
                    <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                        {row.columns.map((cell, j) => (
                            <td key={j} className="px-6 py-3 text-slate-700 dark:text-slate-300 text-sm">
                                {cell}
                            </td>
                        ))}
                        {hasActions && (
                            <td className="px-6 py-3 text-right w-32">
                                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={row.onEdit} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="แก้ไข">
                                        <Edit2 size={16} />
                                    </button>
                                    <button onClick={row.onDelete} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors" title="ลบ">
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </td>
                        )}
                    </tr>
                )) : (
                    <tr>
                        <td colSpan={headers.length} className="px-6 py-8 text-center text-slate-400">
                            ไม่พบข้อมูล
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
    </div>
);

export default ManageView;

