### 2. Google Apps Script (GAS) Code

โปรดคัดลอกโค้ดนี้ไปแทนที่ในไฟล์ `Code.gs` บน Google Apps Script ของคุณครับ

โค้ดนี้รองรับ:
-   **Hierarchy**: จัดการ Main Agency + Province ในชีทเดียว
-   **Duplicates**: ป้องกันข้อมูลซ้ำซ้อน
-   **CRUD**: เพิ่ม/ลบ/แก้ไข ครบทุกฟังก์ชัน

```javascript
/* 
  Budget Plan Management System - Google Apps Script
  Updated to support Hierarchy (MainAgency + Province) pairing
*/

const SCRIPT_PROP = PropertiesService.getScriptProperties();

// Configuration: Sheet Names
const SHEET_DB = 'Database';
const SHEET_DATA = 'Database'; // Settings/Master Data Sheet Name

// --- MAIN DO GET ---
function doGet(e) {
  return handleRequest(e);
}

// --- MAIN DO POST ---
function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const params = e.parameter.action ? e.parameter : JSON.parse(e.postData.contents);
    const doc = SpreadsheetApp.getActiveSpreadsheet();

    // 1. GET ALL DATA (Sync)
    if (!params.action || params.action === 'GET_ALL') {
      const data = getAllData(doc);
      return jsonResponse({ status: 'success', data: data });
    }

    // 2. MANAGE RECORD (Add/Update/Delete Budget Record)
    if (params.action === 'MANAGE_RECORD') {
      const result = manageRecord(doc, params);
      return jsonResponse(result);
    }

    // 3. MANAGE MASTER DATA (Dropdowns)
    if (params.action === 'MANAGE_MASTER') {
      const result = manageMasterData(doc, params);
      return jsonResponse(result);
    }

    return jsonResponse({ status: 'error', message: 'Invalid Action' });

  } catch (e) {
    return jsonResponse({ status: 'error', message: e.toString() });
  } finally {
    lock.releaseLock();
  }
}

// --- HELPER FUNCTIONS ---

function jsonResponse(data) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// Get Sheet Data as Array of Objects
function getSheetData(sheet) {
  if (!sheet) return [];
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return []; // Only header or empty
  const headers = rows[0];
  const data = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
    }
    data.push(obj);
  }
  return data;
}

// --- CORE LOGIC ---

function getAllData(doc) {
  // 1. Get Database Records
  const dbSheet = doc.getSheetByName(SHEET_DB);
  const records = getSheetData(dbSheet);

  // 2. Get Master Data Sheets
  // Define Master Sheets (Create if not exist manually or handling errors)
  const hierarchySheet = doc.getSheetByName('Hierarchy');
  const respSheet = doc.getSheetByName('ResponsibleAgency');
  const compareSheet = doc.getSheetByName('Compare');
  const unitSheet = doc.getSheetByName('Unit');
  const integSheet = doc.getSheetByName('Integration');

  // Helper to extract column data
  const getCol = (sheet, colIndex) => {
    if (!sheet) return [];
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) return [];
    const vals = sheet.getRange(2, colIndex, lastRow - 1, 1).getValues();
    return vals.flat().filter(String); // Remove empty
  };

  const getTable = (sheet) => getSheetData(sheet);

  // Construct Response
  return {
    records: records,
    dropdowns: {
      integration: getCol(integSheet, 1).sort(),
      unit: getCol(unitSheet, 1).sort(),
      // Derived dropdowns will be handled by client, or we can send raw lists
      activity: getCol(compareSheet, 2).sort() // Activity name is col 2
    },
    hierarchy: getTable(hierarchySheet), // [{MainAgency, Province}, ...]
    respData: getTable(respSheet), // [{MainAgency, ResponsibleAgency, IntegrationArea}, ...]
    compareData: getTable(compareSheet) // [{ID, Activity, ReferenceBudget}, ...]
  };
}


function manageRecord(doc, params) {
  const sheet = doc.getSheetByName(SHEET_DB);
  if (!sheet) return { status: 'error', message: 'Sheet Database not found' };

  const type = params.type; // add, update, delete
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  if (type === 'add') {
    const data = params.data;
    const row = headers.map(h => data[h] || '');
    // Ensure ID is unique/present if needed, but client sends ID
    sheet.appendRow(row);
    return { status: 'success', message: 'Added' };
  }

  if (type === 'update') {
    const data = params.data;
    const id = data.id;
    const dataRange = sheet.getDataRange();
    const values = dataRange.getValues();
    const idIndex = headers.indexOf('id'); // Case sensitive? assuming lowercase 'id' from client matches header

    // Find row by ID
    for (let i = 1; i < values.length; i++) {
      if (String(values[i][idIndex]) === String(id)) {
        const newRow = headers.map(h => data[h] !== undefined ? data[h] : values[i][headers.indexOf(h)]);
        sheet.getRange(i + 1, 1, 1, headers.length).setValues([newRow]);
        return { status: 'success', message: 'Updated' };
      }
    }
    return { status: 'error', message: 'ID not found' };
  }

  if (type === 'delete') {
    const id = params.id;
    const dataRange = sheet.getDataRange();
    const values = dataRange.getValues();
    const idIndex = headers.indexOf('id');

    for (let i = 1; i < values.length; i++) {
      if (String(values[i][idIndex]) === String(id)) {
        sheet.deleteRow(i + 1);
        return { status: 'success', message: 'Deleted' };
      }
    }
    return { status: 'error', message: 'ID not found' };
  }
}

function manageMasterData(doc, params) {
  const target = params.target; // Hierarchy, ResponsibleAgency, Compare, Unit, Integration
  const type = params.type; // add, update, delete
  const sheet = doc.getSheetByName(target);

  if (!sheet) return { status: 'error', message: `Sheet ${target} not found` };

  // --- HIERARCHY (MainAgency + Province) ---
  if (target === 'Hierarchy') {
    const data = params.data;
    const rows = sheet.getDataRange().getValues();

    if (type === 'add') {
      // Check duplicate
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.mainAgency && rows[i][1] == data.province) {
          return { status: 'success', message: 'Duplicate, skipped' };
        }
      }
      sheet.appendRow([data.mainAgency, data.province]);
      return { status: 'success' };
    }

    if (type === 'update') {
      for (let i = 1; i < rows.length; i++) {
        // Find by OLD values
        if (rows[i][0] == data.oldMainAgency && rows[i][1] == data.oldProvince) {
          sheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
          return { status: 'success' };
        }
      }
    }

    if (type === 'delete') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.mainAgency && rows[i][1] == data.province) {
          sheet.deleteRow(i + 1);
          return { status: 'success' };
        }
      }
    }
  }

  // --- RESPONSIBLE AGENCY ---
  if (target === 'ResponsibleAgency') {
    const data = params.data;
    const rows = sheet.getDataRange().getValues(); // Cols: MainAgency, ResponsibleAgency, IntegrationArea

    if (type === 'add') {
      sheet.appendRow([data.mainAgency, data.responsibleAgency, data.integrationArea]);
      return { status: 'success' };
    }
    if (type === 'update') {
      for (let i = 1; i < rows.length; i++) {
        // Identify record by Main + Resp + Area (Old)
        if (rows[i][0] == data.mainAgency && rows[i][1] == data.oldResponsibleAgency && rows[i][2] == data.oldIntegrationArea) {
          sheet.getRange(i + 1, 2, 1, 2).setValues([[data.responsibleAgency, data.integrationArea]]);
          return { status: 'success' };
        }
      }
    }
    if (type === 'delete') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.mainAgency && rows[i][1] == data.responsibleAgency && rows[i][2] == data.integrationArea) {
          sheet.deleteRow(i + 1);
          return { status: 'success' };
        }
      }
    }
  }

  // --- COMPARE (Activity) ---
  if (target === 'Compare') {
    const data = params.data; // {activity, referenceBudget, oldActivity...}
    const rows = sheet.getDataRange().getValues(); // Cols: id, activity, referenceBudget

    if (type === 'add') {
      // ID is Activity Name for simplicity in this logic, or generate one
      sheet.appendRow([data.activity, data.activity, data.referenceBudget]); 
      return { status: 'success' };
    }
    if (type === 'update') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][1] == data.oldActivity) {
          sheet.getRange(i + 1, 2, 1, 2).setValues([[data.activity, data.referenceBudget]]);
          return { status: 'success' };
        }
      }
    }
    if (type === 'delete') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][1] == data.activity) {
          sheet.deleteRow(i + 1);
          return { status: 'success' };
        }
      }
    }
  }

  // --- UNIT & INTEGRATION (Simple Lists) ---
  if (target === 'Unit' || target === 'Integration') {
    const data = params.data;
    const rows = sheet.getDataRange().getValues(); // Col 1 is name

    if (type === 'add') {
      sheet.appendRow([data.name]);
      return { status: 'success' };
    }
    if (type === 'update') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.oldName) {
          sheet.getRange(i + 1, 1).setValue(data.name);
          return { status: 'success' };
        }
      }
    }
    if (type === 'delete') {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.name) {
          sheet.deleteRow(i + 1);
          return { status: 'success' };
        }
      }
    }
  }

  return { status: 'error', message: 'Target not handled' };
}

