        if (!dateString) return '-';

        // Try to parse as standard Date object first
        const date = new Date(dateString);
        if (!isNaN(date.getTime())) {
            return date.toLocaleDateString('th-TH', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
            });
        }

        // Fallback: If it's already a string like "26/12/2568 10:00:00" or similar
        const parts = dateString.split(' ');
