                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">ค่าจ้างเหมา</Th>
                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">ค่าสาธารณูปโภค</Th>

                                {/* Investment */}
                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">ค่าครุภัณฑ์</Th>
                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">ที่ดิน/สิ่งก่อสร้าง</Th>

                                {/* Other */}
                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">เงินอุดหนุน</Th>
                                <Th width="120px" align="center" className="border-t border-slate-300 dark:border-slate-700">รายจ่ายอื่น</Th>
                            </tr>
                        </thead>
                        <tbody className="bg-white dark:bg-slate-800 divide-y divide-slate-100 dark:divide-slate-700">
                            {paginatedRecords.length > 0 ? paginatedRecords.map((r) => (
                                <tr key={r.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-700/50 transition-colors group">
                                    <DataCell text={r.integration} />
                                    <DataCell text={r.mainAgency} />
                                    <DataCell text={r.province} />
