                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Bottom Pagination */}
                <PaginationControls isTop={false} />
            </div>
        </div>
    );
};

// Resizable Header Component with rowspan/colspan support
const Th = ({ children, align = 'left', width, isStickyRight = false, rowSpan, colSpan, className = '' }: { children?: React.ReactNode, align?: 'left'|'right'|'center', width?: string, isStickyRight?: boolean, rowSpan?: number, colSpan?: number, className?: string }) => (
    <th 
        rowSpan={rowSpan}
        colSpan={colSpan}
        className={`px-4 py-4 text-${align} text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-r border-slate-300 dark:border-slate-700 last:border-r-0 relative group ${isStickyRight ? 'sticky right-0 z-20 bg-slate-200 dark:bg-slate-950 shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.05)] dark:shadow-[-4px_0_8px_-2px_rgba(0,0,0,0.2)]' : ''} ${className}`}
        style={{ width: width, minWidth: isStickyRight ? 'auto' : (colSpan && colSpan > 1 ? 'auto' : '100px'), resize: isStickyRight ? 'none' : 'horizontal', overflow: isStickyRight ? 'visible' : 'auto' }}
    >
        <div className={`flex items-center w-full h-full ${align === 'center' ? 'justify-center' : ''}`}>
            <span className="truncate w-full">{children}</span>
        </div>
    </th>
);

// Data Cell with Tooltip and Truncation
const DataCell = ({ text, align = 'left', isNumber = false }: { text: string | number, align?: 'left'|'right'|'center', isNumber?: boolean }) => {
    return (
        <td className={`px-4 py-3 border-b border-r border-slate-100 dark:border-slate-700 last:border-r-0 text-sm text-${align} text-slate-700 dark:text-slate-200 ${isNumber ? 'font-mono' : ''}`}>
            <div className="w-full truncate" title={String(text)}>
                {text || '-'}
            </div>
        </td>
    );
};

const SummaryCard = ({ title, amount, color, icon, isTotal = false }: any) => {
    const colorClasses: Record<string, string> = {
        blue: 'bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 border-blue-100 dark:border-blue-900/50',
        emerald: 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 border-emerald-100 dark:border-emerald-900/50',
        amber: 'bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300 border-amber-100 dark:border-amber-900/50',
        purple: 'bg-purple-50 dark:bg-purple-900/20 text-purple-700 dark:text-purple-300 border-purple-100 dark:border-purple-900/50',
        slate: 'bg-slate-800 dark:bg-slate-700 text-white border-slate-700 shadow-lg',
    };

    return (
        <div className={`rounded-2xl p-5 border ${colorClasses[color]} flex flex-col justify-between h-full transition-transform hover:-translate-y-1 duration-300`}>
            <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-bold uppercase tracking-wider ${isTotal ? 'text-slate-400' : 'opacity-70'}`}>{title}</span>
                <div className={`p-1.5 rounded-lg ${isTotal ? 'bg-slate-700 text-emerald-400' : 'bg-white/50 dark:bg-black/20'}`}>
                    {icon}
                </div>
            </div>
            <p className={`font-bold ${isTotal ? 'text-3xl' : 'text-2xl'}`}>{formatNumber(amount)}</p>
        </div>
    );
};

export default DatabaseView;

import React, { useState, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale, Edit2, RefreshCw } from 'lucide-react';
import Swal from 'sweetalert2';
import { CompareRecord } from '../../types';

const CompareView: React.FC = () => {
    const [refreshTrigger, setRefreshTrigger] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Get Data
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = records.reduce((acc, r) => {
        const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                      (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                      (r.equipment || 0) + (r.landConstruction || 0) +
                      (r.subsidies || 0) + (r.otherExpenses || 0);
        acc[r.activity] = (acc[r.activity] || 0) + total;
        return acc;
    }, {} as Record<string, number>);

    const comparisonResults = compareTargets.map(target => {
        const actual = actualsByActivity[target.activity] || 0;
        const variance = actual - target.referenceBudget;
        let status = 'match';

        // Logic check: if actual is 0 and ref > 0, treating as 'nodata' usually means we haven't started. 
        // If you want to treat it as 'under' (red), change logic here. Keeping 'nodata' as distinct state for now.
        if (actual === 0 && target.referenceBudget > 0) status = 'nodata';
        else if (actual === 0 && target.referenceBudget === 0) status = 'nodata';
        else if (variance > 0) status = 'over';
        else if (variance < 0) status = 'under';

        return { ...target, actual, variance, status };
    });

    const totalRef = comparisonResults.reduce((sum, r) => sum + r.referenceBudget, 0);
    const totalAct = comparisonResults.reduce((sum, r) => sum + r.actual, 0);
    const totalVar = totalAct - totalRef;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลล่าสุดเรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error: any) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'ไม่สามารถดึงข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleEdit = async (record: CompareRecord) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูลกิจกรรม',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">ชื่อกิจกรรม</div>' +
                `<input id="swal-input-activity" class="swal2-input" placeholder="ชื่อกิจกรรม" value="${record.activity}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">งบอ้างอิง (บาท)</div>' +
                `<input id="swal-input-budget" type="text" class="swal2-input" placeholder="งบประมาณ" value="${formatNumber(record.referenceBudget)}" style="margin: 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-top: 0.25rem; font-size: 0.875rem; color: #6b7280;">* ใส่ลูกน้ำ (,) เพื่อให้อ่านง่าย</div>',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            didOpen: () => {
                const input = Swal.getPopup()?.querySelector('#swal-input-budget') as HTMLInputElement;
                if (input) {
                    input.addEventListener('input', (e) => {
                        let val = (e.target as HTMLInputElement).value.replace(/[^0-9.]/g, '');
                        // Prevent multiple dots
                        const parts = val.split('.');
                        if (parts.length > 2) val = parts[0] + '.' + parts.slice(1).join('');

                        if (val) {
                            const numberParts = val.split('.');
                            numberParts[0] = numberParts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
                            (e.target as HTMLInputElement).value = numberParts.join('.');
                        } else {
                            (e.target as HTMLInputElement).value = '';
                        }
                    });
                }
            },
            preConfirm: () => {
                const activity = (document.getElementById('swal-input-activity') as HTMLInputElement).value;
                const budgetStr = (document.getElementById('swal-input-budget') as HTMLInputElement).value;
                if (!activity) {
                    Swal.showValidationMessage('กรุณาระบุชื่อกิจกรรม');
                }
                const budget = parseFloat(budgetStr.replace(/,/g, '')) || 0;
                return {
                    activity: activity,
                    budget: budget
                };
            }
        });

        if (formValues) {
            dataService.updateCompareData(record.id, formValues.activity, formValues.budget);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">เปรียบเทียบงบประมาณ</h2>
                    <p className="text-slate-500 dark:text-slate-400 transition-colors">วิเคราะห์ความแตกต่างระหว่างงบประมาณที่ตั้งไว้และงบที่ใช้จริง</p>
                </div>
                <button 
                    onClick={handleSync}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-5 py-2.5 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors font-medium text-base shadow-sm disabled:opacity-70 disabled:cursor-not-allowed`}
                >
                    <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูล'}
                </button>
            </div>

            {/* Summary */}
             <div className="grid md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">งบอ้างอิงรวม</p>
                        <p className="text-2xl font-bold text-blue-600 dark:text-blue-400">{formatNumber(totalRef)}</p>
                    </div>
                    <div className="p-3 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl">
                        <Target size={24} />
                    </div>
                </div>
                 <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">งบที่บันทึกรวม</p>
                        <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{formatNumber(totalAct)}</p>
                    </div>
                    <div className="p-3 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl">
                        <TrendingUp size={24} />
                    </div>
                </div>
                 <div className={`p-6 rounded-2xl shadow-sm border flex items-center justify-between transition-colors ${
                     totalVar > 0 
                     ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-100 dark:border-amber-900/50' 
                     : totalVar < 0 
                        ? 'bg-red-50 dark:bg-red-900/20 border-red-100 dark:border-red-900/50'
                        : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-900/50'
                 }`}>
                    <div>
                        <p className={`text-sm font-medium mb-1 ${
                            totalVar > 0 ? 'text-amber-700 dark:text-amber-400' 
                            : totalVar < 0 ? 'text-red-700 dark:text-red-400'
                            : 'text-emerald-700 dark:text-emerald-400'
                        }`}>ส่วนต่างรวม</p>
                        <p className={`text-2xl font-bold ${
                            totalVar > 0 ? 'text-amber-700 dark:text-amber-400' 
                            : totalVar < 0 ? 'text-red-700 dark:text-red-400'
                            : 'text-emerald-700 dark:text-emerald-400'
                        }`}>
                            {totalVar > 0 ? '+' : ''}{formatNumber(totalVar)}
                        </p>
                    </div>
                    <div className={`p-3 rounded-xl ${
                        totalVar > 0 ? 'bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400' 
                        : totalVar < 0 ? 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-400'
                        : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400'
                    }`}>
                        <Scale size={24} />
                    </div>
                </div>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-slate-100 dark:divide-slate-700">
                        <thead className="bg-slate-200 dark:bg-slate-950">
                            <tr>
                                <th className="px-6 py-4 text-left text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">กิจกรรม</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">งบอ้างอิง</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">งบที่บันทึก</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">ส่วนต่าง</th>
                                <th className="px-6 py-4 text-center text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">สถานะ</th>
                                <th className="px-6 py-4 text-center text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider border-b border-slate-300 dark:border-slate-700">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
                            {comparisonResults.map(res => (
                                <tr key={res.id} className={`transition-colors group ${
                                    res.status === 'over' 
                                        ? 'bg-amber-50 dark:bg-amber-900/20 hover:bg-amber-100 dark:hover:bg-amber-900/30' 
                                        : res.status === 'under' 
                                            ? 'bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/30'
                                            : res.status === 'match'
                                                ? 'bg-emerald-50 dark:bg-emerald-900/10 hover:bg-emerald-100 dark:hover:bg-emerald-900/20'
                                                : 'hover:bg-slate-50/50 dark:hover:bg-slate-700/50'
                                }`}>
                                    <td className="px-6 py-5 text-base font-medium text-slate-700 dark:text-slate-200">{res.activity}</td>
                                    <td className="px-6 py-5 text-base text-slate-600 dark:text-slate-400 text-right">{formatNumber(res.referenceBudget)}</td>
                                    <td className="px-6 py-5 text-base text-slate-900 dark:text-slate-100 text-right font-medium">{formatNumber(res.actual)}</td>
                                    <td className={`px-6 py-5 text-base text-right font-bold ${
                                        res.variance > 0 ? 'text-amber-700 dark:text-amber-400' 
                                        : res.variance < 0 ? 'text-red-700 dark:text-red-400' 
                                        : 'text-slate-400'
                                    }`}>
                                        {res.variance > 0 ? '+' : ''}{formatNumber(res.variance)}
                                    </td>
                                    <td className="px-6 py-5 text-base text-center">
                                        {res.status === 'nodata' && <span className="px-3 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-300 rounded-full text-xs font-medium">ไม่มีข้อมูล</span>}
                                        {res.status === 'over' && <span className="px-3 py-1 bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400 rounded-full text-xs font-bold">เกินงบ</span>}
                                        {res.status === 'under' && <span className="px-3 py-1 bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-400 rounded-full text-xs font-bold">ต่ำกว่างบ</span>}
                                        {res.status === 'match' && <span className="px-3 py-1 bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400 rounded-full text-xs font-bold">ตรงตามงบ</span>}
                                    </td>
                                    <td className="px-6 py-5 text-base text-center">
                                        <button 
                                            onClick={() => handleEdit(res)}
                                            className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors"
                                            title="แก้ไข"
                                        >
                                            <Edit2 size={18} />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

