                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {fieldKeys.map((key) => (
                                <div key={key} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${fieldVisibility[key] ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 opacity-70'}`}>
