                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action, ...payload })
            });
        } catch (e) {
            console.error('API Error:', e);
        }
    }

    // --- Data Normalization ---
    private normalizeRecord(raw: any): BudgetRecord {
        const find = (keys: string[]) => {
             for (const k of keys) {
                 if (raw[k] !== undefined && raw[k] !== null) return raw[k];
             }
             const rawKeys = Object.keys(raw);
             for (const k of keys) {
                 const match = rawKeys.find(rk => rk.toLowerCase() === k.toLowerCase());
                 if (match) return raw[match];
             }
             return undefined;
        };

        const getNum = (keys: string[]) => {
            const val = find(keys);
            if (typeof val === 'number') return val;
            return parseNumber(String(val || 0));
        };

        return {
            id: String(find(['id', 'ID', 'Id', 'ลำดับ', 'รหัส', 'no', 'No']) || raw.id || ''),
            integration: String(find(['integration', 'Integration', 'บูรณาการ', 'ประเภทหน่วยงาน']) || ''),
