ใช่ครับ **จำเป็นต้องแก้ไขโค้ด Google Apps Script (GAS)** ให้รองรับการทำงานแบบใหม่ครับ

เนื่องจากผมได้ปรับปรุงระบบฝั่งหน้าเว็บ (Frontend) ให้ส่งข้อมูลแบบ `POST` แทน `GET` เพื่อความเสถียรและรองรับข้อมูลจำนวนมากได้ดีขึ้น ดังนั้นฝั่ง Server (GAS) ต้องมีฟังก์ชัน `doPost(e)` เพื่อรับและประมวลผลคำสั่งครับ

คุณสามารถ **คัดลอกโค้ดด้านล่างนี้** ไปทับโค้ดเดิมใน Google Apps Script ได้เลยครับ

### โค้ด Google Apps Script (`Code.gs`)

```javascript
// ตั้งค่าชื่อ Sheet ให้ตรงกับที่คุณสร้างไว้
const SHEETS = {
  DB: 'Database',      // เก็บข้อมูลงบประมาณ
  HIERARCHY: 'Hierarchy', // เก็บหน่วยงานหลัก-จังหวัด
  RESP: 'Responsible',    // เก็บหน่วยงานบูรณาการ
  COMPARE: 'Compare',     // เก็บข้อมูลเปรียบเทียบ (กิจกรรม-งบ)
  OPTIONS: 'Options'      // เก็บตัวเลือกอื่นๆ (Integration, Unit)
};

function doPost(e) {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000); // รอ Lock สูงสุด 30 วินาทีป้องกันข้อมูลชนกัน

    const jsonString = e.postData.contents;
    const params = JSON.parse(jsonString);
    const action = params.action;

    let result = {};

    if (action === 'TEST_CONNECTION') {
      result = { status: 'success', message: 'Connection established' };
    } 
    else if (action === 'GET_DATA') {
      result = getAllData();
    }
    else if (action === 'MANAGE_RECORD') {
      result = manageRecord(params);
    }
    else if (action === 'MANAGE_MASTER') {
      result = manageMaster(params);
    }
    else {
      throw new Error('Unknown action: ' + action);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  // รองรับการกด Test URL ผ่าน Browser
  return ContentService.createTextOutput(JSON.stringify({
    status: 'success',
    message: 'Service is running. Please use POST method for operations.'
  })).setMimeType(ContentService.MimeType.JSON);
}

// --- Functions จัดการข้อมูล ---

function getAllData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. Get Records
  const dbSheet = getOrCreateSheet(ss, SHEETS.DB);
  const records = getDataFromSheet(dbSheet);

  // 2. Get Hierarchy
  const hierarchySheet = getOrCreateSheet(ss, SHEETS.HIERARCHY);
  const hierarchy = getDataFromSheet(hierarchySheet);

  // 3. Get Responsible
  const respSheet = getOrCreateSheet(ss, SHEETS.RESP);
  const respData = getDataFromSheet(respSheet);

  // 4. Get Compare
  const compareSheet = getOrCreateSheet(ss, SHEETS.COMPARE);
  const compareData = getDataFromSheet(compareSheet).map(r => ({
    ...r,
    referenceBudget: Number(r.referenceBudget || 0)
  }));

  // 5. Get Options
  const optSheet = getOrCreateSheet(ss, SHEETS.OPTIONS);
  const optData = getDataFromSheet(optSheet);

  const dropdowns = {
    integration: optData.map(r => r.integration).filter(Boolean),
    unit: optData.map(r => r.unit).filter(Boolean)
  };

  return {
    status: 'success',
    data: {
      records: records,
      hierarchy: hierarchy,
      respData: respData,
      compareData: compareData,
      dropdowns: dropdowns
    }
  };
}

function manageRecord(params) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = getOrCreateSheet(ss, SHEETS.DB);
  const type = params.type;
  const data = params.data; // สำหรับ add/update
  const id = params.id || (data ? data.id : null);

  const headers = getHeaders(sheet);

  if (type === 'add') {
    const row = headers.map(h => data[h] || '');
    sheet.appendRow(row);
  } 
  else if (type === 'update') {
    const dataRef = sheet.getDataRange().getValues();
    // สมมติคอลัมน์แรกเป็น ID (index 0)
    // headers[0] ควรเป็น 'id'
    const idIndex = headers.indexOf('id');
    if (idIndex === -1) throw new Error("ID column not found");

    // หาแถวที่ตรงกัน (เริ่มที่ row 2 เพราะ row 1 คือ header)
    for (let i = 1; i < dataRef.length; i++) {
      if (String(dataRef[i][idIndex]) === String(id)) {
        const row = headers.map(h => data[h] === undefined ? dataRef[i][headers.indexOf(h)] : data[h]);
        sheet.getRange(i + 1, 1, 1, row.length).setValues([row]);
        break;
      }
    }
  } 
  else if (type === 'delete') {
    const dataRef = sheet.getDataRange().getValues();
    const idIndex = headers.indexOf('id');
    for (let i = 1; i < dataRef.length; i++) {
      if (String(dataRef[i][idIndex]) === String(id)) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  }

  return { status: 'success' };
}

function manageMaster(params) {
  const target = params.target; // Hierarchy, ResponsibleAgency, Compare, Unit, Integration
  const type = params.type; // add, update, delete
  const data = params.data;

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheetName, keyField;

  if (target === 'Hierarchy') {
    sheetName = SHEETS.HIERARCHY;
  } else if (target === 'ResponsibleAgency') {
    sheetName = SHEETS.RESP;
  } else if (target === 'Compare') {
    sheetName = SHEETS.COMPARE;
  } else if (target === 'Unit' || target === 'Integration') {
    sheetName = SHEETS.OPTIONS;
  }

  const sheet = getOrCreateSheet(ss, sheetName);
  const headers = getHeaders(sheet);

  // Logic การจัดการจะคล้ายๆ manageRecord แต่ไม่มี ID กลาง ต้องเช็คตาม Key
  // เพื่อความง่าย ให้ลบแล้วเพิ่มใหม่ หรือค้นหาตาม Key ของแต่ละตาราง
  // ในที่นี้เขียนแบบง่ายคือการ Append สำหรับ Add 
  // การ Update/Delete ต้องค้นหา Row ให้เจอ

  const allValues = sheet.getDataRange().getValues();

  if (type === 'add') {
    if (target === 'Unit' || target === 'Integration') {
       // หาคอลัมน์ที่ว่างหรือต่อท้าย
       const colIndex = headers.indexOf(target === 'Unit' ? 'unit' : 'integration');
       // เนื่องจาก Options เก็บหลายคอลัมน์อิสระ ต้องหาแถวแรกที่ว่างในคอลัมน์นั้น
       const lastRow = sheet.getLastRow();
       // วิธีง่ายสุดคือ appendRow แต่จะทำให้คอลัมน์อื่นเป็นว่าง
       // หรือเขียนฟังก์ชันเฉพาะ
       // เพื่อความง่าย ให้ frontend ส่ง array เต็มมาทับ หรือใช้วิธี appendRow ปกติ
       // สำหรับเคสนี้ขอทำแบบ Append row ปกติโดย map header
       const row = headers.map(h => {
           if (target === 'Unit' && h === 'unit') return data.name;
           if (target === 'Integration' && h === 'integration') return data.name;
           return '';
       });
       sheet.appendRow(row);
    } else {
       const row = headers.map(h => data[h] || '');
       sheet.appendRow(row);
    }
  } else if (type === 'delete' || type === 'update') {
      // Logic การค้นหาแถวเพื่อลบหรือแก้ไข
      // ต้อง Implement ตาม Key ของแต่ละ Table
      // เช่น Hierarchy ใช้ mainAgency + province เป็น Key
      for (let i = 1; i < allValues.length; i++) {
          let match = false;
          if (target === 'Hierarchy') {
             match = allValues[i][headers.indexOf('mainAgency')] == (data.oldMainAgency || data.mainAgency) && 
                     allValues[i][headers.indexOf('province')] == (data.oldProvince || data.province);
          } else if (target === 'ResponsibleAgency') {
             match = allValues[i][headers.indexOf('mainAgency')] == data.mainAgency && 
                     allValues[i][headers.indexOf('responsibleAgency')] == (data.oldResponsibleAgency || data.responsibleAgency) &&
                     allValues[i][headers.indexOf('integrationArea')] == (data.oldIntegrationArea || data.integrationArea);
          } else if (target === 'Compare') {
             match = allValues[i][headers.indexOf('activity')] == (data.oldActivity || data.activity);
          } else if (target === 'Unit') {
             match = allValues[i][headers.indexOf('unit')] == (data.oldName || data.name);
          } else if (target === 'Integration') {
             match = allValues[i][headers.indexOf('integration')] == (data.oldName || data.name);
          }

          if (match) {
              if (type === 'delete') {
                  sheet.deleteRow(i + 1);
                  // ถ้าเป็น Options อาจจะแค่เคลียร์เซลล์ถ้าต้องการเก็บข้อมูลคอลัมน์ข้างๆไว้
                  // แต่ถ้าง่ายสุดคือ Delete Row (ระวังข้อมูลข้างเคียงหายถ้าออกแบบไม่ดี)
                  // แนะนำแยก Sheet : UnitSheet, IntegrationSheet จะดีสุด
              } else if (type === 'update') {
                  const newRow = headers.map(h => data[h] === undefined ? allValues[i][headers.indexOf(h)] : data[h]);
                  // พิเศษสำหรับ unit/integration ที่ data.name แมพเข้าฟิลด์
                  if (target === 'Unit') newRow[headers.indexOf('unit')] = data.name;
                  if (target === 'Integration') newRow[headers.indexOf('integration')] = data.name;

                  sheet.getRange(i + 1, 1, 1, newRow.length).setValues([newRow]);
              }
              break;
          }
      }
  }

  return { status: 'success' };
}

// --- Helper Functions ---

function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    // สร้าง Header เริ่มต้นให้ถ้าเพิ่งสร้างใหม่
    let headers = [];
    if (name === SHEETS.DB) {
      headers = ['id', 'integration', 'mainAgency', 'province', 'responsibleAgency', 'integrationArea', 'activity', 'target', 'unit', 'salaryPermanent', 'governmentCompensation', 'compensationSupplies', 'contractEmployees', 'utilities', 'equipment', 'landConstruction', 'subsidies', 'otherExpenses', 'timestamp'];
    } else if (name === SHEETS.HIERARCHY) {
      headers = ['mainAgency', 'province'];
    } else if (name === SHEETS.RESP) {
      headers = ['mainAgency', 'responsibleAgency', 'integrationArea'];
    } else if (name === SHEETS.COMPARE) {
      headers = ['id', 'activity', 'referenceBudget'];
    } else if (name === SHEETS.OPTIONS) {
      headers = ['integration', 'unit'];
    }
    if (headers.length > 0) sheet.appendRow(headers);
  }
  return sheet;
}

function getDataFromSheet(sheet) {
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const results = [];

  for (let i = 1; i < data.length; i++) {
    let row = {};
    let hasData = false;
    for (let j = 0; j < headers.length; j++) {
      row[headers[j]] = data[i][j];
      if (data[i][j] !== '') hasData = true;
    }
    if (hasData) results.push(row);
  }
  return results;
}

function getHeaders(sheet) {
  return sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
}
```

### คำแนะนำเพิ่มเติม:
1.  **สร้าง Sheet ใหม่:** ใน Google Spreadsheet ของคุณ แนะนำให้สร้าง Sheet รอไว้ หรือลบ Sheet เดิมทิ้งแล้วรันสคริปต์ (ระบบจะสร้าง Sheet ชื่อ `Database`, `Hierarchy`, `Responsible`, `Compare`, `Options` ให้เองอัตโนมัติเมื่อมีการเรียกใช้งานครั้งแรก แต่ถ้าสร้างรอไว้จะดีกว่า)
2.  **Deploy ใหม่:** หลังจากแก้โค้ดเสร็จแล้ว อย่าลืมกด **Deploy > New deployment** และเลือก **Execute as: Me** และ **Who has access: Anyone** เพื่อให้เว็บเรียกใช้ได้ครับ

สาเหตุหลักของ Error `TypeError: Cannot read properties of undefined (reading 'contents')` คือ **Google Apps Script ยังรันโค้ดเก่าอยู่** หรือ **การตั้งค่า Deployment ไม่ถูกต้อง** ครับ

แม้คุณจะแก้โค้ดใน Script Editor แล้ว แต่ถ้าไม่ได้สร้าง **"New Deployment"** (การทำให้ใช้งานได้รายการใหม่) ตัว Web App URL เดิมจะยังคงชี้ไปที่โค้ดเวอร์ชันเก่าอยู่ ทำให้มันไม่รู้จักคำสั่ง `doPost` หรือโครงสร้างข้อมูลใหม่ที่ผมเพิ่งให้ไป

กรุณาทำตามขั้นตอนการ **Deploy** ด้านล่างนี้ให้ครบถ้วนครับ:

1.  ไปที่หน้า Google Apps Script ที่คุณวางโค้ด
2.  กดปุ่ม **Deploy (การทำให้ใช้งานได้)** มุมขวาบน > เลือก **Manage deployments (จัดการการทำให้ใช้งานได้)**
3.  คลิกที่รูปดินสอ (Edit) ด้านบน
4.  ตรง **Version (เวอร์ชัน)** ให้เลือกเป็น **"New version" (เวอร์ชันใหม่)** <--- **(สำคัญมาก! ต้องเลือกอันนี้ทุกครั้งที่มีการแก้โค้ด)**
5.  ตรวจสอบว่า **Execute as (ดำเนินการในฐานะ)** เป็น **Me (ฉัน)**
6.  ตรวจสอบว่า **Who has access (ผู้มีสิทธิ์เข้าถึง)** เป็น **Anyone (ทุกคน)**
7.  กดปุ่ม **Deploy (การทำให้ใช้งานได้)**
8.  **Copy URL ใหม่** (หรือใช้ URL เดิมถ้ามันไม่เปลี่ยน) นำไปแปะในหน้า **ตั้งค่า (Settings)** ของเว็บแอป

และเพื่อให้มั่นใจ ผมได้อัปเดตโค้ดฝั่งเว็บ (`services/dataService.ts`) ให้แสดงข้อความ Error ที่ชัดเจนขึ้นหากข้อมูลที่ได้จาก Server ไม่ถูกต้องครับ

### 💡 แนะนำเพิ่มเติม: โค้ด GAS ที่ปลอดภัยขึ้น
คุณสามารถนำโค้ดนี้ไปทับใน `Code.gs` อีกครั้ง เพื่อป้องกัน Error กรณีไม่มีข้อมูลส่งมา (จะแจ้งเตือนชัดเจนแทนที่จะ Error พังไปเลย):

