// --- MAIN HANDLERS ---

function doPost(e) {
  const lock = LockService.getScriptLock();
  // รอ Lock สูงสุด 30 วินาที เพื่อป้องกันการเขียนข้อมูลชนกัน
  if (!lock.tryLock(30000)) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: 'Server is busy, please try again.'
    })).setMimeType(ContentService.MimeType.JSON);
  }

  try {
    // ตรวจสอบข้อมูลที่ส่งมา
    if (!e || !e.postData || !e.postData.contents) {
       throw new Error("No POST data received.");
    }

    const jsonString = e.postData.contents;
    const params = JSON.parse(jsonString);
    const action = params.action;

    let result = {};

    // Router เลือกการทำงานตาม Action
    if (action === 'TEST_CONNECTION') {
      result = { status: 'success', message: 'Connection established' };
    } 
    else if (action === 'GET_DATA') {
      result = getAllData();
    }
    else if (action === 'MANAGE_RECORD') {
      result = manageRecord(params);
    }
    else if (action === 'MANAGE_MASTER') {
      result = manageMaster(params);
    }
    else {
      throw new Error('Unknown action: ' + action);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'error',
      message: error.toString(),
      stack: error.stack
    })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: 'success',
    message: 'API is running. Please use POST method.'
  })).setMimeType(ContentService.MimeType.JSON);
}

// --- DATA ACCESS FUNCTIONS ---

function getAllData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. Get Records (Database)
  const dbSheet = getOrCreateSheet(ss, SHEETS.DB);
  const records = getDataFromSheet(dbSheet);

  // 2. Get Hierarchy
  const hierarchySheet = getOrCreateSheet(ss, SHEETS.HIERARCHY);
  const hierarchy = getDataFromSheet(hierarchySheet);

  // 3. Get Responsible Data
  const respSheet = getOrCreateSheet(ss, SHEETS.RESP);
  const respData = getDataFromSheet(respSheet);

  // 4. Get Compare Data
  const compareSheet = getOrCreateSheet(ss, SHEETS.COMPARE);
  const compareData = getDataFromSheet(compareSheet).map(r => ({
    ...r,
    referenceBudget: Number(r.referenceBudget || 0)
  }));

  // 5. Get Options (Integration & Unit)
  const optSheet = getOrCreateSheet(ss, SHEETS.OPTIONS);
  const optData = getDataFromSheet(optSheet);

  // แยก Options เป็น 2 Arrays
  const dropdowns = {
    integration: optData.map(r => r.integration).filter(x => x && x !== ''),
    unit: optData.map(r => r.unit).filter(x => x && x !== '')
  };

  return {
    status: 'success',
    data: {
      records: records,
      hierarchy: hierarchy,
      respData: respData,
      compareData: compareData,
      dropdowns: dropdowns
    }
  };
}

// --- CRUD: Budget Records ---

function manageRecord(params) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = getOrCreateSheet(ss, SHEETS.DB);
  const type = params.type; // add, update, delete
  const data = params.data; 
  const id = params.id || (data ? data.id : null);

  const headers = getHeaders(sheet);
  const idIndex = headers.indexOf('id');
  if (idIndex === -1) throw new Error("Column 'id' not found in Database");

  if (type === 'add') {
    // เรียงข้อมูลให้ตรงตาม Header
    const row = headers.map(h => {
        // แปลง timestamp ให้เป็น string เพื่อป้องกัน format เพี้ยน
        if (h === 'timestamp' && data[h]) return "'" + data[h]; 
        return data[h] || '';
    });
    sheet.appendRow(row);
  } 
  else {
    // สำหรับ Update/Delete ต้องหา Row เดิมก่อน
    const dataRange = sheet.getDataRange();
    const values = dataRange.getValues();

    // loop หา id (เริ่ม row 1 เพราะ 0 คือ header)
    for (let i = 1; i < values.length; i++) {
      // เปรียบเทียบเป็น String เพื่อความชัวร์
      if (String(values[i][idIndex]) === String(id)) {
        const rowIndex = i + 1; // Google Sheet เริ่มนับที่ 1

        if (type === 'update') {
          const newRow = headers.map(h => {
             if (data[h] === undefined) return values[i][headers.indexOf(h)]; // ค่าเดิม
             if (h === 'timestamp' && data[h]) return "'" + data[h];
             return data[h];
          });
          sheet.getRange(rowIndex, 1, 1, newRow.length).setValues([newRow]);
        } 
        else if (type === 'delete') {
          sheet.deleteRow(rowIndex);
        }
        return { status: 'success' };
      }
    }
    // ถ้าหา ID ไม่เจอในกรณี update/delete
    // อาจจะไม่ต้อง throw error ก็ได้ถ้าต้องการให้ idempotent
  }

  return { status: 'success' };
}

// --- CRUD: Master Data (Hierarchy, Options, etc.) ---

function manageMaster(params) {
  const target = params.target; // Hierarchy, ResponsibleAgency, Compare, Unit, Integration
  const type = params.type;     // add, update, delete
  const data = params.data;

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheetName;

  // Map target to sheet name
  switch(target) {
    case 'Hierarchy': sheetName = SHEETS.HIERARCHY; break;
    case 'ResponsibleAgency': sheetName = SHEETS.RESP; break;
    case 'Compare': sheetName = SHEETS.COMPARE; break;
    case 'Unit': 
    case 'Integration': sheetName = SHEETS.OPTIONS; break;
    default: throw new Error("Unknown master target: " + target);
  }

  const sheet = getOrCreateSheet(ss, sheetName);
  const headers = getHeaders(sheet);
  const allValues = sheet.getDataRange().getValues();

  // ฟังก์ชันช่วยตรวจสอบว่าแถวนี้ตรงกับเงื่อนไขไหม (Primary Key Check)
  const isMatch = (rowValue) => {
    if (target === 'Hierarchy') {
      return rowValue[headers.indexOf('mainAgency')] == (data.oldMainAgency || data.mainAgency) && 
             rowValue[headers.indexOf('province')] == (data.oldProvince || data.province);
    } 
    else if (target === 'ResponsibleAgency') {
      return rowValue[headers.indexOf('mainAgency')] == data.mainAgency && 
             rowValue[headers.indexOf('responsibleAgency')] == (data.oldResponsibleAgency || data.responsibleAgency) &&
             rowValue[headers.indexOf('integrationArea')] == (data.oldIntegrationArea || data.integrationArea);
    } 
    else if (target === 'Compare') {
      return rowValue[headers.indexOf('activity')] == (data.oldActivity || data.activity);
    } 
    else if (target === 'Unit') {
      return rowValue[headers.indexOf('unit')] == (data.oldName || data.name);
    } 
    else if (target === 'Integration') {
      return rowValue[headers.indexOf('integration')] == (data.oldName || data.name);
    }
    return false;
  };

  if (type === 'add') {
    if (target === 'Unit' || target === 'Integration') {
        // กรณี Options: เนื่องจาก Unit และ Integration อยู่ Sheet เดียวกันแต่คนละคอลัมน์
        // เราต้องหาแถวแรกที่ว่างของคอลัมน์นั้นๆ หรือ append ไปเลย
        // เพื่อความง่าย: ใช้ appendRow แต่ใส่เฉพาะคอลัมน์ที่ต้องการ
        const row = headers.map(h => {
           if (target === 'Unit' && h === 'unit') return data.name;
           if (target === 'Integration' && h === 'integration') return data.name;
           return '';
        });
        sheet.appendRow(row);
    } else {
        // ตารางปกติ
        const row = headers.map(h => data[h] || '');
        sheet.appendRow(row);
    }
  } 
  else {
    // Update / Delete
    for (let i = 1; i < allValues.length; i++) {
      if (isMatch(allValues[i])) {
        const rowIndex = i + 1;

        if (type === 'delete') {
          if (target === 'Unit' || target === 'Integration') {
            // กรณี Options: ลบเฉพาะ Cell ไม่ลบทั้ง Row เพราะอาจกระทบอีกคอลัมน์
            const colName = target === 'Unit' ? 'unit' : 'integration';
            const colIndex = headers.indexOf(colName) + 1;
            sheet.getRange(rowIndex, colIndex).clearContent();

            // (Optional) Sort เพื่อไม่ให้เกิดช่องว่างกลางตาราง (ทำหรือไม่ทำก็ได้)
            // sheet.getRange(2, colIndex, sheet.getLastRow(), 1).sort(1);
          } else {
            sheet.deleteRow(rowIndex);
          }
        } 
        else if (type === 'update') {
          const newRow = [...allValues[i]]; // copy row เดิม

          if (target === 'Unit') {
            newRow[headers.indexOf('unit')] = data.name;
          } else if (target === 'Integration') {
            newRow[headers.indexOf('integration')] = data.name;
          } else {
            // ตารางปกติ Map ค่าใหม่ทับ
            headers.forEach((h, idx) => {
              if (data[h] !== undefined) newRow[idx] = data[h];
            });
          }

          sheet.getRange(rowIndex, 1, 1, newRow.length).setValues([newRow]);
        }
        break; // ทำรายการเดียวแล้วจบ
      }
    }
  }

  return { status: 'success' };
}

// --- HELPER FUNCTIONS ---

function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    // สร้าง Header เริ่มต้นหากไม่มี
    let headers = [];
    if (name === SHEETS.DB) {
      headers = [
        'id', 'integration', 'mainAgency', 'province', 'responsibleAgency', 
        'integrationArea', 'activity', 'target', 'unit', 'salaryPermanent', 
        'governmentCompensation', 'compensationSupplies', 'contractEmployees', 
        'utilities', 'equipment', 'landConstruction', 'subsidies', 'otherExpenses', 
        'timestamp'
      ];
    } else if (name === SHEETS.HIERARCHY) {
      headers = ['mainAgency', 'province'];
    } else if (name === SHEETS.RESP) {
      headers = ['mainAgency', 'responsibleAgency', 'integrationArea'];
    } else if (name === SHEETS.COMPARE) {
      headers = ['id', 'activity', 'referenceBudget'];
    } else if (name === SHEETS.OPTIONS) {
      headers = ['integration', 'unit'];
    }

    if (headers.length > 0) {
      sheet.appendRow(headers);
      sheet.setFrozenRows(1); // แช่แข็งแถวหัวตาราง
    }
  }
  return sheet;
}

function getDataFromSheet(sheet) {
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return []; // มีแค่ Header หรือว่างเปล่า

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const results = [];

  for (let i = 1; i < data.length; i++) {
    let row = {};
    let hasData = false;
    for (let j = 0; j < headers.length; j++) {
      const val = data[i][j];
      row[headers[j]] = val;
      if (val !== '') hasData = true;
    }
    // กรองแถวว่างทิ้ง
    if (hasData) results.push(row);
  }
  return results;
}

function getHeaders(sheet) {
  const lastCol = sheet.getLastColumn();
  if (lastCol === 0) return [];
  return sheet.getRange(1, 1, 1, lastCol).getValues()[0];
}
```

### ขั้นตอนการติดตั้งและ Deploy (สำคัญมาก):

1.  **วางโค้ด:** ลบโค้ดเก่าในไฟล์ `Code.gs` ทั้งหมด แล้ววางโค้ดด้านบนลงไป
2.  **บันทึก:** กด Save (ไอคอนแผ่นดิสก์)
3.  **Deploy ใหม่:**
    *   กดปุ่ม **Deploy** (การทำให้ใช้งานได้) มุมขวาบน -> **Manage deployments** (จัดการการทำให้ใช้งานได้)
    *   กดไอคอน **ดินสอ (Edit)** ตรงรายการ Active ล่าสุด
    *   **Version (เวอร์ชัน):** เลือก **"New version" (เวอร์ชันใหม่)** <--- *ต้องเลือกทุกครั้งที่แก้โค้ด*
    *   กด **Deploy**
4.  **เสร็จสิ้น:** ระบบ Frontend จะสามารถใช้งานกับ Backend ใหม่นี้ได้ทันที (ไม่ต้องเปลี่ยน URL หากใช้วิธี Edit deployment)

ใช่ครับ **โค้ด GAS ที่คุณแนบมาจำเป็นต้องแก้ไข** ครับ

สาเหตุหลักคือชื่อคำสั่ง (Action) ในโค้ด GAS ของคุณไม่ตรงกับที่หน้าเว็บ (Frontend) ส่งไปครับ (เช่น หน้าเว็บส่ง `GET_DATA` แต่ GAS รอรับ `GET_ALL` และยังขาดฟังก์ชัน `TEST_CONNECTION` สำหรับปุ่มทดสอบการเชื่อมต่อ)

เพื่อให้ระบบทำงานได้สมบูรณ์ **ให้ใช้โค้ดด้านล่างนี้ไปวางทับใน Google Apps Script (ไฟล์ `Code.gs`) ทั้งหมดครับ**

ผมปรับปรุงจากโค้ดที่คุณให้มา โดยแก้ไขจุดสำคัญคือ:
1.  เปลี่ยนให้รองรับ Action: `GET_DATA` และ `TEST_CONNECTION` ให้ตรงกับหน้าเว็บ
2.  เพิ่มฟังก์ชัน `getOrCreateSheet` เพื่อช่วยสร้าง Sheet อัตโนมัติหากยังไม่มี (ป้องกัน Error)
3.  ปรับปรุงการจัดการวันที่ (Timestamp) ให้แสดงผลถูกต้องใน Google Sheets

### โค้ด Google Apps Script (`Code.gs`) ที่แก้ไขแล้ว

```javascript
/* 
  Budget Plan Management System - Google Apps Script
  Updated for React Frontend Compatibility
*/

// Configuration: Sheet Names
const SHEET_DB = 'Database';
const SHEETS = {
  DB: 'Database',
  HIERARCHY: 'Hierarchy',
  RESP: 'ResponsibleAgency',
  COMPARE: 'Compare',
  UNIT: 'Unit',
  INTEGRATION: 'Integration'
};

// --- MAIN DO GET ---
function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: 'success',
    message: 'API is running. Please use POST method.'
  })).setMimeType(ContentService.MimeType.JSON);
}

// --- MAIN DO POST ---
function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  // รอ Lock สูงสุด 30 วินาที
  if (!lock.tryLock(30000)) {
     return jsonResponse({ status: 'error', message: 'Server is busy' });
  }

  try {
    // ตรวจสอบว่ามีข้อมูลส่งมาหรือไม่
    if (!e || !e.postData || !e.postData.contents) {
       return jsonResponse({ status: 'error', message: 'No POST data received' });
    }

    const params = JSON.parse(e.postData.contents);
    const doc = SpreadsheetApp.getActiveSpreadsheet();

    // 1. TEST CONNECTION
    if (params.action === 'TEST_CONNECTION') {
      return jsonResponse({ status: 'success', message: 'Connection established' });
    }

    // 2. GET ALL DATA (Sync Dropdowns & Records)
    if (params.action === 'GET_DATA') {
      const data = getAllData(doc);
      return jsonResponse({ status: 'success', data: data });
    }

    // 3. MANAGE RECORD (Add/Update/Delete Budget Record)
    if (params.action === 'MANAGE_RECORD') {
      const result = manageRecord(doc, params);
      return jsonResponse(result);
    }

    // 4. MANAGE MASTER DATA (Dropdowns)
    if (params.action === 'MANAGE_MASTER') {
      const result = manageMasterData(doc, params);
      return jsonResponse(result);
    }

    return jsonResponse({ status: 'error', message: 'Invalid Action: ' + params.action });

  } catch (err) {
    return jsonResponse({ status: 'error', message: err.toString(), stack: err.stack });
  } finally {
    lock.releaseLock();
  }
}

// --- HELPER FUNCTIONS ---

function jsonResponse(data) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// Helper to get data from sheet as array of objects
function getSheetData(sheet) {
  if (!sheet) return [];
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return []; 

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const results = [];

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    const obj = {};
    let hasData = false;
    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
      if (row[j] !== '') hasData = true;
    }
    if (hasData) results.push(obj);
  }
  return results;
}

// Helper: Ensure sheet exists with headers
function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    let headers = [];
    if (name === SHEETS.DB) {
      headers = ['id', 'integration', 'mainAgency', 'province', 'responsibleAgency', 'integrationArea', 'activity', 'target', 'unit', 'salaryPermanent', 'governmentCompensation', 'compensationSupplies', 'contractEmployees', 'utilities', 'equipment', 'landConstruction', 'subsidies', 'otherExpenses', 'timestamp'];
    } else if (name === SHEETS.HIERARCHY) {
      headers = ['mainAgency', 'province'];
    } else if (name === SHEETS.RESP) {
      headers = ['mainAgency', 'responsibleAgency', 'integrationArea'];
    } else if (name === SHEETS.COMPARE) {
      headers = ['id', 'activity', 'referenceBudget'];
    } else if (name === SHEETS.UNIT || name === SHEETS.INTEGRATION) {
      headers = ['name']; // Simple list
    }

    if (headers.length > 0) {
      sheet.appendRow(headers);
      sheet.setFrozenRows(1);
    }
  }
  return sheet;
}

// --- CORE LOGIC ---

function getAllData(doc) {
  // Get Sheets (Create if not exist)
  const dbSheet = getOrCreateSheet(doc, SHEETS.DB);
  const hierarchySheet = getOrCreateSheet(doc, SHEETS.HIERARCHY);
  const respSheet = getOrCreateSheet(doc, SHEETS.RESP);
  const compareSheet = getOrCreateSheet(doc, SHEETS.COMPARE);
  const unitSheet = getOrCreateSheet(doc, SHEETS.UNIT);
  const integSheet = getOrCreateSheet(doc, SHEETS.INTEGRATION);

  const getCol = (sheet, colIndex) => { // colIndex 1-based
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) return [];
    return sheet.getRange(2, colIndex, lastRow - 1, 1).getValues().flat().filter(String);
  };

  const records = getSheetData(dbSheet);
  const dropdowns = {
    integration: getCol(integSheet, 1).sort(),
    unit: getCol(unitSheet, 1).sort(),
    activity: getCol(compareSheet, 2).sort() // Activity is column 2 in Compare sheet
  };

  return {
    records: records,
    dropdowns: dropdowns,
    hierarchy: getSheetData(hierarchySheet),
    respData: getSheetData(respSheet),
    compareData: getSheetData(compareSheet)
  };
}

function manageRecord(doc, params) {
  const sheet = getOrCreateSheet(doc, SHEETS.DB);
  const type = params.type; 
  const data = params.data;
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const idIndex = headers.indexOf('id');

  if (idIndex === -1) throw new Error("ID column not found");

  if (type === 'add') {
    const row = headers.map(h => {
        if (h === 'timestamp' && data[h]) return "'" + data[h]; // Force string for date
        return data[h] || '';
    });
    sheet.appendRow(row);
    return { status: 'success', message: 'Added' };
  }

  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();
  const id = params.id || (data ? data.id : null);

  for (let i = 1; i < values.length; i++) {
    if (String(values[i][idIndex]) === String(id)) {
      if (type === 'update') {
        const newRow = headers.map(h => {
             if (data[h] === undefined) return values[i][headers.indexOf(h)];
             if (h === 'timestamp' && data[h]) return "'" + data[h];
             return data[h];
        });
        sheet.getRange(i + 1, 1, 1, headers.length).setValues([newRow]);
        return { status: 'success', message: 'Updated' };
      }
      if (type === 'delete') {
        sheet.deleteRow(i + 1);
        return { status: 'success', message: 'Deleted' };
      }
    }
  }
  return { status: 'error', message: 'ID not found' };
}

function manageMasterData(doc, params) {
  const target = params.target; 
  const type = params.type; 
  const data = params.data;

  let sheetName;
  switch(target) {
    case 'Hierarchy': sheetName = SHEETS.HIERARCHY; break;
    case 'ResponsibleAgency': sheetName = SHEETS.RESP; break;
    case 'Compare': sheetName = SHEETS.COMPARE; break;
    case 'Unit': sheetName = SHEETS.UNIT; break;
    case 'Integration': sheetName = SHEETS.INTEGRATION; break;
    default: return { status: 'error', message: 'Unknown target' };
  }

  const sheet = getOrCreateSheet(doc, sheetName);
  const rows = sheet.getDataRange().getValues();

  // --- HIERARCHY ---
  if (target === 'Hierarchy') {
    if (type === 'add') {
      sheet.appendRow([data.mainAgency, data.province]);
    } else {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == (data.oldMainAgency || data.mainAgency) && rows[i][1] == (data.oldProvince || data.province)) {
          if (type === 'update') sheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
          if (type === 'delete') sheet.deleteRow(i + 1);
          break;
        }
      }
    }
  }

  // --- RESPONSIBLE AGENCY ---
  else if (target === 'ResponsibleAgency') {
    if (type === 'add') {
      sheet.appendRow([data.mainAgency, data.responsibleAgency, data.integrationArea]);
    } else {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.mainAgency && rows[i][1] == (data.oldResponsibleAgency || data.responsibleAgency) && rows[i][2] == (data.oldIntegrationArea || data.integrationArea)) {
          if (type === 'update') sheet.getRange(i + 1, 2, 1, 2).setValues([[data.responsibleAgency, data.integrationArea]]);
          if (type === 'delete') sheet.deleteRow(i + 1);
          break;
        }
      }
    }
  }

  // --- COMPARE ---
  else if (target === 'Compare') {
    if (type === 'add') {
      sheet.appendRow([data.activity, data.activity, data.referenceBudget]); 
    } else {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][1] == (data.oldActivity || data.activity)) { // Check Activity Name (Col 2)
          if (type === 'update') sheet.getRange(i + 1, 2, 1, 2).setValues([[data.activity, data.referenceBudget]]);
          if (type === 'delete') sheet.deleteRow(i + 1);
          break;
        }
      }
    }
  }

  // --- UNIT & INTEGRATION ---
  else if (target === 'Unit' || target === 'Integration') {
    if (type === 'add') {
      sheet.appendRow([data.name]);
    } else {
      for (let i = 1; i < rows.length; i++) {
        if (rows[i][0] == (data.oldName || data.name)) {
          if (type === 'update') sheet.getRange(i + 1, 1).setValue(data.name);
          if (type === 'delete') sheet.deleteRow(i + 1);
          break;
        }
      }
    }
  }

  return { status: 'success' };
}
```

**สิ่งที่ต้องทำหลังจากแก้โค้ด:**
1.  กดปุ่ม **Save** (ไอคอนแผ่นดิสก์)
2.  กด **Deploy** > **Manage deployments**
3.  กดรูปดินสอ (Edit) -> ตรง Version เลือก **New version** (สำคัญมาก!)
4.  กด **Deploy** อีกครั้ง

ระบบจะทำงานร่วมกันได้อย่างสมบูรณ์ครับ

โค้ด GAS ที่คุณแนบมา **"เกือบสมบูรณ์ 100%"** ครับ แต่มีจุดเล็กน้อยที่ต้องปรับเพื่อให้ทำงานร่วมกับฟีเจอร์ในหน้า **"จัดการข้อมูลตัวเลือก (ManageView)"** และ **"การซิงค์ข้อมูล (Sync)"** ได้อย่างไร้รอยต่อ

ผมได้ปรับปรุงโค้ด GAS ชุดสุดท้ายนี้ให้:
1.  **รองรับ Action `GET_DATA`:** เพื่อให้ปุ่ม "ซิงค์ข้อมูล" ในหน้า Database และหน้า Manage ทำงานได้ (ของเดิมในไฟล์แนบใช้ `doGet` ซึ่งอาจมีปัญหาเรื่อง Cache ของ Google)
2.  **รองรับ `TEST_CONNECTION`:** สำหรับปุ่มทดสอบในหน้าตั้งค่า
3.  **แก้บั๊กการจัดการ Hierarchy/Responsible:** ให้รองรับการแก้ไขชื่อ (Update) และการลบ (Delete) ตามที่หน้า ManageView ส่งมา
4.  **ระบบสร้าง Sheet อัตโนมัติ:** หากคุณเผลอลบชีททิ้ง ระบบจะสร้างใหม่พร้อมหัวตาราง (Headers) ที่ถูกต้องให้ทันที

---

### 📄 โค้ด Google Apps Script (`Code.gs`) ฉบับสมบูรณ์ที่สุด

```javascript
/**
 * DNP Budget Plan - Backend API (Full CRUD v2.1)
 * รองรับ: Database CRUD, Master Data Management, Connection Testing
 */

const SHEETS = {
  DB: 'Database',
  INTEGRATION: 'Integration',
  HIERARCHY: 'Hierarchy',
  RESPONSIBLE: 'ResponsibleAgency',
  COMPARE: 'Compare',
  UNIT: 'Unit'
};

const DB_HEADERS = [
  'id', 'integration', 'mainAgency', 'province', 'responsibleAgency', 
  'integrationArea', 'activity', 'target', 'unit', 
  'salaryPermanent', 'governmentCompensation', 'compensationSupplies', 
  'contractEmployees', 'utilities', 'equipment', 'landConstruction', 
  'subsidies', 'otherExpenses', 'timestamp'
];

/**
 * GET: ตรวจสอบสถานะ Server เบื้องต้น
 */
function doGet(e) {
  return responseJSON({ status: 'success', message: 'API is active. Please use POST for data operations.' });
}

/**
 * POST: จัดการข้อมูลทุกประเภท (Action Router)
 */
function doPost(e) {
  const lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000); // รอสูงสุด 30 วินาที
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const params = JSON.parse(e.postData.contents);
    const action = params.action;

    let result = {};

    if (action === 'TEST_CONNECTION') {
      result = { message: 'Connection established successfully' };
    } 
    else if (action === 'GET_DATA') {
      result = fetchAllData(ss);
    } 
    else if (action === 'MANAGE_RECORD') {
      result = manageRecord(ss, params);
    } 
    else if (action === 'MANAGE_MASTER') {
      result = manageMaster(ss, params);
    } 
    else {
      throw new Error('Invalid action: ' + action);
    }

    return responseJSON({ status: 'success', ...result });

  } catch (error) {
    return responseJSON({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

// --- CORE FUNCTIONS ---

function fetchAllData(ss) {
  const hierarchyData = getTableData(ss, SHEETS.HIERARCHY, ['mainAgency', 'province']);
  const respDataRaw = getTableData(ss, SHEETS.RESPONSIBLE, ['mainAgency', 'responsibleAgency', 'integrationArea']);
  const compareData = getTableData(ss, SHEETS.COMPARE, ['id', 'activity', 'referenceBudget']);
  const integrationList = getSimpleList(ss, SHEETS.INTEGRATION);
  const unitList = getSimpleList(ss, SHEETS.UNIT);
  const records = getTableData(ss, SHEETS.DB, DB_HEADERS);

  return {
    data: {
      records: records,
      dropdowns: {
        integration: integrationList,
        unit: unitList,
        // ตัวเลือกอื่นๆ จะถูกคำนวณจาก Hierarchy/RespData ในฝั่ง Frontend เอง
      },
      hierarchy: hierarchyData,
      respData: respDataRaw,
      compareData: compareData
    }
  };
}

function manageRecord(ss, params) {
  const sheet = getOrCreateSheet(ss, SHEETS.DB, DB_HEADERS);
  const type = params.type; 
  const record = params.data;
  const id = params.id || (record ? record.id : null);

  if (type === 'add') {
    const row = DB_HEADERS.map(h => h === 'timestamp' ? record[h] || new Date().toLocaleString('th-TH') : record[h] || '');
    sheet.appendRow(row);
    return { message: 'Record added' };
  }

  const values = sheet.getDataRange().getValues();
  const idIndex = DB_HEADERS.indexOf('id');

  for (let i = 1; i < values.length; i++) {
    if (String(values[i][idIndex]) === String(id)) {
      if (type === 'delete') {
        sheet.deleteRow(i + 1);
        return { message: 'Record deleted' };
      }
      if (type === 'update') {
        const newRow = DB_HEADERS.map((h, idx) => {
          if (h === 'timestamp') return record[h] || new Date().toLocaleString('th-TH');
          return record[h] !== undefined ? record[h] : values[i][idx];
        });
        sheet.getRange(i + 1, 1, 1, newRow.length).setValues([newRow]);
        return { message: 'Record updated' };
      }
    }
  }
  throw new Error('Record ID not found: ' + id);
}

function manageMaster(ss, params) {
  const target = params.target; 
  const type = params.type; 
  const data = params.data;

  if (target === 'Integration' || target === 'Unit') {
    return handleSimpleCRUD(ss, SHEETS[target.toUpperCase()], type, data);
  }
  if (target === 'Compare') return handleCompareCRUD(ss, type, data);
  if (target === 'Hierarchy') return handleHierarchyCRUD(ss, type, data);
  if (target === 'ResponsibleAgency') return handleResponsibleCRUD(ss, type, data);

  throw new Error('Unknown target: ' + target);
}

// --- HANDLERS FOR MASTER DATA ---

function handleSimpleCRUD(ss, sheetName, type, data) {
  const sheet = getOrCreateSheet(ss, sheetName, ['name']);
  const rows = sheet.getDataRange().getValues();
  if (type === 'add') {
    sheet.appendRow([data.name]);
  } else {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][0] === (data.oldName || data.name)) {
        if (type === 'update') sheet.getRange(i + 1, 1).setValue(data.name);
        if (type === 'delete') sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

function handleCompareCRUD(ss, type, data) {
  const headers = ['id', 'activity', 'referenceBudget'];
  const sheet = getOrCreateSheet(ss, SHEETS.COMPARE, headers);
  const rows = sheet.getDataRange().getValues();
  if (type === 'add') {
    sheet.appendRow([data.activity, data.activity, data.referenceBudget || 0]);
  } else {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][1] === (data.oldActivity || data.activity)) {
        if (type === 'update') sheet.getRange(i + 1, 1, 1, 3).setValues([[data.activity, data.activity, data.referenceBudget]]);
        if (type === 'delete') sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

function handleHierarchyCRUD(ss, type, data) {
  const sheet = getOrCreateSheet(ss, SHEETS.HIERARCHY, ['mainAgency', 'province']);
  const rows = sheet.getDataRange().getValues();
  if (type === 'add') {
    sheet.appendRow([data.mainAgency, data.province]);
  } else {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][0] === (data.oldMainAgency || data.mainAgency) && rows[i][1] === (data.oldProvince || data.province)) {
        if (type === 'update') sheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
        if (type === 'delete') sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

function handleResponsibleCRUD(ss, type, data) {
  const sheet = getOrCreateSheet(ss, SHEETS.RESPONSIBLE, ['mainAgency', 'responsibleAgency', 'integrationArea']);
  const rows = sheet.getDataRange().getValues();
  if (type === 'add') {
    sheet.appendRow([data.mainAgency, data.responsibleAgency, data.integrationArea]);
  } else {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][0] === data.mainAgency && rows[i][1] === (data.oldResponsibleAgency || data.responsibleAgency) && rows[i][2] === (data.oldIntegrationArea || data.integrationArea)) {
        if (type === 'update') sheet.getRange(i + 1, 1, 1, 3).setValues([[data.mainAgency, data.responsibleAgency, data.integrationArea]]);
        if (type === 'delete') sheet.deleteRow(i + 1);
        break;
      }
    }
  }
  return { message: 'Success' };
}

// --- UTILS ---

function getOrCreateSheet(ss, name, headers) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.appendRow(headers);
    sheet.setFrozenRows(1);
  }
  return sheet;
}

function getTableData(ss, name, headers) {
  const sheet = ss.getSheetByName(name);
  if (!sheet) return [];
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return [];
  const sheetHeaders = rows[0];
  const results = [];
  for (let i = 1; i < rows.length; i++) {
    let obj = {};
    let hasData = false;
    headers.forEach(h => {
      const idx = sheetHeaders.indexOf(h);
      obj[h] = idx > -1 ? rows[i][idx] : '';
      if (obj[h] !== '') hasData = true;
    });
    if (hasData) results.push(obj);
  }
  return results;
}

function getSimpleList(ss, name) {
  const sheet = ss.getSheetByName(name);
  if (!sheet) return [];
  const vals = sheet.getDataRange().getValues();
  return vals.slice(1).map(r => r[0]).filter(Boolean).sort();
}

function responseJSON(content) {
  return ContentService.createTextOutput(JSON.stringify(content)).setMimeType(ContentService.MimeType.JSON);
}
```

### ✅ จุดที่คุณควรตรวจสอบหลังวางโค้ด:
1.  **การ Deploy:** ต้องเลือก **"New Version"** ทุกครั้งที่วางโค้ดใหม่ และสิทธิ์ต้องเป็น **"Anyone"**
2.  **ชื่อหัวตาราง:** โค้ดนี้จะสร้างชีทให้เองถ้าไม่มี แต่ถ้ามีชีทอยู่แล้ว **กรุณาตรวจสอบว่าแถวที่ 1 (Header) พิมพ์สะกดถูกต้องตามตัวพิมพ์เล็ก-ใหญ่** (เช่น `id`, `mainAgency`, `province`)
3.  **การทดสอบ:** กดปุ่ม "ทดสอบการเชื่อมต่อ" ในหน้าตั้งค่าของเว็บ ถ้าขึ้นสีเขียว แสดงว่าทุกอย่างพร้อมใช้งาน 100% ครับ!

