export class DataService {
    private records: BudgetRecord[] = [];
    private dropdowns: DropdownOptions = INITIAL_DROPDOWN_DATA;
    private hierarchy: HierarchyData[] = INITIAL_HIERARCHY;
    private respData: ResponsibleAgencyData[] = INITIAL_RESP_DATA;
    private compareData: CompareRecord[] = INITIAL_COMPARE_DATA;
    private fieldVisibility: FieldVisibility = DEFAULT_VISIBILITY;

    constructor() {
        this.loadFromCache();
    }

    private loadFromCache() {
        const cached = localStorage.getItem(CACHE_KEY);
        if (cached) {
            const parsed = JSON.parse(cached);
            this.records = parsed.records || INITIAL_BUDGET_RECORDS;
            this.dropdowns = parsed.dropdowns || INITIAL_DROPDOWN_DATA;
            this.hierarchy = parsed.hierarchy || INITIAL_HIERARCHY;
            this.respData = parsed.respData || INITIAL_RESP_DATA;
            this.compareData = parsed.compareData || INITIAL_COMPARE_DATA;
            this.fieldVisibility = parsed.fieldVisibility || DEFAULT_VISIBILITY;
        } else {
            this.records = INITIAL_BUDGET_RECORDS;
            this.fieldVisibility = DEFAULT_VISIBILITY;
        }
    }

    private saveToCache() {
        localStorage.setItem(CACHE_KEY, JSON.stringify({
            records: this.records,
            dropdowns: this.dropdowns,
            hierarchy: this.hierarchy,
            respData: this.respData,
            compareData: this.compareData,
            fieldVisibility: this.fieldVisibility
        }));
    }

    private async sendToGas(action: string, payload: any) {
        const settings = getSettings();
        if (!settings.gasUrl) return;

        try {
            await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action, ...payload })
            });
        } catch (e) {
            console.error('API Error:', e);
        }
    }

    private normalizeRecord(raw: any): BudgetRecord {
        const find = (keys: string[]) => {
             for (const k of keys) {
                 if (raw[k] !== undefined && raw[k] !== null) return raw[k];
             }
             const rawKeys = Object.keys(raw);
             for (const k of keys) {
                 const match = rawKeys.find(rk => rk.toLowerCase() === k.toLowerCase());
                 if (match) return raw[match];
             }
             return undefined;
        };

        const getNum = (keys: string[]) => {
            const val = find(keys);
            if (typeof val === 'number') return val;
            return parseNumber(String(val || 0));
        };

        return {
            id: String(find(['id', 'ID', 'Id', 'ลำดับ', 'รหัส', 'no', 'No']) || raw.id || ''),
            integration: String(find(['integration', 'Integration', 'บูรณาการ', 'ประเภทหน่วยงาน']) || ''),
            mainAgency: String(find(['mainAgency', 'MainAgency', 'หน่วยงานหลัก', 'สังกัด']) || ''),
            province: String(find(['province', 'Province', 'จังหวัด']) || ''),
            responsibleAgency: String(find(['responsibleAgency', 'ResponsibleAgency', 'หน่วยงานบูรณาการ', 'หน่วยงานรับผิดชอบ']) || ''),
            integrationArea: String(find(['integrationArea', 'IntegrationArea', 'พื้นที่บูรณาการ', 'พื้นที่']) || ''),
            activity: String(find(['activity', 'Activity', 'กิจกรรม', 'ชื่อกิจกรรม']) || ''),
            target: String(find(['target', 'Target', 'เป้าหมาย']) || ''),
            unit: String(find(['unit', 'Unit', 'หน่วยนับ']) || ''),

            salaryPermanent: getNum(['salaryPermanent', 'SalaryPermanent', 'เงินเดือนและค่าจ้างประจำ', 'เงินเดือน']),
            governmentCompensation: getNum(['governmentCompensation', 'GovernmentCompensation', 'ค่าตอบแทนพนักงานราชการ', 'ค่าตอบแทน']),
            compensationSupplies: getNum(['compensationSupplies', 'CompensationSupplies', 'ค่าตอบแทน ใช้สอย และวัสดุ', 'ค่าใช้สอย']),
            contractEmployees: getNum(['contractEmployees', 'ContractEmployees', 'ค่าจ้างเหมาพนักงาน', 'จ้างเหมา']),
            utilities: getNum(['utilities', 'Utilities', 'ค่าสาธารณูปโภค']),
            equipment: getNum(['equipment', 'Equipment', 'ค่าครุภัณฑ์']),
            landConstruction: getNum(['landConstruction', 'LandConstruction', 'ค่าที่ดินและสิ่งก่อสร้าง', 'สิ่งก่อสร้าง']),
            subsidies: getNum(['subsidies', 'Subsidies', 'งบเงินอุดหนุน', 'เงินอุดหนุน']),
            otherExpenses: getNum(['otherExpenses', 'OtherExpenses', 'งบรายจ่ายอื่น', 'รายจ่ายอื่น']),

            timestamp: String(find(['timestamp', 'Timestamp', 'วันที่บันทึก', 'เวลาที่บันทึก']) || '')
        };
    }

    private normalizeCompareRecord(raw: any): CompareRecord {
        return {
            id: String(raw.id || raw.activity || ''),
            activity: String(raw.activity || ''),
            referenceBudget: typeof raw.referenceBudget === 'number' ? raw.referenceBudget : parseNumber(String(raw.referenceBudget || 0))
        };
    }

    getRecords(): BudgetRecord[] { return this.records; }
    getDropdowns() { return this.dropdowns; }
    getHierarchy() { return this.hierarchy; }
    getResponsibleData() { return this.respData; }
    getCompareData() { return this.compareData; }
    getFieldVisibility() { return this.fieldVisibility; }

    addRecord(record: BudgetRecord) {
        this.records = [...this.records, record];
        this.saveToCache();
        this.sendToGas('MANAGE_RECORD', { type: 'add', data: record });
    }

    updateRecord(updatedRecord: BudgetRecord) {
        this.records = this.records.map(r => r.id === updatedRecord.id ? updatedRecord : r);
        this.saveToCache();
        this.sendToGas('MANAGE_RECORD', { type: 'update', data: updatedRecord, id: updatedRecord.id });
    }

    deleteRecord(id: string) {
        this.records = this.records.filter(r => r.id !== id);
        this.saveToCache();
        this.sendToGas('MANAGE_RECORD', { type: 'delete', id: id });
    }

    checkDuplicate(record: Partial<BudgetRecord>): boolean {
        return this.records.some(existing => {
            if (record.id && existing.id === record.id) return false;
            const isSameIntegration = (existing.integration || '').trim() === (record.integration || '').trim();
            const isSameAgency = (existing.mainAgency || '').trim() === (record.mainAgency || '').trim();
            const isSameProvince = (existing.province || '').trim() === (record.province || '').trim();
            const isSameActivity = (existing.activity || '').trim() === (record.activity || '').trim();
            return isSameIntegration && isSameAgency && isSameProvince && isSameActivity;
        });
    }

    toggleFieldVisibility(field: string) {
        this.fieldVisibility = { ...this.fieldVisibility, [field]: !this.fieldVisibility[field] };
        this.saveToCache();
    }

    setAllFieldsVisibility(visible: boolean) {
        const newVisibility: FieldVisibility = {};
        Object.keys(FIELD_LABELS).forEach(key => newVisibility[key] = visible);
        this.fieldVisibility = newVisibility;
        this.saveToCache();
    }

    private updateDerivedDropdowns() {
        const unique = (arr: any[]) => Array.from(new Set(arr.filter(item => item && typeof item === 'string' && item.trim() !== ''))).sort();
        this.dropdowns.mainAgency = unique(this.hierarchy.map(h => h.mainAgency));
        this.dropdowns.province = unique(this.hierarchy.map(h => h.province));
        this.dropdowns.responsibleAgency = unique(this.respData.map(r => r.responsibleAgency));
        this.dropdowns.integrationArea = unique(this.respData.map(r => r.integrationArea));
        this.dropdowns.activity = unique(this.compareData.map(c => c.activity));
    }

    addHierarchyItem(mainAgency: string, province: string) {
        this.hierarchy.push({ mainAgency, province });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'add', data: { mainAgency, province } });
    }

    updateHierarchyItem(oldMain: string, oldProv: string, newMain: string, newProv: string) {
        const index = this.hierarchy.findIndex(h => h.mainAgency === oldMain && h.province === oldProv);
        if (index !== -1) {
            this.hierarchy[index] = { mainAgency: newMain, province: newProv };
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'update', data: { mainAgency: newMain, province: newProv, oldMainAgency: oldMain, oldProvince: oldProv } });
        }
    }

    deleteHierarchyItem(mainAgency: string, province: string) {
        this.hierarchy = this.hierarchy.filter(h => !(h.mainAgency === mainAgency && h.province === province));
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'delete', data: { mainAgency, province } });
    }

    addResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData.push({ mainAgency, responsibleAgency, integrationArea });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'add', data: { mainAgency, responsibleAgency, integrationArea } });
    }

    updateResponsibleAgency(mainAgency: string, oldResp: string, oldArea: string, newResp: string, newArea: string) {
        const index = this.respData.findIndex(r => r.mainAgency === mainAgency && r.responsibleAgency === oldResp && r.integrationArea === oldArea);
        if (index !== -1) {
            this.respData[index] = { mainAgency, responsibleAgency: newResp, integrationArea: newArea };
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'update', data: { mainAgency, responsibleAgency: newResp, integrationArea: newArea, oldResponsibleAgency: oldResp, oldIntegrationArea: oldArea } });
        }
    }

    deleteResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData = this.respData.filter(r => !(r.mainAgency === mainAgency && r.responsibleAgency === responsibleAgency && r.integrationArea === integrationArea));
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'delete', data: { mainAgency, responsibleAgency, integrationArea } });
    }

    addActivity(name: string) {
        this.compareData.push({ id: name, activity: name, referenceBudget: 0 });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'add', data: { activity: name, referenceBudget: 0 } });
    }

    updateActivity(oldName: string, newName: string) {
        const record = this.compareData.find(c => c.activity === oldName);
        if (record) {
            record.activity = newName;
            this.records = this.records.map(r => r.activity === oldName ? { ...r, activity: newName } : r);
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newName, oldActivity: oldName, referenceBudget: record.referenceBudget } });
        }
    }

    updateCompareData(id: string, newActivity: string, newBudget: number) {
        const index = this.compareData.findIndex(c => c.id === id || c.activity === id);
        if (index !== -1) {
            const oldActivity = this.compareData[index].activity;
            this.compareData[index].activity = newActivity;
            this.compareData[index].referenceBudget = newBudget;
            if (oldActivity !== newActivity) {
                this.records = this.records.map(r => r.activity === oldActivity ? { ...r, activity: newActivity } : r);
            }
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newActivity, oldActivity: oldActivity, referenceBudget: newBudget } });
        }
    }

    deleteActivity(name: string) {
        this.compareData = this.compareData.filter(c => c.activity !== name);
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'delete', data: { activity: name } });
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');

        try {
            const response = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'GET_DATA' })
            });
            const json = await response.json();

            if (json.status === 'success' && json.data) {
                const serverData = json.data;

                // Sync Lists
                this.hierarchy = serverData.hierarchy || [];
                this.respData = serverData.respData || [];
                this.compareData = (serverData.compareData || []).map((c: any) => this.normalizeCompareRecord(c));

                // Sync Records
                if (serverData.records && Array.isArray(serverData.records)) {
                    this.records = serverData.records.map((r: any) => this.normalizeRecord(r));
                }

                // Sync Specific Dropdowns
                this.dropdowns.integration = serverData.dropdowns?.integration || [];
                this.dropdowns.unit = serverData.dropdowns?.unit || [];

                // Re-calculate derived dropdowns
                this.updateDerivedDropdowns();

                this.saveToCache();
            } else {
                throw new Error(json.message || 'Failed to fetch data');
            }
        } catch (error: any) {
            console.error('Sync Error:', error);
            throw error;
        }
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const response = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'TEST_CONNECTION' })
            });
            const json = await response.json();
            return json.status === 'success';
        } catch (error) {
            return false;
        }
    }
}

