            dataService.addHierarchyItem(main, prov);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditHierarchy = async (oldMain: string, oldProv: string) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูล',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">หน่วยงานหลัก</div>' +
                `<input id="swal-input-main" class="swal2-input" value="${oldMain}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">จังหวัด</div>' +
                `<input id="swal-input-prov" class="swal2-input" value="${oldProv}" style="margin: 0; width: 100%; box-sizing: border-box;">`,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                const m = (document.getElementById('swal-input-main') as HTMLInputElement).value;
                const p = (document.getElementById('swal-input-prov') as HTMLInputElement).value;
                if (!m || !p) return false;
                return [m, p];
            }
        });

        if (formValues) {
            const [newMain, newProv] = formValues;
            dataService.updateHierarchyItem(oldMain, oldProv, newMain, newProv);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteHierarchy = async (main: string, prov: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ต้องการลบข้อมูล "${main} - ${prov}" ใช่หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบข้อมูล',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#ef4444',
        });
        if (result.isConfirmed) {
            dataService.deleteHierarchyItem(main, prov);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบเรียบร้อยแล้ว', 'success');
        }
    };

    const handleAddResponsible = async () => {
        if (!selectedMainAgency) return;
        const { value: formValues } = await Swal.fire({
            title: 'เพิ่มหน่วยงานบูรณาการ',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">หน่วยงานบูรณาการ</div>' +
                '<input id="swal-input1" class="swal2-input" placeholder="ชื่อหน่วยงาน" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">' +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">พื้นที่บูรณาการ</div>' +
                '<input id="swal-input2" class="swal2-input" placeholder="พื้นที่" style="margin: 0; width: 100%; box-sizing: border-box;">',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                const r = (document.getElementById('swal-input1') as HTMLInputElement).value;
                const a = (document.getElementById('swal-input2') as HTMLInputElement).value;
                if (!r) return false;
                return [r, a];
            }
        });
        if (formValues) {
            const [resp, area] = formValues;
            dataService.addResponsibleAgency(selectedMainAgency, resp, area);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditResponsible = async (oldResp: string, oldArea: string) => {
        if (!selectedMainAgency) return;
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูล',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">หน่วยงานบูรณาการ</div>' +
                `<input id="swal-input1" class="swal2-input" value="${oldResp}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">พื้นที่บูรณาการ</div>' +
                `<input id="swal-input2" class="swal2-input" value="${oldArea}" style="margin: 0; width: 100%; box-sizing: border-box;">`,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            preConfirm: () => {
                const r = (document.getElementById('swal-input1') as HTMLInputElement).value;
                const a = (document.getElementById('swal-input2') as HTMLInputElement).value;
                if (!r) return false;
                return [r, a];
            }
        });
        if (formValues) {
            const [newResp, newArea] = formValues;
            dataService.updateResponsibleAgency(selectedMainAgency, oldResp, oldArea, newResp, newArea);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteResponsible = async (resp: string, area: string) => {
        if (!selectedMainAgency) return;
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: `ลบหน่วยงาน "${resp}" ใช่หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: 'ลบ',
            confirmButtonColor: '#ef4444',
        });
        if (result.isConfirmed) {
            dataService.deleteResponsibleAgency(selectedMainAgency, resp, area);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('ลบสำเร็จ', 'ข้อมูลถูกลบแล้ว', 'success');
        }
    };

    const handleAddActivity = async () => {
        const { value: name } = await Swal.fire({
            title: 'เพิ่มกิจกรรม',
            input: 'text',
            inputLabel: 'ชื่อกิจกรรม',
            confirmButtonText: 'บันทึก',
            confirmButtonColor: '#059669',
            showCancelButton: true
        });
        if (name) {
            dataService.addActivity(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'เพิ่มกิจกรรมเรียบร้อยแล้ว', 'success');
        }
    };

    const handleEditActivity = async (oldName: string) => {
        const { value: name } = await Swal.fire({
            title: 'แก้ไขกิจกรรม',
            input: 'text',
            inputValue: oldName,
            confirmButtonText: 'บันทึก',
            confirmButtonColor: '#059669',
            showCancelButton: true
        });
        if (name && name !== oldName) {
            dataService.updateActivity(oldName, name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'แก้ไขเรียบร้อยแล้ว', 'success');
        }
    };

    const handleDeleteActivity = async (name: string) => {
        const result = await Swal.fire({ title: 'ลบกิจกรรม?', text: name, icon: 'warning', showCancelButton: true, confirmButtonColor: '#ef4444' });
        if (result.isConfirmed) {
            dataService.deleteActivity(name);
            setRefreshTrigger(prev => prev + 1);
            Swal.fire('สำเร็จ', 'ลบเรียบร้อยแล้ว', 'success');
        }
    };

    const handleAddUnit = async () => {
        const { value: name } = await Swal.fire({ title: 'เพิ่มหน่วยนับ', input: 'text', confirmButtonColor: '#059669', showCancelButton: true });
        if (name) { dataService.addUnit(name); setRefreshTrigger(prev => prev + 1); }
    };

    const handleEditUnit = async (oldName: string) => {
        const { value: name } = await Swal.fire({ title: 'แก้ไขหน่วยนับ', input: 'text', inputValue: oldName, confirmButtonColor: '#059669', showCancelButton: true });
        if (name && name !== oldName) { dataService.updateUnit(oldName, name); setRefreshTrigger(prev => prev + 1); }
    };

    const handleDeleteUnit = async (name: string) => {
        if ((await Swal.fire({ title: 'ลบหน่วยนับ?', text: name, icon: 'warning', showCancelButton: true, confirmButtonColor: '#ef4444' })).isConfirmed) {
            dataService.deleteUnit(name); setRefreshTrigger(prev => prev + 1);
        }
    };

    const handleAddIntegration = async () => {
        const { value: name } = await Swal.fire({ title: 'เพิ่มรายการบูรณาการ', input: 'text', confirmButtonColor: '#059669', showCancelButton: true });
        if (name) { dataService.addIntegration(name); setRefreshTrigger(prev => prev + 1); }
    };

    const handleEditIntegration = async (oldName: string) => {
        const { value: name } = await Swal.fire({ title: 'แก้ไขรายการ', input: 'text', inputValue: oldName, confirmButtonColor: '#059669', showCancelButton: true });
        if (name && name !== oldName) { dataService.updateIntegration(oldName, name); setRefreshTrigger(prev => prev + 1); }
    };

    const handleDeleteIntegration = async (name: string) => {
        if ((await Swal.fire({ title: 'ลบรายการ?', text: name, icon: 'warning', showCancelButton: true, confirmButtonColor: '#ef4444' })).isConfirmed) {
            dataService.deleteIntegration(name); setRefreshTrigger(prev => prev + 1);
        }
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'hierarchy':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                            <h4 className="text-lg font-semibold text-slate-800 dark:text-white">โครงสร้างหน่วยงานหลักและจังหวัด ({hierarchy.length})</h4>
                            <button onClick={handleAddHierarchy} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มข้อมูล
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'หน่วยงานหลัก', 'จังหวัด', 'จัดการ']}
                            data={hierarchy.map((item, idx) => ({
                                columns: [idx + 1, item.mainAgency, item.province],
                                onEdit: () => handleEditHierarchy(item.mainAgency, item.province),
                                onDelete: () => handleDeleteHierarchy(item.mainAgency, item.province)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'responsible':
                const responsibles = selectedMainAgency 
                    ? respData.filter(r => r.mainAgency === selectedMainAgency)
                    : [];
                return (
                    <div className="space-y-6">
                        <div className="max-w-md">
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">เลือกหน่วยงานหลักเพื่อดูข้อมูล</label>
                            <select
                                value={selectedMainAgency}
                                onChange={(e) => setSelectedMainAgency(e.target.value)}
                                className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl focus:ring-4 focus:ring-emerald-100 dark:focus:ring-emerald-900 focus:border-emerald-500 outline-none text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-900"
                            >
                                <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                {dropdowns.mainAgency.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        {selectedMainAgency ? (
                             <div className="space-y-4">
                                <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                                    <h4 className="text-lg font-semibold text-slate-800 dark:text-white">หน่วยงานบูรณาการของ {selectedMainAgency}</h4>
                                    <button onClick={handleAddResponsible} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                        <Plus size={16} /> เพิ่มข้อมูล
                                    </button>
                                </div>
                                <Table 
                                    headers={['หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'จัดการ']}
                                    data={responsibles.map((item) => ({
                                        columns: [item.responsibleAgency, item.integrationArea],
                                        onEdit: () => handleEditResponsible(item.responsibleAgency, item.integrationArea),
                                        onDelete: () => handleDeleteResponsible(item.responsibleAgency, item.integrationArea)
                                    }))}
                                    hasActions
                                />
                            </div>
                        ) : (
                            <div className="text-center py-20 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700">
                                <Users size={48} className="mx-auto mb-3 text-slate-300 dark:text-slate-600" />
                                <p className="text-slate-500 dark:text-slate-400">กรุณาเลือกหน่วยงานหลักด้านบน</p>
                            </div>
                        )}
                    </div>
                );
            case 'integration':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                            <h4 className="text-lg font-semibold text-slate-800 dark:text-white">รายการบูรณาการ ({dropdowns.integration.length})</h4>
                            <button onClick={handleAddIntegration} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มรายการ
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อรายการบูรณาการ', 'จัดการ']}
                            data={dropdowns.integration.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditIntegration(item),
                                onDelete: () => handleDeleteIntegration(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'activity':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                            <h4 className="text-lg font-semibold text-slate-800 dark:text-white">รายการกิจกรรม ({dropdowns.activity.length})</h4>
                            <button onClick={handleAddActivity} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มกิจกรรม
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อกิจกรรม', 'จัดการ']}
                            data={dropdowns.activity.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditActivity(item),
                                onDelete: () => handleDeleteActivity(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'unit':
                return (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 dark:border-slate-700 pb-2">
                            <h4 className="text-lg font-semibold text-slate-800 dark:text-white">รายการหน่วยนับ ({dropdowns.unit.length})</h4>
                            <button onClick={handleAddUnit} className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium">
                                <Plus size={16} /> เพิ่มหน่วยนับ
                            </button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อหน่วยนับ', 'จัดการ']}
                            data={dropdowns.unit.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleEditUnit(item),
                                onDelete: () => handleDeleteUnit(item)
                            }))}
                            hasActions
                        />
                    </div>
                );
            case 'fields':
                const fieldKeys = Object.keys(FIELD_LABELS);
                return (
                    <div className="space-y-4">
                         <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center mb-4">
                            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/50 rounded-xl p-4 flex-1">
                                <p className="text-sm text-blue-700 dark:text-blue-300 flex items-center gap-2">
                                    <Eye size={16} /> 
                                    ฟิลด์ที่ปิดจะถูกซ่อนในหน้าบันทึกข้อมูล
                                </p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => handleSetAllFields(true)} className="px-3 py-1.5 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-lg text-xs font-bold hover:bg-emerald-200 transition-colors">แสดงทั้งหมด</button>
                                <button onClick={() => handleSetAllFields(false)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-xs font-bold hover:bg-slate-200 transition-colors">ซ่อนทั้งหมด</button>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                            {fieldKeys.map((key) => (
                                <div key={key} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${fieldVisibility[key] ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 opacity-60'}`}>
                                    <span className="font-medium text-slate-700 dark:text-slate-300 text-sm">{FIELD_LABELS[key]}</span>
                                    <button
                                        onClick={() => handleToggleField(key)}
                                        className={`p-2 rounded-lg transition-colors flex items-center gap-1.5 text-xs font-bold ${fieldVisibility[key] ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' : 'bg-slate-200 dark:bg-slate-700 text-slate-500'}`}
                                    >
                                        {fieldVisibility[key] ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                                        {fieldVisibility[key] ? 'เปิด' : 'ปิด'}
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                );
            default: return null;
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">จัดการข้อมูลตัวเลือก</h2>
                    <p className="text-slate-500 dark:text-slate-400 transition-colors">จัดการข้อมูลพื้นฐานเพื่อนำไปใช้ในหน้าแบบฟอร์มบันทึกข้อมูล</p>
                </div>
                <button 
                    onClick={handleRefresh}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-5 py-2.5 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 border border-emerald-100 dark:border-emerald-800 rounded-xl hover:bg-emerald-100 transition-all font-bold text-base shadow-sm disabled:opacity-70`}
                >
                    <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูลจาก Sheets'}
                </button>
            </div>

            <div className="flex flex-col lg:flex-row gap-6">
                <div className="w-full lg:w-72 flex-shrink-0">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-2 sticky top-24">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl text-left transition-all duration-200 mb-1 last:mb-0 ${
                                    activeTab === tab.id 
                                    ? 'bg-emerald-600 text-white font-bold shadow-lg shadow-emerald-900/20' 
                                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700/50 hover:text-emerald-600 dark:hover:text-emerald-400'
                                }`}
                            >
                                {tab.icon}
                                <span>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-8 min-h-[600px]">
                    {renderContent()}
                </div>
            </div>
        </div>
    );
};

interface TableProps {
    headers: string[];
    data: {
        columns: (string | number)[];
        onEdit?: () => void;
        onDelete?: () => void;
    }[];
    hasActions?: boolean;
}

const Table = ({ headers, data, hasActions = false }: TableProps) => (
    <div className="overflow-hidden rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800">
        <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
                <thead>
                    <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                        {headers.map((h, i) => (
                            <th key={i} className={`px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ${i === headers.length - 1 && hasActions ? 'text-right' : ''}`}>
                                {h}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                    {data.length > 0 ? data.map((row, i) => (
                        <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                            {row.columns.map((cell, j) => (
                                <td key={j} className="px-6 py-4 text-slate-700 dark:text-slate-200 text-sm font-medium">
                                    {cell}
                                </td>
                            ))}
                            {hasActions && (
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-1.5">
                                        <button onClick={row.onEdit} className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors" title="แก้ไข">
                                            <Edit2 size={16} />
