        this.hierarchy.push({ mainAgency, province });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'add', data: { mainAgency, province } });
    }

    updateHierarchyItem(oldMain: string, oldProv: string, newMain: string, newProv: string) {
        const idx = this.hierarchy.findIndex(h => h.mainAgency === oldMain && h.province === oldProv);
        if (idx !== -1) {
            this.hierarchy[idx] = { mainAgency: newMain, province: newProv };
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'update', data: { mainAgency: newMain, province: newProv, oldMainAgency: oldMain, oldProvince: oldProv } });
        }
    }

    deleteHierarchyItem(main: string, prov: string) {
        this.hierarchy = this.hierarchy.filter(h => !(h.mainAgency === main && h.province === prov));
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'delete', data: { mainAgency: main, province: prov } });
    }

    addResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        this.respData.push({ mainAgency, responsibleAgency, integrationArea });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'add', data: { mainAgency, responsibleAgency, integrationArea } });
    }

    updateResponsibleAgency(main: string, oldResp: string, oldArea: string, newResp: string, newArea: string) {
        const idx = this.respData.findIndex(r => r.mainAgency === main && r.responsibleAgency === oldResp && r.integrationArea === oldArea);
        if (idx !== -1) {
            this.respData[idx] = { mainAgency: main, responsibleAgency: newResp, integrationArea: newArea };
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'update', data: { mainAgency: main, responsibleAgency: newResp, integrationArea: newArea, oldResponsibleAgency: oldResp, oldIntegrationArea: oldArea } });
        }
    }

    deleteResponsibleAgency(main: string, resp: string, area: string) {
        this.respData = this.respData.filter(r => !(r.mainAgency === main && r.responsibleAgency === resp && r.integrationArea === area));
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'delete', data: { mainAgency: main, responsibleAgency: resp, integrationArea: area } });
    }

    addActivity(name: string) {
        this.compareData.push({ id: name, activity: name, referenceBudget: 0 });
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'add', data: { activity: name, referenceBudget: 0 } });
    }

    updateActivity(old: string, newName: string) {
        const record = this.compareData.find(c => c.activity === old);
        if (record) {
            record.activity = newName;
            this.records = this.records.map(r => r.activity === old ? { ...r, activity: newName } : r);
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newName, oldActivity: old, referenceBudget: record.referenceBudget } });
        }
    }

    updateCompareData(id: string, newActivity: string, newBudget: number) {
        const idx = this.compareData.findIndex(c => c.id === id || c.activity === id);
        if (idx !== -1) {
            const old = this.compareData[idx].activity;
            this.compareData[idx].activity = newActivity;
            this.compareData[idx].referenceBudget = newBudget;
            if (old !== newActivity) {
                this.records = this.records.map(r => r.activity === old ? { ...r, activity: newActivity } : r);
            }
            this.updateDerivedDropdowns();
            this.saveToCache();
            this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newActivity, oldActivity: old, referenceBudget: newBudget } });
        }
    }

    deleteActivity(name: string) {
        this.compareData = this.compareData.filter(c => c.activity !== name);
        this.updateDerivedDropdowns();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'delete', data: { activity: name } });
    }

    addUnit(name: string) {
        this.dropdowns.unit = Array.from(new Set([...this.dropdowns.unit, name])).sort();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'add', data: { name } });
    }

    updateUnit(old: string, newName: string) {
        this.dropdowns.unit = this.dropdowns.unit.map(u => u === old ? newName : u).sort();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'update', data: { name: newName, oldName: old } });
    }

    deleteUnit(name: string) {
        this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'delete', data: { name } });
    }

    addIntegration(name: string) {
        this.dropdowns.integration = Array.from(new Set([...this.dropdowns.integration, name])).sort();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'add', data: { name } });
    }

    updateIntegration(old: string, newName: string) {
        this.dropdowns.integration = this.dropdowns.integration.map(i => i === old ? newName : i).sort();
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'update', data: { name: newName, oldName: old } });
    }

    deleteIntegration(name: string) {
        this.dropdowns.integration = this.dropdowns.integration.filter(i => i !== name);
        this.saveToCache();
        this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'delete', data: { name } });
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'GET_DATA' })
            });
            const json = await res.json();
            if (json.status === 'success' && json.data) {
                const s = json.data;
                // Normalize master data using Thai/English aliases
                this.hierarchy = (s.hierarchy || []).map((h: any) => this.normalizeHierarchy(h));
                this.respData = (s.respData || []).map((r: any) => this.normalizeResponsible(r));
                this.compareData = (s.compareData || []).map((c: any) => this.normalizeCompare(c));
                this.records = (s.records || []).map((r: any) => this.normalizeRecord(r));
                this.dropdowns.integration = s.dropdowns?.integration || [];
                this.dropdowns.unit = s.dropdowns?.unit || [];
                this.updateDerivedDropdowns();
                this.saveToCache();
            } else throw new Error(json.message || 'Sync failed');
        } catch (e: any) { console.error('Sync Error:', e); throw e; }
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action: 'TEST_CONNECTION' })
            });
            const json = await res.json();
            return json.status === 'success';
        } catch { return false; }
    }
}

