    private async sendToGas(action: string, payload: any) {
        const settings = getSettings();
        if (!settings.gasUrl) {
            console.error('GAS URL is not configured');
            return false;
        }

        // แปลงข้อมูลเป็นภาษาไทยก่อนส่ง (เพื่อให้ตรงกับหัวตารางใน Sheet)
        let dataToSend = payload;
        if (payload.data && typeof payload.data === 'object' && !Array.isArray(payload.data)) {
            const mappedData: any = {};
            // วนลูปตามหัวตารางที่ระบบต้องการ
            Object.keys(FIELD_LABELS).forEach(key => {
                if (payload.data[key] !== undefined) {
                    mappedData[FIELD_LABELS[key]] = payload.data[key];
                }
            });
            // ใส่ ID และ Timestamp กลับเข้าไป
            if (payload.data.id) mappedData['ID'] = payload.data.id;
            if (payload.data.timestamp) mappedData['วันที่บันทึก'] = payload.data.timestamp;

            dataToSend = { ...payload, data: mappedData };
        }

        try {
            console.log(`Sending action: ${action}`, dataToSend);
            const response = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ action, ...dataToSend })
            });
            const result = await response.json();
            console.log('Server response:', result);
            return result.status === 'success';
        } catch (e) {
            console.error('API Network Error:', e);
            return false;
        }
    }

