    private async sendToGas(action: string, payload: any): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) {
            console.error('GAS URL is not configured');
            return false;
        }

        // เตรียมข้อมูลที่รวมเอาการตั้งค่าชีทไปด้วย เพื่อให้ Script ทำงานถูกที่
        let finalPayload = {
            action,
            sheetsId: settings.sheetsId,
            databaseSheetName: settings.databaseSheetName,
            dataSheetName: settings.dataSheetName,
            ...payload
        };

        // แปลงข้อมูลเป็นภาษาไทยก่อนส่ง (เฉพาะส่วน data)
        if (payload.data && typeof payload.data === 'object' && !Array.isArray(payload.data)) {
            const mappedData: any = {};
            Object.keys(FIELD_LABELS).forEach(key => {
                if (payload.data[key] !== undefined) {
                    mappedData[FIELD_LABELS[key]] = payload.data[key];
                }
            });
            if (payload.data.id) mappedData['ID'] = payload.data.id;
            if (payload.data.timestamp) mappedData['วันที่บันทึก'] = payload.data.timestamp;
            finalPayload.data = mappedData;
        }

        try {
            console.log(`Sending to GAS: ${action}`, finalPayload);
            const response = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify(finalPayload)
            });

            if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

            const result = await response.json();
            console.log('GAS Response:', result);
            return result.status === 'success';
        } catch (e) {
            console.error('GAS Connection Failed:', e);
            return false;
        }
    }

