            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
        });

        if (confirmResult.isConfirmed) {
            setIsSubmitting(true);
            Swal.fire({
                title: 'กำลังบันทึกข้อมูล...',
                text: 'กรุณารอสักครู่ ระบบกำลังส่งข้อมูลไปที่ Google Sheets',
