        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'delete', data: { name } });
        if (result.success) {
            this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name).sort();
            this.saveToCache();
        }
