};

export class DataService {
    private records: BudgetRecord[] = [];
    private dropdowns: DropdownOptions = INITIAL_DROPDOWN_DATA;
    private hierarchy: HierarchyData[] = INITIAL_HIERARCHY;
    private respData: ResponsibleAgencyData[] = INITIAL_RESP_DATA;
    private compareData: CompareRecord[] = INITIAL_COMPARE_DATA;
    private fieldVisibility: FieldVisibility = {
        integration: true, mainAgency: true, province: true, responsibleAgency: true,
        integrationArea: true, activity: true, target: true, unit: true,
        salaryPermanent: true, governmentCompensation: true, compensationSupplies: true,
        contractEmployees: true, utilities: true, equipment: true, landConstruction: true,
        subsidies: true, otherExpenses: true
    };

    constructor() {
        this.loadFromCache();
    }

    private sortIntegrationData(list: string[]): string[] {
        return [...list].sort((a, b) => {
            const idxA = INTEGRATION_PRIORITY.indexOf(a);
            const idxB = INTEGRATION_PRIORITY.indexOf(b);

            if (idxA !== -1 && idxB !== -1) return idxA - idxB;
            if (idxA !== -1) return -1;
            if (idxB !== -1) return 1;
            return a.localeCompare(b, 'th');
        });
    }

    private loadFromCache() {
        const cached = localStorage.getItem(CACHE_KEY);
        if (cached) {
            const parsed = JSON.parse(cached);
            this.records = parsed.records || INITIAL_BUDGET_RECORDS;
            this.dropdowns = parsed.dropdowns || INITIAL_DROPDOWN_DATA;
            this.dropdowns.integration = this.sortIntegrationData(this.dropdowns.integration);

            this.hierarchy = parsed.hierarchy || INITIAL_HIERARCHY;
            this.respData = parsed.respData || INITIAL_RESP_DATA;
            this.compareData = parsed.compareData || INITIAL_COMPARE_DATA;
            this.fieldVisibility = parsed.fieldVisibility || this.fieldVisibility;
        }
    }

    private saveToCache() {
        localStorage.setItem(CACHE_KEY, JSON.stringify({
            records: this.records,
            dropdowns: this.dropdowns,
            hierarchy: this.hierarchy,
            respData: this.respData,
            compareData: this.compareData,
            fieldVisibility: this.fieldVisibility
        }));
    }

    private getValueByAliases(obj: any, aliases: string[]): any {
        if (!obj) return undefined;
        for (const alias of aliases) {
            if (obj[alias] !== undefined && obj[alias] !== null) return obj[alias];
        }
        return undefined;
    }

    private normalizeRecord(raw: any): BudgetRecord {
        const getStr = (aliases: string[]) => String(this.getValueByAliases(raw, aliases) || '');
        const getNum = (aliases: string[]) => {
            const val = this.getValueByAliases(raw, aliases);
            return typeof val === 'number' ? val : parseNumber(String(val || 0));
        };

        return {
            id: getStr(['id', 'ID', 'ลำดับ', 'รหัส']),
            integration: getStr(['integration', 'บูรณาการ', 'ประเภทหน่วยงาน']),
            mainAgency: getStr(['mainAgency', 'หน่วยงานหลัก', 'สังกัด']),
            province: getStr(['province', 'จังหวัด']),
            responsibleAgency: getStr(['responsibleAgency', 'หน่วยงานบูรณาการ', 'หน่วยงานรับผิดชอบ']),
            integrationArea: getStr(['integrationArea', 'พื้นที่บูรณาการ', 'พื้นที่']),
            activity: getStr(['activity', 'กิจกรรม', 'ชื่อกิจกรรม']),
            target: getStr(['target', 'เป้าหมาย']),
            unit: getStr(['unit', 'หน่วยนับ']),
            salaryPermanent: getNum(['salaryPermanent', 'เงินเดือนและค่าจ้างประจำ', 'เงินเดือน']),
            governmentCompensation: getNum(['governmentCompensation', 'ค่าตอบแทนพนักงานราชการ', 'ค่าตอบแทน']),
            compensationSupplies: getNum(['compensationSupplies', 'ค่าตอบแทน ใช้สอย และวัสดุ', 'ค่าใช้สอย']),
            contractEmployees: getNum(['contractEmployees', 'ค่าจ้างเหมาพนักงาน', 'จ้างเหมา']),
            utilities: getNum(['utilities', 'ค่าสาธารณูปโภค']),
            equipment: getNum(['equipment', 'ค่าครุภัณฑ์']),
            landConstruction: getNum(['landConstruction', 'ค่าที่ดินและสิ่งก่อสร้าง', 'สิ่งก่อสร้าง']),
            subsidies: getNum(['subsidies', 'งบเงินอุดหนุน', 'เงินอุดหนุน']),
            otherExpenses: getNum(['otherExpenses', 'งบรายจ่ายอื่น', 'รายจ่ายอื่น']),
            timestamp: getStr(['timestamp', 'วันที่บันทึก', 'เวลา'])
        };
    }

    private async sendToGas(action: string, payload: any): Promise<{ success: boolean; message?: string }> {
        const settings = getSettings();
        if (!settings.gasUrl) return { success: false, message: 'กรุณาตั้งค่า URL ของ Google Apps Script' };

        // Start with original data to preserve unmapped fields (like oldActivity, oldMainAgency)
        const mappedData: any = { ...payload.data };

        if (payload.data) {
            Object.keys(FIELD_LABELS).forEach(key => {
                const label = FIELD_LABELS[key];
                const value = payload.data[key];
                if (value !== undefined) {
                    mappedData[label] = value;
                }
            });

            if (payload.data.integration) {
                mappedData['บูรณาการ'] = payload.data.integration;
                mappedData['บูรณาการ (ประเภทหน่วยงาน)'] = payload.data.integration;
                mappedData['ประเภทหน่วยงาน'] = payload.data.integration;
            }

            if (payload.data.id) {
                mappedData['ID'] = payload.data.id;
                mappedData['id'] = payload.data.id;
                mappedData['ลำดับ'] = payload.data.id;
            }
        }

        const finalPayload = {
            action,
            sheetsId: settings.sheetsId,
            databaseSheetName: settings.databaseSheetName,
            dataSheetName: settings.dataSheetName,
            ...payload,
            data: mappedData,
            id: payload.id || payload.data?.id
        };

        try {
            const response = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify(finalPayload)
            });

            if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);
            const result = await response.json();

            if (result.status === 'success') return { success: true };
            return { success: false, message: result.message || 'Unknown error' };
        } catch (e: any) {
            console.error('[GAS Connection Failed]', e);
            return { success: false, message: e.message };
        }
    }

    getRecords() { return this.records; }
    getDropdowns() { return this.dropdowns; }
    getHierarchy() { return this.hierarchy; }
    getResponsibleData() { return this.respData; }
    getCompareData() { return this.compareData; }
    getFieldVisibility() { return this.fieldVisibility; }

    async addRecord(record: BudgetRecord): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_RECORD', { type: 'add', data: record });
        if (result.success) {
            this.records = [...this.records, record];
            this.saveToCache();
        }
        return result;
    }

    async updateRecord(updated: BudgetRecord): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_RECORD', { type: 'update', data: updated, id: updated.id });
        if (result.success) {
            this.records = this.records.map(r => r.id === updated.id ? updated : r);
            this.saveToCache();
        }
        return result;
    }

    async deleteRecord(id: string): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_RECORD', { type: 'delete', id: id });
        if (result.success) {
            this.records = this.records.filter(r => r.id !== id);
            this.saveToCache();
        }
        return result;
    }

    checkDuplicate(record: Partial<BudgetRecord>): boolean {
        return this.records.some(existing => {
            if (record.id && existing.id === record.id) return false;
            return (existing.integration || '').trim() === (record.integration || '').trim() &&
                   (existing.mainAgency || '').trim() === (record.mainAgency || '').trim() &&
                   (existing.province || '').trim() === (record.province || '').trim() &&
                   (existing.activity || '').trim() === (record.activity || '').trim();
        });
    }

    toggleFieldVisibility(field: string) {
        this.fieldVisibility = { ...this.fieldVisibility, [field]: !this.fieldVisibility[field] };
        this.saveToCache();
    }

    setAllFieldsVisibility(visible: boolean) {
        const newVisibility: FieldVisibility = {};
        Object.keys(FIELD_LABELS).forEach(key => {
            if (key !== 'id' && key !== 'timestamp') newVisibility[key] = visible;
        });
        this.fieldVisibility = newVisibility;
        this.saveToCache();
    }

    private updateDerivedDropdowns() {
        const unique = (arr: any[]) => Array.from(new Set(arr.filter(item => item && item.trim() !== '')));
        // นำ .sort() ออกเพื่อให้เรียงตามลำดับใน Hierarchy/RespData (ซึ่งมาจาก Sheet)
        this.dropdowns.mainAgency = unique(this.hierarchy.map(h => h.mainAgency));
        this.dropdowns.province = unique(this.hierarchy.map(h => h.province));
        this.dropdowns.responsibleAgency = unique(this.respData.map(r => r.responsibleAgency));
        this.dropdowns.integrationArea = unique(this.respData.map(r => r.integrationArea));
        this.dropdowns.activity = unique(this.compareData.map(c => c.activity));

        // บูรณาการยังคงเรียงตามลำดับความสำคัญพิเศษ
        this.dropdowns.integration = this.sortIntegrationData(this.dropdowns.integration);
    }

    // Master Data Methods
    async addHierarchyItem(mainAgency: string, province: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'add', data: { mainAgency, province } });
        if (result.success) {
            this.hierarchy.push({ mainAgency, province });
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async updateHierarchyItem(oldMain: string, oldProv: string, newMain: string, newProv: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'update', data: { mainAgency: newMain, province: newProv, oldMainAgency: oldMain, oldProvince: oldProv } });
        if (result.success) {
            const idx = this.hierarchy.findIndex(h => h.mainAgency === oldMain && h.province === oldProv);
            if (idx !== -1) {
                this.hierarchy[idx] = { mainAgency: newMain, province: newProv };
                this.updateDerivedDropdowns();
                this.saveToCache();
            }
        }
        return result;
    }

    async deleteHierarchyItem(main: string, prov: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Hierarchy', type: 'delete', data: { mainAgency: main, province: prov } });
        if (result.success) {
            this.hierarchy = this.hierarchy.filter(h => !(h.mainAgency === main && h.province === prov));
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async addResponsibleAgency(mainAgency: string, responsibleAgency: string, integrationArea: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'add', data: { mainAgency, responsibleAgency, integrationArea } });
        if (result.success) {
            this.respData.push({ mainAgency, responsibleAgency, integrationArea });
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async updateResponsibleAgency(main: string, oldResp: string, oldArea: string, newResp: string, newArea: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'update', data: { mainAgency: main, responsibleAgency: newResp, integrationArea: newArea, oldResponsibleAgency: oldResp, oldIntegrationArea: oldArea } });
        if (result.success) {
            const idx = this.respData.findIndex(r => r.mainAgency === main && r.responsibleAgency === oldResp && r.integrationArea === oldArea);
            if (idx !== -1) {
                this.respData[idx] = { mainAgency: main, responsibleAgency: newResp, integrationArea: newArea };
                this.updateDerivedDropdowns();
                this.saveToCache();
            }
        }
        return result;
    }

    async deleteResponsibleAgency(main: string, resp: string, area: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'ResponsibleAgency', type: 'delete', data: { mainAgency: main, responsibleAgency: resp, integrationArea: area } });
        if (result.success) {
            this.respData = this.respData.filter(r => !(r.mainAgency === main && r.responsibleAgency === resp && r.integrationArea === area));
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async addActivity(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'add', data: { activity: name, referenceBudget: 0 } });
        if (result.success) {
            this.compareData.push({ id: name, activity: name, referenceBudget: 0 });
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async updateActivity(old: string, newName: string) {
        const record = this.compareData.find(c => c.activity === old);
        if (record) {
            const result = await this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newName, oldActivity: old, referenceBudget: record.referenceBudget } });
            if (result.success) {
                record.activity = newName;
                this.records = this.records.map(r => r.activity === old ? { ...r, activity: newName } : r);
                this.updateDerivedDropdowns();
                this.saveToCache();
            }
            return result;
        }
        return { success: false, message: 'Activity not found' };
    }

    async updateCompareData(id: string, newActivity: string, newBudget: number) {
        const idx = this.compareData.findIndex(c => c.id === id || c.activity === id);
        if (idx !== -1) {
            const old = this.compareData[idx].activity;
            const result = await this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'update', data: { activity: newActivity, oldActivity: old, referenceBudget: newBudget } });
            if (result.success) {
                this.compareData[idx].activity = newActivity;
                this.compareData[idx].referenceBudget = newBudget;
                if (old !== newActivity) {
                    this.records = this.records.map(r => r.activity === old ? { ...r, activity: newActivity } : r);
                }
                this.updateDerivedDropdowns();
                this.saveToCache();
            }
            return result;
        }
        return { success: false, message: 'Data not found' };
    }

    async deleteActivity(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Compare', type: 'delete', data: { activity: name } });
        if (result.success) {
            this.compareData = this.compareData.filter(c => c.activity !== name);
            this.updateDerivedDropdowns();
            this.saveToCache();
        }
        return result;
    }

    async addUnit(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'add', data: { name } });
        if (result.success) {
            this.dropdowns.unit = Array.from(new Set([...this.dropdowns.unit, name]));
            this.saveToCache();
        }
        return result;
    }

    async updateUnit(old: string, newName: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'update', data: { name: newName, oldName: old } });
        if (result.success) {
            this.dropdowns.unit = this.dropdowns.unit.map(u => u === old ? newName : u);
            this.saveToCache();
        }
        return result;
    }

    async deleteUnit(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'delete', data: { name } });
        if (result.success) {
            this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name);
            this.saveToCache();
        }
        return result;
    }

    async addIntegration(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'add', data: { name } });
        if (result.success) {
            const newList = Array.from(new Set([...this.dropdowns.integration, name]));
            this.dropdowns.integration = this.sortIntegrationData(newList);
            this.saveToCache();
        }
        return result;
    }

    async updateIntegration(old: string, newName: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'update', data: { name: newName, oldName: old } });
        if (result.success) {
            const newList = this.dropdowns.integration.map(i => i === old ? newName : i);
            this.dropdowns.integration = this.sortIntegrationData(newList);
            this.saveToCache();
        }
        return result;
    }

    async deleteIntegration(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'delete', data: { name } });
        if (result.success) {
            const newList = this.dropdowns.integration.filter(i => i !== name);
            this.dropdowns.integration = this.sortIntegrationData(newList);
            this.saveToCache();
        }
        return result;
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ 
                    action: 'GET_DATA',
                    sheetsId: settings.sheetsId,
                    databaseSheetName: settings.databaseSheetName,
                    dataSheetName: settings.dataSheetName
                })
            });
            const json = await res.json();
            if (json.status === 'success' && json.data) {
                const s = json.data;
                const normalizeH = (raw: any): HierarchyData => ({
                    mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                    province: String(this.getValueByAliases(raw, ['province', 'จังหวัด']) || '')
                });
                const normalizeR = (raw: any): ResponsibleAgencyData => ({
                    mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                    responsibleAgency: String(this.getValueByAliases(raw, ['responsibleAgency', 'หน่วยงานบูรณาการ']) || ''),
                    integrationArea: String(this.getValueByAliases(raw, ['integrationArea', 'พื้นที่บูรณาการ']) || '')
                });
                const normalizeC = (raw: any): CompareRecord => {
                    const activity = String(this.getValueByAliases(raw, ['activity', 'กิจกรรม']) || '');
                    return {
                        id: String(this.getValueByAliases(raw, ['id', 'ID']) || activity),
                        activity: activity,
                        referenceBudget: parseNumber(String(this.getValueByAliases(raw, ['referenceBudget', 'งบอ้างอิง', 'งบประมาณ']) || 0))
                    };
                };

                this.hierarchy = (s.hierarchy || []).map(normalizeH);
                this.respData = (s.respData || []).map(normalizeR);
                this.compareData = (s.compareData || []).map(normalizeC);
                this.records = (s.records || []).map((r: any) => this.normalizeRecord(r));

                // นำ .sort() ออกเพื่อให้เป็นไปตามลำดับใน Sheet
                this.dropdowns.integration = this.sortIntegrationData(s.dropdowns?.integration || []);
                this.dropdowns.unit = s.dropdowns?.unit || [];

                this.updateDerivedDropdowns();
                this.saveToCache();
            } else throw new Error(json.message || 'Sync failed');
        } catch (e: any) { console.error('Sync Error:', e); throw e; }
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ 
                    action: 'TEST_CONNECTION',
                    sheetsId: settings.sheetsId 
                })
            });
            const json = await res.json();
            return json.status === 'success';
        } catch { return false; }
    }
}

export const dataService = new DataService();

import React, { useState, useEffect, useMemo } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale, Edit2, RefreshCw, AlertCircle, CheckCircle2, TrendingDown } from 'lucide-react';
import Swal from 'sweetalert2';
import { CompareRecord } from '../../types';

const CompareView: React.FC = () => {
    const [refreshTrigger, setRefreshTrigger] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Get Data
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = useMemo(() => {
        return records.reduce((acc, r) => {
            const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                          (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                          (r.equipment || 0) + (r.landConstruction || 0) +
                          (r.subsidies || 0) + (r.otherExpenses || 0);
            const activityName = (r.activity || '').trim();
            acc[activityName] = (acc[activityName] || 0) + total;
            return acc;
        }, {} as Record<string, number>);
    }, [records, refreshTrigger]);

    const comparisonResults = useMemo(() => {
        return compareTargets.map(target => {
            const activityName = (target.activity || '').trim();
            const actual = actualsByActivity[activityName] || 0;
            const refBudget = Number(target.referenceBudget || 0);
            const variance = actual - refBudget;

            let status = 'match';
            if (actual === 0 && refBudget > 0) status = 'nodata';
            else if (actual === 0 && refBudget === 0) status = 'nodata';
            else if (variance > 0) status = 'over';
            else if (variance < 0) status = 'under';

            return { ...target, actual, variance, status };
        });
    }, [compareTargets, actualsByActivity, refreshTrigger]);

    const totalRef = useMemo(() => comparisonResults.reduce((sum, r) => sum + (r.referenceBudget || 0), 0), [comparisonResults]);
    const totalAct = useMemo(() => comparisonResults.reduce((sum, r) => sum + (r.actual || 0), 0), [comparisonResults]);
    const totalVar = totalAct - totalRef;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลล่าสุดเรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error: any) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'ไม่สามารถดึงข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    const handleEdit = async (record: CompareRecord) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขข้อมูลกิจกรรม',
            html:
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">ชื่อกิจกรรม</div>' +
                `<input id="swal-input-activity" class="swal2-input" placeholder="ชื่อกิจกรรม" value="${record.activity}" style="margin: 0 0 1.5rem 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-bottom: 0.5rem; font-weight: 500; color: #374151;">งบอ้างอิง (บาท)</div>' +
                `<input id="swal-input-budget" type="text" class="swal2-input" placeholder="งบประมาณ" value="${formatNumber(record.referenceBudget)}" style="margin: 0; width: 100%; box-sizing: border-box;">` +
                '<div style="text-align: left; margin-top: 0.25rem; font-size: 0.875rem; color: #6b7280;">* ใส่ลูกน้ำ (,) เพื่อให้อ่านง่าย</div>',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            didOpen: () => {
                const input = Swal.getPopup()?.querySelector('#swal-input-budget') as HTMLInputElement;
                if (input) {
                    input.addEventListener('input', (e) => {
                        let val = (e.target as HTMLInputElement).value.replace(/[^0-9.]/g, '');
                        const parts = val.split('.');
                        if (parts.length > 2) val = parts[0] + '.' + parts.slice(1).join('');

                        if (val) {
                            const numberParts = val.split('.');
                            numberParts[0] = numberParts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
                            (e.target as HTMLInputElement).value = numberParts.join('.');
                        } else {
                            (e.target as HTMLInputElement).value = '';
                        }
                    });
                }
            },
            preConfirm: () => {
                const activity = (document.getElementById('swal-input-activity') as HTMLInputElement).value;
                const budgetStr = (document.getElementById('swal-input-budget') as HTMLInputElement).value;
                if (!activity) {
                    Swal.showValidationMessage('กรุณาระบุชื่อกิจกรรม');
                }
                const budget = parseFloat(budgetStr.replace(/,/g, '')) || 0;
                return {
                    activity: activity,
                    budget: budget
                };
            }
        });

        if (formValues) {
             Swal.fire({
                title: 'กำลังบันทึก...',
                text: 'กรุณารอสักครู่ ระบบกำลังส่งข้อมูลไปที่ Google Sheets',
                allowOutsideClick: false,
                didOpen: () => { Swal.showLoading(); }
            });

            try {
                const result = await dataService.updateCompareData(record.id, formValues.activity, formValues.budget);

                if (result.success) {
                    setRefreshTrigger(prev => prev + 1);
                    Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อยแล้ว', 'success');
                } else {
                    throw new Error(result.message || 'บันทึกไม่สำเร็จ');
                }
            } catch (error: any) {
                Swal.fire({
                    title: 'บันทึกล้มเหลว',
                    text: error.message || 'ไม่สามารถติดต่อ Google Sheets ได้',
                    icon: 'error',
                    confirmButtonColor: '#ef4444'
                });
            }
        }
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">เปรียบเทียบงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">วิเคราะห์ความแตกต่างระหว่างงบประมาณที่ตั้งไว้และงบที่ใช้จริงตามกิจกรรม</p>
                </div>
                <button 
                    onClick={handleSync}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-5 py-2.5 bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-600 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-sm disabled:opacity-70 disabled:cursor-not-allowed active:scale-95`}
                >
                    <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูล'}
                </button>
            </div>

            {/* Summary Cards */}
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors hover:shadow-md">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">งบอ้างอิงรวม</p>
                        <p className="text-2xl font-bold text-blue-600 dark:text-blue-400">{formatNumber(totalRef)} <span className="text-sm font-normal opacity-70">บาท</span></p>
                    </div>
                    <div className="p-4 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-2xl shadow-inner">
                        <Target size={24} />
                    </div>
                </div>
                 <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 flex items-center justify-between transition-colors hover:shadow-md">
                    <div>
                        <p className="text-slate-500 dark:text-slate-400 text-xs font-bold uppercase tracking-wider mb-1">งบที่บันทึกรวม</p>
                        <p className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{formatNumber(totalAct)} <span className="text-sm font-normal opacity-70">บาท</span></p>
                    </div>
                    <div className="p-4 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-2xl shadow-inner">
                        <TrendingUp size={24} />
                    </div>
                </div>
                 <div className={`p-6 rounded-2xl shadow-sm border flex items-center justify-between transition-colors hover:shadow-md ${
                     totalVar > 0 
                     ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-900/50' 
                     : totalVar < 0 
                        ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-900/50'
                        : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-900/50'
                 }`}>
                    <div>
                        <p className={`text-xs font-bold uppercase tracking-wider mb-1 ${
                            totalVar > 0 ? 'text-amber-700 dark:text-amber-400' 
                            : totalVar < 0 ? 'text-rose-700 dark:text-rose-400'
                            : 'text-emerald-700 dark:text-emerald-400'
                        }`}>ส่วนต่างรวม</p>
                        <p className={`text-2xl font-bold ${
                            totalVar > 0 ? 'text-amber-700 dark:text-amber-400' 
                            : totalVar < 0 ? 'text-rose-700 dark:text-rose-400'
                            : 'text-emerald-700 dark:text-emerald-400'
                        }`}>
                            {totalVar > 0 ? '+' : ''}{formatNumber(totalVar)} <span className="text-sm font-normal opacity-70">บาท</span>
                        </p>
                    </div>
                    <div className={`p-4 rounded-2xl shadow-inner ${
                        totalVar > 0 ? 'bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400' 
                        : totalVar < 0 ? 'bg-rose-100 dark:bg-rose-900/40 text-rose-700 dark:text-rose-400'
                        : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400'
                    }`}>
                        <Scale size={24} />
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="min-w-full border-collapse">
                        <thead className="bg-slate-100 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-700">
                            <tr>
                                <th className="px-6 py-4 text-left text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">กิจกรรม</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">งบอ้างอิง</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">งบที่บันทึก</th>
                                <th className="px-6 py-4 text-right text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">ส่วนต่าง</th>
                                <th className="px-6 py-4 text-center text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">สถานะ</th>
                                <th className="px-6 py-4 text-center text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight">จัดการ</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
                            {comparisonResults.length > 0 ? comparisonResults.map(res => (
                                <tr key={res.id} className={`transition-all group ${
                                    res.status === 'over' 
                                        ? 'bg-amber-100/50 dark:bg-amber-900/20 hover:bg-amber-200/50 dark:hover:bg-amber-900/30' 
                                        : res.status === 'under' 
                                            ? 'bg-rose-100/50 dark:bg-rose-900/20 hover:bg-rose-200/50 dark:hover:bg-rose-900/30'
                                            : res.status === 'match'
                                                ? 'bg-emerald-100/50 dark:bg-emerald-900/20 hover:bg-emerald-200/50 dark:hover:bg-emerald-900/30'
                                                : 'bg-white dark:bg-slate-800 hover:bg-slate-50/50 dark:hover:bg-slate-700/30'
                                }`}>
                                    <td className="px-6 py-4 text-base font-medium text-slate-800 dark:text-slate-100">{res.activity || '-'}</td>
                                    <td className="px-6 py-4 text-base text-slate-600 dark:text-slate-400 text-right">{formatNumber(res.referenceBudget)}</td>
                                    <td className="px-6 py-4 text-base text-slate-900 dark:text-slate-100 text-right font-bold">{formatNumber(res.actual)}</td>
                                    <td className={`px-6 py-4 text-base text-right font-bold ${
                                        res.variance > 0 ? 'text-amber-700 dark:text-amber-400' 
                                        : res.variance < 0 ? 'text-rose-700 dark:text-rose-400' 
                                        : 'text-slate-400'
                                    }`}>
                                        {res.variance > 0 ? '+' : ''}{formatNumber(res.variance)}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <div className="flex justify-center">
                                            {res.status === 'nodata' && (
                                                <span className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-300 rounded-full text-xs font-semibold border border-slate-200 dark:border-slate-600">
                                                    <AlertCircle size={14} /> ไม่มีข้อมูล
                                                </span>
                                            )}
                                            {res.status === 'over' && (
                                                <span className="flex items-center gap-1.5 px-3 py-1 bg-amber-200/80 dark:bg-amber-900/60 text-amber-800 dark:text-amber-300 rounded-full text-xs font-bold border border-amber-300 dark:border-amber-700">
                                                    <TrendingUp size={14} /> เกินงบ
                                                </span>
                                            )}
                                            {res.status === 'under' && (
                                                <span className="flex items-center gap-1.5 px-3 py-1 bg-rose-200/80 dark:bg-rose-900/60 text-rose-800 dark:text-rose-300 rounded-full text-xs font-bold border border-rose-300 dark:border-rose-700">
                                                    <TrendingDown size={14} /> ต่ำกว่างบ
                                                </span>
                                            )}
                                            {res.status === 'match' && (
                                                <span className="flex items-center gap-1.5 px-3 py-1 bg-emerald-200/80 dark:bg-emerald-900/60 text-emerald-800 dark:text-emerald-300 rounded-full text-xs font-bold border border-emerald-300 dark:border-emerald-700">
                                                    <CheckCircle2 size={14} /> ตรงตามงบ
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <button 
                                            onClick={() => handleEdit(res)}
                                            className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/40 rounded-lg transition-all shadow-sm bg-white dark:bg-slate-700 border border-slate-100 dark:border-slate-600 active:scale-90"
                                            title="แก้ไข"
                                        >
                                            <Edit2 size={18} />
                                        </button>
                                    </td>
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan={6} className="px-6 py-20 text-center">
                                        <div className="flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                                            <Target size={64} className="mb-4 opacity-10" />
                                            <p className="text-xl font-medium">ไม่พบข้อมูลกิจกรรมเพื่อเปรียบเทียบ</p>
                                            <p className="text-base mt-1">กรุณากด "ซิงค์ข้อมูล" หรือเพิ่มกิจกรรมในหน้าจัดการข้อมูล</p>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-8 bg-blue-50 dark:bg-blue-900/10 p-6 rounded-3xl border border-blue-100 dark:border-blue-900/30">
                <div className="flex items-start gap-4">
                    <div className="p-2 bg-blue-500 text-white rounded-lg shadow-md shrink-0">
                        <AlertCircle size={20} />
                    </div>
                    <div>
                        <h4 className="font-bold text-blue-800 dark:text-blue-300 mb-1">เกี่ยวกับสถานะงบประมาณ</h4>
                        <ul className="text-sm text-blue-700 dark:text-blue-400 space-y-1 list-disc ml-4">
                            <li><strong>ตรงตามงบ:</strong> งบประมาณที่บันทึกใช้จริงเท่ากับงบอ้างอิง</li>
                            <li><strong>เกินงบ:</strong> งบประมาณที่บันทึกใช้จริงสูงกว่างบอ้างอิง (แสดงเป็นส่วนต่างสีเหลือง)</li>
                            <li><strong>ต่ำกว่างบ:</strong> งบประมาณที่บันทึกใช้จริงน้อยกว่างบอ้างอิง (แสดงเป็นส่วนต่างสีแดง)</li>
                            <li><strong>ไม่มีข้อมูล:</strong> ยังไม่มีการบันทึกงบประมาณสำหรับกิจกรรมนี้ในฐานข้อมูล</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CompareView;

payload.text:
ใช่ครับ **จำเป็นต้องแก้ไข Google Apps Script (GAS) ด้วยครับ**

สาเหตุที่ข้อมูลบนหน้าเว็บเปลี่ยนแต่ Google Sheet ไม่เปลี่ยน เป็นเพราะฝั่ง Script บน Google Sheet อาจจะยังไม่มี "ตรรกะ" ในการค้นหาและแก้ไขข้อมูลสำหรับตารางเปรียบเทียบ (Compare Data) โดยเฉพาะเมื่อมีการ **เปลี่ยนชื่อกิจกรรม** ระบบจำเป็นต้องใช้ชื่อเดิม (`oldActivity`) เพื่อไปค้นหาบรรทัดที่ถูกต้องก่อนทำการแก้ไขครับ

ผมได้อัปเดตไฟล์ `services/dataService.ts` เพื่อส่งข้อมูล "ชื่อกิจกรรมเดิม" ในรูปแบบภาษาไทยไปด้วย (เช่น `กิจกรรมเดิม`, `ชื่อกิจกรรมเดิม`) เพื่อให้ Script นำไปใช้ง่ายขึ้น และขอแนะนำให้คุณนำโค้ดด้านล่างนี้ไป **เพิ่มหรือแก้ไขใน Google Apps Script** ของคุณครับ

### 1. โค้ด Google Apps Script (นำไปวางทับฟังก์ชัน `handleManageMaster` หรือเพิ่มในส่วนจัดการ Master Data)

ตรวจสอบให้แน่ใจว่าใน Google Sheet มีชีทชื่อ **"Compare"** (หรือชื่อที่คุณตั้งไว้เก็บข้อมูลกิจกรรม) และมีหัวตารางอย่างน้อย: `กิจกรรม` และ `งบอ้างอิง`

```javascript
function handleManageMaster(payload) {
  var target = payload.target; // Hierarchy, ResponsibleAgency, Compare, etc.
  var type = payload.type;     // add, update, delete
  var data = payload.data;

  // กำหนดชื่อ Sheet ตาม Target
  var sheetName = "";
  if (target === "Compare") sheetName = "Compare"; // *ตรวจสอบชื่อชีทใน Google Sheet ให้ตรงกัน*
  else if (target === "Hierarchy") sheetName = "Hierarchy";
  else if (target === "ResponsibleAgency") sheetName = "ResponsibleAgency";
  else if (target === "Unit") sheetName = "Unit";
  else if (target === "Integration") sheetName = "Integration";

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName(sheetName);

  if (!sheet) {
    // ถ้าไม่มีชีท ให้สร้างใหม่และใส่หัวตาราง
    sheet = ss.insertSheet(sheetName);
    if (target === "Compare") sheet.appendRow(["กิจกรรม", "งบอ้างอิง"]);
    // ... (สร้างหัวตารางสำหรับ target อื่นๆ ตามต้องการ)
  }

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  var lastRow = sheet.getLastRow();

  // === กรณีจัดการ Compare (กิจกรรมและงบอ้างอิง) ===
  if (target === "Compare") {
    // หา index ของคอลัมน์ (เริ่มที่ 0)
    var colActivity = headers.indexOf("กิจกรรม");
    var colBudget = headers.indexOf("งบอ้างอิง");

    if (colActivity === -1) return { status: "error", message: "ไม่พบคอลัมน์ 'กิจกรรม'" };

    if (type === "add") {
      sheet.appendRow([data.activity || data['กิจกรรม'], data.referenceBudget || data['งบอ้างอิง'] || 0]);
      return { status: "success" };
    } 
    else if (type === "update") {
      var oldVal = data.oldActivity || data['กิจกรรมเดิม'] || data['ชื่อกิจกรรมเดิม'] || data.activity;
      var newVal = data.activity || data['กิจกรรม'];
      var newBudget = data.referenceBudget || data['งบอ้างอิง'];

      // ค้นหาแถวที่ต้องแก้ไข
      var range = sheet.getDataRange().getValues();
      for (var i = 1; i < range.length; i++) { // เริ่ม i=1 เพื่อข้ามหัวตาราง
        if (String(range[i][colActivity]) === String(oldVal)) {
          // อัปเดตข้อมูล (บวก 1 เพราะ row ใน Sheet เริ่มที่ 1)
          sheet.getRange(i + 1, colActivity + 1).setValue(newVal);
          if (colBudget !== -1) {
            sheet.getRange(i + 1, colBudget + 1).setValue(newBudget);
          }
          return { status: "success" };
        }
      }
      return { status: "error", message: "ไม่พบข้อมูลกิจกรรมเดิม: " + oldVal };
    }
    else if (type === "delete") {
      var valToDelete = data.activity || data['กิจกรรม'];
      var range = sheet.getDataRange().getValues();
      for (var i = 1; i < range.length; i++) {
        if (String(range[i][colActivity]) === String(valToDelete)) {
          sheet.deleteRow(i + 1);
          return { status: "success" };
        }
      }
    }
  }

  // ... (Logic สำหรับ Target อื่นๆ: Hierarchy, ResponsibleAgency) ...

  return { status: "success" };
}
```

