import { BudgetRecord, AppSettings, DropdownOptions, HierarchyData, ResponsibleAgencyData, CompareRecord, FieldVisibility } from '../types';
import { INITIAL_BUDGET_RECORDS, INITIAL_DROPDOWN_DATA, INITIAL_HIERARCHY, INITIAL_RESP_DATA, INITIAL_COMPARE_DATA } from './mockData';
import { parseNumber } from '../utils';

const SETTINGS_KEY = 'budgetPlanSettings';
const CACHE_KEY = 'budgetPlanCache';

// ลำดับความสำคัญสำหรับรายการบูรณาการ
const INTEGRATION_PRIORITY = [
    'ไม่เป็นหน่วยงานบูรณาการ',
