    const totalBudget = summary.personnel + summary.operational + summary.investment + summary.other;

    // Helper for date formatting (DD/MM/YYYY)
    const formatDateThai = (dateString: string) => {
        if (!dateString) return '-';

        // Try to parse as standard Date object first
        const date = new Date(dateString);
        if (!isNaN(date.getTime())) {
            return date.toLocaleDateString('th-TH', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
            });
        }

        // Fallback: If it's already a string like "26/12/2568 10:00:00" or similar
        const parts = dateString.split(' ');
        const datePart = parts[0];

        // Format to DD/MM/YYYY if possible
        const dmy = datePart.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
        if (dmy) {
            return `${dmy[1].padStart(2, '0')}/${dmy[2].padStart(2, '0')}/${dmy[3]}`;
        }

        return datePart.replace(',', '');
    };

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
