    async updateUnit(old: string, newName: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'update', data: { name: newName, oldName: old } });
        if (result.success) {
            this.dropdowns.unit = this.dropdowns.unit.map(u => u === old ? newName : u);
            this.saveToCache();
        }
        return result;
    }

    async deleteUnit(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Unit', type: 'delete', data: { name } });
        if (result.success) {
            this.dropdowns.unit = this.dropdowns.unit.filter(u => u !== name);
            this.saveToCache();
