// Component to handle route protection
const ProtectedRoute = ({ children, roles }: { children: React.ReactNode, roles?: UserRole[] }) => {
    const { isAuthenticated, hasPermission } = useAuth();
    const location = useLocation();

    if (!isAuthenticated) {
        return <Navigate to="/login" state={{ from: location }} replace />;
    }

    if (roles && !hasPermission(roles)) {
        return <Navigate to="/" replace />;
    }

    return <>{children}</>;
};

const AppContent: React.FC = () => {
    const { isAuthenticated } = useAuth();

    return (
        <div className="min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 font-sans transition-colors duration-300">
            {isAuthenticated && <Navbar />}
            <main className="flex-grow">
                <Routes>
                    <Route path="/login" element={<LoginView />} />

                    {/* Public/Staff Routes */}
                    <Route path="/" element={<ProtectedRoute roles={['admin', 'staff', 'viewer']}><HomeView /></ProtectedRoute>} />
                    <Route path="/database" element={<ProtectedRoute roles={['admin', 'staff', 'viewer']}><DatabaseView /></ProtectedRoute>} />
                    <Route path="/compare" element={<ProtectedRoute roles={['admin', 'staff', 'viewer']}><CompareView /></ProtectedRoute>} />
                    <Route path="/contact" element={<ProtectedRoute roles={['admin', 'staff', 'viewer']}><ContactView /></ProtectedRoute>} />

                    {/* Admin Only Routes */}
                    <Route path="/settings" element={<ProtectedRoute roles={['admin']}><SettingsView /></ProtectedRoute>} />
                    <Route path="/manage" element={<ProtectedRoute roles={['admin']}><ManageView /></ProtectedRoute>} />

                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </main>
            <ThemeToggle />
            {isAuthenticated && (
                <footer className="bg-slate-900 dark:bg-slate-950 text-white py-8 text-center mt-auto border-t border-slate-800">
