// Component to handle route protection
const ProtectedRoute = ({ children }: { children: React.ReactNode }) => {
    const { isAuthenticated, hasPermission } = useAuth();
    const location = useLocation();

    if (!isAuthenticated) {
        return <Navigate to="/login" state={{ from: location }} replace />;
    }

    // Check permission for current path
    // We remove query parameters or hash fragments for simple matching if necessary, 
    // but here we just check pathname.
    // For root path '/', simple match.
    if (!hasPermission(location.pathname)) {
        // If unauthorized, redirect to first authorized page or a dedicated 403 page.
        // For simplicity, redirect to login which handles auth state, or just '/' if they have it.
        // Since we don't have a dedicated dashboard that is always open, we rely on the Navbar to show what's available.
        // If the user lands here, it means they manually typed a URL they can't access.
        return <div className="p-8 text-center text-red-500">คุณไม่มีสิทธิ์เข้าถึงหน้านี้ <br/><button onClick={() => window.history.back()} className="mt-4 px-4 py-2 bg-slate-200 rounded">ย้อนกลับ</button></div>;
    }

    return <>{children}</>;
};

const AppContent: React.FC = () => {
    const { isAuthenticated } = useAuth();

    return (
        <div className="min-h-screen flex flex-col bg-slate-50 dark:bg-slate-900 font-sans transition-colors duration-300">
            {isAuthenticated && <Navbar />}
            <main className="flex-grow">
                <Routes>
                    <Route path="/login" element={<LoginView />} />

                    <Route path="/" element={<ProtectedRoute><HomeView /></ProtectedRoute>} />
                    <Route path="/database" element={<ProtectedRoute><DatabaseView /></ProtectedRoute>} />
                    <Route path="/compare" element={<ProtectedRoute><CompareView /></ProtectedRoute>} />
                    <Route path="/contact" element={<ProtectedRoute><ContactView /></ProtectedRoute>} />
                    <Route path="/settings" element={<ProtectedRoute><SettingsView /></ProtectedRoute>} />
                    <Route path="/manage" element={<ProtectedRoute><ManageView /></ProtectedRoute>} />

                    <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
            </main>
            <ThemeToggle />
            {isAuthenticated && (
                <footer className="bg-slate-900 dark:bg-slate-950 text-white py-8 text-center mt-auto border-t border-slate-800">
                    <div className="max-w-[98vw] mx-auto px-4">
                        <p className="text-slate-400 mb-2">&copy; 2025 ฝ่ายแผนปฏิบัติการ ส่วนจัดการงบประมาณ สงวนลิขสิทธิ์.</p>
                        <p className="text-sm text-slate-600 dark:text-slate-500">DNP Budget System v2.0 (React)</p>
                    </div>
                </footer>
            )}
        </div>
    );
};

