    private getValueByAliases(obj: any, aliases: string[]): any {
        if (!obj) return undefined;
        for (const alias of aliases) {
            if (obj[alias] !== undefined && obj[alias] !== null) return obj[alias];
        }
        return undefined;
    }

    private normalizeRecord(raw: any): BudgetRecord {
