                                                                <button
                                                                    type="button"
                                                                    onClick={() => togglePermission(role.id, route.path)}
                                                                    className={`p-2 rounded-lg transition-colors ${isChecked ? 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' : 'text-slate-300 hover:text-slate-400'}`}
                                                                >
