                                                            const isChecked = (settings.rolePermissions[role.id] || []).includes(subRoute.path);
                                                            const hasParentPermission = (settings.rolePermissions[role.id] || []).includes('/manage');

                                                            return (
                                                                <td key={role.id} className="px-4 py-2 text-center">
                                                                    <button
                                                                        type="button"
                                                                        disabled={!hasParentPermission}
                                                                        onClick={() => togglePermission(role.id, subRoute.path)}
                                                                        className={`p-1.5 rounded-lg transition-colors ${
                                                                            !hasParentPermission 
                                                                                ? 'text-slate-200 dark:text-slate-700 cursor-not-allowed'
                                                                                : isChecked 
                                                                                    ? 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' 
                                                                                    : 'text-slate-300 hover:text-slate-400'
                                                                        }`}
                                                                    >
