export const getSettings = (): AppSettings => {
    const stored = localStorage.getItem(SETTINGS_KEY);
    const defaults = {
        gasUrl: 'https://script.google.com/macros/s/AKfycbwdmg-DcHes5WGTWihXPIuREB5JJAxHox8ROAAiFDU5hCnMAvXbf2X5j4eh3FYu2B4v/exec',
        sheetsId: '1rwyAt0TsSSpZ7uqrAHq6C39AYvGogK0rj1b7QI8efkM',
        dataSheetName: 'Database',
        databaseSheetName: 'Database',
        rolePermissions: DEFAULT_ROLE_PERMISSIONS
    };

    if (stored) {
        const parsed = JSON.parse(stored);
        // Ensure rolePermissions exists if loading from old settings
        return { ...defaults, ...parsed, rolePermissions: parsed.rolePermissions || defaults.rolePermissions };
    }
    return defaults;
};

