                                                                                    ? 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' 
                                                                                    : 'text-slate-300 hover:text-slate-400'
                                                                        }`}
                                                                    >
                                                                        {isChecked ? <CheckSquare size={18} /> : <Square size={18} />}
                                                                    </button>
                                                                </td>
                                                            );
                                                        })}
                                                    </tr>
                                                ))}
                                            </React.Fragment>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}

                    <div className="pt-6 border-t border-slate-100 dark:border-slate-700 sticky bottom-0 bg-white dark:bg-slate-800 pb-4 z-10">
                        <button type="submit" className="w-full bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-4 rounded-xl font-bold transition-all shadow-lg shadow-emerald-900/20 hover:shadow-emerald-900/30 flex items-center justify-center gap-2">
                            <Save size={20} />
                            บันทึกการตั้งค่า
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default SettingsView;

payload.text:
ใช่ครับ **จำเป็นต้องมีการแก้ไข Google Apps Script (GAS)** เพื่อให้รองรับฟีเจอร์ใหม่ที่คุณต้องการ (การจัดการผู้ใช้งาน, การล็อกอิน, และการบันทึกสิทธิ์ลง Google Sheets)

คุณต้องดำเนินการดังนี้ในไฟล์ Google Sheets และ Google Apps Script เดิมของคุณครับ:

### 1. เตรียม Google Sheets
ให้คุณสร้างชีทใหม่เพิ่ม 2 ชีท ในไฟล์ Google Sheets เดิมของคุณ:

1.  **ชีทชื่อ "Users"** (สำหรับเก็บข้อมูลผู้ใช้)
    *   สร้างหัวตารางในบรรทัดที่ 1 ดังนี้: `Username`, `Password`, `Name`, `Role`
2.  **ชีทชื่อ "Settings"** (สำหรับเก็บการตั้งค่าสิทธิ์ `rolePermissions`)
    *   สร้างหัวตารางในบรรทัดที่ 1 ดังนี้: `Key`, `Value`

---

### 2. อัปเดตโค้ด Google Apps Script (.gs)
ให้ลบโค้ดเดิมบางส่วนหรือแก้ไขฟังก์ชัน `doPost`, `getData`, และเพิ่มฟังก์ชันใหม่ตามนี้ครับ:

#### 2.1 อัปเดตฟังก์ชัน `doPost`
เพิ่มเคสสำหรับ `SAVE_PERMISSIONS` และตรวจสอบ `target` ใน `MANAGE_MASTER`

```javascript
function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var request = JSON.parse(e.postData.contents);
    var action = request.action;
    var ss = SpreadsheetApp.openById(request.sheetsId);

    var result = { status: 'error', message: 'Invalid Action' };

    if (action === 'GET_DATA') {
      result = getData(ss, request);
    } else if (action === 'MANAGE_RECORD') {
      result = manageRecord(ss, request);
    } else if (action === 'MANAGE_MASTER') {
      // เพิ่มส่วนนี้เพื่อรองรับ Users
      if (request.target === 'Users') {
        result = manageUsers(ss, request);
      } else {
        result = manageMaster(ss, request);
      }
    } else if (action === 'SAVE_PERMISSIONS') {
      // เพิ่มส่วนนี้สำหรับบันทึกสิทธิ์
      result = savePermissions(ss, request);
    } else if (action === 'TEST_CONNECTION') {
      result = { status: 'success', message: 'Connection OK' };
    }

    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}
```

#### 2.2 อัปเดตฟังก์ชัน `getData`
ให้ดึงข้อมูล Users และ Permissions ส่งกลับไปที่หน้าเว็บด้วย

```javascript
function getData(ss, request) {
  var result = {};

  // ... (โค้ดเดิมที่ดึง dropdowns, hierarchy, records ฯลฯ) ...
  // ตัวอย่างโค้ดเดิม:
  // result.records = getSheetData(ss, request.databaseSheetName);
  // result.hierarchy = getSheetData(ss, 'Hierarchy');
  // ...

  // --- เพิ่มส่วนนี้: ดึงข้อมูล Users ---
  var userSheet = ss.getSheetByName('Users');
  if (userSheet) {
    result.users = getSheetData(ss, 'Users'); 
  } else {
    result.users = []; // ถ้าไม่มีชีท Users ให้ส่ง array ว่าง
  }

  // --- เพิ่มส่วนนี้: ดึงข้อมูล Permissions ---
  var settingsSheet = ss.getSheetByName('Settings');
  if (settingsSheet) {
    var data = settingsSheet.getDataRange().getValues();
    // ค้นหา row ที่ Key = 'ROLE_PERMISSIONS'
    for (var i = 1; i < data.length; i++) {
      if (data[i][0] === 'ROLE_PERMISSIONS') {
        try {
          result.rolePermissions = JSON.parse(data[i][1]);
        } catch (e) {
          result.rolePermissions = null;
        }
        break;
      }
    }
  }

  return { status: 'success', data: result };
}
```

#### 2.3 เพิ่มฟังก์ชัน `manageUsers` (สำหรับเพิ่ม/ลบ/แก้ไข User)

```javascript
function manageUsers(ss, request) {
  var sheet = ss.getSheetByName('Users');
  if (!sheet) return { status: 'error', message: 'Sheet "Users" not found' };

  var type = request.type;
  var data = request.data;

  // Headers: Username, Password, Name, Role

  if (type === 'add') {
    // เช็ค Username ซ้ำ
    var existing = findRowIndex(sheet, 0, data.username); // 0 คือ column index ของ Username
    if (existing !== -1) return { status: 'error', message: 'Username already exists' };

    sheet.appendRow([data.username, data.password, data.name, data.role]);
    return { status: 'success' };
  } 
  else if (type === 'update') {
    var rowIndex = findRowIndex(sheet, 0, data.oldUsername || data.username);
    if (rowIndex === -1) return { status: 'error', message: 'User not found' };

    // อัปเดตข้อมูล (Row index เริ่มที่ 1 ใน Apps Script แต่ array เริ่ม 0 ดังนั้น +1)
    var range = sheet.getRange(rowIndex + 1, 1, 1, 4);
    range.setValues([[data.username, data.password, data.name, data.role]]);
    return { status: 'success' };
  } 
  else if (type === 'delete') {
    var rowIndex = findRowIndex(sheet, 0, data.username);
    if (rowIndex === -1) return { status: 'error', message: 'User not found' };

    sheet.deleteRow(rowIndex + 1);
    return { status: 'success' };
  }

  return { status: 'error', message: 'Invalid type' };
}

// Helper function to find row by value in a specific column
function findRowIndex(sheet, colIndex, value) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) { // Start from 1 to skip header
    if (String(data[i][colIndex]) === String(value)) {
      return i;
    }
  }
  return -1;
}
```

#### 2.4 เพิ่มฟังก์ชัน `savePermissions`

```javascript
function savePermissions(ss, request) {
  var sheet = ss.getSheetByName('Settings');
  if (!sheet) {
    sheet = ss.insertSheet('Settings');
    sheet.appendRow(['Key', 'Value']);
  }

  var permissionsJson = JSON.stringify(request.rolePermissions);
  var data = sheet.getDataRange().getValues();
  var rowIndex = -1;

  // ค้นหาว่ามี Key 'ROLE_PERMISSIONS' อยู่แล้วหรือไม่
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === 'ROLE_PERMISSIONS') {
      rowIndex = i;
      break;
    }
  }

  if (rowIndex !== -1) {
    // ถ้ามีแล้ว ให้อัปเดต
    sheet.getRange(rowIndex + 1, 2).setValue(permissionsJson);
  } else {
    // ถ้ายังไม่มี ให้เพิ่มใหม่
    sheet.appendRow(['ROLE_PERMISSIONS', permissionsJson]);
  }

  return { status: 'success' };
}
```

หลังจากอัปเดตโค้ดทั้งหมดแล้ว **อย่าลืม Deploy Web App ใหม่อีกครั้ง** (New Deployment) เพื่อให้โค้ดล่าสุดทำงานครับ

นี่คือโค้ด **Google Apps Script (GAS)** ฉบับสมบูรณ์ที่ออกแบบมาเพื่อรองรับฟีเจอร์ทั้งหมดของระบบ DNP Budget System รวมถึงระบบจัดการผู้ใช้งาน (Users) และสิทธิ์การเข้าถึง (Permissions) ตามที่คุณต้องการครับ

### วิธีการใช้งาน
1. เปิดไฟล์ Google Sheets ของคุณ
2. ไปที่เมนู **Extensions (ส่วนขยาย)** -> **Apps Script**
3. ลบโค้ดเดิมออกทั้งหมดแล้ววางโค้ดด้านล่างนี้ลงไป
4. กดบันทึก และกดปุ่ม **Deploy (ทำให้ใช้งานได้)** -> **New Deployment**
5. เลือกประเภทเป็น **Web App**
   - **Execute as:** Me (ตัวฉัน)
   - **Who has access:** Anyone (ทุกคน)
6. คัดลอก **Web App URL** ไปใส่ในหน้า "ตั้งค่าระบบ" ของตัวเว็บ

---

### โค้ด Google Apps Script (.gs)

```javascript
/**
 * DNP Budget System - Google Apps Script Backend v2.0
 * รองรับ: บันทึกข้อมูล, จัดการข้อมูลตัวเลือก, จัดการผู้ใช้, และสิทธิ์การใช้งาน
 */

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000); // ป้องกันปัญหาการบันทึกพร้อมกัน

  try {
    var request = JSON.parse(e.postData.contents);
    var action = request.action;
    var ss = SpreadsheetApp.openById(request.sheetsId);

    var result = { status: 'error', message: 'Invalid Action' };

    // เส้นทางการทำงานหลัก
    if (action === 'GET_DATA') {
      result = getData(ss, request);
    } else if (action === 'MANAGE_RECORD') {
      result = manageRecord(ss, request);
    } else if (action === 'MANAGE_MASTER') {
      if (request.target === 'Users') {
        result = manageUsers(ss, request);
      } else {
        result = manageMaster(ss, request);
      }
    } else if (action === 'SAVE_PERMISSIONS') {
      result = savePermissions(ss, request);
    } else if (action === 'TEST_CONNECTION') {
      result = { status: 'success', message: 'เชื่อมต่อสำเร็จ' };
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

/**
 * ดึงข้อมูลทั้งหมดจากทุกชีทเพื่อส่งให้ Frontend
 */
function getData(ss, request) {
  var data = {};

  // 1. ดึงข้อมูลบันทึกงบประมาณ (Database)
  data.records = getSheetDataAsObjects(ss, request.databaseSheetName || 'Database');

  // 2. ดึงข้อมูล Hierarchy (สังกัด/จังหวัด)
  data.hierarchy = getSheetDataAsObjects(ss, 'Hierarchy');

  // 3. ดึงข้อมูลหน่วยงานบูรณาการ (ResponsibleAgency)
  data.respData = getSheetDataAsObjects(ss, 'ResponsibleAgency');

  // 4. ดึงข้อมูลเปรียบเทียบงบประมาณ (Compare)
  data.compareData = getSheetDataAsObjects(ss, 'Compare');

  // 5. ดึงข้อมูลตัวเลือกพื้นฐาน (Dropdowns)
  var integrationList = getSheetColumnData(ss, 'Integration', 1);
  var unitList = getSheetColumnData(ss, 'Unit', 1);
  data.dropdowns = {
    integration: integrationList,
    unit: unitList
  };

  // 6. ดึงข้อมูลผู้ใช้งาน (Users)
  data.users = getSheetDataAsObjects(ss, 'Users');

  // 7. ดึงข้อมูลการตั้งค่าสิทธิ์ (Permissions)
  data.rolePermissions = loadPermissions(ss);

  return { status: 'success', data: data };
}

/**
 * จัดการเพิ่ม/แก้ไข/ลบ ข้อมูลบันทึกงบประมาณ
 */
function manageRecord(ss, request) {
  var sheet = ss.getSheetByName(request.databaseSheetName || 'Database');
  if (!sheet) return { status: 'error', message: 'ไม่พบชีท Database' };

  var type = request.type;
  var data = request.data;
  var id = request.id;

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  if (type === 'add') {
    var row = headers.map(function(h) { return data[h] || ''; });
    sheet.appendRow(row);
    return { status: 'success' };
  } 
  else if (type === 'update') {
    var rowIndex = findRowIndex(sheet, 0, id); // ค้นหาจากคอลัมน์แรก (ID)
    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลที่ต้องการแก้ไข' };

    var rowData = headers.map(function(h) { return data[h] !== undefined ? data[h] : ''; });
    sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([rowData]);
    return { status: 'success' };
  } 
  else if (type === 'delete') {
    var rowIndex = findRowIndex(sheet, 0, id);
    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลที่ต้องการลบ' };
    sheet.deleteRow(rowIndex + 1);
    return { status: 'success' };
  }

  return { status: 'error', message: 'ไม่พบคำสั่งที่ต้องการ' };
}

/**
 * จัดการข้อมูล Master Data (Hierarchy, ResponsibleAgency, Compare, ฯลฯ)
 */
function manageMaster(ss, request) {
  var target = request.target;
  var type = request.type;
  var data = request.data;
  var sheetName = target;

  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    // สร้าง Header เบื้องต้นตามประเภทข้อมูล
    if (target === 'Hierarchy') sheet.appendRow(['mainAgency', 'province']);
    if (target === 'ResponsibleAgency') sheet.appendRow(['mainAgency', 'responsibleAgency', 'integrationArea']);
    if (target === 'Compare') sheet.appendRow(['activity', 'referenceBudget']);
    if (target === 'Unit' || target === 'Integration') sheet.appendRow(['name']);
  }

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  if (type === 'add') {
    var row = headers.map(function(h) { return data[h] || ''; });
    sheet.appendRow(row);
  } 
  else if (type === 'update') {
    var rowIndex = -1;
    // ปรับ Logic การค้นหาตามประเภทข้อมูล
    if (target === 'Hierarchy') {
      rowIndex = findRowIndexMultiple(sheet, {0: data.oldMainAgency, 1: data.oldProvince});
    } else if (target === 'ResponsibleAgency') {
      rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.oldResponsibleAgency, 2: data.oldIntegrationArea});
    } else if (target === 'Compare') {
      rowIndex = findRowIndex(sheet, 0, data.oldActivity);
    } else {
      rowIndex = findRowIndex(sheet, 0, data.oldName);
    }

    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลที่ต้องการแก้ไข' };
    var rowData = headers.map(function(h) { return data[h] || ''; });
    sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([rowData]);
  } 
  else if (type === 'delete') {
    var rowIndex = -1;
    if (target === 'Hierarchy') {
      rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.province});
    } else if (target === 'ResponsibleAgency') {
      rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.responsibleAgency, 2: data.integrationArea});
    } else if (target === 'Compare') {
      rowIndex = findRowIndex(sheet, 0, data.activity);
    } else {
      rowIndex = findRowIndex(sheet, 0, data.name);
    }

    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลที่ต้องการลบ' };
    sheet.deleteRow(rowIndex + 1);
  }

  return { status: 'success' };
}

/**
 * จัดการข้อมูลผู้ใช้งาน (Users)
 */
function manageUsers(ss, request) {
  var sheet = ss.getSheetByName('Users');
  if (!sheet) {
    sheet = ss.insertSheet('Users');
    sheet.appendRow(['username', 'password', 'name', 'role']);
  }

  var type = request.type;
  var data = request.data;

  if (type === 'add') {
    if (findRowIndex(sheet, 0, data.username) !== -1) return { status: 'error', message: 'ชื่อผู้ใช้นี้มีอยู่ในระบบแล้ว' };
    sheet.appendRow([data.username, data.password, data.name, data.role]);
  } 
  else if (type === 'update') {
    var rowIndex = findRowIndex(sheet, 0, data.oldUsername || data.username);
    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบผู้ใช้ที่ต้องการแก้ไข' };
    sheet.getRange(rowIndex + 1, 1, 1, 4).setValues([[data.username, data.password, data.name, data.role]]);
  } 
  else if (type === 'delete') {
    var rowIndex = findRowIndex(sheet, 0, data.username);
    if (rowIndex === -1) return { status: 'error', message: 'ไม่พบผู้ใช้ที่ต้องการลบ' };
    sheet.deleteRow(rowIndex + 1);
  }

  return { status: 'success' };
}

/**
 * บันทึกการตั้งค่าสิทธิ์ (Permissions) ลงในชีท Settings
 */
function savePermissions(ss, request) {
  var sheet = ss.getSheetByName('Settings');
  if (!sheet) {
    sheet = ss.insertSheet('Settings');
    sheet.appendRow(['Key', 'Value']);
  }

  var permissionsJson = JSON.stringify(request.rolePermissions);
  var data = sheet.getDataRange().getValues();
  var rowIndex = -1;

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === 'ROLE_PERMISSIONS') {
      rowIndex = i;
      break;
    }
  }

  if (rowIndex !== -1) {
    sheet.getRange(rowIndex + 1, 2).setValue(permissionsJson);
  } else {
    sheet.appendRow(['ROLE_PERMISSIONS', permissionsJson]);
  }

  return { status: 'success' };
}

/**
 * โหลดข้อมูลสิทธิ์การใช้งานจากชีท Settings
 */
function loadPermissions(ss) {
  var sheet = ss.getSheetByName('Settings');
  if (!sheet) return null;

  var values = sheet.getDataRange().getValues();
  for (var i = 1; i < values.length; i++) {
    if (values[i][0] === 'ROLE_PERMISSIONS') {
      try {
        return JSON.parse(values[i][1]);
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

// --- Helper Functions ---

function getSheetDataAsObjects(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  var data = sheet.getDataRange().getValues();
  var headers = data[0];
  var result = [];
  for (var i = 1; i < data.length; i++) {
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = data[i][j];
    }
    result.push(obj);
  }
  return result;
}

function getSheetColumnData(ss, sheetName, colIndex) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  var data = sheet.getRange(2, colIndex, lastRow - 1, 1).getValues();
  return data.map(function(r) { return r[0]; }).filter(Boolean);
}

function findRowIndex(sheet, colIndex, value) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (String(data[i][colIndex]) === String(value)) return i;
  }
  return -1;
}

function findRowIndexMultiple(sheet, colValueMap) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    var match = true;
    for (var colIndex in colValueMap) {
      if (String(data[i][colIndex]) !== String(colValueMap[colIndex])) {
        match = false;
        break;
      }
    }
    if (match) return i;
  }
  return -1;
}
