    // --- User Management Methods ---

    async addUser(user: User): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Users', type: 'add', data: user });
        if (result.success) {
            this.users.push(user);
            this.saveToCache();
        }
