    }

    async updateUser(oldUsername: string, updatedUser: User): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_MASTER', { 
            target: 'Users', 
            type: 'update', 
            data: { ...updatedUser, oldUsername } 
        });
        if (result.success) {
            const idx = this.users.findIndex(u => u.username === oldUsername);
            if (idx !== -1) {
                this.users[idx] = updatedUser;
                this.saveToCache();
            }
        }
        return result;
    }

    async deleteUser(username: string): Promise<{ success: boolean; message?: string }> {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Users', type: 'delete', data: { username } });
        if (result.success) {
            this.users = this.users.filter(u => u.username !== username);
            this.saveToCache();
        }
        return result;
    }

    async savePermissionsToCloud(): Promise<{ success: boolean; message?: string }> {
        const settings = getSettings();
        return await this.sendToGas('SAVE_PERMISSIONS', { rolePermissions: settings.permissions });
    }

    async syncDropdowns(): Promise<void> {
        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ 
                    action: 'GET_DATA',
                    sheetsId: settings.sheetsId,
                    databaseSheetName: settings.databaseSheetName,
                    dataSheetName: settings.dataSheetName
                })
            });
            const json = await res.json();
            if (json.status === 'success' && json.data) {
                const s = json.data;
                const normalizeH = (raw: any): HierarchyData => ({
                    mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                    province: String(this.getValueByAliases(raw, ['province', 'จังหวัด']) || '')
                });
                const normalizeR = (raw: any): ResponsibleAgencyData => ({
                    mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                    responsibleAgency: String(this.getValueByAliases(raw, ['responsibleAgency', 'หน่วยงานบูรณาการ']) || ''),
                    integrationArea: String(this.getValueByAliases(raw, ['integrationArea', 'พื้นที่บูรณาการ']) || '')
                });
                const normalizeC = (raw: any): CompareRecord => {
                    const activity = String(this.getValueByAliases(raw, ['activity', 'กิจกรรม']) || '');
                    return {
                        id: String(this.getValueByAliases(raw, ['id', 'ID']) || activity),
                        activity: activity,
                        referenceBudget: parseNumber(String(this.getValueByAliases(raw, ['referenceBudget', 'งบอ้างอิง', 'งบประมาณ']) || 0))
                    };
                };

                // User mapping
                const normalizeU = (raw: any): User => ({
                    username: String(this.getValueByAliases(raw, ['username', 'ชื่อผู้ใช้']) || ''),
                    password: String(this.getValueByAliases(raw, ['password', 'รหัสผ่าน']) || ''),
                    name: String(this.getValueByAliases(raw, ['name', 'ชื่อ-นามสกุล', 'ชื่อ']) || ''),
                    role: (String(this.getValueByAliases(raw, ['role', 'สิทธิ์']) || 'viewer')) as UserRole
                });

                this.hierarchy = (s.hierarchy || []).map(normalizeH);
                this.respData = (s.respData || []).map(normalizeR);
                this.compareData = (s.compareData || []).map(normalizeC);
                this.records = (s.records || []).map((r: any) => this.normalizeRecord(r));

                // Sync Users if available in response
                if (s.users && Array.isArray(s.users)) {
                    this.users = s.users.map(normalizeU);
                }

                // Sync rolePermissions
                if (s.rolePermissions) {
                    const currentSettings = getSettings();
                    saveSettings({ ...currentSettings, permissions: s.rolePermissions });
                }

                // นำ .sort() ออกเพื่อให้เป็นไปตามลำดับใน Sheet
                this.dropdowns.integration = this.sortIntegrationData(s.dropdowns?.integration || []);
                this.dropdowns.unit = s.dropdowns?.unit || [];

                this.updateDerivedDropdowns();
                this.saveToCache();
            } else throw new Error(json.message || 'Sync failed');
        } catch (e: any) { console.error('Sync Error:', e); throw e; }
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ 
                    action: 'TEST_CONNECTION',
                    sheetsId: settings.sheetsId 
                })
            });
            const json = await res.json();
            return json.status === 'success';
        } catch { return false; }
    }

    // Login checks against local user list (which is synced with GAS)
    async login(username: string, password: string): Promise<User | null> {
        return new Promise((resolve) => {
            setTimeout(() => {
                const user = this.users.find(u => u.username === username && u.password === password);
                if (user) {
                    resolve({ ...user }); // Return copy to avoid mutation issues
                } else {
                    resolve(null);
                }
            }, 500);
        });
    }
}

export const dataService = new DataService();

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';
import { dataService, getSettings } from '../services/dataService';

interface AuthContextType {
    user: User | null;
    isAuthenticated: boolean;
    login: (username: string, password: string) => Promise<boolean>;
    logout: () => void;
    hasPermission: (path: string) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);

    useEffect(() => {
        // Restore session from localStorage if available
        const savedUser = localStorage.getItem('budgetAppUser');
        if (savedUser) {
            try {
                setUser(JSON.parse(savedUser));
            } catch (e) {
                localStorage.removeItem('budgetAppUser');
            }
        }
    }, []);

    const login = async (username: string, password: string): Promise<boolean> => {
        const foundUser = await dataService.login(username, password);
        if (foundUser) {
            setUser(foundUser);
            localStorage.setItem('budgetAppUser', JSON.stringify(foundUser));
            return true;
        }
        return false;
    };

    const logout = () => {
        setUser(null);
        localStorage.removeItem('budgetAppUser');
    };

    const hasPermission = (path: string): boolean => {
        if (!user) return false;
        const settings = getSettings();

        // 1. Check for User-specific permissions first
        const userPerms = settings.permissions[user.username];
        if (userPerms) {
            return userPerms.includes(path);
        }

        // 2. Fallback to Role-based permissions
        const rolePerms = settings.permissions[user.role] || [];
        return rolePerms.includes(path);
    };

    return (
        <AuthContext.Provider value={{ user, isAuthenticated: !!user, login, logout, hasPermission }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

