            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-8 transition-colors">
                <form onSubmit={handleSave} className="space-y-8">
                    {activeTab === 'general' && (
