import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { dataService } from '../../services/dataService';
import { PieChart, Lock, User, LogIn, Eye, EyeOff, RefreshCw } from 'lucide-react';
import Swal from 'sweetalert2';

const LoginView: React.FC = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [status, setStatus] = useState<'idle' | 'logging_in' | 'syncing'>('idle');
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!username || !password) {
            Swal.fire({
                icon: 'warning',
                title: 'กรุณากรอกข้อมูล',
                text: 'กรุณากรอกชื่อผู้ใช้และรหัสผ่าน',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        setStatus('logging_in');
        try {
            const success = await login(username, password);
            if (success) {
                // Phase 2: Automatic Sync
                setStatus('syncing');
                try {
                    await dataService.syncDropdowns();

                    const Toast = Swal.mixin({
                        toast: true,
                        position: 'top-end',
                        showConfirmButton: false,
                        timer: 1500,
                        timerProgressBar: true,
                    });
                    Toast.fire({
                        icon: 'success',
                        title: 'เข้าสู่ระบบและเตรียมข้อมูลสำเร็จ'
                    });
                    navigate('/');
                } catch (syncError) {
                    console.error('Initial sync failed:', syncError);
                    // Even if sync fails, we still navigate but warn the user
                    Swal.fire({
                        icon: 'warning',
                        title: 'เข้าสู่ระบบสำเร็จ',
                        text: 'แต่ไม่สามารถซิงค์ข้อมูลล่าสุดได้ ระบบจะใช้ข้อมูลสำรองในเครื่องแทน',
                        confirmButtonColor: '#f59e0b'
                    }).then(() => navigate('/'));
                }
            } else {
                setStatus('idle');
                Swal.fire({
                    icon: 'error',
                    title: 'เข้าสู่ระบบไม่สำเร็จ',
                    text: 'ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง',
                    confirmButtonColor: '#ef4444'
                });
            }
        } catch (error) {
            setStatus('idle');
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: 'ไม่สามารถเชื่อมต่อระบบได้',
                confirmButtonColor: '#ef4444'
            });
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 px-4">
            <div className="max-w-md w-full bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden">
                <div className="bg-emerald-600 p-8 text-center relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-emerald-500 to-teal-700 opacity-90"></div>
                    <div className="relative z-10 flex flex-col items-center">
                        <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-lg mb-4">
                            <PieChart size={32} />
                        </div>
                        <h1 className="text-2xl font-bold text-white mb-1">DNP Budget System</h1>
                        <p className="text-emerald-100 text-sm">ระบบบริหารและติดตามงบประมาณ</p>
                    </div>
                </div>

                <div className="p-8">
                    <div className="mb-6 text-center">
                        <h2 className="text-xl font-bold text-slate-800 dark:text-white">ลงชื่อเข้าใช้งาน</h2>
                        <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">กรุณากรอกข้อมูลเพื่อยืนยันตัวตน</p>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-5">
                        <div className="space-y-1">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300 ml-1">ชื่อผู้ใช้</label>
