import { PieChart, Lock, User, LogIn, Eye, EyeOff, RefreshCw } from 'lucide-react';
import Swal from 'sweetalert2';

const LoginView: React.FC = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [status, setStatus] = useState<'idle' | 'logging_in' | 'syncing' | 'refreshing_users'>('idle');
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!username || !password) {
            Swal.fire({
                icon: 'warning',
                title: 'กรุณากรอกข้อมูล',
                text: 'กรุณากรอกชื่อผู้ใช้และรหัสผ่าน',
                confirmButtonColor: '#fbbf24'
            });
            return;
        }

        setStatus('logging_in');
        try {
            // Step 1: Try to login with current local cache
            let success = await login(username, password);

            // Step 2: If local login fails, attempt to refresh user list from cloud
            if (!success) {
                setStatus('refreshing_users');
                try {
                    await dataService.syncDropdowns();
                    // Try login again after sync
                    success = await login(username, password);
                } catch (syncError) {
                    console.error('Failed to refresh user list during login:', syncError);
                    // Continue to failure message if sync fails
                }
