        dataSheetName: 'Database',
        databaseSheetName: 'Database',
        permissions: DEFAULT_ROLE_PERMISSIONS
    };

    if (stored) {
        const parsed = JSON.parse(stored);
        // Handle migration from rolePermissions to permissions
        const permissions = parsed.permissions || parsed.rolePermissions || defaults.permissions;
        return { ...defaults, ...parsed, permissions };
    }
    return defaults;
};

