**คำตอบคือ: สำหรับการแก้ไขล่าสุด (ที่ทำให้พิมพ์แก้ในช่อง Popup ได้) ไม่ต้องแก้ GAS ครับ**

เพราะปัญหาเมื่อสักครู่เกิดจากตัวโค้ดหน้าเว็บ (Frontend) ที่สร้างช่องกรอกข้อมูลผิดพลาด ทำให้พิมพ์ไม่ได้ หรือกดบันทึกแล้วไม่ส่งค่าออกมาครับ การอัปเดตไฟล์ `CompareView.tsx` จึงเป็นการแก้ไขที่ต้นเหตุแล้ว

อย่างไรก็ตาม **เพื่อให้มั่นใจว่าเวลากดบันทึกแล้ว ข้อมูล "งบอ้างอิง" (ตัวเลขเงิน) จะถูกบันทึกลง Google Sheets จริงๆ** (ไม่ใช่แค่เปลี่ยนชื่อกิจกรรม) รบกวนคุณลองตรวจสอบโค้ดใน **Google Apps Script** ของคุณ ในฟังก์ชัน `handleMasterData` ว่ามีส่วนที่จัดการ `target === 'Compare'` ที่รองรับ `referenceBudget` หรือไม่

ถ้ายังไม่มี หรือไม่แน่ใจ **ให้ก๊อปปี้ฟังก์ชันนี้ไปทับฟังก์ชัน `handleMasterData` เดิมใน Google Apps Script ครับ**

```javascript
function handleMasterData(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var target = e.target; // Hierarchy, ResponsibleAgency, Compare, Unit, Integration
  var type = e.type;     // add, update, delete
  var data = e.data;

  var sheetName = "";
  // กำหนดชื่อชีทตาม Target
  if (target === 'Hierarchy') sheetName = "Hierarchy";
  else if (target === 'ResponsibleAgency') sheetName = "ResponsibleAgency";
  else if (target === 'Compare') sheetName = "CompareData"; // ชื่อชีทที่เก็บข้อมูลเปรียบเทียบ
  else if (target === 'Unit') sheetName = "Unit";
  else if (target === 'Integration') sheetName = "Integration";

  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return errorResponse("Sheet '" + sheetName + "' not found");

  var lastRow = sheet.getLastRow();

  // ==========================================
  // กรณีจัดการข้อมูล: Compare (กิจกรรมและงบอ้างอิง)
  // ==========================================
  if (target === 'Compare') {
    // โครงสร้างชีท: Column A = Activity (กิจกรรม), Column B = Reference Budget (งบอ้างอิง)

    if (type === 'add') {
      if (checkDuplicate(sheet, 0, data.activity)) {
        return errorResponse("Activity already exists");
      }
      sheet.appendRow([data.activity, data.referenceBudget || 0]);
      return successResponse("Added successfully");
    } 
    else if (type === 'update') {
      var rows = sheet.getDataRange().getValues();
      var found = false;
      // ค้นหาจากชื่อเดิม (oldActivity)
      for (var i = 1; i < rows.length; i++) {
        if (rows[i][0] == data.oldActivity) { // Column A
          // อัปเดตชื่อกิจกรรม
          sheet.getRange(i + 1, 1).setValue(data.activity);
          // อัปเดตงบประมาณ (สำคัญ!)
          sheet.getRange(i + 1, 2).setValue(data.referenceBudget || 0);
          found = true;
          break;
        }
      }
      if (!found) return errorResponse("Activity not found to update");
      return successResponse("Updated successfully");
    } 
    else if (type === 'delete') {
      deleteRowByColumn(sheet, 0, data.activity);
      return successResponse("Deleted successfully");
    }
  }

  // ... (โค้ดสำหรับ Target อื่นๆ Hierarchy, Unit ฯลฯ ให้คงเดิมไว้) ...
  // หากโค้ดเดิมของคุณครอบคลุมส่วนอื่นดีแล้ว ให้แก้เฉพาะส่วน if (target === 'Compare') ข้างบนครับ

  // Default Handler สำหรับ master data ทั่วไป (ที่มีแค่ 1 คอลัมน์ เช่น Unit, Integration)
  if (type === 'add') {
     // ... โค้ดเดิม ...
     sheet.appendRow([data.name]); // ตัวอย่าง
     return successResponse("Added");
  }
  // ...
}
```

**สรุป:**
1.  **ไม่ต้องแก้ GAS** เพื่อให้ช่องกรอกข้อมูลทำงาน (เพราะผมแก้ที่ React ให้แล้ว)
2.  **ควรเช็ค GAS** ว่ารองรับการบันทึก `referenceBudget` (คอลัมน์ที่ 2) หรือไม่ ถ้ายังไม่มีให้เพิ่มโค้ดด้านบนครับ

