### 2. แก้ไข Google Apps Script (สำคัญมาก)

ให้คุณนำโค้ดด้านล่างนี้ ไปวางทับฟังก์ชัน `manageMaster` ใน Google Apps Script ของคุณครับ (ลบฟังก์ชัน `manageMaster` เดิมออก แล้วใส่ตัวนี้แทน)

โค้ดนี้ถูกปรับปรุงให้:
1.  **รองรับทั้งชื่อ Header ภาษาไทยและอังกฤษ** โดยอัตโนมัติ
2.  **ค้นหาข้อมูลแม่นยำขึ้น** (ตัดช่องว่างหน้าหลังออกก่อนเปรียบเทียบ) ทำให้แก้ปัญหา "เพิ่มได้แต่ลบไม่ได้"

```javascript
/**
 * ฟังก์ชันจัดการ Master Data (ปรับปรุงใหม่ รองรับ Header ไทย/อังกฤษ)
 */
function manageMaster(ss, request) {
  var target = request.target;
  var type = request.type;
  var data = request.data;

  // Mapping ชื่อชีท
  var sheetName = target;
  if (target === 'Compare') sheetName = 'CompareData'; // ชื่อชีทแนะนำสำหรับ Compare

  var sheet = ss.getSheetByName(sheetName);
  // ถ้าไม่เจอชีท ลองหาชื่อเดิม หรือสร้างใหม่
  if (!sheet) {
    sheet = ss.getSheetByName(target); // ลองหาชื่อเดิม (เช่น Compare)
    if (!sheet) {
      sheet = ss.insertSheet(sheetName);
      // สร้าง Header เริ่มต้น (ภาษาอังกฤษ)
      if (target === 'Hierarchy') sheet.appendRow(['mainAgency', 'province']);
      else if (target === 'ResponsibleAgency') sheet.appendRow(['mainAgency', 'responsibleAgency', 'integrationArea']);
      else if (target === 'Compare') sheet.appendRow(['activity', 'referenceBudget']);
      else if (target === 'Unit' || target === 'Integration') sheet.appendRow(['name']);
    }
  }

  var lastRow = sheet.getLastRow();

  // ฟังก์ชันช่วยดึงค่าจาก Data Object โดยรองรับหลายชื่อ key (ไทย/อังกฤษ)
  function getValue(keys) {
    if (!Array.isArray(keys)) keys = [keys];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (data[k] !== undefined && data[k] !== null) return data[k];
    }
    return '';
  }

  // --- LOGIC การเพิ่ม/ลบ/แก้ไข แยกตามประเภท ---

  // 1. จัดการ Unit (หน่วยนับ) และ Integration (รายการบูรณาการ)
  // โครงสร้าง: Column 1 = Name
  if (target === 'Unit' || target === 'Integration') {
    var name = getValue(['name', 'ชื่อ', 'หน่วยนับ', 'รายการบูรณาการ']);
    var oldName = getValue(['oldName', 'ชื่อเดิม']);

    if (type === 'add') {
      if (findRowIndexStrict(sheet, 0, name) !== -1) return { status: 'error', message: 'ข้อมูลซ้ำ' };
      sheet.appendRow([name]);
    } 
    else if (type === 'update') {
      var rowIndex = findRowIndexStrict(sheet, 0, oldName);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลเดิมเพื่อแก้ไข' };
      sheet.getRange(rowIndex + 1, 1).setValue(name);
    } 
    else if (type === 'delete') {
      var rowIndex = findRowIndexStrict(sheet, 0, name);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลที่ต้องการลบ' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }

  // 2. จัดการ Compare (ข้อมูลเปรียบเทียบ/กิจกรรม)
  // โครงสร้าง: Column 1 = Activity, Column 2 = Budget
  else if (target === 'Compare') {
    var activity = getValue(['activity', 'กิจกรรม']);
    var budget = getValue(['referenceBudget', 'งบอ้างอิง', 'งบประมาณ']);
    var oldActivity = getValue(['oldActivity', 'กิจกรรมเดิม']);

    if (type === 'add') {
      if (findRowIndexStrict(sheet, 0, activity) !== -1) return { status: 'error', message: 'ชื่อกิจกรรมซ้ำ' };
      sheet.appendRow([activity, budget || 0]);
    } 
    else if (type === 'update') {
      var rowIndex = findRowIndexStrict(sheet, 0, oldActivity);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบกิจกรรมเดิม' };

      // อัปเดตชื่อกิจกรรม
      sheet.getRange(rowIndex + 1, 1).setValue(activity);
      // อัปเดตงบประมาณ (ถ้ามีค่าส่งมา)
      if (budget !== '' && budget !== undefined) {
        sheet.getRange(rowIndex + 1, 2).setValue(budget);
      }
    } 
    else if (type === 'delete') {
      var rowIndex = findRowIndexStrict(sheet, 0, activity);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบกิจกรรมที่ต้องการลบ' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }

  // 3. จัดการ Hierarchy และ ResponsibleAgency (ใช้ Logic เดิมแบบ Generic แต่ปรับปรุงการหาแถว)
  else {
    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    if (type === 'add') {
      // ใช้ headers.map แต่ต้องมั่นใจว่า Header ตรงกับ key
      var row = headers.map(function(h) { return data[h] || ''; }); 
      sheet.appendRow(row);
    } 
    else if (type === 'update') {
      var rowIndex = -1;
      if (target === 'Hierarchy') rowIndex = findRowIndexMultiple(sheet, {0: data.oldMainAgency, 1: data.oldProvince});
      else if (target === 'ResponsibleAgency') rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.oldResponsibleAgency, 2: data.oldIntegrationArea});

      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูล' };
      var rowData = headers.map(function(h) { return data[h] || ''; });
      sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([rowData]);
    } 
    else if (type === 'delete') {
      var rowIndex = -1;
      if (target === 'Hierarchy') rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.province});
      else if (target === 'ResponsibleAgency') rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.responsibleAgency, 2: data.integrationArea});

      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูล' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }
}

// ฟังก์ชันค้นหาที่แม่นยำขึ้น (ตัดช่องว่างและแปลงเป็น String)
function findRowIndexStrict(sheet, colIndex, value) {
  var data = sheet.getDataRange().getValues();
  var targetVal = String(value).trim();
  for (var i = 1; i < data.length; i++) {
    var cellVal = String(data[i][colIndex]).trim();
    if (cellVal === targetVal) return i;
  }
  return -1;
}

