payload.text:
นี่คือ **โค้ด Google Apps Script (GAS) ฉบับสมบูรณ์** ที่ได้รับการแก้ไขปรับปรุงให้รองรับปัญหาที่คุณแจ้งมาทั้งหมดครับ

**สิ่งที่ปรับปรุงในเวอร์ชันนี้:**
1.  **รองรับภาษาไทย/อังกฤษ:** แก้ไขฟังก์ชัน `manageMaster` ให้ฉลาดขึ้น สามารถอ่านค่าได้ไม่ว่า Frontend จะส่งมาเป็น key ภาษาอังกฤษ (เช่น `activity`) หรือภาษาไทย (เช่น `กิจกรรม`)
2.  **ค้นหาแม่นยำขึ้น:** เพิ่มฟังก์ชันทำความสะอาดข้อมูล (ตัดช่องว่างหน้าหลัง) ก่อนค้นหา ทำให้แก้ปัญหา "ลบไม่ได้" หรือ "หาไม่เจอ"
3.  **แก้ปัญหาหน้า Compare:** รองรับการบันทึก "งบอ้างอิง" (Reference Budget) ลงในคอลัมน์ที่ 2 อย่างถูกต้อง
4.  **จัดการ Unit/Integration:** แก้ไขให้ เพิ่ม/ลบ/แก้ไข ได้สมบูรณ์

### วิธีการติดตั้ง
1.  ไปที่ [script.google.com](https://script.google.com/) (โปรเจกต์เดิมของคุณ)
2.  ลบโค้ดเก่าทิ้ง **ทั้งหมด**
3.  คัดลอกโค้ดด้านล่างนี้ไปวางแทนที่
4.  กด **Save** (รูปแผ่นดิสก์)
5.  กด **Deploy** (ทำให้ใช้งานได้) -> **New deployment** (การทำให้ใช้งานได้รายการใหม่)
6.  เลือก **Web app**
    *   Description: `Update v3`
    *   Execute as: **Me** (ฉัน)
    *   Who has access: **Anyone** (ทุกคน)
7.  กด **Deploy** และนำ URL ไปใช้ในไฟล์ `.env` หรือ `dataService.ts` ของคุณ

---

```javascript
/**
 * DNP Budget System - Google Apps Script Backend v3.0 (Full Fix)
 * แก้ไขปัญหา: การจัดการ Master Data, ภาษาไทย, และการบันทึกงบเปรียบเทียบ
 */

function doPost(e) {
  var lock = LockService.getScriptLock();
  // รอ Lock สูงสุด 30 วินาที เพื่อป้องกันการชนกันของข้อมูล
  if (lock.tryLock(30000)) {
    try {
      var request = JSON.parse(e.postData.contents);
      var action = request.action;
      var ss = SpreadsheetApp.openById(request.sheetsId);

      var result = { status: 'error', message: 'Invalid Action' };

      if (action === 'GET_DATA') {
        result = getData(ss, request);
      } else if (action === 'MANAGE_RECORD') {
        result = manageRecord(ss, request);
      } else if (action === 'MANAGE_MASTER') {
        if (request.target === 'Users') {
          result = manageUsers(ss, request);
        } else {
          result = manageMaster(ss, request);
        }
      } else if (action === 'SAVE_PERMISSIONS') {
        result = savePermissions(ss, request);
      } else if (action === 'TEST_CONNECTION') {
        result = { status: 'success', message: 'Connected successfully' };
      }

      return ContentService.createTextOutput(JSON.stringify(result))
        .setMimeType(ContentService.MimeType.JSON);

    } catch (err) {
      return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: err.toString() }))
        .setMimeType(ContentService.MimeType.JSON);
    } finally {
      lock.releaseLock();
    }
  } else {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: 'Server is busy, please try again.' }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

/**
 * ดึงข้อมูลทั้งหมด
 */
function getData(ss, request) {
  var data = {};

  data.records = getSheetDataAsObjects(ss, request.databaseSheetName || 'Database');
  data.hierarchy = getSheetDataAsObjects(ss, 'Hierarchy');
  data.respData = getSheetDataAsObjects(ss, 'ResponsibleAgency');

  // รองรับชื่อชีท Compare หรือ CompareData
  var compareSheetName = ss.getSheetByName('CompareData') ? 'CompareData' : 'Compare';
  data.compareData = getSheetDataAsObjects(ss, compareSheetName);

  data.dropdowns = {
    integration: getSheetColumnData(ss, 'Integration', 1),
    unit: getSheetColumnData(ss, 'Unit', 1)
  };

  data.users = getSheetDataAsObjects(ss, 'Users');
  data.rolePermissions = loadPermissions(ss);

  return { status: 'success', data: data };
}

/**
 * จัดการข้อมูลหลัก (Database Records)
 */
function manageRecord(ss, request) {
  var sheet = ss.getSheetByName(request.databaseSheetName || 'Database');
  if (!sheet) return { status: 'error', message: 'Sheet Database not found' };

  var type = request.type;
  var data = request.data;
  var id = request.id;
  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  // ฟังก์ชันหาค่าจาก data โดยเทียบกับ Header
  // เช่น Header "จังหวัด" ก็จะไปหา data["จังหวัด"] หรือ data["province"]
  function getVal(header) {
    return data[header] !== undefined ? data[header] : '';
  }

  if (type === 'add') {
    var row = headers.map(function(h) { return getVal(h); });
    sheet.appendRow(row);
    return { status: 'success' };
  } 
  else if (type === 'update') {
    var rowIndex = findRowIndex(sheet, 0, id); 
    if (rowIndex === -1) return { status: 'error', message: 'ID Not Found: ' + id };

    var rowData = headers.map(function(h) { return getVal(h); });
    sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([rowData]);
    return { status: 'success' };
  } 
  else if (type === 'delete') {
    var rowIndex = findRowIndex(sheet, 0, id);
    if (rowIndex === -1) return { status: 'error', message: 'ID Not Found: ' + id };
    sheet.deleteRow(rowIndex + 1);
    return { status: 'success' };
  }
  return { status: 'error' };
}

/**
 * จัดการ Master Data (แก้ไขใหม่ รองรับ Key ไทย/อังกฤษ และ Logic แยกตามประเภท)
 */
function manageMaster(ss, request) {
  var target = request.target;
  var type = request.type;
  var data = request.data;

  // Mapping ชื่อชีท
  var sheetName = target;
  if (target === 'Compare') {
    // เช็คว่ามีชีทไหนอยู่
    sheetName = ss.getSheetByName('CompareData') ? 'CompareData' : 'Compare';
  }

  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    // สร้าง Header ถ้ายังไม่มี
    if (target === 'Hierarchy') sheet.appendRow(['mainAgency', 'province']);
    else if (target === 'ResponsibleAgency') sheet.appendRow(['mainAgency', 'responsibleAgency', 'integrationArea']);
    else if (target === 'Compare') sheet.appendRow(['activity', 'referenceBudget']);
    else if (target === 'Unit' || target === 'Integration') sheet.appendRow(['name']);
  }

  // Helper ในการดึงค่าจาก Payload (รองรับหลายชื่อ)
  function getValue(keys) {
    if (!Array.isArray(keys)) keys = [keys];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (data[k] !== undefined && data[k] !== null) return data[k];
    }
    return '';
  }

  // --- 1. จัดการ Unit และ Integration (คอลัมน์เดียว) ---
  if (target === 'Unit' || target === 'Integration') {
    var name = getValue(['name', 'ชื่อ', 'หน่วยนับ', 'รายการบูรณาการ']);
    var oldName = getValue(['oldName', 'ชื่อเดิม', 'oldName']);

    if (type === 'add') {
      if (findRowIndexStrict(sheet, 0, name) !== -1) return { status: 'error', message: 'ข้อมูลซ้ำ (Duplicate)' };
      sheet.appendRow([name]);
    } 
    else if (type === 'update') {
      var rowIndex = findRowIndexStrict(sheet, 0, oldName);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูลเดิม (Not Found)' };
      sheet.getRange(rowIndex + 1, 1).setValue(name);
    } 
    else if (type === 'delete') {
      var rowIndex = findRowIndexStrict(sheet, 0, name);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูล (Not Found)' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }

  // --- 2. จัดการ Compare (กิจกรรม และ งบประมาณ) ---
  else if (target === 'Compare') {
    var activity = getValue(['activity', 'กิจกรรม', 'name']);
    var budget = getValue(['referenceBudget', 'งบอ้างอิง', 'งบประมาณ']);
    var oldActivity = getValue(['oldActivity', 'กิจกรรมเดิม', 'oldName']);

    if (type === 'add') {
      if (findRowIndexStrict(sheet, 0, activity) !== -1) return { status: 'error', message: 'กิจกรรมซ้ำ' };
      sheet.appendRow([activity, budget || 0]);
    } 
    else if (type === 'update') {
      // หาจากชื่อเดิม
      var rowIndex = findRowIndexStrict(sheet, 0, oldActivity);
      // ถ้าหาชื่อเดิมไม่เจอ ลองหาจากชื่อใหม่ (กรณีชื่อไม่ได้เปลี่ยนแต่แก้งบ)
      if (rowIndex === -1) rowIndex = findRowIndexStrict(sheet, 0, activity);

      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบกิจกรรมที่ต้องการแก้ไข' };

      // อัปเดตชื่อกิจกรรม (Col 1)
      sheet.getRange(rowIndex + 1, 1).setValue(activity);
      // อัปเดตงบประมาณ (Col 2) - ตรวจสอบว่ามีค่าส่งมาไหม
      if (budget !== '' && budget !== undefined) {
        sheet.getRange(rowIndex + 1, 2).setValue(budget);
      }
    } 
    else if (type === 'delete') {
      var rowIndex = findRowIndexStrict(sheet, 0, activity);
      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบกิจกรรม' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }

  // --- 3. จัดการ Hierarchy และ ResponsibleAgency (หลายคอลัมน์) ---
  else {
    var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    if (type === 'add') {
      var row = headers.map(function(h) { return data[h] || ''; });
      sheet.appendRow(row);
    } 
    else if (type === 'update') {
      var rowIndex = -1;
      if (target === 'Hierarchy') {
        rowIndex = findRowIndexMultiple(sheet, {0: data.oldMainAgency, 1: data.oldProvince});
      } else if (target === 'ResponsibleAgency') {
        rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.oldResponsibleAgency, 2: data.oldIntegrationArea});
      }

      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูล' };
      var rowData = headers.map(function(h) { return data[h] || ''; });
      sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([rowData]);
    } 
    else if (type === 'delete') {
      var rowIndex = -1;
      if (target === 'Hierarchy') {
        rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.province});
      } else if (target === 'ResponsibleAgency') {
        rowIndex = findRowIndexMultiple(sheet, {0: data.mainAgency, 1: data.responsibleAgency, 2: data.integrationArea});
      }

      if (rowIndex === -1) return { status: 'error', message: 'ไม่พบข้อมูล' };
      sheet.deleteRow(rowIndex + 1);
    }
    return { status: 'success' };
  }
}

/**
 * จัดการ User
 */
function manageUsers(ss, request) {
  var sheet = ss.getSheetByName('Users');
  if (!sheet) {
    sheet = ss.insertSheet('Users');
    sheet.appendRow(['username', 'password', 'name', 'role']);
  }
  var type = request.type;
  var data = request.data;

  if (type === 'add') {
    if (findRowIndexStrict(sheet, 0, data.username) !== -1) return { status: 'error', message: 'Username exists' };
    sheet.appendRow([data.username, data.password, data.name, data.role]);
  } else if (type === 'update') {
    var rowIndex = findRowIndexStrict(sheet, 0, data.oldUsername || data.username);
    if (rowIndex === -1) return { status: 'error', message: 'User not found' };
    sheet.getRange(rowIndex + 1, 1, 1, 4).setValues([[data.username, data.password, data.name, data.role]]);
  } else if (type === 'delete') {
    var rowIndex = findRowIndexStrict(sheet, 0, data.username);
    if (rowIndex === -1) return { status: 'error', message: 'User not found' };
    sheet.deleteRow(rowIndex + 1);
  }
  return { status: 'success' };
}

/**
 * บันทึก Permissions
 */
function savePermissions(ss, request) {
  var sheet = ss.getSheetByName('Settings');
  if (!sheet) {
    sheet = ss.insertSheet('Settings');
    sheet.appendRow(['Key', 'Value']);
  }

  var permJson = JSON.stringify(request.rolePermissions);
  var rowIndex = findRowIndexStrict(sheet, 0, 'ROLE_PERMISSIONS');

  if (rowIndex !== -1) {
    sheet.getRange(rowIndex + 1, 2).setValue(permJson);
  } else {
    sheet.appendRow(['ROLE_PERMISSIONS', permJson]);
  }
  return { status: 'success' };
}

function loadPermissions(ss) {
  var sheet = ss.getSheetByName('Settings');
  if (!sheet) return null;
  var rowIndex = findRowIndexStrict(sheet, 0, 'ROLE_PERMISSIONS');
  if (rowIndex !== -1) {
    try {
      var val = sheet.getRange(rowIndex + 1, 2).getValue();
      return JSON.parse(val);
    } catch(e) { return null; }
  }
  return null;
}

// --- Helper Functions ---

function getSheetDataAsObjects(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  var data = sheet.getDataRange().getValues();
  if (data.length < 2) return [];

  var headers = data[0];
  var result = [];
  for (var i = 1; i < data.length; i++) {
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = data[i][j];
    }
    result.push(obj);
  }
  return result;
}

function getSheetColumnData(ss, sheetName, colIndex) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];
  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  // ดึงข้อมูลคอลัมน์แล้วกรองค่าว่าง
  var values = sheet.getRange(2, colIndex, lastRow - 1, 1).getValues();
  var result = [];
  for (var i = 0; i < values.length; i++) {
    if (values[i][0]) result.push(values[i][0]);
  }
  return result;
}

// ค้นหา Row Index แบบปกติ (สำหรับ ID)
function findRowIndex(sheet, colIndex, value) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (String(data[i][colIndex]) == String(value)) return i;
  }
  return -1;
}

// ค้นหาแบบเข้มงวด (ตัดช่องว่าง, แปลงเป็น String) เพื่อความแม่นยำในการหาชื่อไทย
function findRowIndexStrict(sheet, colIndex, value) {
  var data = sheet.getDataRange().getValues();
  var target = String(value).trim();
  for (var i = 1; i < data.length; i++) {
    var cell = String(data[i][colIndex]).trim();
    if (cell === target) return i;
  }
  return -1;
}

function findRowIndexMultiple(sheet, criteria) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    var match = true;
    for (var col in criteria) {
      if (String(data[i][col]).trim() !== String(criteria[col]).trim()) {
        match = false;
        break;
      }
    }
    if (match) return i;
  }
  return -1;
}

