import React, { useState, useEffect, useMemo } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber } from '../../utils';
import { TrendingUp, Target, Scale, Edit2, RefreshCw, AlertCircle, CheckCircle2, TrendingDown, Save, X } from 'lucide-react';
import Swal from 'sweetalert2';
import { CompareRecord } from '../../types';

const CompareView: React.FC = () => {
    const [refreshTrigger, setRefreshTrigger] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    // Inline Editing State
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState<string>('');

    // Get Data
    const records = dataService.getRecords();
    const compareTargets = dataService.getCompareData();

    // Aggregate actual budget by activity
    const actualsByActivity = useMemo(() => {
        return records.reduce((acc, r) => {
            const total = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                          (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                          (r.equipment || 0) + (r.landConstruction || 0) +
                          (r.subsidies || 0) + (r.otherExpenses || 0);
            const activityName = (r.activity || '').trim();
            acc[activityName] = (acc[activityName] || 0) + total;
            return acc;
        }, {} as Record<string, number>);
    }, [records, refreshTrigger]);

    const comparisonResults = useMemo(() => {
        return compareTargets.map(target => {
            const activityName = (target.activity || '').trim();
            const actual = actualsByActivity[activityName] || 0;
            const refBudget = Number(target.referenceBudget || 0);
            const variance = actual - refBudget;

            let status = 'match';
            if (actual === 0 && refBudget > 0) status = 'nodata';
            else if (actual === 0 && refBudget === 0) status = 'nodata';
            else if (variance > 0) status = 'over';
            else if (variance < 0) status = 'under';

            return { ...target, actual, variance, status };
        });
    }, [compareTargets, actualsByActivity, refreshTrigger]);

    const totalRef = useMemo(() => comparisonResults.reduce((sum, r) => sum + (r.referenceBudget || 0), 0), [comparisonResults]);
    const totalAct = useMemo(() => comparisonResults.reduce((sum, r) => sum + (r.actual || 0), 0), [comparisonResults]);
    const totalVar = totalAct - totalRef;

    const handleSync = async () => {
        setIsLoading(true);
        try {
            await dataService.syncDropdowns();
            setRefreshTrigger(prev => prev + 1);
            Swal.fire({
                icon: 'success',
                title: 'ซิงค์ข้อมูลสำเร็จ',
                text: 'อัปเดตข้อมูลล่าสุดเรียบร้อยแล้ว',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error: any) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'ไม่สามารถดึงข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    // Inline Editing Handlers
    const startInlineEdit = (record: CompareRecord) => {
        setEditingId(record.id || record.activity);
        setEditValue(record.referenceBudget ? formatNumber(record.referenceBudget) : '');
    };

    const cancelInlineEdit = () => {
        setEditingId(null);
        setEditValue('');
    };

    const saveInlineEdit = async (record: CompareRecord) => {
        const newBudget = parseFloat(editValue.replace(/,/g, '')) || 0;

        // Optimistic update prevention if no change
        if (newBudget === record.referenceBudget) {
            cancelInlineEdit();
            return;
        }

        // Show a small toast or non-blocking loader? 
        // For now, standard SweetAlert loading, but maybe simpler.

        try {
            // Using the service to update. 
            // Note: We keep activity name same as original to ensure we update the correct row.
            const result = await dataService.updateCompareData(record.id, record.activity, newBudget);

            if (result.success) {
                setRefreshTrigger(prev => prev + 1);
                const Toast = Swal.mixin({
                    toast: true,
                    position: 'top-end',
                    showConfirmButton: false,
                    timer: 2000,
                    timerProgressBar: true
                });
                Toast.fire({ icon: 'success', title: 'บันทึกงบอ้างอิงแล้ว' });
            } else {
                Swal.fire({
                    title: 'บันทึกไม่สำเร็จ',
                    text: result.message || 'ไม่สามารถบันทึกข้อมูลได้',
                    icon: 'error',
                    confirmButtonColor: '#ef4444'
                });
            }
        } catch (error: any) {
             Swal.fire({
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'การเชื่อมต่อขัดข้อง',
                icon: 'error',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setEditingId(null);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent, record: CompareRecord) => {
        if (e.key === 'Enter') {
            saveInlineEdit(record);
        } else if (e.key === 'Escape') {
            cancelInlineEdit();
        }
    };

    const handleEditActivityName = async (record: CompareRecord) => {
        const { value: newActivity } = await Swal.fire({
            title: 'แก้ไขชื่อกิจกรรม',
