                return null;
            }
        });

        if (newActivity && newActivity !== record.activity) {
             Swal.fire({
                title: 'กำลังบันทึก...',
                allowOutsideClick: false,
                didOpen: () => { Swal.showLoading(); }
            });

            try {
                const result = await dataService.updateCompareData(record.id, newActivity, record.referenceBudget);

                if (result.success) {
                    setRefreshTrigger(prev => prev + 1);
                    Swal.fire({
                        title: 'สำเร็จ',
                        text: 'แก้ไขชื่อกิจกรรมเรียบร้อยแล้ว',
                        icon: 'success',
                        timer: 1500,
                        showConfirmButton: false
                    });
                } else {
                    throw new Error(result.message || 'บันทึกไม่สำเร็จ');
                }
            } catch (error: any) {
                Swal.fire({
                    title: 'บันทึกล้มเหลว',
                    text: error.message || 'ไม่สามารถติดต่อ Google Sheets ได้',
                    icon: 'error',
                    confirmButtonColor: '#ef4444'
