    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // Filter State
    const [selectedResponsible, setSelectedResponsible] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');

    // Filter Logic
    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const matchesResp = selectedResponsible ? (r.responsibleAgency || '').trim() === selectedResponsible.trim() : true;
            const matchesProv = selectedProvince ? (r.province || '').trim() === selectedProvince.trim() : true;
            return matchesResp && matchesProv;
        });
    }, [records, selectedResponsible, selectedProvince]);

    // Group records by Integration type (simulating Plan structure)
    // And aggregate records with same Activity name within each group
    const groupedData = useMemo(() => {
        const groups: Record<string, BudgetRecord[]> = {};

        // 1. Group by Integration first
        const rawGroups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const key = r.integration || 'งานพื้นฐาน';
            if (!rawGroups[key]) rawGroups[key] = [];
            rawGroups[key].push(r);
        });

        // 2. Aggregate by Activity within each group
        Object.keys(rawGroups).forEach(groupKey => {
            const recordsInGroup = rawGroups[groupKey];
            const activityMap: Record<string, BudgetRecord> = {};

            recordsInGroup.forEach(r => {
                const actKey = (r.activity || '').trim();

                if (!activityMap[actKey]) {
                    // Clone the record to start the aggregate
                    // Create a new object to avoid mutating original data
                    activityMap[actKey] = { ...r };

                    // Ensure numeric fields are numbers (sometimes they might be undefined)
                    activityMap[actKey].salaryPermanent = r.salaryPermanent || 0;
                    activityMap[actKey].governmentCompensation = r.governmentCompensation || 0;
                    activityMap[actKey].compensationSupplies = r.compensationSupplies || 0;
                    activityMap[actKey].contractEmployees = r.contractEmployees || 0;
                    activityMap[actKey].utilities = r.utilities || 0;
                    activityMap[actKey].equipment = r.equipment || 0;
                    activityMap[actKey].landConstruction = r.landConstruction || 0;
                    activityMap[actKey].subsidies = r.subsidies || 0;
                    activityMap[actKey].otherExpenses = r.otherExpenses || 0;

                } else {
                    // Aggregate Logic
                    const exist = activityMap[actKey];

                    // Sum Budgets
                    exist.salaryPermanent = (exist.salaryPermanent || 0) + (r.salaryPermanent || 0);
                    exist.governmentCompensation = (exist.governmentCompensation || 0) + (r.governmentCompensation || 0);
                    exist.compensationSupplies = (exist.compensationSupplies || 0) + (r.compensationSupplies || 0);
                    exist.contractEmployees = (exist.contractEmployees || 0) + (r.contractEmployees || 0);
                    exist.utilities = (exist.utilities || 0) + (r.utilities || 0);
                    exist.equipment = (exist.equipment || 0) + (r.equipment || 0);
                    exist.landConstruction = (exist.landConstruction || 0) + (r.landConstruction || 0);
                    exist.subsidies = (exist.subsidies || 0) + (r.subsidies || 0);
                    exist.otherExpenses = (exist.otherExpenses || 0) + (r.otherExpenses || 0);

                    // Max Target logic (Find max value)
                    const currentTargetVal = parseNumber(exist.target || '0');
                    const newTargetVal = parseNumber(r.target || '0');
                    if (newTargetVal > currentTargetVal) {
                        exist.target = r.target;
                    }

                    // Keep existing unit unless new one is present and old one is missing
                    if (!exist.unit && r.unit) exist.unit = r.unit;
                }
            });

            // Convert back to array
            groups[groupKey] = Object.values(activityMap);
