                                                <td className="border border-black px-1 py-1 text-right">{r.otherExpenses ? formatNumber(r.otherExpenses) : '-'}</td>
                                                <td className="border border-black px-1 py-1 text-right font-bold">{formatNumber(rowTotal)}</td>
                                            </tr>
                                        );
                                    })}

                                    {/* Group Total */}
                                    <tr className="bg-gray-100 font-bold italic text-gray-700">
                                        <td className="border border-black px-2 py-1 text-right" colSpan={3}>รวม {groupName}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.salaryPermanent)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.governmentCompensation)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.compensationSupplies)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.contractEmployees)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.utilities)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.equipment)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.landConstruction)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.subsidies)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.otherExpenses)}</td>
                                        <td className="border border-black px-1 py-1 text-right">{formatNumber(groupTotal.total)}</td>
                                    </tr>
                                </React.Fragment>
                            );
                        })}

                         {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={13} className="border border-black px-4 py-8 text-center text-gray-400">
                                    ไม่พบข้อมูลตามเงื่อนไขที่เลือก
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

