        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'update', data: { name: newName, oldName: old, 'ชื่อ': newName, 'ชื่อเดิม': old, 'รายการบูรณาการ': newName } });
        if (result.success) {
            const newList = this.dropdowns.integration.map(i => i === old ? newName : i);
            this.dropdowns.integration = this.sortIntegrationData(newList);
            this.saveToCache();
        }
        return result;
    }

    async deleteIntegration(name: string) {
        const result = await this.sendToGas('MANAGE_MASTER', { target: 'Integration', type: 'delete', data: { name, 'ชื่อ': name, 'รายการบูรณาการ': name } });
        if (result.success) {
            const newList = this.dropdowns.integration.filter(i => i !== name);
            this.dropdowns.integration = this.sortIntegrationData(newList);
            this.saveToCache();
        }
        return result;
    }

    async fetchUsersFromFirestore(): Promise<void> {
        try {
            const querySnapshot = await getDocs(collection(db, "users"));
            const fetchedUsers: User[] = [];
            querySnapshot.forEach((doc) => {
                const u = doc.data() as User;
                fetchedUsers.push({ ...u, username: doc.id });
            });

            if (fetchedUsers.length === 0) {
                console.log('No users found in Firestore. Seeding initial users...');
                for (const u of INITIAL_USERS) {
                    await setDoc(doc(db, "users", u.username), u);
                }
                this.users = INITIAL_USERS;
            } else {
                this.users = fetchedUsers;
            }
            this.saveToCache();
        } catch (error) {
            console.error("Error fetching users from Firestore: ", error);
        }
    }

    async addUser(user: User): Promise<{ success: boolean; message?: string }> {
        try {
            const docRef = doc(db, "users", user.username);
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                return { success: false, message: 'ชื่อผู้ใช้นี้มีอยู่แล้ว' };
            }
            await setDoc(docRef, user);
            this.users.push(user);
            this.saveToCache();
            return { success: true };
        } catch (e: any) {
            return { success: false, message: e.message };
        }
    }

    async updateUser(oldUsername: string, updatedUser: User): Promise<{ success: boolean; message?: string }> {
        try {
            if (oldUsername !== updatedUser.username) {
                 const newDocRef = doc(db, "users", updatedUser.username);
                 const newDocSnap = await getDoc(newDocRef);
                 if (newDocSnap.exists()) {
                     return { success: false, message: 'ชื่อผู้ใช้ใหม่ซ้ำกับที่มีอยู่แล้ว' };
                 }
                 await setDoc(newDocRef, updatedUser);
                 await deleteDoc(doc(db, "users", oldUsername));
            } else {
                await updateDoc(doc(db, "users", oldUsername), { ...updatedUser });
            }

            const idx = this.users.findIndex(u => u.username === oldUsername);
            if (idx !== -1) {
                this.users[idx] = updatedUser;
                this.saveToCache();
            }
            return { success: true };
        } catch (e: any) {
             return { success: false, message: e.message };
        }
    }

    async deleteUser(username: string): Promise<{ success: boolean; message?: string }> {
        try {
            await deleteDoc(doc(db, "users", username));
            this.users = this.users.filter(u => u.username !== username);
            this.saveToCache();
            return { success: true };
        } catch (e: any) {
            return { success: false, message: e.message };
        }
    }

    async savePermissionsToCloud(): Promise<{ success: boolean; message?: string }> {
        const settings = getSettings();
        return await this.sendToGas('SAVE_PERMISSIONS', { rolePermissions: settings.permissions });
    }

    async syncDropdowns(): Promise<void> {
        if (this.syncPromise) {
            return this.syncPromise;
        }

        const settings = getSettings();
        if (!settings.gasUrl) throw new Error('Google Apps Script URL not configured');

        this.syncPromise = (async () => {
            try {
                const res = await fetch(settings.gasUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                    body: JSON.stringify({ 
                        action: 'GET_DATA',
                        sheetsId: settings.sheetsId,
                        databaseSheetName: settings.databaseSheetName,
                        dataSheetName: settings.dataSheetName
                    })
                });
                const json = await res.json();
                if (json.status === 'success' && json.data) {
                    const s = json.data;
                    const normalizeH = (raw: any): HierarchyData => ({
                        mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                        province: String(this.getValueByAliases(raw, ['province', 'จังหวัด']) || '')
                    });
                    const normalizeR = (raw: any): ResponsibleAgencyData => ({
                        mainAgency: String(this.getValueByAliases(raw, ['mainAgency', 'หน่วยงานหลัก']) || ''),
                        responsibleAgency: String(this.getValueByAliases(raw, ['responsibleAgency', 'หน่วยงานบูรณาการ']) || ''),
                        integrationArea: String(this.getValueByAliases(raw, ['integrationArea', 'พื้นที่บูรณาการ']) || '')
                    });
                    const normalizeC = (raw: any): CompareRecord => {
                        const activity = String(this.getValueByAliases(raw, ['activity', 'กิจกรรม']) || '');
                        return {
                            id: String(this.getValueByAliases(raw, ['id', 'ID']) || activity),
                            activity: activity,
                            referenceBudget: parseNumber(String(this.getValueByAliases(raw, ['referenceBudget', 'งบอ้างอิง', 'งบประมาณ']) || 0))
                        };
                    };

                    this.hierarchy = (s.hierarchy || []).map(normalizeH);
                    this.respData = (s.respData || []).map(normalizeR);
                    this.compareData = (s.compareData || []).map(normalizeC);
                    this.records = (s.records || []).map((r: any) => this.normalizeRecord(r));

                    if (s.rolePermissions) {
                        const currentSettings = getSettings();
                        saveSettings({ ...currentSettings, permissions: s.rolePermissions });
                    }

                    this.dropdowns.integration = this.sortIntegrationData(s.dropdowns?.integration || []);
                    this.dropdowns.unit = s.dropdowns?.unit || [];

                    // Note: Report Structure Sync is likely separate or part of master data in future.
                    // For now, it stays local/cached.

                    this.updateDerivedDropdowns();
                    this.saveToCache();
                } else throw new Error(json.message || 'Sync failed');
            } catch (e: any) { 
                console.error('Sync Error:', e); 
                throw e; 
            } finally {
                this.syncPromise = null;
            }
        })();

        return this.syncPromise;
    }

    async testConnection(): Promise<boolean> {
        const settings = getSettings();
        if (!settings.gasUrl) return false;
        try {
            const res = await fetch(settings.gasUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify({ 
                    action: 'TEST_CONNECTION',
                    sheetsId: settings.sheetsId 
                })
            });
            const json = await res.json();
            return json.status === 'success';
        } catch { return false; }
    }

    async login(username: string, password: string): Promise<User | null> {
        try {
            if (this.users.length === 0) {
                await this.fetchUsersFromFirestore();
            }
            let user = this.users.find(u => u.username === username && u.password === password);
            if (!user) {
                const docRef = doc(db, "users", username);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    const userData = docSnap.data() as User;
                    if (userData.password === password) {
                        user = { ...userData, username: docSnap.id };
                        const idx = this.users.findIndex(u => u.username === username);
                        if (idx === -1) this.users.push(user);
                        else this.users[idx] = user;
                        this.saveToCache();
                    }
                }
            }
            return user ? { ...user } : null;
        } catch (e) {
            console.error('Login Error:', e);
            return null;
        }
    }
}

export const dataService = new DataService();

import React, { useState, useMemo, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber, parseNumber } from '../../utils';
import { Printer, Filter } from 'lucide-react';
import { BudgetRecord, ReportNode } from '../../types';
import AutocompleteInput from '../Form/AutocompleteInput';

const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // Hardcoded constant (REPORT_HIERARCHY) removed in favor of dataService
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    // Initialize Hierarchy from Service
    useEffect(() => {
        // Fetch current structure. If empty, dataService might initialize it with default if configured so.
        // But for explicit initial load:
        const structure = dataService.getReportStructure();

        // If structure is somehow empty (cleared cache), we can re-populate with default logic here or inside dataService.
        // For robustness, let's assume dataService handles initialization or we fallback.
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        } else {
            // Fallback: This path ideally shouldn't be hit if dataService initializes properly
            // Or we can define the hardcoded constant here as a fallback and save it back.
            // For now, let's assume dataService has the initial data (see dataService update).
            const fromService = dataService.getReportStructure();
            if (fromService.length > 0) setReportHierarchy(fromService);
            // else setReportHierarchy(DEFAULT_HIERARCHY_IF_NEEDED);
        }
    }, []);

    // Filter State
    const [selectedResponsible, setSelectedResponsible] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');

    // Filter Logic
    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const matchesResp = selectedResponsible ? (r.responsibleAgency || '').trim() === selectedResponsible.trim() : true;
            const matchesProv = selectedProvince ? (r.province || '').trim() === selectedProvince.trim() : true;
            return matchesResp && matchesProv;
        });
    }, [records, selectedResponsible, selectedProvince]);

    // Helper to get aggregated data for a specific activity name
    const getAggregatedData = (activityName: string) => {
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityName.trim());
        if (matches.length === 0) return null;

        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            // Max Target Logic
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit // Last non-empty unit wins or just take current
        }), {
            salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
            utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
            target: '0', unit: ''
        });

        // Calculate Row Total
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;

        return { ...agg, total };
    };

    // Helper to collect all used activity names in the hierarchy
    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    // Find records that don't match any activity in the hierarchy (Uncategorized)
    const uncategorizedRecords = useMemo(() => {
        // Group uncategorized records by activity name
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (!usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });

        // Aggregate them similar to getAggregatedData
        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), {
                salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
                utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
                target: '0', unit: ''
            });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    // Grand Total
    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            total: acc.total + ((r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                   (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                   (r.equipment || 0) + (r.landConstruction || 0) +
                   (r.subsidies || 0) + (r.otherExpenses || 0))
        }), {
            salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
            utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0, total: 0
        });
    }, [filteredRecords]);

    const handlePrint = () => {
        window.print();
    };

    // Recursive Renderer
    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node, idx) => {
            const data = node.activityMatcher ? getAggregatedData(node.activityMatcher) : null;

            // Layout Styles based on type
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";

            if (node.type === 'plan') {
                rowClass = "bg-gray-200 text-blue-900";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-gray-50 text-slate-900";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic";
                plClass = "pl-12";
            } else if (node.type === 'subgroup2') {
                fontClass = "font-medium italic";
                plClass = "pl-14";
            } else if (node.type === 'activity') {
                plClass = "pl-16";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-yellow-50`}>
                        <td className={`border border-black py-1 text-left ${plClass} ${fontClass}`}>
                           {node.title}
