type Tab = 'hierarchy' | 'responsible' | 'integration' | 'activity' | 'unit' | 'fields' | 'tableColumns' | 'report';

// Recursively update a node in the tree
const updateNodeInTree = (nodes: ReportNode[], nodeId: string, updates: Partial<ReportNode>): ReportNode[] => {
    return nodes.map(node => {
        if (node.id === nodeId) {
            return { ...node, ...updates };
        }
        if (node.children) {
            return { ...node, children: updateNodeInTree(node.children, nodeId, updates) };
        }
        return node;
    });
};

// Recursively delete a node
const deleteNodeFromTree = (nodes: ReportNode[], nodeId: string): ReportNode[] => {
    return nodes.filter(node => node.id !== nodeId).map(node => {
        if (node.children) {
            return { ...node, children: deleteNodeFromTree(node.children, nodeId) };
        }
        return node;
    });
};

// Find parent array and index of a node
const findNodeParent = (nodes: ReportNode[], nodeId: string): { parentChildren: ReportNode[], index: number } | null => {
    for (let i = 0; i < nodes.length; i++) {
        if (nodes[i].id === nodeId) {
            return { parentChildren: nodes, index: i };
        }
        if (nodes[i].children) {
            const found = findNodeParent(nodes[i].children!, nodeId);
            if (found) return found;
        }
    }
    return null;
};

