    const handleDeleteIntegration = async (n: string) => {};

    // Recursive component for Drag & Drop Tree
    const ReportTreeNode: React.FC<{ node: ReportNode, depth: number, onDragStart: any, onDragEnd: any, onDrop: any }> = ({ node, depth, onDragStart, onDragEnd, onDrop }) => {
        const [isOver, setIsOver] = useState(false);
        const [dropPos, setDropPos] = useState<'before' | 'after' | 'inside' | null>(null);

        const handleDragOver = (e: React.DragEvent) => {
            e.preventDefault();
            e.stopPropagation();
            setIsOver(true);

            // Calculate drop position based on mouse Y in relation to element height
            const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
            const y = e.clientY - rect.top;
            const height = rect.height;

            // Top 25% -> before, Bottom 25% -> after, Middle 50% -> inside
            if (y < height * 0.25) setDropPos('before');
            else if (y > height * 0.75) setDropPos('after');
            else setDropPos('inside');
        };

        const handleDrop = (e: React.DragEvent) => {
            e.preventDefault();
            e.stopPropagation();
            setIsOver(false);
            if (dropPos) {
                onDrop(e, node.id, dropPos);
            }
            setDropPos(null);
        };

        return (
            <div className="select-none">
                <div 
                    draggable 
                    onDragStart={(e) => onDragStart(e, node.id)}
                    onDragEnd={onDragEnd}
                    onDragOver={handleDragOver}
                    onDragLeave={() => { setIsOver(false); setDropPos(null); }}
                    onDrop={handleDrop}
                    className={`
                        relative flex items-center justify-between p-3 rounded-lg border mb-2 transition-all group
                        ${isOver && dropPos === 'inside' ? 'bg-purple-100 border-purple-400' : 'bg-white border-slate-200'}
                        ${isOver && dropPos === 'before' ? 'border-t-4 border-t-purple-400' : ''}
                        ${isOver && dropPos === 'after' ? 'border-b-4 border-b-purple-400' : ''}
                        ${depth === 0 ? 'ml-0 font-bold bg-slate-50' : ''}
                        ${depth === 1 ? 'ml-6 border-l-4 border-l-blue-200' : ''}
                        ${depth > 1 ? 'ml-6' : ''}
                    `}
                    style={{ marginLeft: `${depth * 20}px` }}
                >
