                            <th className="border border-black p-1 w-24" rowSpan={2}>รวมทั้งสิ้น</th>
                        </tr>
                        <tr className="bg-gray-100 text-center font-bold">
                            <th className="border border-black p-1 w-20">เงินเดือน<br/>ค่าจ้างประจำ</th>
                            <th className="border border-black p-1 w-20">ค่าตอบแทน<br/>พนง.ราชการ</th>
