                                        </td>
                                        <td className="border border-black px-1 py-1 text-center">{r.target}</td>
                                        <td className="border border-black px-1 py-1 text-center">{r.unit}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.salaryPermanent ? formatNumber(r.salaryPermanent) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.governmentCompensation ? formatNumber(r.governmentCompensation) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.compensationSupplies ? formatNumber(r.compensationSupplies) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.contractEmployees ? formatNumber(r.contractEmployees) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.utilities ? formatNumber(r.utilities) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.equipment ? formatNumber(r.equipment) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.landConstruction ? formatNumber(r.landConstruction) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.subsidies ? formatNumber(r.subsidies) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right">{r.otherExpenses ? formatNumber(r.otherExpenses) : '-'}</td>
                                        <td className="border border-black px-1 py-1 text-right font-bold">{formatNumber(r.total)}</td>
                                    </tr>
                                ))}
                            </>
                        )}

                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={13} className="border border-black px-4 py-8 text-center text-gray-400">
                                    ไม่พบข้อมูลตามเงื่อนไขที่เลือก
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

