            });
        } catch (error: any) {
            Swal.fire({
                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: error.message || 'ไม่สามารถดึงข้อมูลได้',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsLoading(false);
        }
    };

    // --- Report Structure Handlers ---
    const handleSaveReportStructure = () => {
        dataService.setReportStructure(reportStructure);
        Swal.fire('บันทึกสำเร็จ', 'โครงสร้างรายงานถูกบันทึกแล้ว', 'success');
    };

    const handleAddReportNode = async (parentId: string | null) => {
        const { value: formValues } = await Swal.fire({
            title: 'เพิ่มหัวข้อใหม่',
            html: `
                <input id="swal-title" class="swal2-input" placeholder="ชื่อหัวข้อ/แผนงาน">
                <select id="swal-type" class="swal2-input">
                    <option value="plan">Plan (แผนงานหลัก)</option>
                    <option value="output">Output (ผลผลิต)</option>
                    <option value="project">Project (โครงการ)</option>
                    <option value="group">Group (กลุ่มกิจกรรม)</option>
                    <option value="subgroup">Subgroup (กลุ่มย่อย)</option>
                    <option value="activity">Activity (กิจกรรม - เชื่อมโยงข้อมูล)</option>
                    <option value="subactivity">Sub-activity (กิจกรรมย่อย - เชื่อมโยงข้อมูล)</option>
                </select>
                <input id="swal-matcher" class="swal2-input" placeholder="ชื่อกิจกรรมในฐานข้อมูล (ถ้ามี)">
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'เพิ่ม',
            preConfirm: () => {
                return {
                    title: (document.getElementById('swal-title') as HTMLInputElement).value,
                    type: (document.getElementById('swal-type') as HTMLSelectElement).value,
                    matcher: (document.getElementById('swal-matcher') as HTMLInputElement).value
                };
            }
        });

        if (formValues) {
            const newNode: ReportNode = {
                id: generateId(),
                title: formValues.title,
                type: formValues.type as any,
                activityMatcher: formValues.matcher || undefined,
                children: []
            };

            if (parentId === null) {
                setReportStructure([...reportStructure, newNode]);
            } else {
                setReportStructure(prev => {
                    const addToChildren = (nodes: ReportNode[]): ReportNode[] => {
                        return nodes.map(node => {
                            if (node.id === parentId) {
                                return { ...node, children: [...(node.children || []), newNode] };
                            }
                            if (node.children) {
                                return { ...node, children: addToChildren(node.children) };
                            }
                            return node;
                        });
                    };
                    return addToChildren(prev);
                });
            }
        }
    };

    const handleEditReportNode = async (node: ReportNode) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขหัวข้อ',
            html: `
                <div style="text-align:left; font-size: 14px; margin-bottom: 5px;">ชื่อหัวข้อ</div>
                <input id="swal-title" class="swal2-input" value="${node.title}" style="margin-top: 0;">
                <div style="text-align:left; font-size: 14px; margin-bottom: 5px; margin-top: 10px;">ประเภท</div>
                <select id="swal-type" class="swal2-input" style="margin-top: 0;">
                    <option value="plan" ${node.type === 'plan' ? 'selected' : ''}>Plan (แผนงานหลัก)</option>
                    <option value="output" ${node.type === 'output' ? 'selected' : ''}>Output (ผลผลิต)</option>
                    <option value="project" ${node.type === 'project' ? 'selected' : ''}>Project (โครงการ)</option>
                    <option value="group" ${node.type === 'group' ? 'selected' : ''}>Group (กลุ่มกิจกรรม)</option>
                    <option value="subgroup" ${node.type === 'subgroup' ? 'selected' : ''}>Subgroup (กลุ่มย่อย)</option>
                    <option value="activity" ${node.type === 'activity' ? 'selected' : ''}>Activity (กิจกรรม)</option>
                    <option value="subactivity" ${node.type === 'subactivity' ? 'selected' : ''}>Sub-activity (กิจกรรมย่อย)</option>
                </select>
                <div style="text-align:left; font-size: 14px; margin-bottom: 5px; margin-top: 10px;">ชื่อกิจกรรมในฐานข้อมูล (สำหรับดึงค่า)</div>
                <input id="swal-matcher" class="swal2-input" value="${node.activityMatcher || ''}" placeholder="ระบุชื่อกิจกรรมให้ตรงกับฐานข้อมูล" style="margin-top: 0;">
            `,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            preConfirm: () => {
                return {
                    title: (document.getElementById('swal-title') as HTMLInputElement).value,
                    type: (document.getElementById('swal-type') as HTMLSelectElement).value,
                    matcher: (document.getElementById('swal-matcher') as HTMLInputElement).value
                };
            }
        });

        if (formValues) {
            setReportStructure(prev => updateNodeInTree(prev, node.id, {
                title: formValues.title,
                type: formValues.type as any,
                activityMatcher: formValues.matcher || undefined
            }));
        }
    };

    const handleDeleteReportNode = async (nodeId: string) => {
        const result = await Swal.fire({
            title: 'ยืนยันการลบ?',
            text: 'การลบหัวข้อนี้จะลบหัวข้อย่อยทั้งหมดด้วย',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ef4444'
        });
        if (result.isConfirmed) {
            setReportStructure(prev => deleteNodeFromTree(prev, nodeId));
        }
    };

    // --- Drag & Drop Logic ---

    // 1. Drag Activity from List (Left Column)
    const handleActivityDragStart = (e: React.DragEvent, activityName: string) => {
        e.stopPropagation();
        setDraggedActivity(activityName);
        setDraggedNodeId(null);
        e.dataTransfer.effectAllowed = 'copy';
        e.dataTransfer.setData('text/plain', activityName);
