    // --- Drag & Drop Logic ---

    // 1. Drag Activity from List (Left Column)
    const handleActivityDragStart = (e: React.DragEvent, activityName: string) => {
        e.stopPropagation();
        setDraggedActivity(activityName);
        setDraggedNodeId(null);
        e.dataTransfer.effectAllowed = 'copy';
        e.dataTransfer.setData('text/plain', activityName);
