                <thead>
                    <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                        {headers.map((h, i) => (
                            <th key={i} className={`px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ${i === headers.length - 1 && hasActions ? 'text-right' : ''}`}>
                                {h}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                    {data.length > 0 ? data.map((row, i) => (
                        <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                            {row.columns.map((cell, j) => (
                                <td key={j} className="px-6 py-4 text-slate-700 dark:text-slate-200 text-sm font-medium">
                                    {cell}
                                </td>
                            ))}
                            {hasActions && (
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-1.5">
                                        <button onClick={row.onEdit} className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors" title="แก้ไข">
                                            <Edit2 size={16} />
                                        </button>
                                        <button onClick={row.onDelete} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg transition-colors" title="ลบ">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            )}
                        </tr>
                    )) : (
                        <tr>
                            <td colSpan={headers.length} className="px-6 py-12 text-center text-slate-400">
                                <FileSpreadsheet className="mx-auto mb-3 opacity-20" size={40} />
                                ไม่พบข้อมูล
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    </div>
);

