โปรดนำโค้ดด้านล่างนี้ไปอัปเดตทับในไฟล์ `Code.gs` ของ Google Apps Script ของคุณครับ

```javascript
function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var payload = JSON.parse(e.postData.contents);
    var action = payload.action;
    var sheetsId = payload.sheetsId;
    var ss = SpreadsheetApp.openById(sheetsId);

    // ====================================================================================
    // HANDLE SAVE REPORT STRUCTURE (New)
    // ====================================================================================
    if (action === 'SAVE_REPORT_STRUCTURE') {
      var structure = payload.structure;
      // Define where to store the setting (Sheet "Setting" or use Data sheet)
      // Assuming user asked for "Setting" sheet specifically.
      var settingSheet = ss.getSheetByName("Setting");
      if (!settingSheet) {
        settingSheet = ss.insertSheet("Setting");
        settingSheet.appendRow(["Key", "Value"]); // Header
      }

      // We will store the JSON string in a row where Key = "REPORT_STRUCTURE"
      var data = settingSheet.getDataRange().getValues();
      var rowIndex = -1;

      // Find existing row
      for (var i = 0; i < data.length; i++) {
        if (data[i][0] === "REPORT_STRUCTURE") {
          rowIndex = i + 1;
          break;
        }
      }

      var jsonString = JSON.stringify(structure);

      if (rowIndex > 0) {
        // Update existing
        settingSheet.getRange(rowIndex, 2).setValue(jsonString);
      } else {
        // Add new
        settingSheet.appendRow(["REPORT_STRUCTURE", jsonString]);
      }

      return ContentService.createTextOutput(JSON.stringify({ status: 'success', message: 'Report structure saved to Setting sheet' })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // HANDLE GET_DATA (Updated)
    // ====================================================================================
    if (action === 'GET_DATA') {
      var dbSheet = ss.getSheetByName(payload.databaseSheetName);
      var dataSheet = ss.getSheetByName(payload.dataSheetName);

      // Read main records
      var records = [];
      if (dbSheet) {
        var dbData = dbSheet.getDataRange().getValues();
        var headers = dbData[0];
        for (var i = 1; i < dbData.length; i++) {
          var row = dbData[i];
          var obj = {};
          for (var j = 0; j < headers.length; j++) {
            obj[headers[j]] = row[j];
          }
          records.push(obj);
        }
      }

      // Read dropdowns & master data from 'Data' sheet (Legacy logic preserved)
      var dropdowns = { integration: [], unit: [] };
      var hierarchy = [];
      var respData = [];
      var compareData = [];
      var rolePermissions = {};

      if (dataSheet) {
        // ... (Your existing logic for reading Data sheet columns) ...
        // Simplified Logic assuming columns exist:
        // Adjust these column indexes based on your real Data sheet structure!
        // Example: Col A=MainAgency, B=Province, ...
        // For simplicity in this example, I'm returning placeholder logic or assuming you keep your existing parsing code here.
        // In a real update, you merge this with your existing GET_DATA logic.

        var dData = dataSheet.getDataRange().getValues();
        // Parse columns... (Standard implementation hidden for brevity, assume similar to previous version)

        // --- NEW: Read Permissions from Setting Sheet (if separated) or Data Sheet ---
        // Also Read Report Structure from Setting Sheet
        var reportStructure = [];
        var settingSheet = ss.getSheetByName("Setting");
        if (settingSheet) {
           var sData = settingSheet.getDataRange().getValues();
           for(var i=0; i<sData.length; i++){
             if(sData[i][0] === "REPORT_STRUCTURE"){
               try {
                 reportStructure = JSON.parse(sData[i][1]);
               } catch(e) {
                 reportStructure = [];
               }
             }
             if(sData[i][0] === "PERMISSIONS"){
                try {
                 rolePermissions = JSON.parse(sData[i][1]);
               } catch(e) { }
             }
           }
        }
      }

      return ContentService.createTextOutput(JSON.stringify({ 
        status: 'success', 
        data: { 
          records: records,
          dropdowns: dropdowns, // Fill with actual parsed data
          hierarchy: hierarchy, // Fill with actual parsed data
          respData: respData,   // Fill with actual parsed data
          compareData: compareData, // Fill with actual parsed data
          rolePermissions: rolePermissions,
          reportStructure: reportStructure // <--- Return this
        } 
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // ... (Keep other actions like MANAGE_RECORD, MANAGE_MASTER, SAVE_PERMISSIONS) ...
    // Note: for SAVE_PERMISSIONS, also update to write to "Setting" sheet if you want consistency.

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

แนะนำให้ **"วางทับโค้ดเดิมทั้งหมด"** (Replace All) ในไฟล์ `Code.gs` บน Google Apps Script Editor ครับ เพื่อให้มั่นใจว่าฟังก์ชันการทำงานทั้งหมด (ทั้งการจัดการฐานข้อมูลเดิม, การจัดการสิทธิ์, และฟีเจอร์ใหม่เรื่องโครงสร้างรายงาน) เชื่อมต่อกันได้อย่างสมบูรณ์และไม่มีโค้ดซ้ำซ้อน

นี่คือโค้ดฉบับเต็มที่รวมทุกฟีเจอร์ไว้แล้วครับ:

```javascript
function doPost(e) {
  var lock = LockService.getScriptLock();
  // รอสูงสุด 10 วินาทีเพื่อป้องกันการเขียนทับซ้อนกัน
  lock.tryLock(10000);

  try {
    var payload = JSON.parse(e.postData.contents);
    var action = payload.action;
    var sheetsId = payload.sheetsId;
    var ss = SpreadsheetApp.openById(sheetsId);

    // ====================================================================================
    // 1. TEST CONNECTION
    // ====================================================================================
    if (action === 'TEST_CONNECTION') {
      return ContentService.createTextOutput(JSON.stringify({ status: 'success', message: 'Connection OK' })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // 2. SAVE REPORT STRUCTURE (บันทึกโครงสร้างรายงานลงชีท Setting)
    // ====================================================================================
    if (action === 'SAVE_REPORT_STRUCTURE') {
      var structure = payload.structure;
      var settingSheet = getOrCreateSheet(ss, "Setting");
      saveSettingValue(settingSheet, "REPORT_STRUCTURE", JSON.stringify(structure));
      return ContentService.createTextOutput(JSON.stringify({ status: 'success', message: 'Report structure saved' })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // 3. SAVE PERMISSIONS (บันทึกสิทธิ์ลงชีท Setting)
    // ====================================================================================
    if (action === 'SAVE_PERMISSIONS') {
      var perms = payload.rolePermissions;
      var settingSheet = getOrCreateSheet(ss, "Setting");
      saveSettingValue(settingSheet, "PERMISSIONS", JSON.stringify(perms));
      return ContentService.createTextOutput(JSON.stringify({ status: 'success', message: 'Permissions saved' })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // 4. GET DATA (ดึงข้อมูลทั้งหมดรวมถึง Setting)
    // ====================================================================================
    if (action === 'GET_DATA') {
      var dbSheet = ss.getSheetByName(payload.databaseSheetName);
      var dataSheet = ss.getSheetByName(payload.dataSheetName);
      var settingSheet = ss.getSheetByName("Setting");

      // --- Read Records ---
      var records = [];
      if (dbSheet) {
        records = sheetToObjects(dbSheet);
      }

      // --- Read Dropdowns & Master Data ---
      var dropdowns = { integration: [], unit: [], activity: [], mainAgency: [], responsibleAgency: [], integrationArea: [], province: [] };
      var hierarchy = [];
      var respData = [];
      var compareData = [];

      if (dataSheet) {
        var dData = dataSheet.getDataRange().getValues();
        var headers = dData[0] || [];

        // Helper to find column index by name
        var getColIdx = function(name) { return headers.indexOf(name); };

        for (var i = 1; i < dData.length; i++) {
          var row = dData[i];

          // Hierarchy
          if (getColIdx('หน่วยงานหลัก') > -1 && getColIdx('จังหวัด') > -1) {
            var m = row[getColIdx('หน่วยงานหลัก')];
            var p = row[getColIdx('จังหวัด')];
            if(m && p) hierarchy.push({ mainAgency: String(m), province: String(p) });
          }

          // Responsible Agency
          if (getColIdx('หน่วยงานหลัก') > -1 && getColIdx('หน่วยงานบูรณาการ') > -1 && getColIdx('พื้นที่บูรณาการ') > -1) {
             var m = row[getColIdx('หน่วยงานหลัก')];
             var r = row[getColIdx('หน่วยงานบูรณาการ')];
             var a = row[getColIdx('พื้นที่บูรณาการ')];
             if(m && r) respData.push({ mainAgency: String(m), responsibleAgency: String(r), integrationArea: String(a) });
          }

          // Compare Data (Activity List)
          if (getColIdx('กิจกรรม') > -1) {
             var act = row[getColIdx('กิจกรรม')];
             var bud = 0;
             if (getColIdx('งบอ้างอิง') > -1) bud = row[getColIdx('งบอ้างอิง')];
             if(act) compareData.push({ id: String(act), activity: String(act), referenceBudget: bud });
          }

          // Unit
          if (getColIdx('หน่วยนับ') > -1) {
             var u = row[getColIdx('หน่วยนับ')];
             if(u) dropdowns.unit.push(String(u));
          }

          // Integration List
          if (getColIdx('รายการบูรณาการ') > -1) {
             var intg = row[getColIdx('รายการบูรณาการ')];
             if(intg) dropdowns.integration.push(String(intg));
          }
        }

        // Remove duplicates for dropdowns
        dropdowns.unit = [...new Set(dropdowns.unit)];
        dropdowns.integration = [...new Set(dropdowns.integration)];
      }

      // --- Read Settings (Permissions & Report Structure) ---
      var rolePermissions = {};
      var reportStructure = [];

      if (settingSheet) {
         var sData = settingSheet.getDataRange().getValues();
         for(var i=0; i<sData.length; i++){
           var key = sData[i][0];
           var val = sData[i][1];
           if(key === "REPORT_STRUCTURE"){
             try { reportStructure = JSON.parse(val); } catch(e) {}
           }
           if(key === "PERMISSIONS"){
              try { rolePermissions = JSON.parse(val); } catch(e) {}
           }
         }
      }

      return ContentService.createTextOutput(JSON.stringify({ 
        status: 'success', 
        data: { 
          records: records,
          dropdowns: dropdowns, 
          hierarchy: hierarchy, 
          respData: respData,   
          compareData: compareData, 
          rolePermissions: rolePermissions,
          reportStructure: reportStructure
        } 
      })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // 5. MANAGE RECORD (CRUD ข้อมูลงบประมาณ)
    // ====================================================================================
    if (action === 'MANAGE_RECORD') {
      var sheet = ss.getSheetByName(payload.databaseSheetName);
      if (!sheet) {
        sheet = ss.insertSheet(payload.databaseSheetName);
        // สร้าง Header เริ่มต้นถ้ายังไม่มี
        sheet.appendRow(['ID', 'บูรณาการ', 'หน่วยงานหลัก', 'จังหวัด', 'หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'กิจกรรม', 'เป้าหมาย', 'หน่วยนับ', 'เงินเดือนและค่าจ้างประจำ', 'ค่าตอบแทนพนักงานราชการ', 'ค่าตอบแทน ใช้สอย และวัสดุ', 'ค่าจ้างเหมาพนักงาน', 'ค่าสาธารณูปโภค', 'ค่าครุภัณฑ์', 'ค่าที่ดินและสิ่งก่อสร้าง', 'งบเงินอุดหนุน', 'งบรายจ่ายอื่น', 'วันที่บันทึก']);
      }

      var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
      var idColIdx = headers.indexOf('ID'); // ค้นหาคอลัมน์ ID

      if (idColIdx === -1) return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: 'ID column not found' })).setMimeType(ContentService.MimeType.JSON);

      if (payload.type === 'add') {
        var newRow = [];
        for (var i = 0; i < headers.length; i++) {
          newRow.push(payload.data[headers[i]] || '');
        }
        sheet.appendRow(newRow);
      } 
      else if (payload.type === 'update' || payload.type === 'delete') {
        var data = sheet.getDataRange().getValues();
        var rowToUpdate = -1;

        for (var i = 1; i < data.length; i++) {
          if (String(data[i][idColIdx]) === String(payload.id)) {
            rowToUpdate = i + 1;
            break;
          }
        }

        if (rowToUpdate > 0) {
          if (payload.type === 'delete') {
            sheet.deleteRow(rowToUpdate);
          } else {
            var updateRow = [];
            for (var i = 0; i < headers.length; i++) {
              updateRow.push(payload.data[headers[i]] || '');
            }
            sheet.getRange(rowToUpdate, 1, 1, headers.length).setValues([updateRow]);
          }
        } else {
           return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: 'Record ID not found' })).setMimeType(ContentService.MimeType.JSON);
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ status: 'success' })).setMimeType(ContentService.MimeType.JSON);
    }

    // ====================================================================================
    // 6. MANAGE MASTER (CRUD ข้อมูลตัวเลือก)
    // ====================================================================================
    if (action === 'MANAGE_MASTER') {
      var sheet = ss.getSheetByName(payload.dataSheetName);
      if (!sheet) return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: 'Data sheet not found' })).setMimeType(ContentService.MimeType.JSON);

      var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
      var pData = payload.data;

      // Helper to execute Row operations based on criteria
      var processMaster = function(checkFn, createRowFn, updateRowFn) {
         var data = sheet.getDataRange().getValues();
         var rowIndex = -1;

         // Find row
         for(var i=1; i<data.length; i++) {
           if(checkFn(data[i], headers)) {
             rowIndex = i + 1;
             break;
           }
         }

         if (payload.type === 'add') {
            if (rowIndex === -1) sheet.appendRow(createRowFn(headers)); // Add only if not exists (or allow duplicates? usually master data is unique)
            else return; // Duplicate logic handling could be here
         } else if (payload.type === 'delete' && rowIndex > 0) {
            sheet.deleteRow(rowIndex);
         } else if (payload.type === 'update' && rowIndex > 0) {
            var rowValues = data[rowIndex-1]; // Get current values
            var newValues = updateRowFn(rowValues, headers);
            sheet.getRange(rowIndex, 1, 1, headers.length).setValues([newValues]);
         }
      };

      if (payload.target === 'Hierarchy') {
         // Logic for MainAgency + Province
         var findFn = function(row, h) { 
            return row[h.indexOf('หน่วยงานหลัก')] == (payload.type === 'add' ? pData.mainAgency : pData.oldMainAgency) && 
                   row[h.indexOf('จังหวัด')] == (payload.type === 'add' ? pData.province : pData.oldProvince); 
         };
         var createFn = function(h) {
            var r = new Array(h.length).fill('');
            r[h.indexOf('หน่วยงานหลัก')] = pData.mainAgency;
            r[h.indexOf('จังหวัด')] = pData.province;
            return r;
         };
         var updateFn = function(currRow, h) {
            currRow[h.indexOf('หน่วยงานหลัก')] = pData.mainAgency;
            currRow[h.indexOf('จังหวัด')] = pData.province;
            return currRow;
         }
         processMaster(findFn, createFn, updateFn);
      }

      else if (payload.target === 'ResponsibleAgency') {
         var findFn = function(row, h) {
             return row[h.indexOf('หน่วยงานหลัก')] == pData.mainAgency &&
                    row[h.indexOf('หน่วยงานบูรณาการ')] == (payload.type === 'add' ? pData.responsibleAgency : pData.oldResponsibleAgency) &&
                    row[h.indexOf('พื้นที่บูรณาการ')] == (payload.type === 'add' ? pData.integrationArea : pData.oldIntegrationArea);
         };
         var createFn = function(h) {
            var r = new Array(h.length).fill('');
            r[h.indexOf('หน่วยงานหลัก')] = pData.mainAgency;
            r[h.indexOf('หน่วยงานบูรณาการ')] = pData.responsibleAgency;
            r[h.indexOf('พื้นที่บูรณาการ')] = pData.integrationArea;
            return r;
         };
         var updateFn = function(currRow, h) {
            currRow[h.indexOf('หน่วยงานบูรณาการ')] = pData.responsibleAgency;
            currRow[h.indexOf('พื้นที่บูรณาการ')] = pData.integrationArea;
            return currRow;
         }
         processMaster(findFn, createFn, updateFn);
      }

      else if (payload.target === 'Compare') {
         // Activity List
         var findFn = function(row, h) { return row[h.indexOf('กิจกรรม')] == (payload.type === 'add' ? pData.activity : pData.oldActivity); };
         var createFn = function(h) {
            var r = new Array(h.length).fill('');
            r[h.indexOf('กิจกรรม')] = pData.activity;
            r[h.indexOf('งบอ้างอิง')] = pData.referenceBudget || 0;
            return r;
         };
         var updateFn = function(currRow, h) {
            currRow[h.indexOf('กิจกรรม')] = pData.activity;
            currRow[h.indexOf('งบอ้างอิง')] = pData.referenceBudget;
            return currRow;
         }
         processMaster(findFn, createFn, updateFn);
      }

      else if (payload.target === 'Unit' || payload.target === 'Integration') {
         var colName = payload.target === 'Unit' ? 'หน่วยนับ' : 'รายการบูรณาการ';
         var findFn = function(row, h) { return row[h.indexOf(colName)] == (payload.type === 'add' ? pData.name : pData.oldName); };
         var createFn = function(h) {
            var r = new Array(h.length).fill('');
            r[h.indexOf(colName)] = pData.name;
            return r;
         };
         var updateFn = function(currRow, h) {
            currRow[h.indexOf(colName)] = pData.name;
            return currRow;
         }
         processMaster(findFn, createFn, updateFn);
      }

      return ContentService.createTextOutput(JSON.stringify({ status: 'success' })).setMimeType(ContentService.MimeType.JSON);
    }

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ status: 'error', message: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- Helper Functions ---

function sheetToObjects(sheet) {
  var data = sheet.getDataRange().getValues();
  var headers = data[0];
  var result = [];
  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
    }
    result.push(obj);
  }
  return result;
}

function getOrCreateSheet(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(["Key", "Value"]); // Header
  }
  return sheet;
}

function saveSettingValue(sheet, key, value) {
  var data = sheet.getDataRange().getValues();
  var rowIndex = -1;

  for (var i = 0; i < data.length; i++) {
    if (data[i][0] === key) {
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex > 0) {
    sheet.getRange(rowIndex, 2).setValue(value);
  } else {
    sheet.appendRow([key, value]);
  }
}

