export const getSettings = (): AppSettings => {
    const stored = localStorage.getItem(SETTINGS_KEY);
    const defaults = {
        gasUrl: 'https://script.google.com/macros/s/AKfycbwdmg-DcHes5WGTWihXPIuREB5JJAxHox8ROAAiFDU5hCnMAvXbf2X5j4eh3FYu2B4v/exec',
        sheetsId: '1rwyAt0TsSSpZ7uqrAHq6C39AYvGogK0rj1b7QI8efkM',
        dataSheetName: 'Database',
        databaseSheetName: 'Database',
        permissions: DEFAULT_ROLE_PERMISSIONS
    };

    if (stored) {
        const parsed = JSON.parse(stored);
        let permissions = parsed.permissions || parsed.rolePermissions || defaults.permissions;

        // Robust Fallback: Ensure permissions object is valid and 'admin' always has access
        // This prevents lockout if GAS returns empty permissions
        if (!permissions || Object.keys(permissions).length === 0) {
            permissions = defaults.permissions;
        } else {
            // If admin key is missing in custom permissions (e.g. partial sync), merge default admin permissions
            if (!permissions['admin']) {
                permissions = { ...permissions, 'admin': defaults.permissions['admin'] };
            }
        }

        return { ...defaults, ...parsed, permissions };
    }
    return defaults;
};

