    };

    // 3. Drop Handler (Handles both types of drops)
    const onDrop = (e: React.DragEvent, targetId: string, position: 'before' | 'after' | 'inside') => {
        e.preventDefault();
        e.stopPropagation();

        // Scenario A: Dropping a new Activity from Sidebar
        if (draggedActivity) {
            const newNode: ReportNode = {
                id: generateId(),
                title: draggedActivity,
                type: 'activity',
                activityMatcher: draggedActivity,
                children: []
            };

            const newStructure = JSON.parse(JSON.stringify(reportStructure));

            if (position === 'inside') {
                // Find target node and append child
                const findNode = (nodes: ReportNode[]): ReportNode | null => {
                    for (const n of nodes) {
                        if (n.id === targetId) return n;
                        if (n.children) {
                            const f = findNode(n.children);
                            if (f) return f;
                        }
                    }
                    return null;
                };
                const targetNode = findNode(newStructure);
                if (targetNode) {
                    if (!targetNode.children) targetNode.children = [];
                    targetNode.children.push(newNode);
                }
            } else {
                // Dropping before/after target
                const targetInfo = findNodeParent(newStructure, targetId);
                if (targetInfo) {
                    const insertIndex = position === 'after' ? targetInfo.index + 1 : targetInfo.index;
                    targetInfo.parentChildren.splice(insertIndex, 0, newNode);
                } else {
                    newStructure.push(newNode);
                }
            }
            setReportStructure(newStructure);
            setDraggedActivity(null);
            return;
        }

        // Scenario B: Reordering Internal Nodes
        if (draggedNodeId && draggedNodeId !== targetId) {
            // Clone structure
            const newStructure = JSON.parse(JSON.stringify(reportStructure));

            // 1. Find and remove dragged node
            const sourceInfo = findNodeParent(newStructure, draggedNodeId);
            if (!sourceInfo) return;

            const draggedNode = sourceInfo.parentChildren[sourceInfo.index];
            sourceInfo.parentChildren.splice(sourceInfo.index, 1);

            // 2. Find target and insert
            if (position === 'inside') {
                 const findNode = (nodes: ReportNode[]): ReportNode | null => {
                     for (const n of nodes) {
                         if (n.id === targetId) return n;
                         if (n.children) {
                             const f = findNode(n.children);
                             if (f) return f;
                         }
                     }
                     return null;
                 };

                 const targetNode = findNode(newStructure);
                 if (targetNode) {
                     if (!targetNode.children) targetNode.children = [];
                     targetNode.children.push(draggedNode);
                 } else {
                     newStructure.push(draggedNode);
                 }

            } else {
                 const targetInfo = findNodeParent(newStructure, targetId);
                 if (targetInfo) {
                     const insertIndex = position === 'after' ? targetInfo.index + 1 : targetInfo.index;
                     targetInfo.parentChildren.splice(insertIndex, 0, draggedNode);
                 } else {
                     newStructure.push(draggedNode);
                 }
            }
            setReportStructure(newStructure);
            setDraggedNodeId(null);
        }
    };

