    const ReportTreeNode: React.FC<{ node: ReportNode, depth: number, onDragStart: any, onDragEnd: any, onDrop: any }> = ({ node, depth, onDragStart, onDragEnd, onDrop }) => {
        const [isOver, setIsOver] = useState(false);
        const [dropPos, setDropPos] = useState<'before' | 'after' | 'inside' | null>(null);

        const handleDragOver = (e: React.DragEvent) => {
            e.preventDefault();
            e.stopPropagation();
            setIsOver(true);
            const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
            const y = e.clientY - rect.top;
            const height = rect.height;
            if (y < height * 0.25) setDropPos('before');
            else if (y > height * 0.75) setDropPos('after');
            else setDropPos('inside');
        };

        const handleDrop = (e: React.DragEvent) => {
            e.preventDefault();
            e.stopPropagation();
            setIsOver(false);
            if (dropPos) {
                onDrop(e, node.id, dropPos);
            }
            setDropPos(null);
        };

