                 const targetNode = findNode(newStructure);
                 if (targetNode) {
                     if (!targetNode.children) targetNode.children = [];
                     targetNode.children.push(draggedNode);
                 } else {
                     newStructure.push(draggedNode);
                 }
            } else {
                 const targetInfo = findNodeParent(newStructure, targetId);
                 if (targetInfo) {
