payload.text:
ใช่ครับ **โค้ดใน Google Apps Script (GAS) จำเป็นต้องได้รับการแก้ไข** เพื่อให้รองรับการดึงและบันทึกข้อมูลลงในชีท "Hierarchy" ตามที่คุณตั้งค่าไว้ในหน้าเว็บ

เนื่องจากโค้ดเดิมฝั่ง Frontend (ใน `dataService.ts`) ได้เตรียมการส่งตัวแปร `hierarchySheetName` ไปให้แล้ว คุณต้องอัปเดตฟังก์ชัน `getData` และ `manageMaster` ใน Google Apps Script เพื่อให้รับค่าชื่อชีทนี้ไปใช้งานจริงครับ

กรุณานำโค้ดด้านล่างนี้ไปอัปเดตใน **Google Apps Script** ของคุณ:

### 1. อัปเดตฟังก์ชัน `getData`
เพื่อให้ดึงข้อมูลจากชีท Hierarchy (คอลัมน์ A, B) แทนการดึงจาก Database

```javascript
function getData(ss, payload) {
  var dbSheetName = payload.databaseSheetName || 'Database';
  var dataSheetName = payload.dataSheetName || 'Data';
  var hierarchySheetName = payload.hierarchySheetName || 'Hierarchy'; // รับชื่อชีท Hierarchy

  var dbSheet = ss.getSheetByName(dbSheetName);
  var dataSheet = ss.getSheetByName(dataSheetName);
  var hierarchySheet = ss.getSheetByName(hierarchySheetName); // เปิดชีท Hierarchy

  var records = dbSheet ? getSheetData(dbSheet) : [];
  var dropdowns = { integration: [], unit: [], activity: [] }; // ค่าเริ่มต้น
  var rolePermissions = {};
  var reportStructure = [];

  // ... (ส่วนดึงข้อมูล Dropdowns จาก Data sheet เหมือนเดิม) ...
  if (dataSheet) {
     // ... logic ดึง dropdowns เดิม ...
  }

  // --- ส่วนจัดการ Hierarchy (แก้ไขใหม่) ---
  var hierarchy = [];
  if (hierarchySheet) {
    var lastRow = hierarchySheet.getLastRow();
    if (lastRow > 1) {
      // ดึงข้อมูลตั้งแต่แถวที่ 2 คอลัมน์ 1 (A) ถึง คอลัมน์ 2 (B)
      var values = hierarchySheet.getRange(2, 1, lastRow - 1, 2).getValues();
      hierarchy = values.map(function(row) {
        return {
          mainAgency: row[0], // คอลัมน์ A
          province: row[1]    // คอลัมน์ B
        };
      }).filter(function(item) { return item.mainAgency && item.province; });
    }
  }
  // -------------------------------------

  // ... (ส่วนดึง responsibleAgency / compareData เหมือนเดิม) ...

  return {
    records: records,
    dropdowns: dropdowns,
    hierarchy: hierarchy, // ส่งค่า hierarchy ที่ถูกต้องกลับไป
    rolePermissions: rolePermissions,
    reportStructure: reportStructure
    // ... อื่นๆ
  };
}
```

### 2. อัปเดตฟังก์ชัน `manageMaster`
เพื่อให้การ เพิ่ม/แก้ไข/ลบ ข้อมูลไปทำที่ชีท Hierarchy อย่างถูกต้อง

```javascript
function manageMaster(ss, payload) {
  var target = payload.target;
  var type = payload.type;
  var data = payload.data;
  var sheetName = '';

  // กำหนดชื่อชีทตาม Target
  if (target === 'Hierarchy') {
    sheetName = payload.hierarchySheetName || 'Hierarchy'; // ใช้ชื่อชีท Hierarchy
  } else if (target === 'Compare') {
    sheetName = payload.dataSheetName || 'Data'; // หรือชีทที่เก็บ Compare
  } else {
    sheetName = payload.dataSheetName || 'Data';
  }

  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return { success: false, message: 'Sheet not found: ' + sheetName };

  if (target === 'Hierarchy') {
    // จัดการข้อมูล Hierarchy (คอลัมน์ A, B)
    if (type === 'add') {
      sheet.appendRow([data.mainAgency, data.province]);
      return { success: true };
    } 
    else if (type === 'update' || type === 'delete') {
      var range = sheet.getDataRange();
      var values = range.getValues();
      // ค้นหาแถวที่ตรงกัน (เทียบค่าเก่า)
      for (var i = 1; i < values.length; i++) {
        // ใช้ oldMainAgency/oldProvince ในการค้นหา (ถ้ามีส่งมา) หรือใช้ค่าปัจจุบัน
        var checkMain = data.oldMainAgency || data.mainAgency;
        var checkProv = data.oldProvince || data.province;

        if (values[i][0] == checkMain && values[i][1] == checkProv) {
          if (type === 'delete') {
            sheet.deleteRow(i + 1);
