            sheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
          }
          return { success: true };
        }
      }
      return { success: false, message: 'Item not found' };
    }
  }

  // ... (Logic สำหรับ Target อื่นๆ เช่น ResponsibleAgency, Compare คงเดิม) ...
}
