            if (payload.data.integration) {
                mappedData['บูรณาการ'] = payload.data.integration;
                mappedData['บูรณาการ (ประเภทหน่วยงาน)'] = payload.data.integration;
                mappedData['ประเภทหน่วยงาน'] = payload.data.integration;
