                                            <GripVertical size={14} className="text-slate-400" />
                                            <span className="truncate flex-1">{act}</span>
                                            <ArrowRight size={14} className="text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity" />
                                        </div>
                                    )) : (
                                        <div className="text-center py-8 text-slate-400 text-sm">ไม่พบกิจกรรมที่เหลืออยู่</div>
                                    )}
                                </div>
                            </div>
                            <div className="col-span-8 bg-slate-50 dark:bg-slate-900/50 rounded-xl border border-slate-200 dark:border-slate-700 p-4 overflow-y-auto max-h-[700px]">
                                {reportStructure.length === 0 ? (
                                    <div className="text-center py-20 text-slate-400 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-xl">
                                        <FolderTree size={40} className="mx-auto mb-2 opacity-50" />
                                        <p>ยังไม่มีโครงสร้างรายงาน</p>
                                        <p className="text-xs mt-1">กดปุ่ม "เพิ่มหัวข้อหลัก" หรือลากกิจกรรมจากฝั่งซ้ายมาวาง</p>
                                    </div>
                                ) : (
                                    reportStructure.map(node => (
                                        <ReportTreeNode 
                                            key={node.id} 
                                            node={node} 
                                            depth={0} 
                                            onDragStart={onDragStart}
                                            onDragEnd={onDragEnd}
                                            onDrop={onDrop}
                                        />
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                );
            case 'hierarchy':
                const uniqueMainAgencies = Array.from(new Set(hierarchy.map(h => h.mainAgency))).sort((a, b) => a.localeCompare(b, 'th'));
                const filteredHierarchy = selectedMainAgency 
                    ? hierarchy.filter(h => h.mainAgency === selectedMainAgency)
                    : [];

                return (
                    <div className="space-y-6">
                        <div className="bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-700">
                             <div className="flex flex-col md:flex-row gap-6 items-end">
                                <div className="flex-1 w-full">
                                    <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">
                                        <span className="w-6 h-6 inline-flex items-center justify-center bg-emerald-600 text-white rounded-full text-xs mr-2">1</span>
                                        เลือกหน่วยงานหลัก (Main Agency)
                                    </label>
                                    <div className="relative">
                                        <select 
                                            value={selectedMainAgency} 
                                            onChange={(e) => setSelectedMainAgency(e.target.value)} 
                                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl outline-none bg-white dark:bg-slate-900 focus:ring-2 focus:ring-emerald-500 transition-all text-slate-800 dark:text-slate-200 appearance-none"
                                        >
                                            <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                            {uniqueMainAgencies.map(m => <option key={m} value={m}>{m}</option>)}
                                        </select>
                                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                                            <ChevronRight size={18} className="rotate-90" />
                                        </div>
                                    </div>
                                    <p className="text-xs text-slate-500 mt-2">เลือกหน่วยงานหลักเพื่อดูหรือจัดการรายชื่อจังหวัดในสังกัด</p>
                                </div>
                                <div className="mb-2">
                                     <button 
                                        onClick={() => handleAddHierarchy('')} 
                                        className="bg-white dark:bg-slate-800 text-blue-600 dark:text-blue-400 border border-blue-200 dark:border-blue-800 px-4 py-2.5 rounded-xl flex items-center gap-2 shadow-sm hover:bg-blue-50 dark:hover:bg-blue-900/30 transition-colors text-sm font-bold whitespace-nowrap"
                                    >
                                        <Plus size={18} /> เพิ่มหน่วยงานใหม่
                                    </button>
                                </div>
                            </div>
                        </div>

                        {selectedMainAgency ? (
                            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex justify-between items-center">
                                    <h4 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                                        <span className="w-6 h-6 inline-flex items-center justify-center bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-full text-xs">2</span>
                                        จังหวัดในสังกัด ({filteredHierarchy.length})
                                    </h4>
                                    <button 
                                        onClick={() => handleAddHierarchy(selectedMainAgency)} 
                                        className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium"
                                    >
                                        <Plus size={16} /> เพิ่มจังหวัดในสังกัดนี้
                                    </button>
                                </div>
                                <Table 
                                    headers={['ลำดับ', 'จังหวัด', 'จัดการ']}
                                    data={filteredHierarchy.map((item, idx) => ({
                                        columns: [idx + 1, item.province],
                                        onEdit: () => handleEditHierarchy(item.mainAgency, item.province),
                                        onDelete: () => handleDeleteHierarchy(item.mainAgency, item.province)
                                    }))}
                                    hasActions
                                />
                            </div>
                        ) : (
                            <div className="text-center py-16 bg-white dark:bg-slate-800 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                                <Network size={48} className="mx-auto mb-3 text-slate-300 dark:text-slate-600 opacity-50"/>
                                <h3 className="text-lg font-semibold text-slate-600 dark:text-slate-300">ยังไม่ได้เลือกหน่วยงานหลัก</h3>
                                <p className="text-slate-500 dark:text-slate-400 mt-1">กรุณาเลือกหน่วยงานหลักจากตัวเลือกด้านบน (Step 1) เพื่อดำเนินการต่อ</p>
                            </div>
                        )}
                    </div>
                );
             case 'responsible':
                 const responsibles = selectedMainAgency 
                    ? respData.filter(r => r.mainAgency === selectedMainAgency)
                    : [];
                return (
                    <div className="space-y-6">
                         <div className="max-w-md">
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">เลือกหน่วยงานหลักเพื่อดูข้อมูล</label>
                            <select value={selectedMainAgency} onChange={(e) => setSelectedMainAgency(e.target.value)} className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl outline-none bg-white dark:bg-slate-900">
                                <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                {dropdowns.mainAgency.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        {selectedMainAgency ? (
                             <div className="space-y-4">
                                <div className="flex justify-between items-center border-b border-slate-100 pb-2"><h4 className="text-lg font-semibold">หน่วยงานบูรณาการของ {selectedMainAgency}</h4><button onClick={handleAddResponsible} className="bg-emerald-600 text-white px-4 py-2 rounded-lg text-sm flex gap-2"><Plus size={16}/> เพิ่มข้อมูล</button></div>
                                <Table headers={['หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'จัดการ']} data={responsibles.map((item) => ({ columns: [item.responsibleAgency, item.integrationArea], onEdit: () => handleEditResponsible(item.responsibleAgency, item.integrationArea), onDelete: () => handleDeleteResponsible(item.responsibleAgency, item.integrationArea) }))} hasActions />
                            </div>
                        ) : <div className="text-center py-20 bg-slate-50 rounded-2xl border border-dashed"><Users size={48} className="mx-auto mb-3 text-slate-300"/><p className="text-slate-500">กรุณาเลือกหน่วยงานหลักด้านบน</p></div>}
                    </div>
                );
             case 'fields':
                const fieldKeys = Object.keys(dataService.getFieldVisibility());
                return (
                    <div className="space-y-4">
                         <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center mb-4">
                            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/50 rounded-xl p-4 flex-1">
                                <p className="text-sm text-blue-700 dark:text-blue-300 flex items-center gap-2">
                                    <Eye size={16} /> 
                                    ฟิลด์ที่ปิดจะถูกซ่อนในหน้าบันทึกข้อมูล (แบบฟอร์ม)
                                </p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => handleSetAllFields(true)} className="px-3 py-1.5 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-lg text-xs font-bold hover:bg-emerald-200 transition-colors">แสดงทั้งหมด</button>
                                <button onClick={() => handleSetAllFields(false)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-xs font-bold hover:bg-slate-200 transition-colors">ซ่อนทั้งหมด</button>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                            {fieldKeys.map((key) => (
                                <div key={key} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${fieldVisibility[key] ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 opacity-60'}`}>
                                    <span className="font-medium text-slate-700 dark:text-slate-300 text-sm">{FIELD_LABELS[key] || key}</span>
                                    <button
                                        onClick={() => handleToggleField(key)}
                                        className={`p-2 rounded-lg transition-colors flex items-center gap-1.5 text-xs font-bold ${fieldVisibility[key] ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400' : 'bg-slate-200 dark:bg-slate-700 text-slate-500'}`}
                                    >
                                        {fieldVisibility[key] ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                                        {fieldVisibility[key] ? 'เปิด' : 'ปิด'}
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                );
            case 'tableColumns':
                const tableKeys = Object.keys(dataService.getTableColumnVisibility());
                return (
                    <div className="space-y-4">
                         <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center mb-4">
                            <div className="bg-purple-50 dark:bg-purple-900/20 border border-purple-100 dark:border-purple-900/50 rounded-xl p-4 flex-1">
                                <p className="text-sm text-purple-700 dark:text-purple-300 flex items-center gap-2">
                                    <TableProperties size={16} /> 
                                    คอลัมน์ที่ปิดจะถูกซ่อนในหน้าตารางฐานข้อมูล
                                </p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => handleSetAllTableColumns(true)} className="px-3 py-1.5 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 rounded-lg text-xs font-bold hover:bg-emerald-200 transition-colors">แสดงทั้งหมด</button>
                                <button onClick={() => handleSetAllTableColumns(false)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-lg text-xs font-bold hover:bg-slate-200 transition-colors">ซ่อนทั้งหมด</button>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                            {tableKeys.map((key) => (
                                <div key={key} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${tableVisibility[key] ? 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm' : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-800 opacity-60'}`}>
                                    <span className="font-medium text-slate-700 dark:text-slate-300 text-sm">{FIELD_LABELS[key] || key}</span>
                                    <button
                                        onClick={() => handleToggleTableColumn(key)}
                                        className={`p-2 rounded-lg transition-colors flex items-center gap-1.5 text-xs font-bold ${tableVisibility[key] ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-400' : 'bg-slate-200 dark:bg-slate-700 text-slate-500'}`}
                                    >
                                        {tableVisibility[key] ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                                        {tableVisibility[key] ? 'เปิด' : 'ปิด'}
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                );
             case 'integration': return <div className="space-y-4"><div className="flex justify-between pb-2 border-b"><h4 className="font-bold">รายการบูรณาการ</h4><button onClick={handleAddIntegration} className="bg-emerald-600 text-white px-3 py-1 rounded text-sm"><Plus size={16}/> เพิ่ม</button></div><Table headers={['ลำดับ','ชื่อ','จัดการ']} data={dropdowns.integration.map((i,x)=>({columns:[x+1,i], onEdit:()=>handleEditIntegration(i), onDelete:()=>handleDeleteIntegration(i)}))} hasActions /></div>;
             case 'activity': return <div className="space-y-4"><div className="flex justify-between pb-2 border-b"><h4 className="font-bold">รายการกิจกรรม</h4><button onClick={handleAddActivity} className="bg-emerald-600 text-white px-3 py-1 rounded text-sm"><Plus size={16}/> เพิ่ม</button></div><Table headers={['ลำดับ','ชื่อ','จัดการ']} data={dropdowns.activity.map((i,x)=>({columns:[x+1,i], onEdit:()=>handleEditActivity(i), onDelete:()=>handleDeleteActivity(i)}))} hasActions /></div>;
             case 'unit': return <div className="space-y-4"><div className="flex justify-between pb-2 border-b"><h4 className="font-bold">รายการหน่วยนับ</h4><button onClick={handleAddUnit} className="bg-emerald-600 text-white px-3 py-1 rounded text-sm"><Plus size={16}/> เพิ่ม</button></div><Table headers={['ลำดับ','ชื่อ','จัดการ']} data={dropdowns.unit.map((i,x)=>({columns:[x+1,i], onEdit:()=>handleEditUnit(i), onDelete:()=>handleDeleteUnit(i)}))} hasActions /></div>;

            default: return null;
        }
    };

    if (availableTabs.length === 0) {
        return (
            <div className="flex items-center justify-center min-h-[60vh] p-6 bg-slate-50 dark:bg-slate-900">
                <div className="bg-white dark:bg-slate-800 p-10 rounded-2xl shadow-sm border border-blue-200 dark:border-blue-900/50 max-w-2xl w-full text-center">
                    <div className="w-20 h-20 bg-red-50 dark:bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Lock size={36} />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-2">เข้าถึงไม่ได้</h2>
                    <p className="text-slate-500 dark:text-slate-400 mb-8">คุณไม่มีสิทธิ์ในการเข้าถึงหน้านี้ กรุณาติดต่อผู้ดูแลระบบเพื่อขอสิทธิ์การใช้งาน</p>
                    <button 
                        onClick={() => window.history.back()} 
                        className="px-6 py-2.5 bg-slate-100 dark:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600 font-bold transition-colors"
                    >
                        ย้อนกลับ
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">จัดการข้อมูลตัวเลือก</h2>
                    <p className="text-slate-500 dark:text-slate-400 transition-colors">จัดการข้อมูลพื้นฐานเพื่อนำไปใช้ในหน้าแบบฟอร์มบันทึกข้อมูล</p>
                </div>
                <button 
                    onClick={handleRefresh}
                    disabled={isLoading}
                    className={`flex items-center gap-2 px-5 py-2.5 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 border border-emerald-100 dark:border-emerald-800 rounded-xl hover:bg-emerald-100 transition-all font-bold text-base shadow-sm disabled:opacity-70`}
                >
                    <RefreshCw size={18} className={isLoading ? 'animate-spin' : ''} /> 
                    {isLoading ? 'กำลังซิงค์...' : 'ซิงค์ข้อมูลจาก Sheets'}
                </button>
            </div>

            <div className="flex flex-col lg:flex-row gap-6">
                <div className="w-full lg:w-72 flex-shrink-0">
                    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-2 sticky top-24 max-h-[calc(100vh-120px)] overflow-y-auto">
                        {availableTabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl text-left transition-all duration-200 mb-1 last:mb-0 ${
                                    activeTab === tab.id 
                                    ? 'bg-emerald-600 text-white font-bold shadow-lg shadow-emerald-900/20' 
                                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700/50 hover:text-emerald-600 dark:hover:text-emerald-400'
                                }`}
                            >
                                {tab.icon}
                                <span>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 p-8 min-h-[600px]">
                    {renderContent()}
                </div>
            </div>
        </div>
    );
};

const Table = ({ headers, data, hasActions = false }: TableProps) => (
    <div className="overflow-hidden rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800">
        <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
                <thead>
                    <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                        {headers.map((h, i) => (
                            <th key={i} className={`px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest ${i === headers.length - 1 && hasActions ? 'text-right' : ''}`}>
                                {h}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                    {data.length > 0 ? data.map((row, i) => (
                        <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                            {row.columns.map((cell, j) => (
                                <td key={j} className="px-6 py-4 text-slate-700 dark:text-slate-200 text-sm font-medium">
                                    {cell}
                                </td>
                            ))}
                            {hasActions && (
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-1.5">
                                        <button onClick={row.onEdit} className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors" title="แก้ไข">
                                            <Edit2 size={16} />
                                        </button>
                                        <button onClick={row.onDelete} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg transition-colors" title="ลบ">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            )}
                        </tr>
                    )) : (
                        <tr>
                            <td colSpan={headers.length} className="px-6 py-12 text-center text-slate-400">
                                <FileSpreadsheet className="mx-auto mb-3 opacity-20" size={40} />
                                ไม่พบข้อมูล
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    </div>
);

export default ManageView;

payload.text:
นี่คือโค้ด Google Apps Script (GAS) ฉบับสมบูรณ์ที่ได้รับการปรับปรุงให้รองรับฟีเจอร์ทั้งหมด รวมถึงการแยกชีท "Hierarchy" ตามที่คุณต้องการ และรองรับการจัดการ Master Data ประเภทอื่นๆ ด้วยครับ

### คำแนะนำก่อนติดตั้ง
1.  ไปที่ [script.google.com](https://script.google.com/) สร้างโปรเจกต์ใหม่
2.  ลบโค้ดเดิมทั้งหมดในไฟล์ `Code.gs`
3.  วางโค้ดด้านล่างนี้ลงไป
4.  กด **Save**
5.  กด **Deploy** -> **New Deployment**
    *   Select type: **Web app**
    *   Description: (ตั้งชื่อรุ่น)
    *   Execute as: **Me** (ตัวคุณเอง)
    *   Who has access: **Anyone** (ทุกคน) **สำคัญมาก**
6.  คัดลอก URL ที่ได้ ไปใส่ในหน้า `Settings` ของเว็บแอป

### โครงสร้าง Google Sheets ที่ระบบต้องการ
เพื่อให้โค้ดทำงานได้สมบูรณ์ ในไฟล์ Google Sheets ของคุณควรมีชีทดังนี้:
1.  **Database**: สำหรับเก็บข้อมูลบันทึกงบประมาณ (หัวข้อคอลัมน์แถวแรก: `ID`, `บูรณาการ`, `หน่วยงานหลัก`, `จังหวัด`, ...)
2.  **Hierarchy**: สำหรับเก็บโครงสร้าง (หัวข้อคอลัมน์แถวแรก: `MainAgency`, `Province`)
3.  **Data**: สำหรับเก็บข้อมูลตัวเลือกอื่นๆ และ Master Data (ดูรายละเอียดในโค้ด)
4.  **Config**: (สร้างให้อัตโนมัติถ้าไม่มี) สำหรับเก็บการตั้งค่าสิทธิ์และโครงสร้างรายงาน

