### โค้ด Google Apps Script (Code.gs)

```javascript
/**
 * DNP Budget Plan - Backend API
 * Version: 2.0 (Full Support)
 */

// --- Configuration ---
// ชื่อชีทเริ่มต้น (จะถูก override ถ้า frontend ส่งค่ามา)
var DEFAULT_DB_SHEET = 'Database';
var DEFAULT_DATA_SHEET = 'Data';
var DEFAULT_HIERARCHY_SHEET = 'Hierarchy';
var CONFIG_SHEET = 'Config'; // ใช้เก็บ Permissions และ Report Structure

// --- Entry Points ---

function doGet(e) {
  return handleResponse({ status: 'success', message: 'Service is running' });
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    // รอ Lock สูงสุด 10 วินาที เพื่อป้องกัน Race Condition การเขียนข้อมูลพร้อมกัน
    lock.waitLock(10000); 

    if (!e.postData || !e.postData.contents) {
      return handleResponse({ status: 'error', message: 'No data found' });
    }

    var payload = JSON.parse(e.postData.contents);
    var action = payload.action;
    var ss = openSpreadsheet(payload.sheetsId);

    if (!ss) {
      return handleResponse({ status: 'error', message: 'Spreadsheet not found or ID invalid' });
    }

    var result;
    switch (action) {
      case 'TEST_CONNECTION':
        result = { status: 'success', message: 'Connected' };
        break;
      case 'GET_DATA':
        result = getData(ss, payload);
        break;
      case 'MANAGE_RECORD':
        result = manageRecord(ss, payload);
        break;
      case 'MANAGE_MASTER':
        result = manageMaster(ss, payload);
        break;
      case 'SAVE_PERMISSIONS':
        result = saveConfig(ss, 'PERMISSIONS', payload.rolePermissions);
        break;
      case 'SAVE_REPORT_STRUCTURE':
        result = saveConfig(ss, 'REPORT_STRUCTURE', payload.structure);
        break;
      default:
        result = { status: 'error', message: 'Unknown action: ' + action };
    }

    return handleResponse(result);

  } catch (err) {
    return handleResponse({ status: 'error', message: err.toString(), stack: err.stack });
  } finally {
    lock.releaseLock();
  }
}

// --- Helper: Response Handling ---
function handleResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// --- Helper: Open Spreadsheet ---
function openSpreadsheet(id) {
  if (id) {
    try {
      return SpreadsheetApp.openById(id);
    } catch (e) {
      return null;
    }
  }
  return SpreadsheetApp.getActiveSpreadsheet();
}

// --- Action: Get Data ---
function getData(ss, payload) {
  var dbSheetName = payload.databaseSheetName || DEFAULT_DB_SHEET;
  var dataSheetName = payload.dataSheetName || DEFAULT_DATA_SHEET;
  var hierarchySheetName = payload.hierarchySheetName || DEFAULT_HIERARCHY_SHEET;

  var dbSheet = ss.getSheetByName(dbSheetName);
  var dataSheet = ss.getSheetByName(dataSheetName);
  var hierarchySheet = ss.getSheetByName(hierarchySheetName);
  var configSheet = ss.getSheetByName(CONFIG_SHEET);

  // 1. Get Records
  var records = dbSheet ? getSheetData(dbSheet) : [];

  // 2. Get Hierarchy (จากชีท Hierarchy ที่กำหนด)
  var hierarchy = [];
  if (hierarchySheet) {
    var lastRow = hierarchySheet.getLastRow();
    if (lastRow > 1) {
      // อ่านคอลัมน์ A (MainAgency) และ B (Province)
      var hValues = hierarchySheet.getRange(2, 1, lastRow - 1, 2).getValues();
      hierarchy = hValues.map(function(row) {
        return { mainAgency: row[0], province: row[1] };
      }).filter(function(item) { return item.mainAgency && item.province; });
    }
  }

  // 3. Get Master Data & Dropdowns (จากชีท Data)
  var dropdowns = { integration: [], unit: [], activity: [] };
  var respData = [];
  var compareData = [];

  if (dataSheet) {
    var dData = getSheetData(dataSheet); // อ่านทั้งชีทเป็น Object Array

    // Extract Distinct Lists & Master Tables
    dData.forEach(function(row) {
      // Integration List
      if (row['รายการบูรณาการ']) dropdowns.integration.push(row['รายการบูรณาการ']);
      // Unit List
      if (row['หน่วยนับ']) dropdowns.unit.push(row['หน่วยนับ']);

      // Responsible Agency Mapping (หน่วยงานหลัก -> หน่วยงานบูรณาการ -> พื้นที่)
      if (row['หน่วยงานหลัก'] && row['หน่วยงานบูรณาการ']) {
        respData.push({
          mainAgency: row['หน่วยงานหลัก'],
          responsibleAgency: row['หน่วยงานบูรณาการ'],
          integrationArea: row['พื้นที่บูรณาการ'] || ''
        });
      }

      // Compare Data (กิจกรรม -> งบอ้างอิง)
      if (row['กิจกรรม'] || row['ID']) { 
         // ใช้ Logic ตรวจสอบว่าเป็น row ของ Compare Data หรือไม่
         // สมมติว่าถ้ามีคอลัมน์ 'งบอ้างอิง' หรือเป็น row ที่ตั้งใจเก็บ Activity
         if (row['งบอ้างอิง'] !== undefined || (row['กิจกรรม'] && !row['หน่วยงานหลัก'])) {
             compareData.push({
               id: row['ID'] || row['กิจกรรม'],
               activity: row['กิจกรรม'],
               referenceBudget: row['งบอ้างอิง'] || 0
             });
         }
      }
    });

    // Clean up duplicates
    dropdowns.integration = unique(dropdowns.integration);
    dropdowns.unit = unique(dropdowns.unit);
  }

  // 4. Get Configs (Permissions & Report Structure)
  var rolePermissions = {};
  var reportStructure = [];

  if (configSheet) {
    var cData = configSheet.getDataRange().getValues();
    for (var i = 0; i < cData.length; i++) {
      var key = cData[i][0];
      var val = cData[i][1];
      if (key === 'PERMISSIONS' && val) {
        try { rolePermissions = JSON.parse(val); } catch(e) {}
      }
      if (key === 'REPORT_STRUCTURE' && val) {
        try { reportStructure = JSON.parse(val); } catch(e) {}
      }
    }
  }

  return {
    status: 'success',
    data: {
      records: records,
      hierarchy: hierarchy,
      dropdowns: dropdowns,
      respData: respData,
      compareData: compareData,
      rolePermissions: rolePermissions,
      reportStructure: reportStructure
    }
  };
}

// --- Action: Manage Record (Database) ---
function manageRecord(ss, payload) {
  var sheetName = payload.databaseSheetName || DEFAULT_DB_SHEET;
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    // สร้าง Header ถ้าเพิ่งสร้างชีทใหม่
    sheet.appendRow(['ID', 'บูรณาการ', 'หน่วยงานหลัก', 'จังหวัด', 'หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'กิจกรรม', 'เป้าหมาย', 'หน่วยนับ', 'เงินเดือนและค่าจ้างประจำ', 'ค่าตอบแทนพนักงานราชการ', 'ค่าตอบแทน ใช้สอย และวัสดุ', 'ค่าจ้างเหมาพนักงาน', 'ค่าสาธารณูปโภค', 'ค่าครุภัณฑ์', 'ค่าที่ดินและสิ่งก่อสร้าง', 'งบเงินอุดหนุน', 'งบรายจ่ายอื่น', 'วันที่บันทึก']);
  }

  var type = payload.type; // add, update, delete
  var data = payload.data; // object data
  var id = payload.id;

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  var idColIndex = headers.indexOf('ID');

  if (idColIndex === -1) return { status: 'error', message: 'ID column not found in ' + sheetName };

  if (type === 'add') {
    var row = mapObjectToRow(headers, data);
    sheet.appendRow(row);
    return { status: 'success' };
  } 
  else if (type === 'update' || type === 'delete') {
    var ids = sheet.getRange(2, idColIndex + 1, sheet.getLastRow() - 1, 1).getValues().flat();
    // แปลงเป็น String เพื่อการค้นหาที่แม่นยำ
    var rowIndex = ids.map(String).indexOf(String(id));

    if (rowIndex !== -1) {
      var actualRow = rowIndex + 2; // +2 เพราะ header=1 และ index เริ่ม 0
      if (type === 'delete') {
        sheet.deleteRow(actualRow);
      } else {
        var row = mapObjectToRow(headers, data);
        sheet.getRange(actualRow, 1, 1, row.length).setValues([row]);
      }
      return { status: 'success' };
    } else {
      return { status: 'error', message: 'Record ID not found: ' + id };
    }
  }
}

// --- Action: Manage Master Data ---
function manageMaster(ss, payload) {
  var target = payload.target; // Hierarchy, ResponsibleAgency, Compare, Unit, Integration
  var type = payload.type;     // add, update, delete
  var data = payload.data;

  // 1. Handle Hierarchy (Specific Sheet)
  if (target === 'Hierarchy') {
    var hSheetName = payload.hierarchySheetName || DEFAULT_HIERARCHY_SHEET;
    var hSheet = ss.getSheetByName(hSheetName);
    if (!hSheet) {
      hSheet = ss.insertSheet(hSheetName);
      hSheet.appendRow(['MainAgency', 'Province']);
    }

    if (type === 'add') {
      hSheet.appendRow([data.mainAgency, data.province]);
      return { status: 'success' };
    } else {
      // Find row based on Old Values (or Current values if no old provided)
      var range = hSheet.getDataRange();
      var values = range.getValues();
      var checkMain = data.oldMainAgency || data.mainAgency;
      var checkProv = data.oldProvince || data.province;

      for (var i = 1; i < values.length; i++) {
        if (values[i][0] == checkMain && values[i][1] == checkProv) {
          if (type === 'delete') {
            hSheet.deleteRow(i + 1);
          } else {
            hSheet.getRange(i + 1, 1, 1, 2).setValues([[data.mainAgency, data.province]]);
          }
          return { status: 'success' };
        }
      }
      return { status: 'error', message: 'Hierarchy Item not found' };
    }
  }

  // 2. Handle Data Sheet items (ResponsibleAgency, Compare, Unit, Integration)
  var dSheetName = payload.dataSheetName || DEFAULT_DATA_SHEET;
  var dSheet = ss.getSheetByName(dSheetName);
  if (!dSheet) {
    dSheet = ss.insertSheet(dSheetName);
    // Create default headers if new
    dSheet.appendRow(['รายการบูรณาการ', 'หน่วยงานหลัก', 'หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'กิจกรรม', 'งบอ้างอิง', 'หน่วยนับ']);
  }

  var headers = dSheet.getRange(1, 1, 1, dSheet.getLastColumn()).getValues()[0];

  // Helper to append/update/delete in Data Sheet
  // Strategy: 
  // - Add: Just append row with mapped headers.
  // - Update/Delete: Search based on key columns.

  if (type === 'add') {
    var row = mapObjectToRow(headers, data);
    dSheet.appendRow(row);
    return { status: 'success' };
  } else {
    // Find Row
    var dataRange = dSheet.getDataRange();
    var values = dataRange.getValues();
    var foundIndex = -1;

    // Define search keys based on Target
    var searchCriteria = {};
    if (target === 'ResponsibleAgency') {
      searchCriteria['หน่วยงานหลัก'] = data.oldMainAgency || data.mainAgency;
      searchCriteria['หน่วยงานบูรณาการ'] = data.oldResponsibleAgency || data.responsibleAgency;
      searchCriteria['พื้นที่บูรณาการ'] = data.oldIntegrationArea || data.integrationArea;
    } else if (target === 'Compare') {
      searchCriteria['กิจกรรม'] = data.oldActivity || data.activity;
    } else if (target === 'Unit') {
      searchCriteria['หน่วยนับ'] = data.oldName || data.name;
    } else if (target === 'Integration') {
      searchCriteria['รายการบูรณาการ'] = data.oldName || data.name;
    }

    // Search loop
    for (var i = 1; i < values.length; i++) {
      var match = true;
      for (var key in searchCriteria) {
        var colIdx = headers.indexOf(key);
        if (colIdx === -1 || String(values[i][colIdx]) !== String(searchCriteria[key])) {
          match = false;
          break;
        }
      }
      if (match) {
        foundIndex = i;
        break;
      }
    }

    if (foundIndex !== -1) {
      if (type === 'delete') {
        dSheet.deleteRow(foundIndex + 1);
      } else {
        // Update: We need to preserve other columns in this row that are NOT part of this update?
        // Actually, simpler to just map the new data to the headers and update only those cells?
        // Or simpler: Get the full row, update specific keys, write back.
        var currentRow = values[foundIndex];
        // Create an object from current row
        var rowObj = {};
        headers.forEach(function(h, idx) { rowObj[h] = currentRow[idx]; });

        // Merge with new data (data object has keys matching headers like 'กิจกรรม', 'งบอ้างอิง')
        for (var k in data) {
          if (headers.indexOf(k) !== -1) {
            rowObj[k] = data[k];
          }
        }

        var newRow = mapObjectToRow(headers, rowObj);
        dSheet.getRange(foundIndex + 1, 1, 1, newRow.length).setValues([newRow]);
      }
      return { status: 'success' };
    } else {
      return { status: 'error', message: 'Item not found in Data sheet' };
    }
  }
}

// --- Action: Save Config (Permissions / Report Structure) ---
function saveConfig(ss, key, jsonData) {
  var sheet = ss.getSheetByName(CONFIG_SHEET);
  if (!sheet) {
    sheet = ss.insertSheet(CONFIG_SHEET);
    sheet.appendRow(['Key', 'Value']);
  }

  var data = sheet.getDataRange().getValues();
  var found = false;
  var jsonString = JSON.stringify(jsonData);

  // Check if exceeds cell limit (50,000 chars). Usually fine for this app.

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === key) {
      sheet.getRange(i + 1, 2).setValue(jsonString);
      found = true;
      break;
    }
  }

  if (!found) {
    sheet.appendRow([key, jsonString]);
  }

  return { status: 'success' };
}

// --- Utilities ---

// Map object keys to spreadsheet row array based on headers
function mapObjectToRow(headers, dataObj) {
  return headers.map(function(header) {
    // Handle specific mappings if header names differ slightly or match directly
    // Also handle alias logic if needed, but Frontend usually sends correct Keys now.
    return dataObj[header] !== undefined ? dataObj[header] : '';
  });
}

function getSheetData(sheet) {
  var data = sheet.getDataRange().getValues();
  if (data.length < 2) return []; // No data

  var headers = data[0];
  var result = [];

  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
    }
    result.push(obj);
  }
  return result;
}

function unique(arr) {
  var seen = {};
  return arr.filter(function(item) {
    return item && seen.hasOwnProperty(item) ? false : (seen[item] = true);
  });
}

