payload.text:
นี่คือโค้ด Google Apps Script (Code.gs) ฉบับสมบูรณ์ที่ได้รับการปรับปรุงให้รองรับการแยกชีททั้ง 4 ประเภท (ResponsibleAgency, Integration, Compare, Unit) ตามที่คุณระบุ พร้อมระบบจัดการ Lock เพื่อป้องกันข้อมูลชนกันครับ

### วิธีการติดตั้ง
1.  ไปที่ [script.google.com](https://script.google.com/)
2.  เปิดโปรเจกต์เดิม หรือสร้างใหม่
3.  ลบโค้ดเก่าทั้งหมดในไฟล์ `Code.gs`
4.  วางโค้ดชุดใหม่นี้ลงไป
5.  กด **Save**
6.  กด **Deploy** -> **New Deployment** (เลือก Web app, Execute as Me, Access Anyone)
7.  **สำคัญ:** เนื่องจากมีการเปลี่ยน Logic การเข้าถึงชีท คุณอาจต้องกด Authorize (ให้สิทธิ์) ใหม่อีกครั้งตอน Deploy หรือตอนรันครั้งแรก

### โครงสร้างชีทที่ระบบจะสร้าง/เรียกใช้ (อัตโนมัติ)
1.  **Database**: เก็บข้อมูลงบประมาณ
2.  **Hierarchy**: คอลัมน์ A (MainAgency), B (Province)
3.  **ResponsibleAgency**: คอลัมน์ A (MainAgency), B (ResponsibleAgency), C (IntegrationArea)
4.  **Integration**: คอลัมน์ A (Name)
5.  **Compare**: คอลัมน์ A (Activity), B (Budget)
6.  **Unit**: คอลัมน์ A (Name)
7.  **Config**: เก็บค่า Settings และ Permissions

```javascript
/**
 * DNP Budget Plan - Backend API
 * Version: 3.0 (Multi-Sheet Master Data Support)
 */

// --- Configuration ---
// ชื่อชีทเริ่มต้น (จะถูก override ถ้า frontend ส่งค่ามา)
var DEFAULT_DB_SHEET = 'Database';
var DEFAULT_HIERARCHY_SHEET = 'Hierarchy';
var DEFAULT_RESP_SHEET = 'ResponsibleAgency';
var DEFAULT_INT_SHEET = 'Integration';
var DEFAULT_COMPARE_SHEET = 'Compare';
var DEFAULT_UNIT_SHEET = 'Unit';
var CONFIG_SHEET = 'Config';

// --- Entry Points ---

function doGet(e) {
  return handleResponse({ status: 'success', message: 'Service is running' });
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(30000); // รอ Lock สูงสุด 30 วินาที

    if (!e.postData || !e.postData.contents) {
      return handleResponse({ status: 'error', message: 'No data found' });
    }

    var payload = JSON.parse(e.postData.contents);
    var action = payload.action;
    var ss = openSpreadsheet(payload.sheetsId);

    if (!ss) {
      return handleResponse({ status: 'error', message: 'Spreadsheet not found or ID invalid' });
    }

    var result;
    switch (action) {
      case 'TEST_CONNECTION':
        result = { status: 'success', message: 'Connected' };
        break;
      case 'GET_DATA':
        result = getData(ss, payload);
        break;
      case 'MANAGE_RECORD':
        result = manageRecord(ss, payload);
        break;
      case 'MANAGE_MASTER':
        result = manageMaster(ss, payload);
        break;
      case 'SAVE_PERMISSIONS':
        result = saveConfig(ss, 'PERMISSIONS', payload.rolePermissions);
        break;
      case 'SAVE_REPORT_STRUCTURE':
        result = saveConfig(ss, 'REPORT_STRUCTURE', payload.structure);
        break;
      default:
        result = { status: 'error', message: 'Unknown action: ' + action };
    }

    return handleResponse(result);

  } catch (err) {
    return handleResponse({ status: 'error', message: err.toString(), stack: err.stack });
  } finally {
    lock.releaseLock();
  }
}

// --- Helper: Response Handling ---
function handleResponse(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// --- Helper: Open Spreadsheet ---
function openSpreadsheet(id) {
  if (id) {
    try {
      return SpreadsheetApp.openById(id);
    } catch (e) {
      return null;
    }
  }
  return SpreadsheetApp.getActiveSpreadsheet();
}

// --- Action: Get Data ---
function getData(ss, payload) {
  // รับชื่อชีทจาก Payload หรือใช้ Default
  var dbSheetName = payload.databaseSheetName || DEFAULT_DB_SHEET;
  var hierarchySheetName = payload.hierarchySheetName || DEFAULT_HIERARCHY_SHEET;
  var respSheetName = payload.responsibleAgencySheetName || DEFAULT_RESP_SHEET;
  var intSheetName = payload.integrationSheetName || DEFAULT_INT_SHEET;
  var compareSheetName = payload.compareSheetName || DEFAULT_COMPARE_SHEET;
  var unitSheetName = payload.unitSheetName || DEFAULT_UNIT_SHEET;

  // 1. Get Records (Database)
  var dbSheet = ss.getSheetByName(dbSheetName);
  var records = dbSheet ? getSheetData(dbSheet) : [];

  // 2. Get Hierarchy (Col A, B)
  var hierarchy = getSimpleSheetData(ss, hierarchySheetName, 2, ['mainAgency', 'province']);

  // 3. Get Responsible Agency (Col A, B, C)
  var respData = getSimpleSheetData(ss, respSheetName, 3, ['mainAgency', 'responsibleAgency', 'integrationArea']);

  // 4. Get Integration List (Col A)
  var rawInt = getSimpleSheetData(ss, intSheetName, 1, ['name']);
  var integrationList = rawInt.map(function(item) { return item.name; });

  // 5. Get Unit List (Col A)
  var rawUnit = getSimpleSheetData(ss, unitSheetName, 1, ['name']);
  var unitList = rawUnit.map(function(item) { return item.name; });

  // 6. Get Compare Data (Col A=Activity, B=Budget)
  var compareData = getSimpleSheetData(ss, compareSheetName, 2, ['activity', 'referenceBudget']);
  // Map fields to match frontend expectation
  compareData = compareData.map(function(item) {
    return {
      id: item.activity,
      activity: item.activity,
      referenceBudget: item.referenceBudget || 0
    };
  });

  // 7. Get Configs
  var configSheet = ss.getSheetByName(CONFIG_SHEET);
  var rolePermissions = {};
  var reportStructure = [];

  if (configSheet) {
    var cData = configSheet.getDataRange().getValues();
    for (var i = 0; i < cData.length; i++) {
      var key = cData[i][0];
      var val = cData[i][1];
      if (key === 'PERMISSIONS' && val) {
        try { rolePermissions = JSON.parse(val); } catch(e) {}
      }
      if (key === 'REPORT_STRUCTURE' && val) {
        try { reportStructure = JSON.parse(val); } catch(e) {}
      }
    }
  }

  return {
    status: 'success',
    data: {
      records: records,
      hierarchy: hierarchy,
      respData: respData,
      compareData: compareData,
      dropdowns: {
        integration: integrationList,
        unit: unitList,
        // Activity list derives from Compare Data for consistency
        activity: compareData.map(function(c) { return c.activity; })
      },
      rolePermissions: rolePermissions,
      reportStructure: reportStructure
    }
  };
}

// --- Action: Manage Record (Database) ---
function manageRecord(ss, payload) {
  var sheetName = payload.databaseSheetName || DEFAULT_DB_SHEET;
  var sheet = ss.getSheetByName(sheetName);

  // Create DB sheet if missing
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(['ID', 'บูรณาการ', 'หน่วยงานหลัก', 'จังหวัด', 'หน่วยงานบูรณาการ', 'พื้นที่บูรณาการ', 'กิจกรรม', 'เป้าหมาย', 'หน่วยนับ', 'เงินเดือนและค่าจ้างประจำ', 'ค่าตอบแทนพนักงานราชการ', 'ค่าตอบแทน ใช้สอย และวัสดุ', 'ค่าจ้างเหมาพนักงาน', 'ค่าสาธารณูปโภค', 'ค่าครุภัณฑ์', 'ค่าที่ดินและสิ่งก่อสร้าง', 'งบเงินอุดหนุน', 'งบรายจ่ายอื่น', 'วันที่บันทึก']);
  }

  var type = payload.type; 
  var data = payload.data;
  var id = payload.id;

  var headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  var idColIndex = headers.indexOf('ID');

  if (idColIndex === -1) return { status: 'error', message: 'ID column not found in ' + sheetName };

  if (type === 'add') {
    var row = mapObjectToRow(headers, data);
    sheet.appendRow(row);
    return { status: 'success' };
  } 
  else if (type === 'update' || type === 'delete') {
    var lastRow = sheet.getLastRow();
    if (lastRow < 2) return { status: 'error', message: 'No data to update' };

    var ids = sheet.getRange(2, idColIndex + 1, lastRow - 1, 1).getValues().flat();
    var rowIndex = ids.map(String).indexOf(String(id));

    if (rowIndex !== -1) {
      var actualRow = rowIndex + 2; 
      if (type === 'delete') {
        sheet.deleteRow(actualRow);
      } else {
        var row = mapObjectToRow(headers, data);
        sheet.getRange(actualRow, 1, 1, row.length).setValues([row]);
      }
      return { status: 'success' };
    } else {
      return { status: 'error', message: 'Record ID not found: ' + id };
    }
  }
}

// --- Action: Manage Master Data (Separate Sheets) ---
function manageMaster(ss, payload) {
  var target = payload.target; 
  var type = payload.type;     
  var data = payload.data;

  var sheetName = '';
  var columns = 0;
  var headers = [];

  // Determine Sheet and Configuration based on Target
  if (target === 'Hierarchy') {
    sheetName = payload.hierarchySheetName || DEFAULT_HIERARCHY_SHEET;
    columns = 2; // MainAgency, Province
    headers = ['MainAgency', 'Province'];
  } else if (target === 'ResponsibleAgency') {
    sheetName = payload.responsibleAgencySheetName || DEFAULT_RESP_SHEET;
    columns = 3; // Main, Resp, Area
    headers = ['MainAgency', 'ResponsibleAgency', 'IntegrationArea'];
  } else if (target === 'Integration') {
    sheetName = payload.integrationSheetName || DEFAULT_INT_SHEET;
    columns = 1; // Name
    headers = ['IntegrationName'];
  } else if (target === 'Unit') {
    sheetName = payload.unitSheetName || DEFAULT_UNIT_SHEET;
    columns = 1; // Name
    headers = ['UnitName'];
  } else if (target === 'Compare') { // Activity List & Budget
    sheetName = payload.compareSheetName || DEFAULT_COMPARE_SHEET;
    columns = 2; // Activity, Budget
    headers = ['Activity', 'ReferenceBudget'];
  } else {
    return { status: 'error', message: 'Unknown target: ' + target };
  }

  // Get or Create Sheet
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    sheet.appendRow(headers);
  }

  // 1. ADD
  if (type === 'add') {
    var rowData = [];
    if (target === 'Hierarchy') rowData = [data.mainAgency, data.province];
    else if (target === 'ResponsibleAgency') rowData = [data.mainAgency, data.responsibleAgency, data.integrationArea];
    else if (target === 'Integration' || target === 'Unit') rowData = [data.name];
    else if (target === 'Compare') rowData = [data.activity, data.referenceBudget];

    sheet.appendRow(rowData);
    return { status: 'success' };
  } 

  // 2. UPDATE / DELETE
  else {
    var range = sheet.getDataRange();
    var values = range.getValues();
    var foundIndex = -1;

    // Search Logic
    for (var i = 1; i < values.length; i++) {
      var row = values[i];
      var match = false;

      if (target === 'Hierarchy') {
        // Match Main AND Province
        var tMain = data.oldMainAgency || data.mainAgency;
        var tProv = data.oldProvince || data.province;
        if (row[0] == tMain && row[1] == tProv) match = true;
      } 
      else if (target === 'ResponsibleAgency') {
        // Match Main AND Resp AND Area
        var tMain = data.oldMainAgency || data.mainAgency;
        var tResp = data.oldResponsibleAgency || data.responsibleAgency;
        var tArea = data.oldIntegrationArea || data.integrationArea;
        if (row[0] == tMain && row[1] == tResp && row[2] == tArea) match = true;
      }
      else if (target === 'Integration' || target === 'Unit') {
        // Match Name (Col A)
        var tName = data.oldName || data.name;
        if (row[0] == tName) match = true;
      }
      else if (target === 'Compare') {
        // Match Activity (Col A)
        var tAct = data.oldActivity || data.activity;
        if (row[0] == tAct) match = true;
      }

      if (match) {
        foundIndex = i;
        break;
      }
    }

    if (foundIndex !== -1) {
      if (type === 'delete') {
        sheet.deleteRow(foundIndex + 1);
      } else {
        // Prepare Update Data
        var updateRow = [];
        if (target === 'Hierarchy') updateRow = [data.mainAgency, data.province];
        else if (target === 'ResponsibleAgency') updateRow = [data.mainAgency, data.responsibleAgency, data.integrationArea];
        else if (target === 'Integration' || target === 'Unit') updateRow = [data.name];
        else if (target === 'Compare') updateRow = [data.activity, data.referenceBudget];

        // Update specific range
        sheet.getRange(foundIndex + 1, 1, 1, updateRow.length).setValues([updateRow]);
      }
      return { status: 'success' };
    } else {
      return { status: 'error', message: 'Item not found in ' + sheetName };
    }
  }
}

// --- Action: Save Config ---
function saveConfig(ss, key, jsonData) {
  var sheet = ss.getSheetByName(CONFIG_SHEET);
  if (!sheet) {
    sheet = ss.insertSheet(CONFIG_SHEET);
    sheet.appendRow(['Key', 'Value']);
  }

  var data = sheet.getDataRange().getValues();
  var found = false;
  var jsonString = JSON.stringify(jsonData);

  for (var i = 1; i < data.length; i++) {
    if (data[i][0] === key) {
      sheet.getRange(i + 1, 2).setValue(jsonString);
      found = true;
      break;
    }
  }

  if (!found) {
    sheet.appendRow([key, jsonString]);
  }

  return { status: 'success' };
}

// --- Utilities ---

// อ่านข้อมูลจากชีทแบบระบุจำนวนคอลัมน์และ Key ที่ต้องการ map
function getSimpleSheetData(ss, sheetName, colCount, keys) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];

  var lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];

  // อ่านข้อมูลเริ่มจากแถว 2 (ข้าม Header)
  var values = sheet.getRange(2, 1, lastRow - 1, colCount).getValues();

  return values.map(function(row) {
    var obj = {};
    for (var i = 0; i < keys.length; i++) {
      obj[keys[i]] = row[i];
    }
    return obj;
  }).filter(function(obj) {
    // กรองแถวว่าง (เช็คแค่คอลัมน์แรก)
    return obj[keys[0]] && String(obj[keys[0]]).trim() !== '';
  });
}

function mapObjectToRow(headers, dataObj) {
  return headers.map(function(header) {
    return dataObj[header] !== undefined ? dataObj[header] : '';
  });
}

function getSheetData(sheet) {
  var data = sheet.getDataRange().getValues();
  if (data.length < 2) return [];

  var headers = data[0];
  var result = [];

  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
    }
    result.push(obj);
  }
  return result;
}

