const getIconForMenu = (id: string) => {
    switch (id) {
        case 'hierarchy': return Network;
        case 'responsible': return Building2;
        case 'integration': return Layers;
        case 'activity': return List;
        case 'unit': return Hash;
        case 'report': return FileText;
        case 'fields': return Layout;
        case 'tableColumns': return TableIcon;
        default: return Settings;
    }
};

