                                        dataService.toggleTableColumnVisibility(key);
                                        triggerRefresh();
                                    }}
                                    className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-all ${
                                        visible 
                                        ? 'bg-white dark:bg-slate-800 border-blue-200 dark:border-blue-900/50 shadow-sm' 
                                        : 'bg-slate-50 dark:bg-slate-900 border-slate-200 dark:border-slate-700 opacity-70'
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-lg ${visible ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'bg-slate-200 dark:bg-slate-800 text-slate-400'}`}>
                                            <TableIcon size={18} />
                                        </div>
                                        <div>
                                            <div className="font-bold text-slate-700 dark:text-slate-200">{FIELD_LABELS[key] || key}</div>
                                            <div className="text-xs text-slate-400">{key}</div>
                                        </div>
                                    </div>
                                    <div className={`w-3 h-3 rounded-full ${visible ? 'bg-blue-500' : 'bg-slate-300'}`}></div>
                                </div>
                            ))}
                        </div>
                    </div>
                );

            default:
                return <div className="p-8 text-center text-slate-400">เลือกเมนูเพื่อจัดการข้อมูล</div>;
        }
    };

    return (
        <div className="flex flex-col lg:flex-row h-[calc(100vh-80px)] overflow-hidden bg-white dark:bg-slate-900">
            {/* Sidebar Navigation */}
            <div className="w-full lg:w-72 bg-slate-50 dark:bg-slate-950 border-r border-slate-100 dark:border-slate-800 overflow-y-auto">
                <div className="p-4 border-b border-slate-100 dark:border-slate-800">
                    <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center gap-2">
                        <Settings size={24} className="text-emerald-600" />
                        จัดการข้อมูล
                    </h2>
                    <p className="text-xs text-slate-500 mt-1">ตั้งค่าตัวเลือกและโครงสร้างระบบ</p>
                </div>
                <div className="p-3 space-y-1">
                    {MANAGE_SUB_MENUS.map(menu => (
                        <button
                            key={menu.id}
                            onClick={() => {
                                setActiveTab(menu.id);
                                setSelectedMainAgency(''); // Reset selection on tab change
                                setSelectedRespAgency('');
                            }}
                            className={`w-full text-left px-4 py-3 rounded-xl text-sm font-semibold transition-all flex items-center justify-between group ${
                                activeTab === menu.id
                                    ? 'bg-white dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 shadow-sm border border-slate-100 dark:border-slate-700'
                                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900'
                            }`}
                        >
                            <span>{menu.label}</span>
                            {activeTab === menu.id && <ChevronRight size={16} className="text-emerald-500" />}
                        </button>
                    ))}
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto bg-white dark:bg-slate-900 p-4 lg:p-8">
                <div className="max-w-5xl mx-auto">
                    <div className="mb-6 pb-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                        <h3 className="text-2xl font-bold text-slate-800 dark:text-white">
                            {MANAGE_SUB_MENUS.find(m => m.id === activeTab)?.label}
                        </h3>
                        {activeTab !== 'report' && (
                            <button 
                                onClick={triggerRefresh} 
                                className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg transition-colors"
                                title="รีเฟรชข้อมูล"
                            >
                                <RotateCcw size={20} />
                            </button>
                        )}
                    </div>
                    {renderContent()}
                </div>
            </div>
        </div>
    );
};

export default ManageView;

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { dataService, MANAGE_SUB_MENUS, FIELD_LABELS } from '../../services/dataService';
import Swal from 'sweetalert2';
import { 
    Plus, Edit2, Trash2, ChevronRight, Network, 
    Layers, List, FileText, Settings, Database, FileBarChart, CheckSquare, Square
} from 'lucide-react';

// Icons mapping
const ICONS: Record<string, React.ReactNode> = {
    hierarchy: <Network size={20} />,
    responsible: <Layers size={20} />,
    integration: <List size={20} />,
    activity: <FileText size={20} />,
    unit: <Database size={20} />,
    report: <FileBarChart size={20} />,
    fields: <CheckSquare size={20} />,
    tableColumns: <Settings size={20} />
};

const ManageView: React.FC = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Determine active tab
    const getActiveTab = () => {
        // Handle /manage/hierarchy -> hierarchy
        const path = location.pathname;
        const found = MANAGE_SUB_MENUS.find(m => m.path === path);
        if (found) return found.id;
        // Default to first item if just /manage
        return MANAGE_SUB_MENUS[0].id;
    };

    const [activeTab, setActiveTab] = useState(getActiveTab());

    useEffect(() => {
        setActiveTab(getActiveTab());
    }, [location]);

    // Data States
    const [hierarchy, setHierarchy] = useState(dataService.getHierarchy());
    const [dropdowns, setDropdowns] = useState(dataService.getDropdowns());
    const [fieldVisibility, setFieldVisibility] = useState(dataService.getFieldVisibility());
    const [tableColumnVisibility, setTableColumnVisibility] = useState(dataService.getTableColumnVisibility());
    const [refreshTrigger, setRefreshTrigger] = useState(0);

    // UI State for Hierarchy
    const [selectedMainAgency, setSelectedMainAgency] = useState('');

    useEffect(() => {
        setHierarchy(dataService.getHierarchy());
        setDropdowns(dataService.getDropdowns());
        setFieldVisibility(dataService.getFieldVisibility());
        setTableColumnVisibility(dataService.getTableColumnVisibility());
    }, [refreshTrigger]);

    const triggerRefresh = () => setRefreshTrigger(prev => prev + 1);

    const handleTabChange = (path: string) => {
        navigate(path);
    };

    // --- Handlers: Hierarchy ---
    const handleAddHierarchy = async (defaultMain: string) => {
        const { value: formValues } = await Swal.fire({
            title: 'เพิ่มโครงสร้างหน่วยงาน',
            html:
                `<input id="swal-main" class="swal2-input" placeholder="หน่วยงานหลัก" value="${defaultMain || ''}">` +
                '<input id="swal-prov" class="swal2-input" placeholder="จังหวัด">',
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            preConfirm: () => {
                return [
                    (document.getElementById('swal-main') as HTMLInputElement).value,
                    (document.getElementById('swal-prov') as HTMLInputElement).value
                ];
            }
        });

        if (formValues) {
            const [main, prov] = formValues;
            if(!main || !prov) return;
            Swal.showLoading();
            const res = await dataService.addHierarchyItem(main, prov);
            if(res.success) {
                triggerRefresh();
                Swal.fire('สำเร็จ', 'เพิ่มข้อมูลเรียบร้อย', 'success');
            } else {
                Swal.fire('ผิดพลาด', res.message, 'error');
            }
        }
    };

    const handleEditHierarchy = async (oldMain: string, oldProv: string) => {
        const { value: formValues } = await Swal.fire({
            title: 'แก้ไขโครงสร้างหน่วยงาน',
            html:
                `<input id="swal-main" class="swal2-input" placeholder="หน่วยงานหลัก" value="${oldMain}">` +
                `<input id="swal-prov" class="swal2-input" placeholder="จังหวัด" value="${oldProv}">`,
            focusConfirm: false,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            preConfirm: () => {
                return [
                    (document.getElementById('swal-main') as HTMLInputElement).value,
                    (document.getElementById('swal-prov') as HTMLInputElement).value
                ];
            }
        });

        if (formValues) {
            const [newMain, newProv] = formValues;
            if(!newMain || !newProv) return;
            Swal.showLoading();
            const res = await dataService.updateHierarchyItem(oldMain, oldProv, newMain, newProv);
            if(res.success) {
                triggerRefresh();
                Swal.fire('สำเร็จ', 'แก้ไขข้อมูลเรียบร้อย', 'success');
            } else {
                Swal.fire('ผิดพลาด', res.message, 'error');
            }
        }
    };

    const handleDeleteHierarchy = async (main: string, prov: string) => {
        const confirm = await Swal.fire({
            title: 'ยืนยันการลบ',
            text: `ต้องการลบ ${main} - ${prov} ใช่หรือไม่?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#d33',
            confirmButtonText: 'ลบ'
        });

        if (confirm.isConfirmed) {
            Swal.showLoading();
            const res = await dataService.deleteHierarchyItem(main, prov);
            if(res.success) {
                triggerRefresh();
                Swal.fire('สำเร็จ', 'ลบข้อมูลเรียบร้อย', 'success');
            } else {
                Swal.fire('ผิดพลาด', res.message, 'error');
            }
        }
    };

    // --- Generic Add/Edit/Delete Handlers for Single Field Items (Integration, Activity, Unit) ---
    const handleManageSingleField = async (
        type: 'integration' | 'activity' | 'unit', 
        action: 'add' | 'edit' | 'delete', 
        currentValue?: string
    ) => {
        const titleMap = { integration: 'รายการบูรณาการ', activity: 'กิจกรรม', unit: 'หน่วยนับ' };
        const label = titleMap[type];

        if (action === 'delete') {
             const confirm = await Swal.fire({
                title: 'ยืนยันการลบ',
                text: `ต้องการลบ ${label}: "${currentValue}" ใช่หรือไม่?`,
                icon: 'warning',
                showCancelButton: true,
                confirmButtonColor: '#d33',
                confirmButtonText: 'ลบ'
            });
            if (confirm.isConfirmed) {
                Swal.showLoading();
                let res;
                if(type === 'integration') res = await dataService.deleteIntegration(currentValue!);
                else if(type === 'activity') res = await dataService.deleteActivity(currentValue!);
                else res = await dataService.deleteUnit(currentValue!);

                if(res.success) { triggerRefresh(); Swal.fire('สำเร็จ', 'ลบข้อมูลเรียบร้อย', 'success'); }
                else Swal.fire('ผิดพลาด', res.message, 'error');
            }
            return;
        }

        const { value: newValue } = await Swal.fire({
            title: action === 'add' ? `เพิ่ม${label}` : `แก้ไข${label}`,
            input: 'text',
            inputValue: action === 'edit' ? currentValue : '',
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            inputValidator: (value) => {
                if (!value) return 'กรุณาระบุข้อมูล';
            }
        });

        if (newValue) {
            Swal.showLoading();
            let res;
            if (action === 'add') {
                if(type === 'integration') res = await dataService.addIntegration(newValue);
                else if(type === 'activity') res = await dataService.addActivity(newValue);
                else res = await dataService.addUnit(newValue);
            } else {
                if(type === 'integration') res = await dataService.updateIntegration(currentValue!, newValue);
                else if(type === 'activity') res = await dataService.updateActivity(currentValue!, newValue);
                else res = await dataService.updateUnit(currentValue!, newValue);
            }

            if(res.success) { triggerRefresh(); Swal.fire('สำเร็จ', 'บันทึกข้อมูลเรียบร้อย', 'success'); }
            else Swal.fire('ผิดพลาด', res.message, 'error');
        }
    };

    // --- Render Content Logic ---
    const renderContent = () => {
        switch (activeTab) {
            case 'hierarchy': {
                const uniqueMainAgencies = Array.from(new Set(hierarchy.map(h => h.mainAgency)));
                const filteredHierarchy = selectedMainAgency 
                    ? hierarchy.filter(h => h.mainAgency === selectedMainAgency)
                    : [];

                return (
                    <div className="space-y-6">
                        <div className="bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-700">
                             <div>
                                <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">
                                    <span className="w-6 h-6 inline-flex items-center justify-center bg-emerald-600 text-white rounded-full text-xs mr-2">1</span>
                                    เลือกหน่วยงานหลัก (Main Agency)
                                </label>

                                <div className="flex gap-3">
                                    <div className="relative flex-1">
                                        <select 
                                            value={selectedMainAgency} 
                                            onChange={(e) => setSelectedMainAgency(e.target.value)} 
                                            className="w-full px-4 py-3 border border-slate-200 dark:border-slate-600 rounded-xl outline-none bg-white dark:bg-slate-900 focus:ring-2 focus:ring-emerald-500 transition-all text-slate-800 dark:text-slate-200 appearance-none"
                                        >
                                            <option value="">-- กรุณาเลือกหน่วยงาน --</option>
                                            {uniqueMainAgencies.map(m => <option key={m} value={m}>{m}</option>)}
                                        </select>
                                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                                            <ChevronRight size={18} className="rotate-90" />
                                        </div>
                                    </div>

                                    <button 
                                        onClick={() => handleAddHierarchy('')} 
                                        className="bg-white dark:bg-slate-800 text-blue-600 dark:text-blue-400 border border-blue-200 dark:border-blue-800 px-4 py-3 rounded-xl flex items-center gap-2 shadow-sm hover:bg-blue-50 dark:hover:bg-blue-900/30 transition-colors text-sm font-bold whitespace-nowrap"
                                    >
                                        <Plus size={18} /> เพิ่มหน่วยงานใหม่
                                    </button>
                                </div>

                                <p className="text-xs text-slate-500 mt-2">เลือกหน่วยงานหลักเพื่อดูหรือจัดการรายชื่อจังหวัดในสังกัด</p>
                            </div>
                        </div>

                        {selectedMainAgency ? (
                            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex justify-between items-center">
                                    <h4 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                                        <span className="w-6 h-6 inline-flex items-center justify-center bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-full text-xs">2</span>
                                        จังหวัดในสังกัด ({filteredHierarchy.length})
                                    </h4>
                                    <button 
                                        onClick={() => handleAddHierarchy(selectedMainAgency)} 
                                        className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-colors text-sm font-medium"
                                    >
                                        <Plus size={16} /> เพิ่มจังหวัดในสังกัดนี้
                                    </button>
                                </div>
                                <Table 
                                    headers={['ลำดับ', 'จังหวัด', 'จัดการ']}
                                    data={filteredHierarchy.map((item, idx) => ({
                                        columns: [idx + 1, item.province],
                                        onEdit: () => handleEditHierarchy(item.mainAgency, item.province),
                                        onDelete: () => handleDeleteHierarchy(item.mainAgency, item.province)
                                    }))}
                                    hasActions
                                />
                            </div>
                        ) : (
                            <div className="text-center py-16 bg-white dark:bg-slate-800 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                                <Network size={48} className="mx-auto mb-3 text-slate-300 dark:text-slate-600 opacity-50"/>
                                <h3 className="text-lg font-semibold text-slate-600 dark:text-slate-300">ยังไม่ได้เลือกหน่วยงานหลัก</h3>
                                <p className="text-slate-500 dark:text-slate-400 mt-1">กรุณาเลือกหน่วยงานหลักจากตัวเลือกด้านบน (Step 1) เพื่อดำเนินการต่อ</p>
                            </div>
                        )}
                    </div>
                );
            }
            case 'responsible':
                return <div className="p-4 text-center text-slate-500">ส่วนจัดการหน่วยงานบูรณาการ (อยู่ในระหว่างการพัฒนาเพิ่มเติม)</div>;

            case 'integration':
                return (
                     <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white">รายการบูรณาการ</h3>
                            <button onClick={() => handleManageSingleField('integration', 'add')} className="bg-emerald-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium"><Plus size={16}/> เพิ่มรายการ</button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อรายการบูรณาการ', 'จัดการ']}
                            data={dropdowns.integration.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleManageSingleField('integration', 'edit', item),
                                onDelete: () => handleManageSingleField('integration', 'delete', item)
                            }))}
                            hasActions
                        />
                    </div>
                );

            case 'activity':
                return (
                     <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white">รายการกิจกรรม</h3>
                            <button onClick={() => handleManageSingleField('activity', 'add')} className="bg-emerald-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium"><Plus size={16}/> เพิ่มกิจกรรม</button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อกิจกรรม', 'จัดการ']}
                            data={dropdowns.activity.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleManageSingleField('activity', 'edit', item),
                                onDelete: () => handleManageSingleField('activity', 'delete', item)
                            }))}
                            hasActions
                        />
                    </div>
                );

            case 'unit':
                 return (
                     <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white">รายการหน่วยนับ</h3>
                            <button onClick={() => handleManageSingleField('unit', 'add')} className="bg-emerald-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium"><Plus size={16}/> เพิ่มหน่วยนับ</button>
                        </div>
                        <Table 
                            headers={['ลำดับ', 'ชื่อหน่วยนับ', 'จัดการ']}
                            data={dropdowns.unit.map((item, idx) => ({
                                columns: [idx + 1, item],
                                onEdit: () => handleManageSingleField('unit', 'edit', item),
                                onDelete: () => handleManageSingleField('unit', 'delete', item)
                            }))}
                            hasActions
                        />
                    </div>
                );

            case 'fields':
                return (
                    <div className="space-y-4">
                         <div className="flex justify-between items-center mb-4">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white">จัดการฟิลด์แบบฟอร์ม</h3>
                            <div className="flex gap-2">
                                <button onClick={() => { dataService.setAllFieldsVisibility(true); triggerRefresh(); }} className="text-sm px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg">แสดงทั้งหมด</button>
                                <button onClick={() => { dataService.setAllFieldsVisibility(false); triggerRefresh(); }} className="text-sm px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg">ซ่อนทั้งหมด</button>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {Object.entries(FIELD_LABELS).map(([key, label]) => {
                                if(fieldVisibility[key] === undefined) return null;
                                return (
                                    <div key={key} className="flex items-center justify-between p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                        <span className="text-slate-700 dark:text-slate-200 font-medium">{label}</span>
                                        <button 
                                            onClick={() => { dataService.toggleFieldVisibility(key); triggerRefresh(); }}
                                            className={`w-12 h-6 rounded-full transition-colors relative ${fieldVisibility[key] ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                                        >
                                            <div className={`absolute top-1 left-1 bg-white w-4 h-4 rounded-full transition-transform ${fieldVisibility[key] ? 'translate-x-6' : ''}`} />
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );

             case 'tableColumns':
                return (
                    <div className="space-y-4">
                         <div className="flex justify-between items-center mb-4">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-white">จัดการคอลัมน์ตาราง</h3>
                            <div className="flex gap-2">
                                <button onClick={() => { dataService.setAllTableColumnsVisibility(true); triggerRefresh(); }} className="text-sm px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg">แสดงทั้งหมด</button>
                                <button onClick={() => { dataService.setAllTableColumnsVisibility(false); triggerRefresh(); }} className="text-sm px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg">ซ่อนทั้งหมด</button>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {Object.entries(FIELD_LABELS).map(([key, label]) => {
                                if(tableColumnVisibility[key] === undefined) return null;
                                return (
                                    <div key={key} className="flex items-center justify-between p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                        <span className="text-slate-700 dark:text-slate-200 font-medium">{label}</span>
                                        <button 
                                            onClick={() => { dataService.toggleTableColumnVisibility(key); triggerRefresh(); }}
                                            className={`w-12 h-6 rounded-full transition-colors relative ${tableColumnVisibility[key] ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
                                        >
                                            <div className={`absolute top-1 left-1 bg-white w-4 h-4 rounded-full transition-transform ${tableColumnVisibility[key] ? 'translate-x-6' : ''}`} />
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );

            case 'report':
                 return <div className="p-8 text-center text-slate-500 border-2 border-dashed border-slate-200 rounded-2xl">ส่วนจัดการโครงสร้างรายงาน (ต้องใช้การแก้ไข JSON ขั้นสูง - ยังไม่เปิดให้ใช้งานผ่าน UI)</div>;

            default:
