        try {
            const success = await login(username, password);

            if (success) {
                // Login successful, now trigger data sync
                setStatus('syncing');
                // We invoke sync but don't block heavily on failure, as it will use cached data
                await dataService.syncDropdowns();

                const Toast = Swal.mixin({
                    toast: true,
                    position: 'top-end',
                    showConfirmButton: false,
                    timer: 1500,
                    timerProgressBar: true,
                });
