                                            <button onClick={row.onEdit} className="p-2 text-slate-400 hover:text-blue-600 bg-slate-50 dark:bg-slate-700 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors">
                                                <Edit2 size={16} />
                                            </button>
