const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // Hardcoded constant (REPORT_HIERARCHY) removed in favor of dataService
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    // Initialize Hierarchy from Service
    useEffect(() => {
        // Fetch current structure. If empty, dataService might initialize it with default if configured so.
        // But for explicit initial load:
        const structure = dataService.getReportStructure();

        // If structure is somehow empty (cleared cache), we can re-populate with default logic here or inside dataService.
        // For robustness, let's assume dataService handles initialization or we fallback.
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        } else {
            // Fallback: This path ideally shouldn't be hit if dataService initializes properly
            // Or we can define the hardcoded constant here as a fallback and save it back.
            // For now, let's assume dataService has the initial data (see dataService update).
            const fromService = dataService.getReportStructure();
            if (fromService.length > 0) setReportHierarchy(fromService);
            // else setReportHierarchy(DEFAULT_HIERARCHY_IF_NEEDED);
        }
    }, []);

    // Filter State
    const [selectedResponsible, setSelectedResponsible] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');

    // Filter Logic
    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const matchesResp = selectedResponsible ? (r.responsibleAgency || '').trim() === selectedResponsible.trim() : true;
            const matchesProv = selectedProvince ? (r.province || '').trim() === selectedProvince.trim() : true;
            return matchesResp && matchesProv;
        });
    }, [records, selectedResponsible, selectedProvince]);

    // Initial zero data structure
    const initialAggregatedData = {
        salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
        utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
        target: '0', unit: '', total: 0
    };

    // Helper to get aggregated data for a specific activity name
    const getAggregatedData = (activityName: string) => {
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityName.trim());
        if (matches.length === 0) return null;

        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            // Max Target Logic
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit // Last non-empty unit wins or just take current
        }), { ...initialAggregatedData });

        // Calculate Row Total
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;

        return { ...agg, total };
    };

    // Recursive function to calculate total for any node (including children)
    const calculateNodeData = (node: ReportNode): typeof initialAggregatedData => {
        let currentTotal = { ...initialAggregatedData };

        // 1. Add direct data if this node matches an activity
        if (node.activityMatcher) {
            const directData = getAggregatedData(node.activityMatcher);
            if (directData) {
                currentTotal = sumAggregatedData(currentTotal, directData);
                // Keep target/unit from direct match
                currentTotal.target = directData.target;
                currentTotal.unit = directData.unit;
            }
        }

        // 2. Recursively add children data
        if (node.children && node.children.length > 0) {
            node.children.forEach(child => {
                const childTotal = calculateNodeData(child);
                currentTotal = sumAggregatedData(currentTotal, childTotal);
                // Note: We generally don't sum Targets/Units from children as they might be different units
            });
        }

        return currentTotal;
    };

    // Helper to sum two data objects (numeric fields only)
    const sumAggregatedData = (a: typeof initialAggregatedData, b: typeof initialAggregatedData) => {
        return {
            ...a,
            salaryPermanent: a.salaryPermanent + b.salaryPermanent,
            governmentCompensation: a.governmentCompensation + b.governmentCompensation,
            compensationSupplies: a.compensationSupplies + b.compensationSupplies,
            contractEmployees: a.contractEmployees + b.contractEmployees,
            utilities: a.utilities + b.utilities,
            equipment: a.equipment + b.equipment,
            landConstruction: a.landConstruction + b.landConstruction,
            subsidies: a.subsidies + b.subsidies,
            otherExpenses: a.otherExpenses + b.otherExpenses,
            total: a.total + b.total,
            // Keep original metadata
            target: a.target, 
            unit: a.unit
        };
    };

    // Helper to collect all used activity names in the hierarchy
    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    // Find records that don't match any activity in the hierarchy (Uncategorized)
    const uncategorizedRecords = useMemo(() => {
        // Group uncategorized records by activity name
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (!usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });

        // Aggregate them similar to getAggregatedData
        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), { ...initialAggregatedData });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    // Grand Total
    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            total: acc.total + ((r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                   (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                   (r.equipment || 0) + (r.landConstruction || 0) +
                   (r.subsidies || 0) + (r.otherExpenses || 0))
        }), { ...initialAggregatedData });
    }, [filteredRecords]);

    const handlePrint = () => {
        window.print();
    };

    // Recursive Renderer
    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node, idx) => {
            // Calculate aggregated data for this node (inclusive of children)
            const data = calculateNodeData(node);

            // Determine if we should show Target/Unit
            // Only show Target/Unit if it's a leaf activity type and has direct data
            // For parents (Plan, Project, etc.), we only show the budget totals to avoid unit confusion
            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');

            // Layout Styles based on type
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";

            if (node.type === 'plan') {
                rowClass = "bg-slate-200 dark:bg-slate-700 text-blue-900 dark:text-blue-200";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-12";
            } else if (node.type === 'activity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-16";
            } else if (node.type === 'subactivity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-20";
            }

            // Define borders for dark mode compatibility
            const cellBorder = "border border-slate-300 dark:border-slate-600";

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-yellow-50 dark:hover:bg-yellow-900/20 transition-colors`}>
                        <td className={`${cellBorder} py-1 text-left ${plClass} ${fontClass}`}>
                           {node.title}
                        </td>

                        {/* Target & Unit */}
                        <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                            {showTargetUnit ? data.target : ''}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                            {showTargetUnit ? data.unit : ''}
                        </td>

                        {/* Budget Columns - Apply fontClass to make totals bold for parents */}
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.governmentCompensation > 0 ? formatNumber(data.governmentCompensation) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.compensationSupplies > 0 ? formatNumber(data.compensationSupplies) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.contractEmployees > 0 ? formatNumber(data.contractEmployees) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.utilities > 0 ? formatNumber(data.utilities) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.equipment > 0 ? formatNumber(data.equipment) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.landConstruction > 0 ? formatNumber(data.landConstruction) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.subsidies > 0 ? formatNumber(data.subsidies) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>
                            {data.otherExpenses > 0 ? formatNumber(data.otherExpenses) : '-'}
                        </td>
                        <td className={`${cellBorder} px-1 py-1 text-right font-bold ${node.type === 'plan' ? 'text-blue-900 dark:text-blue-300' : ''}`}>
                            {data.total > 0 ? formatNumber(data.total) : '-'}
                        </td>
                    </tr>
                    {/* Recursively render children */}
                    {node.children && renderHierarchy(node.children)}
                </React.Fragment>
            );
        });
    };

    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-400 dark:border-slate-500";

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4 print:hidden">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">รายงานสรุปงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">รายงานการจัดสรรงบประมาณ (รูปแบบโครงสร้างราชการ)</p>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 dark:bg-slate-700 text-white dark:text-slate-200 rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-sm"
                    >
                        <Printer size={18} /> พิมพ์รายงาน
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-8 print:hidden transition-colors">
                <div className="flex items-center gap-2 mb-4 text-emerald-700 dark:text-emerald-400 font-semibold">
                    <Filter size={20} /> ตัวกรองรายงาน
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <AutocompleteInput 
                        id="filter-resp"
                        label="หน่วยงานบูรณาการ"
                        value={selectedResponsible}
                        onChange={setSelectedResponsible}
                        options={dropdowns.responsibleAgency}
                        placeholder="เลือกหน่วยงาน..."
                    />
                    <AutocompleteInput 
                        id="filter-prov"
                        label="จังหวัด"
                        value={selectedProvince}
                        onChange={setSelectedProvince}
                        options={dropdowns.province}
                        placeholder="เลือกจังหวัด..."
                    />
                </div>
            </div>

            {/* Report Container */}
            <div className="bg-white dark:bg-slate-900 p-8 rounded-none shadow-lg dark:shadow-none print:shadow-none print:p-0 overflow-x-auto min-w-[1000px] text-slate-900 dark:text-slate-100 transition-colors">
                {/* Header */}
                <div className="text-center mb-6" style={fontStyle}>
                    <h3 className="text-2xl font-bold mb-2 text-slate-900 dark:text-white">การจัดสรรงบประมาณกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ประจำปี พ.ศ. 2569</h3>
                    <h4 className="text-xl font-bold text-slate-900 dark:text-white">
                        {selectedResponsible || 'ภาพรวมทุกหน่วยงาน'} {selectedProvince ? `(จังหวัด${selectedProvince})` : ''}
                    </h4>
                </div>

                {/* Table */}
                <table className="w-full border-collapse border border-slate-400 dark:border-slate-600 text-[16px] leading-tight" style={fontStyle}>
                    <thead>
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-1 w-64`} rowSpan={2}>แผนงาน - ผลผลิต - กิจกรรม/โครงการ</th>
                            <th className={`${headerBorder} p-1 w-16`} rowSpan={2}>เป้าหมาย</th>
                            <th className={`${headerBorder} p-1 w-16`} rowSpan={2}>หน่วยนับ</th>
                            <th className={`${headerBorder} p-1`} colSpan={2}>งบบุคลากร</th>
                            <th className={`${headerBorder} p-1`} colSpan={3}>งบดำเนินงาน</th>
                            <th className={`${headerBorder} p-1`} colSpan={2}>งบลงทุน</th>
                            <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>เงินอุดหนุน</th>
                            <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>รายจ่ายอื่น</th>
                            <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>รวมทั้งสิ้น</th>
                        </tr>
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-1 w-20`}>เงินเดือน<br/>และค่าจ้างประจำ</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่าตอบแทน<br/>พนักงานราชการ</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่าตอบแทน<br/>ใช้สอยและวัสดุ</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่าจ้างเหมา<br/>พนักงาน</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่า<br/>สาธารณูปโภค</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่าครุภัณฑ์</th>
                            <th className={`${headerBorder} p-1 w-20`}>ค่าที่ดิน/<br/>และสิ่งก่อสร้าง</th>
                        </tr>
                    </thead>
                    <tbody>
                        {/* Summary Row */}
                        <tr className="bg-green-50 dark:bg-emerald-900/20 font-bold text-slate-900 dark:text-slate-100">
                            <td className={`${headerBorder} px-2 py-1 text-left`}>รวมทั้งสิ้น</td>
                            <td className={`${headerBorder} px-1 py-1 text-center`}></td>
                            <td className={`${headerBorder} px-1 py-1 text-center`}></td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.salaryPermanent)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.governmentCompensation)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.compensationSupplies)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.contractEmployees)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.utilities)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.equipment)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.landConstruction)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.subsidies)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.otherExpenses)}</td>
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.total)}</td>
                        </tr>

                        {/* Standard Hierarchy Rows */}
                        {renderHierarchy(reportHierarchy)}

                        {/* Uncategorized Section (To prevent data loss) */}
                        {uncategorizedRecords.length > 0 && (
                            <>
                                <tr className="bg-red-50 dark:bg-red-900/20 text-red-900 dark:text-red-300 font-bold">
                                    <td className={`${headerBorder} px-2 py-1 text-left`} colSpan={13}>
                                        *** รายการอื่นๆ (ไม่อยู่ในโครงสร้างที่กำหนด) ***
                                    </td>
                                </tr>
                                {uncategorizedRecords.map((r, idx) => (
                                    <tr key={`uncat-${idx}`} className="hover:bg-red-100 dark:hover:bg-red-900/30 text-slate-800 dark:text-slate-300">
                                        <td className={`${headerBorder} px-2 py-1 text-left pl-6 font-medium text-red-700 dark:text-red-400`}>
                                            - {r.activity}
                                        </td>
                                        <td className={`${headerBorder} px-1 py-1 text-center`}>{r.target}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-center`}>{r.unit}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.salaryPermanent ? formatNumber(r.salaryPermanent) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.governmentCompensation ? formatNumber(r.governmentCompensation) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.compensationSupplies ? formatNumber(r.compensationSupplies) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.contractEmployees ? formatNumber(r.contractEmployees) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.utilities ? formatNumber(r.utilities) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.equipment ? formatNumber(r.equipment) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.landConstruction ? formatNumber(r.landConstruction) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.subsidies ? formatNumber(r.subsidies) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right`}>{r.otherExpenses ? formatNumber(r.otherExpenses) : '-'}</td>
                                        <td className={`${headerBorder} px-1 py-1 text-right font-bold`}>{formatNumber(r.total)}</td>
                                    </tr>
                                ))}
                            </>
                        )}

                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={13} className={`${headerBorder} px-4 py-8 text-center text-slate-400 dark:text-slate-500`}>
                                    ไม่พบข้อมูลตามเงื่อนไขที่เลือก
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ReportView;

import React, { useState, useMemo, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber, parseNumber } from '../../utils';
import { Printer, Filter, CheckCircle2, Circle } from 'lucide-react';
import { BudgetRecord, ReportNode } from '../../types';
import AutocompleteInput from '../Form/AutocompleteInput';

type ReportMode = 'full' | 'summary' | 'province';

const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // Structure State
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    useEffect(() => {
        const structure = dataService.getReportStructure();
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        }
    }, []);

    // Filter State
    const [selectedMainAgency, setSelectedMainAgency] = useState('');
    const [selectedIntegration, setSelectedIntegration] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');

    // Report Mode State
    const [reportMode, setReportMode] = useState<ReportMode>('full');

    // Filter Logic
    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const matchesMain = selectedMainAgency ? (r.mainAgency || '').trim() === selectedMainAgency.trim() : true;
            const matchesInteg = selectedIntegration ? (r.integration || '').trim() === selectedIntegration.trim() : true;
            const matchesProv = selectedProvince ? (r.province || '').trim() === selectedProvince.trim() : true;
            return matchesMain && matchesInteg && matchesProv;
        });
    }, [records, selectedMainAgency, selectedIntegration, selectedProvince]);

    // Initial zero data structure
    const initialAggregatedData = {
        salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
        utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
        target: '0', unit: '', total: 0
    };

    // Helper to get aggregated data for a specific activity name
    const getAggregatedData = (activityName: string) => {
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityName.trim());
        if (matches.length === 0) return null;

        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            // Max Target Logic
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit
        }), { ...initialAggregatedData });

        // Calculate Row Total
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;

        return { ...agg, total };
    };

    // Recursive function to calculate total for any node
    const calculateNodeData = (node: ReportNode): typeof initialAggregatedData => {
        let currentTotal = { ...initialAggregatedData };

        if (node.activityMatcher) {
            const directData = getAggregatedData(node.activityMatcher);
            if (directData) {
                currentTotal = sumAggregatedData(currentTotal, directData);
                currentTotal.target = directData.target;
                currentTotal.unit = directData.unit;
            }
        }

        if (node.children && node.children.length > 0) {
            node.children.forEach(child => {
                const childTotal = calculateNodeData(child);
                currentTotal = sumAggregatedData(currentTotal, childTotal);
            });
        }

        return currentTotal;
    };

    const sumAggregatedData = (a: typeof initialAggregatedData, b: typeof initialAggregatedData) => {
        return {
            ...a,
            salaryPermanent: a.salaryPermanent + b.salaryPermanent,
            governmentCompensation: a.governmentCompensation + b.governmentCompensation,
            compensationSupplies: a.compensationSupplies + b.compensationSupplies,
            contractEmployees: a.contractEmployees + b.contractEmployees,
            utilities: a.utilities + b.utilities,
            equipment: a.equipment + b.equipment,
            landConstruction: a.landConstruction + b.landConstruction,
            subsidies: a.subsidies + b.subsidies,
            otherExpenses: a.otherExpenses + b.otherExpenses,
            total: a.total + b.total,
            target: a.target, 
            unit: a.unit
        };
    };

    // Helper: Calculate Custom Column Groups
    const getRegularBudget = (data: typeof initialAggregatedData) => {
        return data.salaryPermanent + data.governmentCompensation + data.compensationSupplies + 
               data.contractEmployees + data.utilities + data.subsidies + data.otherExpenses;
    };

    const getInvestmentBudget = (data: typeof initialAggregatedData) => {
        return data.equipment + data.landConstruction;
    };

    // Uncategorized Logic
    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    const uncategorizedRecords = useMemo(() => {
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (!usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });

        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), { ...initialAggregatedData });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    // Grand Total
    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            total: acc.total + ((r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                   (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                   (r.equipment || 0) + (r.landConstruction || 0) +
                   (r.subsidies || 0) + (r.otherExpenses || 0))
        }), { ...initialAggregatedData });
    }, [filteredRecords]);

    const handlePrint = () => {
        window.print();
    };

    // --- Styling Constants ---
    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-400 dark:border-slate-500";
    const cellBorder = "border border-slate-300 dark:border-slate-600";

    // --- Render Logic ---

    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node) => {
            const data = calculateNodeData(node);

            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');

            // Styles based on type
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";

            if (node.type === 'plan') {
                rowClass = "bg-slate-200 dark:bg-slate-700 text-blue-900 dark:text-blue-200";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-12";
            } else if (node.type === 'activity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-16";
            } else if (node.type === 'subactivity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-yellow-50 dark:hover:bg-yellow-900/20 transition-colors`}>
                        {/* Name Column */}
                        <td className={`${cellBorder} py-1 text-left ${plClass} ${fontClass}`}>
                           {node.title}
                        </td>

                        {/* Conditional Columns based on Report Mode */}
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                                    {showTargetUnit ? data.target : ''}
                                </td>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                                    {showTargetUnit ? data.unit : ''}
                                </td>
                            </>
                        )}

                        {reportMode === 'full' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.governmentCompensation > 0 ? formatNumber(data.governmentCompensation) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.compensationSupplies > 0 ? formatNumber(data.compensationSupplies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.contractEmployees > 0 ? formatNumber(data.contractEmployees) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.utilities > 0 ? formatNumber(data.utilities) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.equipment > 0 ? formatNumber(data.equipment) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.landConstruction > 0 ? formatNumber(data.landConstruction) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.subsidies > 0 ? formatNumber(data.subsidies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.otherExpenses > 0 ? formatNumber(data.otherExpenses) : '-'}</td>
                            </>
                        )}

                        {reportMode === 'province' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getRegularBudget(data) > 0 ? formatNumber(getRegularBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getInvestmentBudget(data) > 0 ? formatNumber(getInvestmentBudget(data)) : '-'}</td>
                            </>
                        )}

                        {/* Total Column (Always Visible) */}
                        <td className={`${cellBorder} px-1 py-1 text-right font-bold ${node.type === 'plan' ? 'text-blue-900 dark:text-blue-300' : ''}`}>
                            {data.total > 0 ? formatNumber(data.total) : '-'}
                        </td>
                    </tr>
                    {/* Recursively render children */}
                    {node.children && renderHierarchy(node.children)}
                </React.Fragment>
            );
        });
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4 print:hidden">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">รายงานสรุปงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">รายงานการจัดสรรงบประมาณ (รูปแบบโครงสร้างราชการ)</p>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 dark:bg-slate-700 text-white dark:text-slate-200 rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-sm"
                    >
                        <Printer size={18} /> พิมพ์รายงาน
                    </button>
                </div>
            </div>

            {/* Filters & Options */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-8 print:hidden transition-colors">

                {/* 1. Filters */}
                <div className="flex items-center gap-2 mb-4 text-emerald-700 dark:text-emerald-400 font-semibold border-b border-slate-100 dark:border-slate-700 pb-2">
                    <Filter size={20} /> ตัวกรองข้อมูล
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    <AutocompleteInput 
                        id="filter-main"
                        label="หน่วยงานหลัก"
                        value={selectedMainAgency}
                        onChange={setSelectedMainAgency}
                        options={dropdowns.mainAgency}
                        placeholder="เลือกหน่วยงานหลัก..."
                    />
                    <AutocompleteInput 
                        id="filter-integ"
                        label="รายการบูรณาการ"
                        value={selectedIntegration}
                        onChange={setSelectedIntegration}
                        options={dropdowns.integration}
                        placeholder="เลือกรายการบูรณาการ..."
                    />
                    <AutocompleteInput 
                        id="filter-prov"
                        label="จังหวัด"
                        value={selectedProvince}
                        onChange={setSelectedProvince}
                        options={dropdowns.province}
                        placeholder="เลือกจังหวัด..."
                    />
                </div>

                {/* 2. Display Options (Radio Logic) */}
                <div className="flex flex-col md:flex-row gap-6 p-4 bg-slate-50 dark:bg-slate-900/50 rounded-xl border border-slate-200 dark:border-slate-700">
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'full' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'full' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'full'} onChange={() => setReportMode('full')} />
                        <span className={`font-medium ${reportMode === 'full' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>แสดงรายละเอียดครบถ้วน (Default)</span>
                    </label>

                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'summary' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'summary' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'summary'} onChange={() => setReportMode('summary')} />
                        <span className={`font-medium ${reportMode === 'summary' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>สรุปงบประมาณ (แสดงเฉพาะยอดรวม)</span>
                    </label>

                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'province' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'province' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'province'} onChange={() => setReportMode('province')} />
                        <span className={`font-medium ${reportMode === 'province' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>จำแนกรายจังหวัด (งบประจำ/งบลงทุน)</span>
                    </label>
                </div>
            </div>

            {/* Report Container */}
            <div className="bg-white dark:bg-slate-900 p-8 rounded-none shadow-lg dark:shadow-none print:shadow-none print:p-0 overflow-x-auto min-w-[1000px] text-slate-900 dark:text-slate-100 transition-colors">
                {/* Report Header */}
                <div className="text-center mb-6" style={fontStyle}>
                    <h3 className="text-2xl font-bold mb-2 text-slate-900 dark:text-white">การจัดสรรงบประมาณกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ประจำปี พ.ศ. 2569</h3>
                    <h4 className="text-xl font-bold text-slate-900 dark:text-white">
                        {[
                            selectedMainAgency, 
                            selectedIntegration, 
                            selectedProvince ? `จังหวัด${selectedProvince}` : ''
                        ].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน'}
                    </h4>
                </div>

                {/* Table */}
                <table className="w-full border-collapse border border-slate-400 dark:border-slate-600 text-[16px] leading-tight" style={fontStyle}>
                    <thead>
                        {/* Dynamic Header based on Mode */}
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-1 ${reportMode === 'summary' ? 'w-2/3' : 'w-64'}`} rowSpan={2}>แผนงาน - ผลผลิต - กิจกรรม/โครงการ</th>

                            {reportMode !== 'summary' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-16`} rowSpan={2}>เป้าหมาย</th>
                                    <th className={`${headerBorder} p-1 w-16`} rowSpan={2}>หน่วยนับ</th>
                                </>
                            )}

                            {reportMode === 'full' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบบุคลากร</th>
                                    <th className={`${headerBorder} p-1`} colSpan={3}>งบดำเนินงาน</th>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบลงทุน</th>
                                    <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>เงินอุดหนุน</th>
                                    <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>รายจ่ายอื่น</th>
                                </>
                            )}

                            {reportMode === 'province' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-32`} rowSpan={2}>งบประจำ</th>
                                    <th className={`${headerBorder} p-1 w-32`} rowSpan={2}>งบลงทุน</th>
                                </>
                            )}

                            <th className={`${headerBorder} p-1 ${reportMode === 'summary' ? 'w-1/3' : 'w-24'}`} rowSpan={2}>รวมทั้งสิ้น</th>
                        </tr>

                        {/* Sub-header row for Full Mode */}
                        {reportMode === 'full' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                                <th className={`${headerBorder} p-1 w-20`}>เงินเดือน<br/>และค่าจ้างประจำ</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่าตอบแทน<br/>พนักงานราชการ</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่าตอบแทน<br/>ใช้สอยและวัสดุ</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่าจ้างเหมา<br/>พนักงาน</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่า<br/>สาธารณูปโภค</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่าครุภัณฑ์</th>
                                <th className={`${headerBorder} p-1 w-20`}>ค่าที่ดิน/<br/>และสิ่งก่อสร้าง</th>
                            </tr>
                        )}
                        {/* Empty row for others to keep DOM valid if rowspan>1 logic needs it (omitted as logic handles rowspans correctly) */}
                    </thead>
                    <tbody>
                        {/* Summary Row (Grand Total) */}
                        <tr className="bg-green-50 dark:bg-emerald-900/20 font-bold text-slate-900 dark:text-slate-100">
                            <td className={`${headerBorder} px-2 py-1 text-left`}>รวมทั้งสิ้น</td>

                            {reportMode !== 'summary' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-center`}></td>
                                    <td className={`${headerBorder} px-1 py-1 text-center`}></td>
                                </>
                            )}

                            {reportMode === 'full' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.salaryPermanent)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.governmentCompensation)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.compensationSupplies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.contractEmployees)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.utilities)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.equipment)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.landConstruction)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.subsidies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.otherExpenses)}</td>
                                </>
                            )}

                            {reportMode === 'province' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getRegularBudget(grandTotal))}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getInvestmentBudget(grandTotal))}</td>
                                </>
                            )}

                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.total)}</td>
                        </tr>

                        {/* Hierarchy Rows */}
                        {renderHierarchy(reportHierarchy)}

                        {/* Uncategorized Rows */}
                        {uncategorizedRecords.length > 0 && (
                            <>
                                <tr className="bg-red-50 dark:bg-red-900/20 text-red-900 dark:text-red-300 font-bold">
                                    <td className={`${headerBorder} px-2 py-1 text-left`} colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 6 : 2}>
                                        *** รายการอื่นๆ (ไม่อยู่ในโครงสร้างที่กำหนด) ***
                                    </td>
                                </tr>
                                {uncategorizedRecords.map((r, idx) => (
                                    <tr key={`uncat-${idx}`} className="hover:bg-red-100 dark:hover:bg-red-900/30 text-slate-800 dark:text-slate-300">
                                        <td className={`${headerBorder} px-2 py-1 text-left pl-6 font-medium text-red-700 dark:text-red-400`}>
                                            - {r.activity}
                                        </td>

                                        {reportMode !== 'summary' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-center`}>{r.target}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-center`}>{r.unit}</td>
                                            </>
                                        )}

                                        {reportMode === 'full' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.salaryPermanent ? formatNumber(r.salaryPermanent) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.governmentCompensation ? formatNumber(r.governmentCompensation) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.compensationSupplies ? formatNumber(r.compensationSupplies) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.contractEmployees ? formatNumber(r.contractEmployees) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.utilities ? formatNumber(r.utilities) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.equipment ? formatNumber(r.equipment) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.landConstruction ? formatNumber(r.landConstruction) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.subsidies ? formatNumber(r.subsidies) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{r.otherExpenses ? formatNumber(r.otherExpenses) : '-'}</td>
                                            </>
                                        )}

                                        {reportMode === 'province' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{getRegularBudget(r as any) > 0 ? formatNumber(getRegularBudget(r as any)) : '-'}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{getInvestmentBudget(r as any) > 0 ? formatNumber(getInvestmentBudget(r as any)) : '-'}</td>
                                            </>
                                        )}

                                        <td className={`${headerBorder} px-1 py-1 text-right font-bold`}>{formatNumber(r.total)}</td>
                                    </tr>
                                ))}
                            </>
                        )}

                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 6 : 2} className={`${headerBorder} px-4 py-8 text-center text-slate-400 dark:text-slate-500`}>
                                    ไม่พบข้อมูลตามเงื่อนไขที่เลือก
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ReportView;

import React, { useState, useMemo, useEffect } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber, parseNumber } from '../../utils';
import { Printer, Filter, CheckCircle2, Circle } from 'lucide-react';
import { BudgetRecord, ReportNode } from '../../types';
import AutocompleteInput from '../Form/AutocompleteInput';

type ReportMode = 'full' | 'summary' | 'province';

const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // Structure State
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    useEffect(() => {
        const structure = dataService.getReportStructure();
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        }
    }, []);

    // Filter State
    const [selectedMainAgency, setSelectedMainAgency] = useState('');
    const [selectedIntegration, setSelectedIntegration] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');

    // Report Mode State
    const [reportMode, setReportMode] = useState<ReportMode>('full');

    // Filter Logic
    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const matchesMain = selectedMainAgency ? (r.mainAgency || '').trim() === selectedMainAgency.trim() : true;
            const matchesInteg = selectedIntegration ? (r.integration || '').trim() === selectedIntegration.trim() : true;
            const matchesProv = selectedProvince ? (r.province || '').trim() === selectedProvince.trim() : true;
            return matchesMain && matchesInteg && matchesProv;
        });
    }, [records, selectedMainAgency, selectedIntegration, selectedProvince]);

    // Initial zero data structure
    const initialAggregatedData = {
        salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
        utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
        target: '0', unit: '', total: 0
    };

    // Helper to get aggregated data for a specific activity name
    const getAggregatedData = (activityName: string) => {
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityName.trim());
        if (matches.length === 0) return null;

        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            // Max Target Logic
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit
        }), { ...initialAggregatedData });

        // Calculate Row Total
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;

        return { ...agg, total };
    };

    // Recursive function to calculate total for any node
    const calculateNodeData = (node: ReportNode): typeof initialAggregatedData => {
        let currentTotal = { ...initialAggregatedData };

        if (node.activityMatcher) {
            const directData = getAggregatedData(node.activityMatcher);
            if (directData) {
                currentTotal = sumAggregatedData(currentTotal, directData);
                currentTotal.target = directData.target;
                currentTotal.unit = directData.unit;
            }
        }

        if (node.children && node.children.length > 0) {
            node.children.forEach(child => {
                const childTotal = calculateNodeData(child);
                currentTotal = sumAggregatedData(currentTotal, childTotal);
            });
        }

        return currentTotal;
    };

    const sumAggregatedData = (a: typeof initialAggregatedData, b: typeof initialAggregatedData) => {
        return {
            ...a,
            salaryPermanent: a.salaryPermanent + b.salaryPermanent,
            governmentCompensation: a.governmentCompensation + b.governmentCompensation,
            compensationSupplies: a.compensationSupplies + b.compensationSupplies,
            contractEmployees: a.contractEmployees + b.contractEmployees,
            utilities: a.utilities + b.utilities,
            equipment: a.equipment + b.equipment,
            landConstruction: a.landConstruction + b.landConstruction,
            subsidies: a.subsidies + b.subsidies,
            otherExpenses: a.otherExpenses + b.otherExpenses,
            total: a.total + b.total,
            target: a.target, 
            unit: a.unit
        };
    };

    // Helper: Calculate Custom Column Groups
    const getRegularBudget = (data: typeof initialAggregatedData) => {
        return data.salaryPermanent + data.governmentCompensation + data.compensationSupplies + 
               data.contractEmployees + data.utilities + data.subsidies + data.otherExpenses;
    };

    const getInvestmentBudget = (data: typeof initialAggregatedData) => {
        return data.equipment + data.landConstruction;
    };

    // Uncategorized Logic
    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    const uncategorizedRecords = useMemo(() => {
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (!usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });

        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), { ...initialAggregatedData });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    // Grand Total
    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => ({
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            total: acc.total + ((r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                   (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                   (r.equipment || 0) + (r.landConstruction || 0) +
                   (r.subsidies || 0) + (r.otherExpenses || 0)),
            target: '0',
            unit: ''
        }), { ...initialAggregatedData });
    }, [filteredRecords]);

    const handlePrint = () => {
        window.print();
    };

    // --- Styling Constants ---
    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-400 dark:border-slate-500";
    const cellBorder = "border border-slate-300 dark:border-slate-600";

    // --- Render Logic ---

    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node) => {
            const data = calculateNodeData(node);

            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');

            // Styles based on type
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";

            if (node.type === 'plan') {
                rowClass = "bg-slate-200 dark:bg-slate-700 text-blue-900 dark:text-blue-200";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                rowClass = "dark:bg-slate-900";
                plClass = "pl-12";
            } else if (node.type === 'activity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-16";
            } else if (node.type === 'subactivity') {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-yellow-50 dark:hover:bg-yellow-900/20 transition-colors`}>
                        {/* Name Column */}
                        <td className={`${cellBorder} py-1 text-left ${plClass} ${fontClass}`}>
                           {node.title}
                        </td>

                        {/* Conditional Columns based on Report Mode */}
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                                    {showTargetUnit ? data.target : ''}
                                </td>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>
                                    {showTargetUnit ? data.unit : ''}
                                </td>
                            </>
                        )}

                        {reportMode === 'full' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.governmentCompensation > 0 ? formatNumber(data.governmentCompensation) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.compensationSupplies > 0 ? formatNumber(data.compensationSupplies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.contractEmployees > 0 ? formatNumber(data.contractEmployees) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.utilities > 0 ? formatNumber(data.utilities) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.equipment > 0 ? formatNumber(data.equipment) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.landConstruction > 0 ? formatNumber(data.landConstruction) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.subsidies > 0 ? formatNumber(data.subsidies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.otherExpenses > 0 ? formatNumber(data.otherExpenses) : '-'}</td>
                            </>
                        )}

                        {reportMode === 'province' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getRegularBudget(data) > 0 ? formatNumber(getRegularBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getInvestmentBudget(data) > 0 ? formatNumber(getInvestmentBudget(data)) : '-'}</td>
                            </>
                        )}

                        {/* Total Column (Always Visible) */}
                        <td className={`${cellBorder} px-1 py-1 text-right font-bold ${node.type === 'plan' ? 'text-blue-900 dark:text-blue-300' : ''}`}>
                            {data.total > 0 ? formatNumber(data.total) : '-'}
                        </td>
                    </tr>
                    {/* Recursively render children */}
                    {node.children && renderHierarchy(node.children)}
                </React.Fragment>
            );
        });
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4 print:hidden">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">รายงานสรุปงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">รายงานการจัดสรรงบประมาณ (รูปแบบโครงสร้างราชการ)</p>
                </div>
                <div className="flex gap-2">
                     <button 
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 dark:bg-slate-700 text-white dark:text-slate-200 rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-sm"
                    >
                        <Printer size={18} /> พิมพ์รายงาน
                    </button>
                </div>
            </div>

            {/* Filters & Options */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-8 print:hidden transition-colors">

                {/* 1. Filters */}
                <div className="flex items-center gap-2 mb-4 text-emerald-700 dark:text-emerald-400 font-semibold border-b border-slate-100 dark:border-slate-700 pb-2">
                    <Filter size={20} /> ตัวกรองข้อมูล
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    <AutocompleteInput 
                        id="filter-main"
                        label="หน่วยงานหลัก"
                        value={selectedMainAgency}
                        onChange={setSelectedMainAgency}
                        options={dropdowns.mainAgency}
                        placeholder="เลือกหน่วยงานหลัก..."
                    />
                    <AutocompleteInput 
                        id="filter-integ"
                        label="รายการบูรณาการ"
                        value={selectedIntegration}
                        onChange={setSelectedIntegration}
                        options={dropdowns.integration}
                        placeholder="เลือกรายการบูรณาการ..."
                    />
                    <AutocompleteInput 
                        id="filter-prov"
                        label="จังหวัด"
                        value={selectedProvince}
                        onChange={setSelectedProvince}
                        options={dropdowns.province}
                        placeholder="เลือกจังหวัด..."
                    />
                </div>

                {/* 2. Display Options (Radio Logic) */}
                <div className="flex flex-col md:flex-row gap-6 p-4 bg-slate-50 dark:bg-slate-900/50 rounded-xl border border-slate-200 dark:border-slate-700">
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'full' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'full' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'full'} onChange={() => setReportMode('full')} />
                        <span className={`font-medium ${reportMode === 'full' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>แสดงรายละเอียดครบถ้วน (Default)</span>
                    </label>

                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'summary' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'summary' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'summary'} onChange={() => setReportMode('summary')} />
                        <span className={`font-medium ${reportMode === 'summary' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>สรุปงบประมาณ (แสดงเฉพาะยอดรวม)</span>
                    </label>

                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-colors ${reportMode === 'province' ? 'text-emerald-600' : 'text-slate-300'}`}>
                            {reportMode === 'province' ? <CheckCircle2 size={22} className="fill-emerald-50" /> : <Circle size={22} />}
                        </div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'province'} onChange={() => setReportMode('province')} />
                        <span className={`font-medium ${reportMode === 'province' ? 'text-slate-800 dark:text-white' : 'text-slate-500'}`}>จำแนกรายจังหวัด (งบประจำ/งบลงทุน)</span>
                    </label>
                </div>
            </div>

            {/* Report Container */}
            <div className="bg-white dark:bg-slate-900 p-8 rounded-none shadow-lg dark:shadow-none print:shadow-none print:p-0 overflow-x-auto min-w-[1000px] text-slate-900 dark:text-slate-100 transition-colors">
