                    <thead>
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-2 ${reportMode === 'summary' ? 'w-2/3' : 'w-64'}`} rowSpan={2}>แผนงาน - ผลผลิต - กิจกรรม/โครงการ</th>
                            {reportMode !== 'summary' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>เป้าหมาย</th>
                                    <th className={`${headerBorder} p-1 w-20`} rowSpan={2}>หน่วยนับ</th>
                                </>
                            )}
                            {reportMode === 'full' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบบุคลากร</th>
                                    <th className={`${headerBorder} p-1`} colSpan={3}>งบดำเนินงาน</th>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบลงทุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>เงินอุดหนุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>รายจ่ายอื่น</th>
                                </>
                            )}
                            {reportMode === 'province' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-40`} rowSpan={2}>งบประจำ</th>
                                    <th className={`${headerBorder} p-1 w-40`} rowSpan={2}>งบลงทุน</th>
                                </>
                            )}
                            <th className={`${headerBorder} p-1 ${reportMode === 'summary' ? 'w-1/3' : 'w-32'}`} rowSpan={2}>รวมทั้งสิ้น</th>
                        </tr>
                        {reportMode === 'full' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-800 dark:text-slate-200">
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>เงินเดือนฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>พนง.ราชการ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ใช้สอย/วัสดุ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>จ้างเหมาฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>สาธารณูปโภค</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ค่าครุภัณฑ์</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ที่ดินฯ</th>
                            </tr>
                        )}
                    </thead>
                    <tbody>
                        <tr className="bg-emerald-50/50 dark:bg-emerald-900/30 font-bold text-slate-900 dark:text-slate-100">
                            <td className={`${headerBorder} px-3 py-2 text-left`}>รวมทั้งสิ้น</td>
                            {reportMode !== 'summary' && (<><td className={`${headerBorder} px-1 py-1 text-center`}></td><td className={`${headerBorder} px-1 py-1 text-center`}></td></>)}
                            {reportMode === 'full' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.salaryPermanent)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.governmentCompensation)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.compensationSupplies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.contractEmployees)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.utilities)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.equipment)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.landConstruction)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.subsidies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.otherExpenses)}</td>
                                </>
                            )}
                            {reportMode === 'province' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getRegularBudget(grandTotal))}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getInvestmentBudget(grandTotal))}</td>
                                </>
                            )}
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.total)}</td>
                        </tr>
                        {renderHierarchy(reportHierarchy)}
                        {uncategorizedRecords.length > 0 && (
                            <>
                                <tr className="bg-rose-50 dark:bg-rose-900/20 text-rose-800 dark:text-rose-300 font-bold">
                                    <td className={`${headerBorder} px-3 py-2 text-left`} colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 6 : 2}>*** รายการอื่นๆ (อยู่นอกโครงสร้างหลัก) ***</td>
                                </tr>
                                {uncategorizedRecords.map((r, idx) => (
                                    <tr key={`uncat-${idx}`} className="hover:bg-rose-100/30 dark:hover:bg-rose-900/10 text-slate-800 dark:text-slate-300">
                                        <td className={`${headerBorder} px-3 py-1.5 text-left pl-8`}>- {r.activity}</td>
                                        {reportMode !== 'summary' && (<><td className={`${headerBorder} px-1 py-1 text-center`}>{r.target}</td><td className={`${headerBorder} px-1 py-1 text-center`}>{r.unit}</td></>)}
                                        {reportMode === 'full' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.salaryPermanent)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.governmentCompensation)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.compensationSupplies)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.contractEmployees)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.utilities)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.equipment)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.landConstruction)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.subsidies)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.otherExpenses)}</td>
                                            </>
                                        )}
                                        {reportMode === 'province' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getRegularBudget(r as any))}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getInvestmentBudget(r as any))}</td>
                                            </>
                                        )}
                                        <td className={`${headerBorder} px-1 py-1 text-right font-bold`}>{formatNumber(r.total)}</td>
                                    </tr>
                                ))}
                            </>
                        )}
                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 6 : 2} className={`${headerBorder} px-4 py-16 text-center text-slate-400 dark:text-slate-600`}>
                                    <div className="flex flex-col items-center gap-3">
                                        <AlertCircle size={40} className="opacity-20" />
                                        <span className="text-xl">ไม่พบข้อมูลตามเงื่อนไขที่ระบุ</span>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ReportView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber, parseNumber } from '../../utils';
// Added RefreshCw to the imports from lucide-react
import { Printer, Filter, CheckCircle2, Circle, AlertCircle, Edit2, Download, FileSpreadsheet, FileText, ChevronDown, RefreshCw } from 'lucide-react';
import { BudgetRecord, ReportNode } from '../../types';
import AutocompleteInput from '../Form/AutocompleteInput';
import Swal from 'sweetalert2';

type ReportMode = 'full' | 'summary' | 'province';

const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();

    // UI States
    const [downloadDropdownOpen, setDownloadDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Structure State
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    // Custom Report Title State
    const [reportTitle, setReportTitle] = useState(() => {
        return localStorage.getItem('customReportTitle') || 'การจัดสรรงบประมาณกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ประจำปี พ.ศ. 2569';
    });

    useEffect(() => {
        const structure = dataService.getReportStructure();
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        }

        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setDownloadDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Filter State
    const [selectedMainAgency, setSelectedMainAgency] = useState('');
    const [selectedIntegration, setSelectedIntegration] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');
    const [reportMode, setReportMode] = useState<ReportMode>('full');

    const filteredRecords = useMemo(() => {
        return records.filter(r => {
            const rMain = (r.mainAgency || '').trim();
            const rInteg = (r.integration || '').trim();
            const rProv = (r.province || '').trim();
            const matchesMain = selectedMainAgency ? rMain === selectedMainAgency.trim() : true;
            const matchesInteg = selectedIntegration ? (rInteg === selectedIntegration.trim() || rInteg.includes(selectedIntegration.trim())) : true;
            const matchesProv = selectedProvince ? rProv === selectedProvince.trim() : true;
            return matchesMain && matchesInteg && matchesProv;
        });
    }, [records, selectedMainAgency, selectedIntegration, selectedProvince]);

    const initialAggregatedData = {
        salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
        utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
        target: '0', unit: '', total: 0
    };

    const getAggregatedData = (activityName: string) => {
        const activityTrimmed = activityName.trim();
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityTrimmed);
        if (matches.length === 0) return null;
        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit
        }), { ...initialAggregatedData });
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;
        return { ...agg, total };
    };

    const calculateNodeData = (node: ReportNode): typeof initialAggregatedData => {
        let currentTotal = { ...initialAggregatedData };
        if (node.activityMatcher) {
            const directData = getAggregatedData(node.activityMatcher);
            if (directData) {
                currentTotal = sumAggregatedData(currentTotal, directData);
                currentTotal.target = directData.target;
                currentTotal.unit = directData.unit;
            }
        }
        if (node.children && node.children.length > 0) {
            node.children.forEach(child => {
                const childTotal = calculateNodeData(child);
                currentTotal = sumAggregatedData(currentTotal, childTotal);
            });
        }
        return currentTotal;
    };

    const sumAggregatedData = (a: typeof initialAggregatedData, b: typeof initialAggregatedData) => {
        return {
            ...a,
            salaryPermanent: a.salaryPermanent + b.salaryPermanent,
            governmentCompensation: a.governmentCompensation + b.governmentCompensation,
            compensationSupplies: a.compensationSupplies + b.compensationSupplies,
            contractEmployees: a.contractEmployees + b.contractEmployees,
            utilities: a.utilities + b.utilities,
            equipment: a.equipment + b.equipment,
            landConstruction: a.landConstruction + b.landConstruction,
            subsidies: a.subsidies + b.subsidies,
            otherExpenses: a.otherExpenses + b.otherExpenses,
            total: a.total + b.total,
            target: a.target, 
            unit: a.unit
        };
    };

    const getRegularBudget = (data: typeof initialAggregatedData) => {
        return data.salaryPermanent + data.governmentCompensation + data.compensationSupplies + 
               data.contractEmployees + data.utilities + data.subsidies + data.otherExpenses;
    };

    const getInvestmentBudget = (data: typeof initialAggregatedData) => {
        return data.equipment + data.landConstruction;
    };

    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    const uncategorizedRecords = useMemo(() => {
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (name && !usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });
        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.governmentCompensation || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), { ...initialAggregatedData });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => {
            const rowTotal = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                             (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                             (r.equipment || 0) + (r.landConstruction || 0) +
                             (r.subsidies || 0) + (r.otherExpenses || 0);
            return {
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                total: acc.total + rowTotal
            };
        }, { ...initialAggregatedData });
    }, [filteredRecords]);

    const handlePrint = () => {
        window.print();
    };

    const handleDownloadExcel = async () => {
        setIsLoading(true);
        setDownloadDropdownOpen(false);
        try {
            const ExcelJS = await import('https://esm.sh/exceljs');
            const workbook = new ExcelJS.Workbook();
            const worksheet = workbook.addWorksheet('Report');

            // 1. Define Columns based on mode
            let columns: any[] = [{ header: 'แผนงาน - ผลผลิต - กิจกรรม/โครงการ', key: 'title', width: 60 }];
            if (reportMode !== 'summary') {
                columns.push({ header: 'เป้าหมาย', key: 'target', width: 15 });
                columns.push({ header: 'หน่วยนับ', key: 'unit', width: 12 });
            }

            if (reportMode === 'full') {
                const bCols = [
                    { header: 'เงินเดือนฯ', key: 'salaryPermanent', width: 18 },
                    { header: 'พนง.ราชการ', key: 'governmentCompensation', width: 18 },
                    { header: 'ใช้สอย/วัสดุ', key: 'compensationSupplies', width: 18 },
                    { header: 'จ้างเหมาฯ', key: 'contractEmployees', width: 18 },
                    { header: 'สาธารณูปโภค', key: 'utilities', width: 18 },
                    { header: 'ค่าครุภัณฑ์', key: 'equipment', width: 18 },
                    { header: 'ที่ดินฯ', key: 'landConstruction', width: 18 },
                    { header: 'เงินอุดหนุน', key: 'subsidies', width: 18 },
                    { header: 'รายจ่ายอื่น', key: 'otherExpenses', width: 18 }
                ];
                columns = [...columns, ...bCols];
            } else if (reportMode === 'province') {
                columns.push({ header: 'งบประจำ', key: 'regular', width: 20 });
                columns.push({ header: 'งบลงทุน', key: 'investment', width: 20 });
            }
            columns.push({ header: 'รวมทั้งสิ้น', key: 'total', width: 22 });
            worksheet.columns = columns;

            // 2. Report Header Titles
            worksheet.insertRow(1, [reportTitle]);
            worksheet.mergeCells(1, 1, 1, columns.length);
            worksheet.getRow(1).height = 30;
            worksheet.getCell('A1').font = { name: 'Sarabun', size: 16, bold: true };
            worksheet.getCell('A1').alignment = { vertical: 'middle', horizontal: 'center' };

            const subTitleStr = [selectedMainAgency, selectedIntegration, selectedProvince ? `จังหวัด${selectedProvince}` : ''].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน';
            worksheet.insertRow(2, [subTitleStr]);
            worksheet.mergeCells(2, 1, 2, columns.length);
            worksheet.getRow(2).height = 20;
            worksheet.getCell('A2').font = { name: 'Sarabun', size: 12, bold: true };
            worksheet.getCell('A2').alignment = { vertical: 'middle', horizontal: 'center' };

            // 3. Table Header Formatting (Multi-row for Full Mode)
            let headerRowIndex = 4;
            if (reportMode === 'full') {
                const topHeader = ['แผนงาน - ผลผลิต - กิจกรรม/โครงการ', 'เป้าหมาย', 'หน่วยนับ', 'งบบุคลากร', '', 'งบดำเนินงาน', '', '', 'งบลงทุน', '', 'เงินอุดหนุน', 'รายจ่ายอื่น', 'รวมทั้งสิ้น'];
                const rowH1 = worksheet.insertRow(headerRowIndex, topHeader);
                const rowH2 = worksheet.addRow(['', '', '', 'เงินเดือนฯ', 'พนง.ราชการ', 'ใช้สอย/วัสดุ', 'จ้างเหมาฯ', 'สาธารณูปโภค', 'ค่าครุภัณฑ์', 'ที่ดินฯ', '', '', '']);

                // Styling headers
                [rowH1, rowH2].forEach(row => {
                    row.eachCell((cell) => {
                        cell.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF1F5F9'} };
                        cell.font = { bold: true };
                        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                        cell.alignment = { horizontal: 'center', vertical: 'middle' };
                    });
                });

                worksheet.mergeCells(headerRowIndex, 1, headerRowIndex + 1, 1); // Title
                worksheet.mergeCells(headerRowIndex, 2, headerRowIndex + 1, 2); // Target
                worksheet.mergeCells(headerRowIndex, 3, headerRowIndex + 1, 3); // Unit
                worksheet.mergeCells(headerRowIndex, 4, headerRowIndex, 5);     // Personnel
                worksheet.mergeCells(headerRowIndex, 6, headerRowIndex, 8);     // Operational
                worksheet.mergeCells(headerRowIndex, 9, headerRowIndex, 10);    // Investment
                worksheet.mergeCells(headerRowIndex, 11, headerRowIndex + 1, 11); // Subsidies
                worksheet.mergeCells(headerRowIndex, 12, headerRowIndex + 1, 12); // Other
                worksheet.mergeCells(headerRowIndex, 13, headerRowIndex + 1, 13); // Total
                headerRowIndex += 2;
            } else {
                const rowH = worksheet.getRow(headerRowIndex);
                rowH.eachCell((cell) => {
                    cell.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF1F5F9'} };
                    cell.font = { bold: true };
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { horizontal: 'center', vertical: 'middle' };
                });
                headerRowIndex += 1;
            }

            // 4. Grand Total Row
            const addDataRow = (title: string, data: any, level: number = 0, nodeType?: string) => {
                const indent = '   '.repeat(level);
                let rowValues: any[] = [indent + title];

                if (reportMode !== 'summary') {
                    rowValues.push(data.target !== '0' ? data.target : '');
                    rowValues.push(data.unit || '');
                }

                if (reportMode === 'full') {
                    rowValues = [...rowValues, 
                        data.salaryPermanent, data.governmentCompensation, 
                        data.compensationSupplies, data.contractEmployees, data.utilities, 
                        data.equipment, data.landConstruction, 
                        data.subsidies, data.otherExpenses
                    ];
                } else if (reportMode === 'province') {
                    rowValues.push(getRegularBudget(data));
                    rowValues.push(getInvestmentBudget(data));
                }
                rowValues.push(data.total);

                const row = worksheet.addRow(rowValues);

                // Style Row
                if (nodeType === 'plan') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFE2E8F0'} };
                        c.font = { bold: true, color: { argb: 'FF1E3A8A' } };
                    });
                } else if (nodeType === 'project' || nodeType === 'output') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF8FAFC'} };
                        c.font = { bold: true };
                    });
                } else if (nodeType === 'grandTotal') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFD1FAE5'} };
                        c.font = { bold: true };
                    });
                }

                // Format numbers
                row.eachCell((cell, colNumber) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    if (colNumber > (reportMode === 'summary' ? 1 : 3) || (reportMode === 'summary' && colNumber === 2)) {
                        cell.numFmt = '#,##0.00';
                        cell.alignment = { horizontal: 'right' };
                    }
                });
            };

            // Add Grand Total
            addDataRow('รวมทั้งสิ้น', grandTotal, 0, 'grandTotal');

            // 5. Recursive Tree Rows
            const traverseTree = (nodes: ReportNode[], level: number = 0) => {
                nodes.forEach(node => {
                    const data = calculateNodeData(node);
                    if (data.total > 0 || !(selectedMainAgency || selectedIntegration || selectedProvince)) {
                        addDataRow(node.title, data, level, node.type);
                        if (node.children) traverseTree(node.children, level + 1);
                    }
                });
            };
            traverseTree(reportHierarchy);

            // 6. Uncategorized
            if (uncategorizedRecords.length > 0) {
                const uncatRow = worksheet.addRow(['*** รายการอื่นๆ (อยู่นอกโครงสร้างหลัก) ***']);
                uncatRow.getCell(1).font = { bold: true, color: { argb: 'FF991B1B' } };
                uncatRow.getCell(1).fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFFFF1F2'} };

                uncategorizedRecords.forEach(r => {
                    addDataRow('- ' + r.activity, r, 1);
                });
            }

            // Export
            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${reportTitle}.xlsx`;
            a.click();
            window.URL.createObjectURL(blob);
            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Excel Export Error:', error);
            Swal.fire('ผิดพลาด', 'ไม่สามารถสร้างไฟล์ Excel ได้', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownloadPdf = () => {
        handlePrint();
        setDownloadDropdownOpen(false);
    };

    const handleEditTitle = async () => {
        const { value: newTitle } = await Swal.fire({
            title: 'แก้ไขหัวข้อรายงาน',
            input: 'text',
            inputValue: reportTitle,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
            inputValidator: (value) => { if (!value) return 'กรุณาระบุหัวข้อรายงาน'; }
        });
        if (newTitle) {
            setReportTitle(newTitle);
            localStorage.setItem('customReportTitle', newTitle);
        }
    };

    // UI Rendering Logic (Simplified for brevity as it follows the previous logic)
    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-300 dark:border-slate-700";
    const cellBorder = "border border-slate-200 dark:border-slate-800";
    const [isLoading, setIsLoading] = useState(false);

    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node) => {
            const data = calculateNodeData(node);
            if (data.total === 0 && (selectedMainAgency || selectedIntegration || selectedProvince)) return null;
            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";
            if (node.type === 'plan') {
                rowClass = "bg-slate-100 dark:bg-slate-800/80 text-blue-900 dark:text-blue-300";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-900/50 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                plClass = "pl-12";
            } else {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = node.type === 'activity' ? "pl-16" : "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-emerald-50 dark:hover:bg-emerald-900/10 transition-colors`}>
                        <td className={`${cellBorder} px-2 py-1.5 text-left ${plClass} ${fontClass}`}>{node.title}</td>
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.target : ''}</td>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.unit : ''}</td>
                            </>
                        )}
                        {reportMode === 'full' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}</td>
