            if (confirm.isConfirmed) {
                Swal.showLoading();
                const res = await dataService.deleteRegion(currentName!);
                if (res.success) {
                    if (selectedRegion === currentName) setSelectedRegion('');
                    triggerRefresh();
                    Swal.fire('สำเร็จ', 'ลบภูมิภาคเรียบร้อย', 'success');
