                worksheet.mergeCells(headerRowIndex, 1, headerRowIndex + 1, 1);
                worksheet.mergeCells(headerRowIndex, 2, headerRowIndex + 1, 2);
                worksheet.mergeCells(headerRowIndex, 3, headerRowIndex + 1, 3);
