                worksheet.mergeCells(headerRowIndex, 9, headerRowIndex, 10);
                worksheet.mergeCells(headerRowIndex, 11, headerRowIndex + 1, 11);
                worksheet.mergeCells(headerRowIndex, 12, headerRowIndex + 1, 12);
