            if (data.total === 0 && (selectedMainAgency || selectedIntegration || selectedProvince || selectedRegion)) return null;
            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";
            if (node.type === 'plan') {
                rowClass = "bg-slate-100 dark:bg-slate-800/80 text-blue-900 dark:text-blue-300";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-900/50 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                plClass = "pl-12";
            } else {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = node.type === 'activity' ? "pl-16" : "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-emerald-50 dark:hover:bg-emerald-900/10 transition-colors`}>
                        <td className={`${cellBorder} px-2 py-1.5 text-left ${plClass} ${fontClass}`}>{node.title}</td>
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.target : ''}</td>
