            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
            inputValidator: (value) => { if (!value) return 'กรุณาระบุหัวข้อรายงาน'; }
        });
        if (newTitle) {
            setReportTitle(newTitle);
            localStorage.setItem('customReportTitle', newTitle);
        }
    };

    // Styling Constants
    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-300 dark:border-slate-700";
    const cellBorder = "border border-slate-200 dark:border-slate-800";

    // Vertical text style
    const verticalTextStyle: React.CSSProperties = {
        writingMode: 'vertical-rl',
        transform: 'rotate(180deg)',
        whiteSpace: 'nowrap',
        textAlign: 'center',
        height: '100px', // Ensure enough height
    };

    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node) => {
            const data = calculateNodeData(node);
            if (data.total === 0 && (selectedMainAgency || selectedIntegration || selectedProvince || selectedRegion)) return null;
            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";
            if (node.type === 'plan') {
                rowClass = "bg-slate-100 dark:bg-slate-800/80 text-blue-900 dark:text-blue-300";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-900/50 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                plClass = "pl-12";
            } else {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = node.type === 'activity' ? "pl-16" : "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-emerald-50 dark:hover:bg-emerald-900/10 transition-colors`}>
                        <td className={`${cellBorder} px-2 py-1.5 text-left ${plClass} ${fontClass}`}>{node.title}</td>
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.target : ''}</td>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.unit : ''}</td>
                            </>
                        )}
                        {reportMode === 'full' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.governmentCompensation > 0 ? formatNumber(data.governmentCompensation) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.compensationSupplies > 0 ? formatNumber(data.compensationSupplies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.contractEmployees > 0 ? formatNumber(data.contractEmployees) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.utilities > 0 ? formatNumber(data.utilities) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.equipment > 0 ? formatNumber(data.equipment) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.landConstruction > 0 ? formatNumber(data.landConstruction) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.subsidies > 0 ? formatNumber(data.subsidies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.otherExpenses > 0 ? formatNumber(data.otherExpenses) : '-'}</td>
                            </>
                        )}
                        {reportMode === 'province' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getRegularBudget(data) > 0 ? formatNumber(getRegularBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getInvestmentBudget(data) > 0 ? formatNumber(getInvestmentBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>-</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>-</td>
                            </>
                        )}
                        <td className={`${cellBorder} px-1 py-1 text-right font-bold ${node.type === 'plan' ? 'text-blue-900 dark:text-blue-300' : ''}`}>
                            {data.total > 0 ? formatNumber(data.total) : '-'}
                        </td>
                    </tr>
                    {node.children && renderHierarchy(node.children)}
                </React.Fragment>
            );
        });
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 10mm; }
                    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                    nav, footer, .print\\:hidden, .swal2-container { display: none !important; }
                    #root > div { min-height: auto; }
                    .bg-slate-50, .dark .bg-slate-900 { background: white !important; }
                    /* Force visibility of report container */
                    #report-view-container { 
                        display: block !important; 
                        width: 100% !important; 
                        max-width: 100% !important; 
                        margin: 0 !important; 
                        padding: 0 !important;
                        overflow: visible !important;
                    }
                    /* Ensure table doesn't overflow */
                    table { width: 100% !important; border-collapse: collapse; }
                    th, td { border: 1px solid #94a3b8 !important; }
                }
            `}</style>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4 print:hidden">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">รายงานสรุปงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">ระบบประมวลผลการจัดสรรงบประมาณ</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="relative" ref={dropdownRef}>
                        <button 
                            onClick={() => setDownloadDropdownOpen(!downloadDropdownOpen)}
                            disabled={isLoading}
                            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 dark:bg-emerald-700 text-white rounded-xl hover:bg-emerald-700 dark:hover:bg-emerald-600 transition-all font-medium text-base shadow-lg disabled:opacity-50"
                        >
                            {isLoading ? <RefreshCw className="animate-spin" size={18} /> : <Download size={18} />} 
                            ดาวน์โหลด <ChevronDown size={16} className={`transition-transform duration-200 ${downloadDropdownOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {downloadDropdownOpen && (
                            <div className="absolute right-0 mt-2 w-56 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-100 dark:border-slate-700 z-50 animate-in fade-in zoom-in-95 duration-200 overflow-hidden">
                                <button 
                                    onClick={handleDownloadExcel}
                                    className="w-full flex items-center gap-3 px-4 py-3.5 text-left text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors border-b border-slate-50 dark:border-slate-700/50"
                                >
                                    <div className="p-1.5 bg-green-50 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-lg">
                                        <FileSpreadsheet size={18} />
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="font-bold text-sm">Excel (.xlsx)</span>
                                        <span className="text-[11px] text-slate-400">สไตล์และรูปแบบเดียวกับเว็บ</span>
                                    </div>
                                </button>
                                <button 
                                    onClick={handleDownloadPdf}
                                    className="w-full flex items-center gap-3 px-4 py-3.5 text-left text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors"
                                >
                                    <div className="p-1.5 bg-rose-50 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-lg">
                                        <FileText size={18} />
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="font-bold text-sm">PDF (.pdf)</span>
                                        <span className="text-[11px] text-slate-400">ไฟล์เอกสารจริง (คัดลอกได้)</span>
                                    </div>
                                </button>
                            </div>
                        )}
                    </div>
                    <button onClick={handlePrint} className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 dark:bg-slate-700 text-white dark:text-slate-200 rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-lg">
                        <Printer size={18} /> พิมพ์รายงาน
                    </button>
                </div>
            </div>

            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-8 print:hidden">
                <div className="flex items-center gap-2 mb-4 text-emerald-700 dark:text-emerald-400 font-semibold border-b border-slate-100 dark:border-slate-700 pb-2">
                    <Filter size={20} /> ตัวกรองข้อมูล
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    <AutocompleteInput id="filter-main" label="หน่วยงานหลัก" value={selectedMainAgency} onChange={setSelectedMainAgency} options={dropdowns.mainAgency} placeholder="เลือกหน่วยงานหลัก..." />
                    <AutocompleteInput id="filter-integ" label="รายการบูรณาการ" value={selectedIntegration} onChange={setSelectedIntegration} options={dropdowns.integration} placeholder="เลือกรายการบูรณาการ..." />
                    <AutocompleteInput id="filter-region" label="ภูมิภาค" value={selectedRegion} onChange={setSelectedRegion} options={regionOptions} placeholder="เลือกภูมิภาค..." />
                    <AutocompleteInput id="filter-prov" label="จังหวัด" value={selectedProvince} onChange={setSelectedProvince} options={provinceOptions} placeholder="เลือกจังหวัด..." />
                </div>
                <div className="flex flex-col md:flex-row gap-8 p-5 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-700">
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'full' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'full' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'full'} onChange={() => setReportMode('full')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'full' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>แสดงรายละเอียดครบถ้วน</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'summary' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'summary' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'summary'} onChange={() => setReportMode('summary')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'summary' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>สรุปงบประมาณ (ยอดรวม)</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'province' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'province' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'province'} onChange={() => setReportMode('province')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'province' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>จำแนกรายจังหวัด (งบประจำ/ลงทุน)</span>
                    </label>
                </div>
            </div>

            <div id="report-view-container" className="bg-white dark:bg-slate-900 p-10 rounded-none shadow-xl border border-slate-100 dark:border-slate-800 overflow-x-auto min-w-[1000px] text-slate-900 dark:text-slate-100 transition-colors print:p-0 print:border-none print:shadow-none print:w-full print:max-w-none print:overflow-visible">
                <div className="flex flex-col items-center justify-center mb-8 text-center">
                    <div className="flex items-center gap-3 group relative cursor-pointer" onClick={handleEditTitle}>
                        <h3 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-emerald-600 transition-colors" style={fontStyle}>{reportTitle}</h3>
                        <div className="p-1.5 text-slate-400 group-hover:text-emerald-500 group-hover:bg-emerald-50 dark:group-hover:bg-emerald-900/30 rounded-lg transition-all opacity-40 group-hover:opacity-100 print:hidden"><Edit2 size={18} /></div>
                    </div>
                    <p className="text-lg font-bold mt-2 text-slate-700 dark:text-slate-300" style={fontStyle}>{[selectedMainAgency, selectedIntegration, selectedRegion, selectedProvince ? `จังหวัด${selectedProvince}` : ''].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน'}</p>
                </div>

                <table className="w-full border-collapse border border-slate-400 dark:border-slate-600 text-[18px] leading-tight" style={fontStyle}>
                    <thead>
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-2 ${reportMode === 'summary' ? 'w-2/3' : 'w-64'}`} rowSpan={2}>แผนงาน - ผลผลิต - กิจกรรม/โครงการ</th>
                            {reportMode !== 'summary' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-12`} rowSpan={2}><div style={verticalTextStyle}>เป้าหมาย</div></th>
                                    <th className={`${headerBorder} p-1 w-12`} rowSpan={2}><div style={verticalTextStyle}>หน่วยนับ</div></th>
                                </>
                            )}
                            {reportMode === 'full' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบบุคลากร</th>
                                    <th className={`${headerBorder} p-1`} colSpan={3}>งบดำเนินงาน</th>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบลงทุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>เงินอุดหนุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>รายจ่ายอื่น</th>
                                </>
                            )}
                            {reportMode === 'province' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบประมาณตาม พ.ร.บ. ปี {budgetYear}</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>เงินนอก<br/>งบประมาณ</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>งบกลาง<br/>ปี {budgetYear}</th>
                                </>
                            )}
                            <th className={`${headerBorder} p-1 ${reportMode === 'summary' ? 'w-1/3' : 'w-32'}`} rowSpan={2}>รวมทั้งสิ้น (บาท)</th>
                        </tr>
                        {reportMode === 'full' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-800 dark:text-slate-200">
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>เงินเดือนฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>พนง.ราชการ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ใช้สอย/วัสดุ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>จ้างเหมาฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>สาธารณูปโภค</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ค่าครุภัณฑ์</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ที่ดินฯ</th>
                            </tr>
                        )}
                        {reportMode === 'province' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-800 dark:text-slate-200">
                                <th className={`${headerBorder} p-1 w-32`}>งบประจำ</th>
                                <th className={`${headerBorder} p-1 w-32`}>งบลงทุน</th>
                            </tr>
                        )}
                    </thead>
                    <tbody>
                        <tr className="bg-emerald-50/50 dark:bg-emerald-900/30 font-bold text-slate-900 dark:text-slate-100">
                            <td className={`${headerBorder} px-3 py-2 text-left`}>รวมทั้งสิ้น</td>
                            {reportMode !== 'summary' && (<><td className={`${headerBorder} px-1 py-1 text-center`}></td><td className={`${headerBorder} px-1 py-1 text-center`}></td></>)}
                            {reportMode === 'full' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.salaryPermanent)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.governmentCompensation)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.compensationSupplies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.contractEmployees)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.utilities)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.equipment)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.landConstruction)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.subsidies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.otherExpenses)}</td>
                                </>
                            )}
                            {reportMode === 'province' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getRegularBudget(grandTotal))}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getInvestmentBudget(grandTotal))}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>-</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>-</td>
                                </>
                            )}
                            <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.total)}</td>
                        </tr>
                        {renderHierarchy(reportHierarchy)}
                        {uncategorizedRecords.length > 0 && (
                            <>
                                <tr className="bg-rose-50 dark:bg-rose-900/20 text-rose-800 dark:text-rose-300 font-bold">
                                    <td className={`${headerBorder} px-3 py-2 text-left`} colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 8 : 2}>*** รายการอื่นๆ (อยู่นอกโครงสร้างหลัก) ***</td>
                                </tr>
                                {uncategorizedRecords.map((r, idx) => (
                                    <tr key={`uncat-${idx}`} className="hover:bg-rose-100/30 dark:hover:bg-rose-900/10 text-slate-800 dark:text-slate-300">
                                        <td className={`${headerBorder} px-3 py-1.5 text-left pl-8`}>- {r.activity}</td>
                                        {reportMode !== 'summary' && (<><td className={`${headerBorder} px-1 py-1 text-center`}>{r.target}</td><td className={`${headerBorder} px-1 py-1 text-center`}>{r.unit}</td></>)}
                                        {reportMode === 'full' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.salaryPermanent)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.governmentCompensation)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.compensationSupplies)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.contractEmployees)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.utilities)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.equipment)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.landConstruction)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.subsidies)}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(r.otherExpenses)}</td>
                                            </>
                                        )}
                                        {reportMode === 'province' && (
                                            <>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getRegularBudget(r as any))}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(getInvestmentBudget(r as any))}</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>-</td>
                                                <td className={`${headerBorder} px-1 py-1 text-right`}>-</td>
                                            </>
                                        )}
                                        <td className={`${headerBorder} px-1 py-1 text-right font-bold`}>{formatNumber(r.total)}</td>
                                    </tr>
                                ))}
                            </>
                        )}
                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 8 : 2} className={`${headerBorder} px-4 py-16 text-center text-slate-400 dark:text-slate-600`}>
                                    <div className="flex flex-col items-center gap-3">
                                        <AlertCircle size={40} className="opacity-20" />
                                        <span className="text-xl">ไม่พบข้อมูลตามเงื่อนไขที่ระบุ</span>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ReportView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dataService } from '../../services/dataService';
import { formatNumber, parseNumber } from '../../utils';
import { Printer, Filter, CheckCircle2, Circle, AlertCircle, Edit2, Download, FileSpreadsheet, FileText, ChevronDown, RefreshCw } from 'lucide-react';
import { BudgetRecord, ReportNode } from '../../types';
import AutocompleteInput from '../Form/AutocompleteInput';
import Swal from 'sweetalert2';

type ReportMode = 'full' | 'summary' | 'province';

const ReportView: React.FC = () => {
    const records = dataService.getRecords();
    const dropdowns = dataService.getDropdowns();
    const regionData = dataService.getRegionData();

    // UI States
    const [downloadDropdownOpen, setDownloadDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const [isLoading, setIsLoading] = useState(false);

    // Structure State
    const [reportHierarchy, setReportHierarchy] = useState<ReportNode[]>([]);

    // Custom Report Title State
    const [reportTitle, setReportTitle] = useState(() => {
        return localStorage.getItem('customReportTitle') || 'การจัดสรรงบประมาณกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ประจำปี พ.ศ. 2569';
    });

    // Extract year from title
    const budgetYear = useMemo(() => {
        const match = reportTitle.match(/พ\.ศ\.\s*(\d{4})/) || reportTitle.match(/(\d{4})/);
        return match ? match[1] : '2569';
    }, [reportTitle]);

    useEffect(() => {
        const structure = dataService.getReportStructure();
        if (structure && structure.length > 0) {
             setReportHierarchy(structure);
        }

        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setDownloadDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Filter State
    const [selectedMainAgency, setSelectedMainAgency] = useState('');
    const [selectedIntegration, setSelectedIntegration] = useState('');
    const [selectedRegion, setSelectedRegion] = useState('');
    const [selectedProvince, setSelectedProvince] = useState('');
    const [reportMode, setReportMode] = useState<ReportMode>('full');

    // Reset province when region changes
    useEffect(() => {
        if (selectedRegion) setSelectedProvince('');
    }, [selectedRegion]);

    const filteredRecords = useMemo(() => {
        // Prepare region provinces set for faster lookup
        const currentRegion = selectedRegion ? regionData.find(r => r.regionName === selectedRegion) : null;
        const regionProvinces = currentRegion ? currentRegion.provinces : null;

        return records.filter(r => {
            const rMain = (r.mainAgency || '').trim();
            const rInteg = (r.integration || '').trim();
            const rProv = (r.province || '').trim();

            const matchesMain = selectedMainAgency ? rMain === selectedMainAgency.trim() : true;
            const matchesInteg = selectedIntegration ? (rInteg === selectedIntegration.trim() || rInteg.includes(selectedIntegration.trim())) : true;
            const matchesRegion = regionProvinces ? regionProvinces.includes(rProv) : true;
            const matchesProv = selectedProvince ? rProv === selectedProvince.trim() : true;

            return matchesMain && matchesInteg && matchesRegion && matchesProv;
        });
    }, [records, selectedMainAgency, selectedIntegration, selectedProvince, selectedRegion, regionData]);

    const regionOptions = useMemo(() => regionData.map(r => r.regionName), [regionData]);

    const provinceOptions = useMemo(() => {
        if (selectedRegion) {
            const region = regionData.find(r => r.regionName === selectedRegion);
            return region ? region.provinces : [];
        }
        return dropdowns.province;
    }, [selectedRegion, regionData, dropdowns.province]);

    const initialAggregatedData = {
        salaryPermanent: 0, governmentCompensation: 0, compensationSupplies: 0, contractEmployees: 0,
        utilities: 0, equipment: 0, landConstruction: 0, subsidies: 0, otherExpenses: 0,
        target: '0', unit: '', total: 0
    };

    const getAggregatedData = (activityName: string) => {
        const activityTrimmed = activityName.trim();
        const matches = filteredRecords.filter(r => (r.activity || '').trim() === activityTrimmed);
        if (matches.length === 0) return null;
        const agg = matches.reduce((acc, r) => ({
            ...acc,
            salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
            governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
            compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
            contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
            utilities: acc.utilities + (r.utilities || 0),
            equipment: acc.equipment + (r.equipment || 0),
            landConstruction: acc.landConstruction + (r.landConstruction || 0),
            subsidies: acc.subsidies + (r.subsidies || 0),
            otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
            target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
            unit: r.unit || acc.unit
        }), { ...initialAggregatedData });
        const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                      agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                      agg.subsidies + agg.otherExpenses;
        return { ...agg, total };
    };

    const calculateNodeData = (node: ReportNode): typeof initialAggregatedData => {
        let currentTotal = { ...initialAggregatedData };
        if (node.activityMatcher) {
            const directData = getAggregatedData(node.activityMatcher);
            if (directData) {
                currentTotal = sumAggregatedData(currentTotal, directData);
                currentTotal.target = directData.target;
                currentTotal.unit = directData.unit;
            }
        }
        if (node.children && node.children.length > 0) {
            node.children.forEach(child => {
                const childTotal = calculateNodeData(child);
                currentTotal = sumAggregatedData(currentTotal, childTotal);
            });
        }
        return currentTotal;
    };

    const sumAggregatedData = (a: typeof initialAggregatedData, b: typeof initialAggregatedData) => {
        return {
            ...a,
            salaryPermanent: a.salaryPermanent + b.salaryPermanent,
            governmentCompensation: a.governmentCompensation + b.governmentCompensation,
            compensationSupplies: a.compensationSupplies + b.compensationSupplies,
            contractEmployees: a.contractEmployees + b.contractEmployees,
            utilities: a.utilities + b.utilities,
            equipment: a.equipment + b.equipment,
            landConstruction: a.landConstruction + b.landConstruction,
            subsidies: a.subsidies + b.subsidies,
            otherExpenses: a.otherExpenses + b.otherExpenses,
            total: a.total + b.total,
            target: a.target, 
            unit: a.unit
        };
    };

    const getRegularBudget = (data: typeof initialAggregatedData) => {
        return data.salaryPermanent + data.governmentCompensation + data.compensationSupplies + 
               data.contractEmployees + data.utilities + data.subsidies + data.otherExpenses;
    };

    const getInvestmentBudget = (data: typeof initialAggregatedData) => {
        return data.equipment + data.landConstruction;
    };

    const usedActivities = useMemo(() => {
        const set = new Set<string>();
        const traverse = (nodes: ReportNode[]) => {
            nodes.forEach(node => {
                if (node.activityMatcher) set.add(node.activityMatcher.trim());
                if (node.children) traverse(node.children);
            });
        };
        traverse(reportHierarchy);
        return set;
    }, [reportHierarchy]);

    const uncategorizedRecords = useMemo(() => {
        const groups: Record<string, BudgetRecord[]> = {};
        filteredRecords.forEach(r => {
            const name = (r.activity || '').trim();
            if (name && !usedActivities.has(name)) {
                if (!groups[name]) groups[name] = [];
                groups[name].push(r);
            }
        });
        return Object.keys(groups).map(name => {
            const matches = groups[name];
            const agg = matches.reduce((acc, r) => ({
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                target: parseNumber(r.target || '0') > parseNumber(acc.target) ? r.target : acc.target,
                unit: r.unit || acc.unit
            }), { ...initialAggregatedData });
            const total = agg.salaryPermanent + agg.governmentCompensation + agg.compensationSupplies + 
                          agg.contractEmployees + agg.utilities + agg.equipment + agg.landConstruction + 
                          agg.subsidies + agg.otherExpenses;
            return { activity: name, ...agg, total };
        });
    }, [filteredRecords, usedActivities]);

    const grandTotal = useMemo(() => {
        return filteredRecords.reduce((acc, r) => {
            const rowTotal = (r.salaryPermanent || 0) + (r.governmentCompensation || 0) + 
                             (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0) +
                             (r.equipment || 0) + (r.landConstruction || 0) +
                             (r.subsidies || 0) + (r.otherExpenses || 0);
            return {
                ...acc,
                salaryPermanent: acc.salaryPermanent + (r.salaryPermanent || 0),
                governmentCompensation: acc.governmentCompensation + (r.governmentCompensation || 0),
                compensationSupplies: acc.compensationSupplies + (r.compensationSupplies || 0),
                contractEmployees: acc.contractEmployees + (r.contractEmployees || 0),
                utilities: acc.utilities + (r.utilities || 0),
                equipment: acc.equipment + (r.equipment || 0),
                landConstruction: acc.landConstruction + (r.landConstruction || 0),
                subsidies: acc.subsidies + (r.subsidies || 0),
                otherExpenses: acc.otherExpenses + (r.otherExpenses || 0),
                total: acc.total + rowTotal
            };
        }, { ...initialAggregatedData });
    }, [filteredRecords]);

    const handlePrint = () => {
        setTimeout(() => {
            window.print();
        }, 100);
    };

    const handleDownloadExcel = async () => {
        setIsLoading(true);
        setDownloadDropdownOpen(false);
        try {
            // Fix: Correctly access ExcelJS from the default export of the dynamic import
            const exceljsModule = await import('https://esm.sh/exceljs');
            const ExcelJS = exceljsModule.default || exceljsModule;
            const workbook = new ExcelJS.Workbook();
            const worksheet = workbook.addWorksheet('Report');

            // 1. Define Columns based on mode
            let columns: any[] = [{ header: 'แผนงาน - ผลผลิต - กิจกรรม/โครงการ', key: 'title', width: 60 }];
            if (reportMode !== 'summary') {
                columns.push({ header: 'เป้าหมาย', key: 'target', width: 10 }); // Narrower for vertical
                columns.push({ header: 'หน่วยนับ', key: 'unit', width: 10 }); // Narrower for vertical
            }

            if (reportMode === 'full') {
                const bCols = [
                    { header: 'เงินเดือนฯ', key: 'salaryPermanent', width: 18 },
                    { header: 'พนง.ราชการ', key: 'governmentCompensation', width: 18 },
                    { header: 'ใช้สอย/วัสดุ', key: 'compensationSupplies', width: 18 },
                    { header: 'จ้างเหมาฯ', key: 'contractEmployees', width: 18 },
                    { header: 'สาธารณูปโภค', key: 'utilities', width: 18 },
                    { header: 'ค่าครุภัณฑ์', key: 'equipment', width: 18 },
                    { header: 'ที่ดินฯ', key: 'landConstruction', width: 18 },
                    { header: 'เงินอุดหนุน', key: 'subsidies', width: 18 },
                    { header: 'รายจ่ายอื่น', key: 'otherExpenses', width: 18 }
                ];
                columns = [...columns, ...bCols];
            } else if (reportMode === 'province') {
                columns.push({ header: 'งบประจำ', key: 'regular', width: 20 });
                columns.push({ header: 'งบลงทุน', key: 'investment', width: 20 });
                columns.push({ header: 'เงินนอกงบประมาณ', key: 'nonBudget', width: 15 });
                columns.push({ header: `งบกลาง ปี ${budgetYear}`, key: 'centralBudget', width: 15 });
            }
            columns.push({ header: 'รวมทั้งสิ้น', key: 'total', width: 22 });
            worksheet.columns = columns;

            // 2. Report Header Titles
            worksheet.insertRow(1, [reportTitle]);
            worksheet.mergeCells(1, 1, 1, columns.length);
            worksheet.getRow(1).height = 30;
            worksheet.getCell('A1').font = { name: 'Sarabun', size: 16, bold: true };
            worksheet.getCell('A1').alignment = { vertical: 'middle', horizontal: 'center' };

            const subTitleStr = [
                selectedMainAgency, 
                selectedIntegration, 
                selectedRegion ? selectedRegion : '',
                selectedProvince ? `จังหวัด${selectedProvince}` : ''
            ].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน';

            worksheet.insertRow(2, [subTitleStr]);
            worksheet.mergeCells(2, 1, 2, columns.length);
            worksheet.getRow(2).height = 20;
            worksheet.getCell('A2').font = { name: 'Sarabun', size: 12, bold: true };
            worksheet.getCell('A2').alignment = { vertical: 'middle', horizontal: 'center' };

            // 3. Table Header Formatting
            let headerRowIndex = 4;
            if (reportMode === 'full') {
                const topHeader = ['แผนงาน - ผลผลิต - กิจกรรม/โครงการ', 'เป้าหมาย', 'หน่วยนับ', 'งบบุคลากร', '', 'งบดำเนินงาน', '', '', 'งบลงทุน', '', 'เงินอุดหนุน', 'รายจ่ายอื่น', 'รวมทั้งสิ้น'];
                const rowH1 = worksheet.insertRow(headerRowIndex, topHeader);
                const rowH2 = worksheet.addRow(['', '', '', 'เงินเดือนฯ', 'พนง.ราชการ', 'ใช้สอย/วัสดุ', 'จ้างเหมาฯ', 'สาธารณูปโภค', 'ค่าครุภัณฑ์', 'ที่ดินฯ', '', '', '']);

                [rowH1, rowH2].forEach(row => {
                    row.eachCell((cell) => {
                        cell.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF1F5F9'} };
                        cell.font = { bold: true };
                        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                        cell.alignment = { horizontal: 'center', vertical: 'middle' };
                    });
                });

                worksheet.mergeCells(headerRowIndex, 1, headerRowIndex + 1, 1);
                worksheet.mergeCells(headerRowIndex, 2, headerRowIndex + 1, 2);
                worksheet.mergeCells(headerRowIndex, 3, headerRowIndex + 1, 3);
                worksheet.mergeCells(headerRowIndex, 4, headerRowIndex, 5);
                worksheet.mergeCells(headerRowIndex, 6, headerRowIndex, 8);
                worksheet.mergeCells(headerRowIndex, 9, headerRowIndex, 10);
                worksheet.mergeCells(headerRowIndex, 11, headerRowIndex + 1, 11);
                worksheet.mergeCells(headerRowIndex, 12, headerRowIndex + 1, 12);
                worksheet.mergeCells(headerRowIndex, 13, headerRowIndex + 1, 13);
                headerRowIndex += 2;
            } else if (reportMode === 'province') {
                const topHeader = ['แผนงาน - ผลผลิต - กิจกรรม/โครงการ', 'เป้าหมาย', 'หน่วยนับ', `งบประมาณตาม พ.ร.บ. ปี ${budgetYear}`, '', 'เงินนอกงบประมาณ', `งบกลาง ปี ${budgetYear}`, 'รวมทั้งสิ้น (บาท)'];
                const rowH1 = worksheet.insertRow(headerRowIndex, topHeader);
                const rowH2 = worksheet.addRow(['', '', '', 'งบประจำ', 'งบลงทุน', '', '', '']);

                [rowH1, rowH2].forEach(row => {
                    row.eachCell((cell) => {
                        cell.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF1F5F9'} };
                        cell.font = { bold: true };
                        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
                    });
                });

                worksheet.mergeCells(headerRowIndex, 1, headerRowIndex + 1, 1); // Title
                worksheet.mergeCells(headerRowIndex, 2, headerRowIndex + 1, 2); // Target
                worksheet.getCell(headerRowIndex, 2).alignment = { textRotation: 90, horizontal: 'center', vertical: 'middle' };
                worksheet.mergeCells(headerRowIndex, 3, headerRowIndex + 1, 3); // Unit
                worksheet.getCell(headerRowIndex, 3).alignment = { textRotation: 90, horizontal: 'center', vertical: 'middle' };

                worksheet.mergeCells(headerRowIndex, 4, headerRowIndex, 5); // Budget 2569
                worksheet.mergeCells(headerRowIndex, 6, headerRowIndex + 1, 6); // Non-Budget
                worksheet.mergeCells(headerRowIndex, 7, headerRowIndex + 1, 7); // Central Budget
                worksheet.mergeCells(headerRowIndex, 8, headerRowIndex + 1, 8); // Total

                headerRowIndex += 2;
            } else {
                const rowH = worksheet.getRow(headerRowIndex);
                rowH.eachCell((cell) => {
                    cell.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF1F5F9'} };
                    cell.font = { bold: true };
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { horizontal: 'center', vertical: 'middle' };
                });
                headerRowIndex += 1;
            }

            // 4. Grand Total Row
            const addDataRow = (title: string, data: any, level: number = 0, nodeType?: string) => {
                const indent = '   '.repeat(level);
                let rowValues: any[] = [indent + title];

                if (reportMode !== 'summary') {
                    rowValues.push(data.target !== '0' ? data.target : '');
                    rowValues.push(data.unit || '');
                }

                if (reportMode === 'full') {
                    rowValues = [...rowValues, 
                        data.salaryPermanent, data.governmentCompensation, 
                        data.compensationSupplies, data.contractEmployees, data.utilities, 
                        data.equipment, data.landConstruction, 
                        data.subsidies, data.otherExpenses
                    ];
                } else if (reportMode === 'province') {
                    rowValues.push(getRegularBudget(data));
                    rowValues.push(getInvestmentBudget(data));
                    rowValues.push(0); // Non-Budget (Fixed 0)
                    rowValues.push(0); // Central Budget (Fixed 0)
                }
                rowValues.push(data.total);

                const row = worksheet.addRow(rowValues);

                // Style Row
                if (nodeType === 'plan') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFE2E8F0'} };
                        c.font = { bold: true, color: { argb: 'FF1E3A8A' } };
                    });
                } else if (nodeType === 'project' || nodeType === 'output') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFF8FAFC'} };
                        c.font = { bold: true };
                    });
                } else if (nodeType === 'grandTotal') {
                    row.eachCell(c => {
                        c.fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFD1FAE5'} };
                        c.font = { bold: true };
                    });
                }

                // Format numbers
                row.eachCell((cell, colNumber) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    const numStartCol = reportMode === 'summary' ? 2 : (reportMode === 'province' ? 4 : 4); 
                    if (colNumber >= numStartCol) {
                        cell.numFmt = '#,##0.00';
                        cell.alignment = { horizontal: 'right' };
                        // Specific for province 0 values to show as "-"
                        if (reportMode === 'province' && (colNumber === 6 || colNumber === 7) && cell.value === 0) {
                             cell.value = '-';
                             cell.alignment = { horizontal: 'right' };
                        }
                    }
                });
            };

            // Add Grand Total
            addDataRow('รวมทั้งสิ้น', grandTotal, 0, 'grandTotal');

            // 5. Recursive Tree Rows
            const traverseTree = (nodes: ReportNode[], level: number = 0) => {
                nodes.forEach(node => {
                    const data = calculateNodeData(node);
                    if (data.total > 0 || !(selectedMainAgency || selectedIntegration || selectedProvince || selectedRegion)) {
                        addDataRow(node.title, data, level, node.type);
                        if (node.children) traverseTree(node.children, level + 1);
                    }
                });
            };
            traverseTree(reportHierarchy);

            // 6. Uncategorized
            if (uncategorizedRecords.length > 0) {
                const uncatRow = worksheet.addRow(['*** รายการอื่นๆ (อยู่นอกโครงสร้างหลัก) ***']);
                uncatRow.getCell(1).font = { bold: true, color: { argb: 'FF991B1B' } };
                uncatRow.getCell(1).fill = { type: 'pattern', pattern:'solid', fgColor:{argb:'FFFFF1F2'} };

                uncategorizedRecords.forEach(r => {
                    addDataRow('- ' + r.activity, r, 1);
                });
            }

            // Export
            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${reportTitle}.xlsx`;
            a.click();
            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Excel Export Error:', error);
            Swal.fire('ผิดพลาด', 'ไม่สามารถสร้างไฟล์ Excel ได้', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownloadPdf = async () => {
        setIsLoading(true);
        setDownloadDropdownOpen(false);
        try {
            // Dynamic imports for PDF generation
            const { jsPDF } = await import('https://esm.sh/jspdf');
            const autoTableModule = await import('https://esm.sh/jspdf-autotable');
            const autoTable = autoTableModule.default;

            const doc = new jsPDF('l', 'mm', 'a4');

            // 1. Load Thai Font (Sarabun) from CDN
            const fontUrl = 'https://raw.githubusercontent.com/google/fonts/main/ofl/sarabun/Sarabun-Regular.ttf';
            const response = await fetch(fontUrl);
            if (!response.ok) throw new Error('Failed to load font');
            const blob = await response.blob();

            const base64Font = await new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => {
                    const res = reader.result as string;
                    // Extract base64 part
                    resolve(res.split(',')[1]);
                };
                reader.readAsDataURL(blob);
            });

            // 2. Register Font
            doc.addFileToVFS('Sarabun-Regular.ttf', base64Font);
            doc.addFont('Sarabun-Regular.ttf', 'Sarabun', 'normal');
            doc.addFont('Sarabun-Regular.ttf', 'Sarabun', 'bold'); // Map bold to regular for Thai support
            doc.setFont('Sarabun');

            // 3. Add Header Content
            doc.setFontSize(16);
            doc.text(reportTitle, 14, 15);

            doc.setFontSize(11);
            const subTitle = [
                selectedMainAgency, 
                selectedIntegration, 
                selectedRegion ? selectedRegion : '',
                selectedProvince ? `จังหวัด${selectedProvince}` : ''
            ].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน';
            doc.text(subTitle, 14, 22);

            // 4. Configure Column Styles based on Report Mode
            const colStyles: any = { 0: { halign: 'left' } };
            if (reportMode === 'summary') {
                colStyles[1] = { halign: 'right' };
            } else {
                colStyles[1] = { halign: 'center' }; // Target
                colStyles[2] = { halign: 'center' }; // Unit

                // Budget Columns (Right aligned)
                const startBudgetCol = 3;
                const endCol = reportMode === 'province' ? 7 : 12;
                for (let i = startBudgetCol; i <= endCol; i++) {
                    colStyles[i] = { halign: 'right' };
                }
            }

            // 5. Generate Table using jspdf-autotable
            // This reads the HTML table directly, preserving rowspans/colspans
            autoTable(doc, {
                html: '#report-view-container table',
                startY: 28,
                theme: 'grid',
                styles: {
                    font: 'Sarabun', // Use the registered font
                    fontSize: 10,
                    cellPadding: 1.5,
                    lineColor: [220, 220, 220],
                    lineWidth: 0.1,
                    textColor: [40, 40, 40],
                    valign: 'middle'
                },
                headStyles: {
                    fillColor: [240, 245, 250],
                    textColor: [30, 40, 50],
                    fontStyle: 'bold',
                    lineWidth: 0.1,
                    lineColor: [200, 200, 200],
                    halign: 'center',
                    valign: 'middle'
                },
                columnStyles: colStyles,
                didParseCell: (data: any) => {
                    // Ensure headers are bold
                    if (data.section === 'head') {
                        data.cell.styles.fontStyle = 'bold';
                    }
                }
            });

            // 6. Save File
            doc.save(`${reportTitle}.pdf`);

        } catch (error) {
            console.error('PDF Export Error:', error);
            Swal.fire('ผิดพลาด', 'ไม่สามารถสร้างไฟล์ PDF ได้ (ตรวจสอบการเชื่อมต่ออินเทอร์เน็ตเพื่อโหลดฟอนต์)', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleEditTitle = async () => {
        const { value: newTitle } = await Swal.fire({
            title: 'แก้ไขหัวข้อรายงาน',
            input: 'text',
            inputValue: reportTitle,
            showCancelButton: true,
            confirmButtonText: 'บันทึก',
            cancelButtonText: 'ยกเลิก',
            confirmButtonColor: '#059669',
            cancelButtonColor: '#94a3b8',
            inputValidator: (value) => { if (!value) return 'กรุณาระบุหัวข้อรายงาน'; }
        });
        if (newTitle) {
            setReportTitle(newTitle);
            localStorage.setItem('customReportTitle', newTitle);
        }
    };

    // Styling Constants
    const fontStyle = { fontFamily: '"TH SarabunPSK", "TH Sarabun New", "Sarabun", sans-serif' };
    const headerBorder = "border border-slate-300 dark:border-slate-700";
    const cellBorder = "border border-slate-200 dark:border-slate-800";

    // Vertical text style
    const verticalTextStyle: React.CSSProperties = {
        writingMode: 'vertical-rl',
        transform: 'rotate(180deg)',
        whiteSpace: 'nowrap',
        textAlign: 'center',
        height: '100px', // Ensure enough height
    };

    const renderHierarchy = (nodes: ReportNode[]) => {
        return nodes.map((node) => {
            const data = calculateNodeData(node);
            if (data.total === 0 && (selectedMainAgency || selectedIntegration || selectedProvince || selectedRegion)) return null;
            const isLeafActivity = (node.type === 'activity' || node.type === 'subactivity') && node.activityMatcher;
            const showTargetUnit = isLeafActivity && (data.target !== '0' || data.unit !== '');
            let rowClass = "";
            let plClass = "pl-2";
            let fontClass = "";
            if (node.type === 'plan') {
                rowClass = "bg-slate-100 dark:bg-slate-800/80 text-blue-900 dark:text-blue-300";
                fontClass = "font-bold";
            } else if (node.type === 'project' || node.type === 'output') {
                rowClass = "bg-slate-50 dark:bg-slate-900/50 text-slate-900 dark:text-slate-100";
                fontClass = "font-bold";
                plClass = "pl-6";
            } else if (node.type === 'group') {
                fontClass = "font-semibold text-slate-900 dark:text-slate-100";
                plClass = "pl-8";
            } else if (node.type === 'subgroup') {
                fontClass = "font-medium italic text-slate-800 dark:text-slate-200";
                plClass = "pl-12";
            } else {
                rowClass = "dark:bg-slate-900 text-slate-800 dark:text-slate-300";
                plClass = node.type === 'activity' ? "pl-16" : "pl-20";
            }

            return (
                <React.Fragment key={node.id}>
                    <tr className={`${rowClass} hover:bg-emerald-50 dark:hover:bg-emerald-900/10 transition-colors`}>
                        <td className={`${cellBorder} px-2 py-1.5 text-left ${plClass} ${fontClass}`}>{node.title}</td>
                        {reportMode !== 'summary' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.target : ''}</td>
                                <td className={`${cellBorder} px-1 py-1 text-center font-normal`}>{showTargetUnit ? data.unit : ''}</td>
                            </>
                        )}
                        {reportMode === 'full' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.salaryPermanent > 0 ? formatNumber(data.salaryPermanent) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.governmentCompensation > 0 ? formatNumber(data.governmentCompensation) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.compensationSupplies > 0 ? formatNumber(data.compensationSupplies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.contractEmployees > 0 ? formatNumber(data.contractEmployees) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.utilities > 0 ? formatNumber(data.utilities) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.equipment > 0 ? formatNumber(data.equipment) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.landConstruction > 0 ? formatNumber(data.landConstruction) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.subsidies > 0 ? formatNumber(data.subsidies) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{data.otherExpenses > 0 ? formatNumber(data.otherExpenses) : '-'}</td>
                            </>
                        )}
                        {reportMode === 'province' && (
                            <>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getRegularBudget(data) > 0 ? formatNumber(getRegularBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>{getInvestmentBudget(data) > 0 ? formatNumber(getInvestmentBudget(data)) : '-'}</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>-</td>
                                <td className={`${cellBorder} px-1 py-1 text-right ${fontClass}`}>-</td>
                            </>
                        )}
                        <td className={`${cellBorder} px-1 py-1 text-right font-bold ${node.type === 'plan' ? 'text-blue-900 dark:text-blue-300' : ''}`}>
                            {data.total > 0 ? formatNumber(data.total) : '-'}
                        </td>
                    </tr>
                    {node.children && renderHierarchy(node.children)}
                </React.Fragment>
            );
        });
    };

    return (
        <div className="max-w-[98vw] mx-auto px-4 py-8">
            <style>{`
                @media print {
                    @page { size: landscape; margin: 10mm; }
                    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                    nav, footer, .print\\:hidden, .swal2-container { display: none !important; }
                    #root > div { min-height: auto; }
                    .bg-slate-50, .dark .bg-slate-900 { background: white !important; }
                    /* Force visibility of report container */
                    #report-view-container { 
                        display: block !important; 
                        width: 100% !important; 
                        max-width: 100% !important; 
                        margin: 0 !important; 
                        padding: 0 !important;
                        overflow: visible !important;
                    }
                    /* Ensure table doesn't overflow */
                    table { width: 100% !important; border-collapse: collapse; }
                    th, td { border: 1px solid #94a3b8 !important; }
                }
            `}</style>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4 print:hidden">
                <div>
                    <h2 className="text-3xl font-bold text-slate-800 dark:text-white mb-2 transition-colors">รายงานสรุปงบประมาณ</h2>
                    <p className="text-base text-slate-500 dark:text-slate-400 transition-colors">ระบบประมวลผลการจัดสรรงบประมาณ</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="relative" ref={dropdownRef}>
                        <button 
                            onClick={() => setDownloadDropdownOpen(!downloadDropdownOpen)}
                            disabled={isLoading}
                            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 dark:bg-emerald-700 text-white rounded-xl hover:bg-emerald-700 dark:hover:bg-emerald-600 transition-all font-medium text-base shadow-lg disabled:opacity-50"
                        >
                            {isLoading ? <RefreshCw className="animate-spin" size={18} /> : <Download size={18} />} 
                            ดาวน์โหลด <ChevronDown size={16} className={`transition-transform duration-200 ${downloadDropdownOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {downloadDropdownOpen && (
                            <div className="absolute right-0 mt-2 w-56 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-100 dark:border-slate-700 z-50 animate-in fade-in zoom-in-95 duration-200 overflow-hidden">
                                <button 
                                    onClick={handleDownloadExcel}
                                    className="w-full flex items-center gap-3 px-4 py-3.5 text-left text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors border-b border-slate-50 dark:border-slate-700/50"
                                >
                                    <div className="p-1.5 bg-green-50 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-lg">
                                        <FileSpreadsheet size={18} />
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="font-bold text-sm">Excel (.xlsx)</span>
                                        <span className="text-[11px] text-slate-400">สไตล์และรูปแบบเดียวกับเว็บ</span>
                                    </div>
                                </button>
                                <button 
                                    onClick={handleDownloadPdf}
                                    className="w-full flex items-center gap-3 px-4 py-3.5 text-left text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors"
                                >
                                    <div className="p-1.5 bg-rose-50 dark:bg-rose-900/30 text-rose-600 dark:text-rose-400 rounded-lg">
                                        <FileText size={18} />
                                    </div>
                                    <div className="flex flex-col">
                                        <span className="font-bold text-sm">PDF (.pdf)</span>
                                        <span className="text-[11px] text-slate-400">ไฟล์เอกสารจริง (คัดลอกได้)</span>
                                    </div>
                                </button>
                            </div>
                        )}
                    </div>
                    <button onClick={handlePrint} className="flex items-center gap-2 px-5 py-2.5 bg-slate-800 dark:bg-slate-700 text-white dark:text-slate-200 rounded-xl hover:bg-slate-700 dark:hover:bg-slate-600 transition-all font-medium text-base shadow-lg">
                        <Printer size={18} /> พิมพ์รายงาน
                    </button>
                </div>
            </div>

            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 mb-8 print:hidden">
                <div className="flex items-center gap-2 mb-4 text-emerald-700 dark:text-emerald-400 font-semibold border-b border-slate-100 dark:border-slate-700 pb-2">
                    <Filter size={20} /> ตัวกรองข้อมูล
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    <AutocompleteInput id="filter-main" label="หน่วยงานหลัก" value={selectedMainAgency} onChange={setSelectedMainAgency} options={dropdowns.mainAgency} placeholder="เลือกหน่วยงานหลัก..." />
                    <AutocompleteInput id="filter-integ" label="รายการบูรณาการ" value={selectedIntegration} onChange={setSelectedIntegration} options={dropdowns.integration} placeholder="เลือกรายการบูรณาการ..." />
                    <AutocompleteInput id="filter-region" label="ภูมิภาค" value={selectedRegion} onChange={setSelectedRegion} options={regionOptions} placeholder="เลือกภูมิภาค..." />
                    <AutocompleteInput id="filter-prov" label="จังหวัด" value={selectedProvince} onChange={setSelectedProvince} options={provinceOptions} placeholder="เลือกจังหวัด..." />
                </div>
                <div className="flex flex-col md:flex-row gap-8 p-5 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-700">
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'full' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'full' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'full'} onChange={() => setReportMode('full')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'full' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>แสดงรายละเอียดครบถ้วน</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'summary' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'summary' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'summary'} onChange={() => setReportMode('summary')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'summary' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>สรุปงบประมาณ (ยอดรวม)</span>
                    </label>
                    <label className="flex items-center gap-3 cursor-pointer group">
                        <div className={`transition-all duration-200 ${reportMode === 'province' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'province' ? <CheckCircle2 size={24} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={24} />}</div>
                        <input type="radio" name="reportMode" className="hidden" checked={reportMode === 'province'} onChange={() => setReportMode('province')} />
                        <span className={`font-semibold text-lg transition-colors ${reportMode === 'province' ? 'text-emerald-700 dark:text-emerald-400' : 'text-slate-500'}`}>จำแนกรายจังหวัด (งบประจำ/ลงทุน)</span>
                    </label>
                </div>
            </div>

            <div id="report-view-container" className="bg-white dark:bg-slate-900 p-10 rounded-none shadow-xl border border-slate-100 dark:border-slate-800 overflow-x-auto min-w-[1000px] text-slate-900 dark:text-slate-100 transition-colors print:p-0 print:border-none print:shadow-none print:w-full print:max-w-none print:overflow-visible">
                <div className="flex flex-col items-center justify-center mb-8 text-center">
                    <div className="flex items-center gap-3 group relative cursor-pointer" onClick={handleEditTitle}>
                        <h3 className="text-2xl font-bold text-slate-900 dark:text-white group-hover:text-emerald-600 transition-colors" style={fontStyle}>{reportTitle}</h3>
                        <div className="p-1.5 text-slate-400 group-hover:text-emerald-500 group-hover:bg-emerald-50 dark:group-hover:bg-emerald-900/30 rounded-lg transition-all opacity-40 group-hover:opacity-100 print:hidden"><Edit2 size={18} /></div>
                    </div>
                    <p className="text-lg font-bold mt-2 text-slate-700 dark:text-slate-300" style={fontStyle}>{[selectedMainAgency, selectedIntegration, selectedRegion, selectedProvince ? `จังหวัด${selectedProvince}` : ''].filter(Boolean).join(' - ') || 'ภาพรวมทุกหน่วยงาน'}</p>
                </div>

                <table className="w-full border-collapse border border-slate-400 dark:border-slate-600 text-[18px] leading-tight" style={fontStyle}>
                    <thead>
                        <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-900 dark:text-slate-100">
                            <th className={`${headerBorder} p-2 ${reportMode === 'summary' ? 'w-2/3' : 'w-64'}`} rowSpan={2}>แผนงาน - ผลผลิต - กิจกรรม/โครงการ</th>
                            {reportMode !== 'summary' && (
                                <>
                                    <th className={`${headerBorder} p-1 w-12`} rowSpan={2}><div style={verticalTextStyle}>เป้าหมาย</div></th>
                                    <th className={`${headerBorder} p-1 w-12`} rowSpan={2}><div style={verticalTextStyle}>หน่วยนับ</div></th>
                                </>
                            )}
                            {reportMode === 'full' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบบุคลากร</th>
                                    <th className={`${headerBorder} p-1`} colSpan={3}>งบดำเนินงาน</th>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบลงทุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>เงินอุดหนุน</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>รายจ่ายอื่น</th>
                                </>
                            )}
                            {reportMode === 'province' && (
                                <>
                                    <th className={`${headerBorder} p-1`} colSpan={2}>งบประมาณตาม พ.ร.บ. ปี {budgetYear}</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>เงินนอก<br/>งบประมาณ</th>
                                    <th className={`${headerBorder} p-1 w-24`} rowSpan={2}>งบกลาง<br/>ปี {budgetYear}</th>
                                </>
                            )}
                            <th className={`${headerBorder} p-1 ${reportMode === 'summary' ? 'w-1/3' : 'w-32'}`} rowSpan={2}>รวมทั้งสิ้น (บาท)</th>
                        </tr>
                        {reportMode === 'full' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-800 dark:text-slate-200">
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>เงินเดือนฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>พนง.ราชการ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ใช้สอย/วัสดุ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>จ้างเหมาฯ</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>สาธารณูปโภค</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ค่าครุภัณฑ์</th>
                                <th className={`${headerBorder} p-1 w-24 text-[14px]`}>ที่ดินฯ</th>
                            </tr>
                        )}
                        {reportMode === 'province' && (
                            <tr className="bg-slate-100 dark:bg-slate-800 text-center font-bold text-slate-800 dark:text-slate-200">
                                <th className={`${headerBorder} p-1 w-32`}>งบประจำ</th>
                                <th className={`${headerBorder} p-1 w-32`}>งบลงทุน</th>
                            </tr>
                        )}
                    </thead>
                    <tbody>
                        <tr className="bg-emerald-50/50 dark:bg-emerald-900/30 font-bold text-slate-900 dark:text-slate-100">
                            <td className={`${headerBorder} px-3 py-2 text-left`}>รวมทั้งสิ้น</td>
                            {reportMode !== 'summary' && (<><td className={`${headerBorder} px-1 py-1 text-center`}></td><td className={`${headerBorder} px-1 py-1 text-center`}></td></>)}
                            {reportMode === 'full' && (
                                <>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.salaryPermanent)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.governmentCompensation)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.compensationSupplies)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.contractEmployees)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.utilities)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.equipment)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.landConstruction)}</td>
                                    <td className={`${headerBorder} px-1 py-1 text-right`}>{formatNumber(grandTotal.subsidies)}</td>
