                    { header: 'ใช้สอย/วัสดุ', key: 'compensationSupplies', width: 18 },
                    { header: 'จ้างเหมาฯ', key: 'contractEmployees', width: 18 },
                    { header: 'สาธารณูปโภค', key: 'utilities', width: 18 },
                    { header: 'ค่าครุภัณฑ์', key: 'equipment', width: 18 },
