                columns = [{ header: 'แผนงาน - ผลผลิต - กิจกรรม/โครงการ', key: 'title', width: 60 }];
                if (reportMode !== 'summary') {
                    columns.push({ header: 'เป้าหมาย', key: 'target', width: 10 });
                    columns.push({ header: 'หน่วยนับ', key: 'unit', width: 10 });
                }

