                                                <td className={`${headerBorder} px-1 py-1 text-right font-bold`}>{formatNumber(r.total)}</td>
                                            </tr>
                                        ))}
                                    </>
                                )}
                            </>
                        )}
                        {filteredRecords.length === 0 && (
                            <tr>
                                <td colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 8 : (reportMode === 'agency' ? 14 : dropdowns.integration.length + 2)} className={`${headerBorder} px-4 py-16 text-center text-slate-400 dark:text-slate-600`}>
