                                <div className={`transition-all duration-200 ${reportMode === 'full' ? 'text-emerald-600' : 'text-slate-300'}`}>{reportMode === 'full' ? <CheckCircle2 size={22} className="fill-emerald-50 dark:fill-emerald-950" /> : <Circle size={22} />}</div>
