                    Swal.fire('สำเร็จ', 'ลบภูมิภาคเรียบร้อย', 'success');
                } else Swal.fire('ผิดพลาด', res.message, 'error');
            }
            return;
        }

        const { value: newName } = await Swal.fire({
            title: action === 'add' ? 'เพิ่มภูมิภาค' : 'แก้ไขชื่อภูมิภาค',
            input: 'text',
            inputValue: action === 'edit' ? currentName : '',
