            title: 'เพิ่มจังหวัด',
            input: 'text',
            showCancelButton: true,
            confirmButtonText: 'เพิ่ม',
            inputValidator: (value) => {
                if (!value) return 'กรุณาระบุชื่อจังหวัด';
