            Swal.showLoading();
            const res = await dataService.addProvinceToRegion(selectedRegion, newProvince);
            if (res.success) {
                triggerRefresh();
                Swal.fire('สำเร็จ', 'เพิ่มจังหวัดเรียบร้อย', 'success');
