                                <td colSpan={reportMode === 'full' ? 13 : reportMode === 'province' ? 8 : (reportMode === 'agency' ? 14 : dropdowns.integration.length + 2)} className={`${headerBorder} px-4 py-16 text-center text-slate-400 dark:text-slate-600`}>
                                    <div className="flex flex-col items-center gap-3">
                                        <AlertCircle size={40} className="opacity-20" />
                                        <span className="text-xl">ไม่พบข้อมูลตามเงื่อนไขที่ระบุ</span>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ReportView;

