// ReportView.tsx
import React from 'react';

interface ReportData {
  planTitle?: string;
  outputTitle?: string;
  projectTitle?: string;
  groupTitle?: string;
  subgroupTitle?: string;
  activityTitle?: string;
  subactivityTitle?: string;
  title?: string; // This will hold the title for any of the above
  type: 'plan' | 'output' | 'project' | 'group' | 'subgroup' | 'activity' | 'subactivity';
  children?: ReportData[]; // Represents the nested structure
  [key: string]: any; // Allows for dynamic properties, e.g., salary, budget, etc.
}

interface ReportViewProps {
  data: ReportData[];
}

const ReportView: React.FC<ReportViewProps> = ({ data }) => {
  const renderHierarchy = (items: ReportData[], level: number = 0) => {
    return items.map((item, index) => {
      const { type, title, children, ...rest } = item; // Destructure to handle dynamic properties
      const isProject = type === 'project';

      // Define default classes
      let rowClass = 'py-1 border-b border-gray-200 dark:border-gray-700'; // Default row style
      let fontClass = 'font-normal'; // Default font style
      let plClass = 'pl-2'; // Default padding-left
      let bgColorClass = '';

      switch (type) {
        case 'plan':
          plClass = 'pl-2';
          break;
        case 'output':
          plClass = 'pl-6';
          break;
        case 'project':
          plClass = 'pl-10 font-bold';
          bgColorClass = 'bg-teal-50 dark:bg-teal-900/20'; // Highlight project rows
          break;
        case 'group':
          plClass = 'pl-16';
          break;
        case 'subgroup':
          plClass = 'pl-24';
          fontClass = 'font-normal'; // Remove the font-medium and italic
          break;
        case 'activity':
          plClass = 'pl-32';
          break;
        case 'subactivity':
          plClass = 'pl-40';
          break;
        default:
          plClass = 'pl-2'; // Default padding
          break;
      }

      const displayTitle = title || item[`${type}Title`] || `Unnamed ${type}`;

      return (
        <React.Fragment key={`${type}-${index}`}>
          <div className={`${rowClass} ${plClass} ${bgColorClass}`}>
            {displayTitle}
            {Object.keys(rest).map((key) => {
              // This part handles the dynamic properties
              if (key !== 'children' && key !== 'title' && key !== 'type') {
                const value = rest[key];
                return (
                  <span key={key} className="ml-4 text-right">
                    {typeof value === 'number' ? value.toLocaleString() : value}
                  </span>
                );
              }
              return null;
            })}
          </div>
          {children && renderHierarchy(children, level + 1)}
        </React.Fragment>
      );
    });
  };

  return (
    <div className="overflow-x-auto">
      <div className="inline-block min-w-full py-2 align-middle">
        <div className="overflow-hidden shadow ring-1 ring-black ring-opacity-5 md:rounded-lg">
          {renderHierarchy(data)}
        </div>
      </div>
    </div>
  );
};

export default ReportView;
```


