                totalOperational: (acc as any).totalOperational + (r.compensationSupplies || 0) + (r.contractEmployees || 0) + (r.utilities || 0),
                totalInvestment: (acc as any).totalInvestment + (r.equipment || 0) + (r.landConstruction || 0)
