                    <AutocompleteInput id="filter-integ" label="รายการบูรณาการ" value={selectedIntegration} onChange={setSelectedIntegration} options={dropdowns.integration} placeholder="เลือกรายการบูรณาการ..." />
                    <AutocompleteInput id="filter-activity" label="กิจกรรม" value={selectedActivity} onChange={setSelectedActivity} options={dropdowns.activity} placeholder="เลือกกิจกรรม..." />
