                                    {tableVisibility.mainAgency && <DataCell text={r.mainAgency} />}
                                    {tableVisibility.province && <DataCell text={r.province} />}
                                    {tableVisibility.responsibleAgency && <DataCell text={r.responsibleAgency} />}
