        style={{ width: width, minWidth: isStickyRight ? 'auto' : (colSpan && colSpan > 1 ? 'auto' : '100px'), resize: isStickyRight ? 'none' : 'horizontal', overflow: isStickyRight ? 'visible' : 'auto' }}
