                                                            <td className={`${headerBorder} px-1 py-1 text-right font-normal text-[18px]`}>{formatNumber(getInvestmentBudget(r as any))}</td>
                                                            <td className={`${headerBorder} px-1 py-1 text-right font-normal text-[18px]`}>-</td>
