        <th 
            {...props}
            className={`${headerBorder} p-1 relative hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors bg-slate-100 dark:bg-slate-800 z-30 font-bold ${className || ''}`}
            style={{ 
