    private updateDerivedDropdowns() {
        const unique = (arr: any[]) => Array.from(new Set(arr.filter(item => item && item.trim() !== '')));
        this.dropdowns.mainAgency = unique(this.hierarchy.map(h => h.mainAgency));
        this.dropdowns.province = unique(this.hierarchy.map(h => h.province));
        this.dropdowns.responsibleAgency = unique(this.respData.map(r => r.responsibleAgency));
        this.dropdowns.integrationArea = unique(this.respData.map(r => r.integrationArea));
        this.dropdowns.activity = unique(this.compareData.map(c => c.activity));
        this.dropdowns.integration = this.sortIntegrationData(this.dropdowns.integration);
    }

