                icon: 'error',
                title: 'เกิดข้อผิดพลาด',
                text: 'ไม่สามารถสร้างไฟล์ Excel ได้',
                confirmButtonColor: '#ef4444'
            });
        } finally {
            setIsDownloading(false);
        }
    };

    const handleClearFilters = () => {
        setSearchTerm('');
        setFilterIntegration('');
        setFilterMainAgency('');
        setFilterProvince('');
        setFilterResponsibleAgency('');
        setFilterIntegrationArea('');
