                    >
                        <Filter size={20} /> ตัวกรอง
                    </button>
                </div>

                {/* Collapsible Filters */}
                <div className={`transition-all duration-300 ease-in-out ${showFilters ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'} ${filterOverflow ? 'overflow-visible' : 'overflow-hidden'}`}>
                    <div className="pt-4 border-t border-slate-100 dark:border-slate-700 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        <AutocompleteInput id="filter-integration" label="ประเภทบูรณาการ" value={filterIntegration} onChange={setFilterIntegration} options={getOptions('integration')} placeholder="เลือกประเภท..." />
                        <AutocompleteInput id="filter-main" label="หน่วยงานหลัก" value={filterMainAgency} onChange={setFilterMainAgency} options={getOptions('mainAgency')} placeholder="เลือกหน่วยงาน..." />
                        <AutocompleteInput id="filter-prov" label="จังหวัด" value={filterProvince} onChange={setFilterProvince} options={getOptions('province')} placeholder="เลือกจังหวัด..." />
                        <AutocompleteInput id="filter-resp" label="หน่วยงานบูรณาการ" value={filterResponsibleAgency} onChange={setFilterResponsibleAgency} options={getOptions('responsibleAgency')} placeholder="เลือกหน่วยงาน..." />
                        <AutocompleteInput id="filter-area" label="พื้นที่บูรณาการ" value={filterIntegrationArea} onChange={setFilterIntegrationArea} options={getOptions('integrationArea')} placeholder="เลือกพื้นที่..." />
                        <AutocompleteInput id="filter-act" label="กิจกรรม" value={filterActivity} onChange={setFilterActivity} options={getOptions('activity')} placeholder="เลือกกิจกรรม..." />

                        <div className="lg:col-span-3 flex justify-end">
                            <button 
                                onClick={handleClearFilters}
                                className="text-red-500 hover:text-red-700 text-sm font-bold flex items-center gap-1 py-2 px-4 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                            >
                                <X size={16} /> ล้างตัวกรองทั้งหมด
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            <PaginationControls isTop />

            <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden transition-colors">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="min-w-full border-collapse">
                        <thead className="bg-slate-100 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-700">
                            <tr>
                                <th className="sticky left-0 z-20 bg-slate-100 dark:bg-slate-900/90 px-6 py-4 text-left text-sm font-bold text-slate-700 dark:text-slate-200 uppercase tracking-tight min-w-[200px] shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)]">กิจกรรม / หน่วยงาน</th>
                                {tableVisibility.target && <th className="px-4 py-4 text-center text-sm font-bold text-slate-600 dark:text-slate-300 w-24">เป้าหมาย</th>}

                                {(tableVisibility.salaryPermanent || tableVisibility.governmentCompensation) && (
                                    <th className="px-4 py-4 text-center text-sm font-bold text-blue-700 dark:text-blue-300 bg-blue-50/50 dark:bg-blue-900/10 border-l border-r border-slate-200 dark:border-slate-700" colSpan={(tableVisibility.salaryPermanent ? 1 : 0) + (tableVisibility.governmentCompensation ? 1 : 0)}>งบบุคลากร</th>
                                )}

                                {(tableVisibility.compensationSupplies || tableVisibility.contractEmployees || tableVisibility.utilities) && (
                                    <th className="px-4 py-4 text-center text-sm font-bold text-emerald-700 dark:text-emerald-300 bg-emerald-50/50 dark:bg-emerald-900/10 border-r border-slate-200 dark:border-slate-700" colSpan={(tableVisibility.compensationSupplies ? 1 : 0) + (tableVisibility.contractEmployees ? 1 : 0) + (tableVisibility.utilities ? 1 : 0)}>งบดำเนินงาน</th>
                                )}

                                {(tableVisibility.equipment || tableVisibility.landConstruction) && (
                                    <th className="px-4 py-4 text-center text-sm font-bold text-amber-700 dark:text-amber-300 bg-amber-50/50 dark:bg-amber-900/10 border-r border-slate-200 dark:border-slate-700" colSpan={(tableVisibility.equipment ? 1 : 0) + (tableVisibility.landConstruction ? 1 : 0)}>งบลงทุน</th>
                                )}

                                {(tableVisibility.subsidies || tableVisibility.otherExpenses) && (
                                    <th className="px-4 py-4 text-center text-sm font-bold text-purple-700 dark:text-purple-300 bg-purple-50/50 dark:bg-purple-900/10 border-r border-slate-200 dark:border-slate-700" colSpan={(tableVisibility.subsidies ? 1 : 0) + (tableVisibility.otherExpenses ? 1 : 0)}>งบอื่นๆ</th>
                                )}

                                {tableVisibility.timestamp && <th className="px-4 py-4 text-center text-sm font-bold text-slate-500 dark:text-slate-400 w-32">บันทึกเมื่อ</th>}
                                <th className="px-4 py-4 text-center text-sm font-bold text-slate-500 dark:text-slate-400 w-24">จัดการ</th>
                            </tr>
                            <tr className="bg-slate-50 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 text-xs">
                                <th className="sticky left-0 z-20 bg-slate-50 dark:bg-slate-800 px-6 py-2 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)]"></th>
                                {tableVisibility.target && <th className="px-2 py-2"></th>}

                                {tableVisibility.salaryPermanent && <th className="px-2 py-2 text-center text-slate-500 bg-blue-50/30 dark:bg-blue-900/5">เงินเดือนฯ</th>}
                                {tableVisibility.governmentCompensation && <th className="px-2 py-2 text-center text-slate-500 bg-blue-50/30 dark:bg-blue-900/5 border-r border-slate-200 dark:border-slate-700">ค่าตอบแทนฯ</th>}

                                {tableVisibility.compensationSupplies && <th className="px-2 py-2 text-center text-slate-500 bg-emerald-50/30 dark:bg-emerald-900/5">ใช้สอยฯ</th>}
                                {tableVisibility.contractEmployees && <th className="px-2 py-2 text-center text-slate-500 bg-emerald-50/30 dark:bg-emerald-900/5">จ้างเหมา</th>}
                                {tableVisibility.utilities && <th className="px-2 py-2 text-center text-slate-500 bg-emerald-50/30 dark:bg-emerald-900/5 border-r border-slate-200 dark:border-slate-700">สาธารณูปโภค</th>}

                                {tableVisibility.equipment && <th className="px-2 py-2 text-center text-slate-500 bg-amber-50/30 dark:bg-amber-900/5">ครุภัณฑ์</th>}
                                {tableVisibility.landConstruction && <th className="px-2 py-2 text-center text-slate-500 bg-amber-50/30 dark:bg-amber-900/5 border-r border-slate-200 dark:border-slate-700">ที่ดิน/สิ่งก่อสร้าง</th>}

                                {tableVisibility.subsidies && <th className="px-2 py-2 text-center text-slate-500 bg-purple-50/30 dark:bg-purple-900/5">เงินอุดหนุน</th>}
                                {tableVisibility.otherExpenses && <th className="px-2 py-2 text-center text-slate-500 bg-purple-50/30 dark:bg-purple-900/5 border-r border-slate-200 dark:border-slate-700">รายจ่ายอื่น</th>}

                                {tableVisibility.timestamp && <th className="px-2 py-2"></th>}
                                <th className="px-2 py-2"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-700">
                            {paginatedRecords.length > 0 ? (
                                paginatedRecords.map((record) => (
                                    <tr key={record.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-all group">
                                        <td className="sticky left-0 z-10 bg-white dark:bg-slate-800 group-hover:bg-slate-50 dark:group-hover:bg-slate-700/30 px-6 py-4 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.05)] border-r border-transparent">
                                            <div className="font-bold text-slate-800 dark:text-slate-100">{record.activity}</div>
                                            <div className="text-xs text-slate-500 dark:text-slate-400 mt-1 flex flex-col gap-0.5">
                                                {tableVisibility.mainAgency && <span>{record.mainAgency}</span>}
                                                {tableVisibility.province && <span>จ. {record.province}</span>}
                                                {tableVisibility.responsibleAgency && <span className="text-slate-400 dark:text-slate-500 italic">{record.responsibleAgency}</span>}
                                            </div>
                                        </td>

                                        {tableVisibility.target && (
                                            <td className="px-4 py-4 text-center">
                                                <div className="font-bold text-slate-700 dark:text-slate-200">{record.target}</div>
                                                <div className="text-xs text-slate-400">{record.unit}</div>
                                            </td>
                                        )}

                                        {tableVisibility.salaryPermanent && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-blue-50/10">{formatMoney(record.salaryPermanent)}</td>}
                                        {tableVisibility.governmentCompensation && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-blue-50/10 border-r border-slate-100 dark:border-slate-800">{formatMoney(record.governmentCompensation)}</td>}

                                        {tableVisibility.compensationSupplies && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-emerald-50/10">{formatMoney(record.compensationSupplies)}</td>}
                                        {tableVisibility.contractEmployees && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-emerald-50/10">{formatMoney(record.contractEmployees)}</td>}
                                        {tableVisibility.utilities && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-emerald-50/10 border-r border-slate-100 dark:border-slate-800">{formatMoney(record.utilities)}</td>}

