                                        {tableVisibility.landConstruction && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-amber-50/10 border-r border-slate-100 dark:border-slate-800">{formatMoney(record.landConstruction)}</td>}

                                        {tableVisibility.subsidies && <td className="px-4 py-4 text-right text-slate-600 dark:text-slate-300 font-mono bg-purple-50/10">{formatMoney(record.subsidies)}</td>}
